export const scriptureData: ScriptureBookData = {"LUK":{"1":[{"start":1,"end":2,"text":"提阿非罗大人哪，有好些人提笔作书，述说在我们中间所成就的事，是照传道的人从起初亲眼看见又传给我们的。"},{"start":3,"end":3,"text":"这些事我既从起头都详细考察了，就定意要按着次序写给你，"},{"start":4,"end":4,"text":"使你知道所学之道都是确实的。"},{"start":5,"end":5,"text":"当犹太王希律的时候，亚比雅班里有一个祭司，名叫撒迦利亚；他妻子是亚伦的后人，名叫伊利莎白。"},{"start":6,"end":6,"text":"他们二人在　神面前都是义人，遵行主的一切诫命礼仪，没有可指摘的，"},{"start":7,"end":7,"text":"只是没有孩子；因为伊利莎白不生育，两个人又年纪老迈了。"},{"start":8,"end":8,"text":"撒迦利亚按班次在　神面前供祭司的职分，"},{"start":9,"end":9,"text":"照祭司的规矩掣签，得进主殿烧香。"},{"start":10,"end":10,"text":"烧香的时候，众百姓在外面祷告。"},{"start":11,"end":11,"text":"有主的使者站在香坛的右边，向他显现。"},{"start":12,"end":12,"text":"撒迦利亚看见，就惊慌害怕。"},{"start":13,"end":13,"text":"天使对他说：「撒迦利亚，不要害怕，因为你的祈祷已经被听见了。你的妻子伊利莎白要给你生一个儿子，你要给他起名叫约翰。"},{"start":14,"end":14,"text":"你必欢喜快乐；有许多人因他出世，也必喜乐。"},{"start":15,"end":15,"text":"他在主面前将要为大，淡酒浓酒都不喝，从母腹里就被圣灵充满了。"},{"start":16,"end":16,"text":"他要使许多以色列人回转，归于主—他们的　神。"},{"start":17,"end":17,"text":"他必有以利亚的心志能力，行在主的前面，叫为父的心转向儿女，叫悖逆的人转从义人的智慧，又为主预备合用的百姓。」"},{"start":18,"end":18,"text":"撒迦利亚对天使说：「我凭着什么可知道这事呢？我已经老了，我的妻子也年纪老迈了。」"},{"start":19,"end":19,"text":"天使回答说：「我是站在　神面前的加百列，奉差而来对你说话，将这好信息报给你。"},{"start":20,"end":20,"text":"到了时候，这话必然应验；只因你不信，你必哑巴，不能说话，直到这事成就的日子。」"},{"start":21,"end":21,"text":"百姓等候撒迦利亚，诧异他许久在殿里。"},{"start":22,"end":22,"text":"及至他出来，不能和他们说话，他们就知道他在殿里见了异象；因为他直向他们打手式，竟成了哑巴。"},{"start":23,"end":23,"text":"他供职的日子已满，就回家去了。"},{"start":24,"end":24,"text":"这些日子以后，他的妻子伊利莎白怀了孕，就隐藏了五个月，"},{"start":25,"end":25,"text":"说：「主在眷顾我的日子，这样看待我，要把我在人间的羞耻除掉。」"},{"start":26,"end":26,"text":"到了第六个月，天使加百列奉　神的差遣往加利利的一座城去（这城名叫拿撒勒），"},{"start":27,"end":27,"text":"到一个童女那里，是已经许配大卫家的一个人，名叫约瑟。童女的名字叫马利亚；"},{"start":28,"end":28,"text":"天使进去，对她说：「蒙大恩的女子，我问你安，主和你同在了！」"},{"start":29,"end":29,"text":"马利亚因这话就很惊慌，又反复思想这样问安是什么意思。"},{"start":30,"end":30,"text":"天使对她说：「马利亚，不要怕！你在　神面前已经蒙恩了。"},{"start":31,"end":31,"text":"你要怀孕生子，可以给他起名叫耶稣。"},{"start":32,"end":32,"text":"他要为大，称为至高者的儿子；主　神要把他祖大卫的位给他。"},{"start":33,"end":33,"text":"他要作雅各家的王，直到永远；他的国也没有穷尽。」"},{"start":34,"end":34,"text":"马利亚对天使说：「我没有出嫁，怎么有这事呢？」"},{"start":35,"end":35,"text":"天使回答说：「圣灵要临到你身上，至高者的能力要荫庇你，因此所要生的圣者必称为　神的儿子。"},{"start":36,"end":36,"text":"况且你的亲戚伊利莎白，在年老的时候也怀了男胎，就是那素来称为不生育的，现在有孕六个月了。"},{"start":37,"end":37,"text":"因为，出于　神的话，没有一句不带能力的。」"},{"start":38,"end":38,"text":"马利亚说：「我是主的使女，情愿照你的话成就在我身上。」天使就离开她去了。"},{"start":39,"end":39,"text":"那时候，马利亚起身，急忙往山地里去，来到犹大的一座城；"},{"start":40,"end":40,"text":"进了撒迦利亚的家，问伊利莎白安。"},{"start":41,"end":41,"text":"伊利莎白一听马利亚问安，所怀的胎就在腹里跳动。伊利莎白且被圣灵充满，"},{"start":42,"end":42,"text":"高声喊着说：「你在妇女中是有福的！你所怀的胎也是有福的！"},{"start":43,"end":43,"text":"我主的母到我这里来，这是从哪里得的呢？"},{"start":44,"end":44,"text":"因为你问安的声音一入我耳，我腹里的胎就欢喜跳动。"},{"start":45,"end":45,"text":"这相信的女子是有福的！因为主对她所说的话都要应验。」"},{"start":46,"end":46,"text":"马利亚说： 我心尊主为大；"},{"start":47,"end":47,"text":"我灵以　神我的救主为乐；"},{"start":48,"end":48,"text":"因为他顾念他使女的卑微； 从今以后， 万代要称我有福。"},{"start":49,"end":49,"text":"那有权能的，为我成就了大事； 他的名为圣。"},{"start":50,"end":50,"text":"他怜悯敬畏他的人， 直到世世代代。"},{"start":51,"end":51,"text":"他用膀臂施展大能； 那狂傲的人正心里妄想就被他赶散了。"},{"start":52,"end":52,"text":"他叫有权柄的失位， 叫卑贱的升高；"},{"start":53,"end":53,"text":"叫饥饿的得饱美食， 叫富足的空手回去。"},{"start":54,"end":54,"text":"他扶助了他的仆人以色列，"},{"start":55,"end":55,"text":"为要记念亚伯拉罕和他的后裔， 施怜悯直到永远， 正如从前对我们列祖所说的话。"},{"start":56,"end":56,"text":"马利亚和伊利莎白同住，约有三个月，就回家去了。"},{"start":57,"end":57,"text":"伊利莎白的产期到了，就生了一个儿子。"},{"start":58,"end":58,"text":"邻里亲族听见主向她大施怜悯，就和她一同欢乐。"},{"start":59,"end":59,"text":"到了第八日，他们来要给孩子行割礼，并要照他父亲的名字叫他撒迦利亚。"},{"start":60,"end":60,"text":"他母亲说：「不可！要叫他约翰。」"},{"start":61,"end":61,"text":"他们说：「你亲族中没有叫这名字的。」"},{"start":62,"end":62,"text":"他们就向他父亲打手式，问他要叫这孩子什么名字。"},{"start":63,"end":63,"text":"他要了一块写字的板，就写上，说：「他的名字是约翰。」他们便都希奇。"},{"start":64,"end":64,"text":"撒迦利亚的口立时开了，舌头也[舒展了]，就说出话来，称颂　神。"},{"start":65,"end":65,"text":"周围居住的人都惧怕；这一切的事就传遍了犹太的山地。"},{"start":66,"end":66,"text":"凡听见的人都将这事放在心里，说：「这个孩子将来怎么样呢？因为有主与他同在。」"},{"start":67,"end":67,"text":"他父亲撒迦利亚被圣灵充满了，就预言说："},{"start":68,"end":68,"text":"主—以色列的　神是应当称颂的！ 因他眷顾他的百姓，为他们施行救赎，"},{"start":69,"end":69,"text":"在他仆人大卫家中， 为我们兴起了拯救的角，"},{"start":70,"end":70,"text":"正如主借着从创世以来圣先知的口所说的话，"},{"start":71,"end":71,"text":"拯救我们脱离仇敌 和一切恨我们之人的手，"},{"start":72,"end":72,"text":"向我们列祖施怜悯， 记念他的圣约—"},{"start":73,"end":73,"text":"就是他对我们祖宗亚伯拉罕所起的誓—"},{"start":74,"end":74,"text":"叫我们既从仇敌手中被救出来，"},{"start":75,"end":75,"text":"就可以终身在他面前， 坦然无惧地用圣洁、公义事奉他。"},{"start":76,"end":76,"text":"孩子啊！你要称为至高者的先知； 因为你要行在主的前面， 预备他的道路，"},{"start":77,"end":77,"text":"叫他的百姓因罪得赦， 就知道救恩。"},{"start":78,"end":78,"text":"因我们　神怜悯的心肠， 叫清晨的日光从高天临到我们，"},{"start":79,"end":79,"text":"要照亮坐在黑暗中死荫里的人， 把我们的脚引到平安的路上。"},{"start":80,"end":80,"text":"那孩子渐渐长大，心灵强健，住在旷野，直到他显明在以色列人面前的日子。"}],"2":[{"start":1,"end":1,"text":"当那些日子，凯撒奥古斯都有旨意下来，叫天下人民都报名上册。"},{"start":2,"end":2,"text":"这是居里扭作叙利亚巡抚的时候，头一次行报名上册的事。"},{"start":3,"end":3,"text":"众人各归各城，报名上册。"},{"start":4,"end":4,"text":"约瑟也从加利利的拿撒勒城上犹太去，到了大卫的城，名叫伯利恒，因他本是大卫一族一家的人，"},{"start":5,"end":5,"text":"要和他所聘之妻马利亚一同报名上册。那时马利亚的身孕已经重了。"},{"start":6,"end":6,"text":"他们在那里的时候，马利亚的产期到了，"},{"start":7,"end":7,"text":"就生了头胎的儿子，用布包起来，放在马槽里，因为客店里没有地方。"},{"start":8,"end":8,"text":"在伯利恒之野地里有牧羊的人，夜间按着更次看守羊群。"},{"start":9,"end":9,"text":"有主的使者站在他们旁边，主的荣光四面照着他们；牧羊的人就甚惧怕。"},{"start":10,"end":10,"text":"那天使对他们说：「不要惧怕！我报给你们大喜的信息，是关乎万民的；"},{"start":11,"end":11,"text":"因今天在大卫的城里，为你们生了救主，就是主基督。"},{"start":12,"end":12,"text":"你们要看见一个婴孩，包着布，卧在[马]槽里，那就是记号了。」"},{"start":13,"end":13,"text":"忽然，有一大队天兵同那天使赞美　神说："},{"start":14,"end":14,"text":"在至高之处荣耀归与　神！ 在地上平安归与他所喜悦的人！"},{"start":15,"end":15,"text":"众天使离开他们，升天去了。牧羊的人彼此说：「我们往伯利恒去，看看所成的事，就是主所指示我们的。」"},{"start":16,"end":16,"text":"他们急忙去了，就寻见马利亚和约瑟，又有那婴孩卧在[马]槽里；"},{"start":17,"end":17,"text":"既然看见，就把天使论这孩子的话传开了。"},{"start":18,"end":18,"text":"凡听见的，就诧异牧羊之人对他们所说的话。"},{"start":19,"end":19,"text":"马利亚却把这一切的事存在心里，反复思想。"},{"start":20,"end":20,"text":"牧羊的人回去了，因所听见所看见的一切事，正如[天使]向他们所说的，就归荣耀与　神，赞美他。"},{"start":21,"end":21,"text":"满了八天，就给孩子行割礼，与他起名叫耶稣；这就是没有成胎以前，天使所起的名。"},{"start":22,"end":22,"text":"按摩西律法满了洁净的日子，他们带着孩子上耶路撒冷去，要把他献与主，（"},{"start":23,"end":23,"text":"正如主的律法上所记：「凡头生的男子必称圣归主。」）"},{"start":24,"end":24,"text":"又要照主的律法上所说，或用一对斑鸠，或用两只雏鸽献祭。"},{"start":25,"end":25,"text":"在耶路撒冷有一个人，名叫西面；这人又公义又虔诚，素常盼望以色列的安慰[者]来到，又有圣灵在他身上。"},{"start":26,"end":26,"text":"他得了圣灵的启示，知道自己未死以前，必看见主所立的基督。"},{"start":27,"end":27,"text":"他受了[圣]灵的感动，进入圣殿，正遇见耶稣的父母抱着孩子进来，要照律法的规矩办理。"},{"start":28,"end":28,"text":"西面就用手接过他来，称颂　神说："},{"start":29,"end":29,"text":"主啊！如今可以照你的话， 释放仆人安然去世；"},{"start":30,"end":30,"text":"因为我的眼睛已经看见你的救恩—"},{"start":31,"end":31,"text":"就是你在万民面前所预备的："},{"start":32,"end":32,"text":"是照亮外邦人的光， 又是你民以色列的荣耀。"},{"start":33,"end":33,"text":"孩子的父母因这论耶稣的话就希奇。"},{"start":34,"end":34,"text":"西面给他们祝福，又对孩子的母亲马利亚说：「这[孩子]被立，是要叫以色列中许多人跌倒，许多人兴起；又要作毁谤的话柄，叫许多人心里的意念显露出来；你自己的心也要被刀刺透。」"},{"start":36,"end":36,"text":"又有女先知，名叫亚拿，是亚设支派法内力的女儿，年纪已经老迈，从作童女出嫁的时候，同丈夫住了七年就寡居了，"},{"start":37,"end":37,"text":"现在已经八十四岁，并不离开圣殿，禁食祈求，昼夜事奉　神。"},{"start":38,"end":38,"text":"正当那时，她进前来称谢　神，将孩子的事对一切盼望耶路撒冷得救赎的人讲说。"},{"start":39,"end":39,"text":"约瑟和马利亚照主的律法办完了一切的事，就回加利利，到自己的城拿撒勒去了。"},{"start":40,"end":40,"text":"孩子渐渐长大，强健起来，充满智慧，又有　神的恩在他身上。"},{"start":41,"end":41,"text":"每年到逾越节，他父母就上耶路撒冷去。"},{"start":42,"end":42,"text":"当他十二岁的时候，他们按着节期的规矩上去。"},{"start":43,"end":43,"text":"守满了节期，他们回去，孩童耶稣仍旧在耶路撒冷。他的父母并不知道，"},{"start":44,"end":44,"text":"以为他在同行的人中间，走了一天的路程，就在亲族和熟识的人中找他，"},{"start":45,"end":45,"text":"既找不着，就回耶路撒冷去找他。"},{"start":46,"end":46,"text":"过了三天，就遇见他在殿里，坐在教师中间，一面听，一面问。"},{"start":47,"end":47,"text":"凡听见他的，都希奇他的聪明和他的应对。"},{"start":48,"end":48,"text":"他父母看见就很希奇。他母亲对他说：「我儿！为什么向我们这样行呢？看哪，你父亲和我伤心来找你！」"},{"start":49,"end":49,"text":"耶稣说：「为什么找我呢？岂不知我应当以我父的事为念吗？」"},{"start":50,"end":50,"text":"他所说的这话，他们不明白。"},{"start":51,"end":51,"text":"他就同他们下去，回到拿撒勒，并且顺从他们。他母亲把这一切的事都存在心里。"},{"start":52,"end":52,"text":"耶稣的智慧和身量，并　神和人喜爱他的心，都一齐增长。"}],"3":[{"start":1,"end":1,"text":"凯撒提庇留在位第十五年，本丢·彼拉多作犹太巡抚，希律作加利利分封的王，他兄弟腓力作以土利亚和特拉可尼地方分封的王，吕撒聂作亚比利尼分封的王，"},{"start":2,"end":2,"text":"亚那和该亚法作大祭司。那时，撒迦利亚的儿子约翰在旷野里，　神的话临到他。"},{"start":3,"end":3,"text":"他就来到约旦河一带地方，宣讲悔改的洗礼，使罪得赦。"},{"start":4,"end":4,"text":"正如先知以赛亚书上所记的话，说： 在旷野有人声喊着说： 预备主的道， 修直他的路！"},{"start":5,"end":5,"text":"一切山洼都要填满； 大小山冈都要削平！ 弯弯曲曲的地方要改为正直； 高高低低的道路要改为平坦！"},{"start":6,"end":6,"text":"凡有血气的，都要见　神的救恩！"},{"start":7,"end":7,"text":"约翰对那出来要受他洗的众人说：「毒蛇的种类！谁指示你们逃避将来的忿怒呢？"},{"start":8,"end":8,"text":"你们要结出果子来，与悔改的心相称。不要自己心里说：『有亚伯拉罕为我们的祖宗。』我告诉你们，　神能从这些石头中，给亚伯拉罕兴起子孙来。"},{"start":9,"end":9,"text":"现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。」"},{"start":10,"end":10,"text":"众人问他说：「这样，我们当做什么呢？」"},{"start":11,"end":11,"text":"约翰回答说：「有两件衣裳的，就分给那没有的；有食物的，也当这样行。」"},{"start":12,"end":12,"text":"又有税吏来要受洗，问他说：「夫子，我们当做什么呢？」"},{"start":13,"end":13,"text":"约翰说：「除了例定的数目，不要多取。」"},{"start":14,"end":14,"text":"又有兵丁问他说：「我们当做什么呢？」约翰说：「不要以强暴待人，也不要讹诈人，自己有钱粮就当知足。」"},{"start":15,"end":15,"text":"百姓指望[基督来]的时候，人都心里猜疑，或者约翰是基督。"},{"start":16,"end":16,"text":"约翰说：「我是用水给你们施洗，但有一位能力比我更大的要来，我就是给他解鞋带也不配。他要用圣灵与火给你们施洗。"},{"start":17,"end":17,"text":"他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。」"},{"start":18,"end":18,"text":"约翰又用许多别的话劝百姓，向他们传福音。"},{"start":19,"end":19,"text":"只是分封的王希律，因他兄弟之妻希罗底的缘故，并因他所行的一切恶事，受了约翰的责备；"},{"start":20,"end":20,"text":"又另外添了一件，就是把约翰收在监里。"},{"start":21,"end":21,"text":"众百姓都受了洗，耶稣也受了洗。正祷告的时候，天就开了，"},{"start":22,"end":22,"text":"圣灵降临在他身上，形状仿佛鸽子；又有声音从天上来，说：「你是我的爱子，我喜悦你。」"},{"start":23,"end":23,"text":"耶稣开头[传道]，年纪约有三十岁。依人看来，他是约瑟的儿子；约瑟是希里的儿子；"},{"start":24,"end":24,"text":"希里是玛塔的儿子；玛塔是利未的儿子；利未是麦基的儿子；麦基是雅拿的儿子；雅拿是约瑟的儿子；"},{"start":25,"end":25,"text":"约瑟是玛他提亚的儿子；玛他提亚是亚摩斯的儿子；亚摩斯是拿鸿的儿子；拿鸿是以斯利的儿子；以斯利是拿该的儿子；"},{"start":26,"end":26,"text":"拿该是玛押的儿子；玛押是玛他提亚的儿子；玛他提亚是西美的儿子；西美是约瑟的儿子；约瑟是犹大的儿子；犹大是约亚拿的儿子；"},{"start":27,"end":27,"text":"约亚拿是利撒的儿子；利撒是所罗巴伯的儿子；所罗巴伯是撒拉铁的儿子；撒拉铁是尼利的儿子；尼利是麦基的儿子；"},{"start":28,"end":28,"text":"麦基是亚底的儿子；亚底是哥桑的儿子；哥桑是以摩当的儿子；以摩当是珥的儿子；珥是约细的儿子；"},{"start":29,"end":29,"text":"约细是以利以谢的儿子；以利以谢是约令的儿子；约令是玛塔的儿子；玛塔是利未的儿子；"},{"start":30,"end":30,"text":"利未是西缅的儿子；西缅是犹大的儿子；犹大是约瑟的儿子；约瑟是约南的儿子；约南是以利亚敬的儿子；"},{"start":31,"end":31,"text":"以利亚敬是米利亚的儿子；米利亚是买南的儿子；买南是玛达他的儿子；玛达他是拿单的儿子；拿单是大卫的儿子；"},{"start":32,"end":32,"text":"大卫是耶西的儿子；耶西是俄备得的儿子；俄备得是波阿斯的儿子；波阿斯是撒门的儿子；撒门是拿顺的儿子；"},{"start":33,"end":33,"text":"拿顺是亚米拿达的儿子；亚米拿达是亚兰的儿子；亚兰是希斯仑的儿子；希斯仑是法勒斯的儿子；法勒斯是犹大的儿子；"},{"start":34,"end":34,"text":"犹大是雅各的儿子；雅各是以撒的儿子；以撒是亚伯拉罕的儿子；亚伯拉罕是他拉的儿子；他拉是拿鹤的儿子；"},{"start":35,"end":35,"text":"拿鹤是西鹿的儿子；西鹿是拉吴的儿子；拉吴是法勒的儿子；法勒是希伯的儿子；希伯是沙拉的儿子；"},{"start":36,"end":36,"text":"沙拉是该南的儿子；该南是亚法撒的儿子；亚法撒是闪的儿子；闪是挪亚的儿子；挪亚是拉麦的儿子；"},{"start":37,"end":37,"text":"拉麦是玛土撒拉的儿子；玛土撒拉是以诺的儿子；以诺是雅列的儿子；雅列是玛勒列的儿子；玛勒列是该南的儿子；该南是以挪士的儿子；"},{"start":38,"end":38,"text":"以挪士是塞特的儿子；塞特是亚当的儿子；亚当是　神的儿子。"}],"4":[{"start":1,"end":1,"text":"耶稣被圣灵充满，从约旦河回来，圣灵将他引到旷野，"},{"start":2,"end":2,"text":"四十天受魔鬼的试探。那些日子没有吃什么；日子满了，他就饿了。"},{"start":3,"end":3,"text":"魔鬼对他说：「你若是　神的儿子，可以吩咐这块石头变成食物。」"},{"start":4,"end":4,"text":"耶稣回答说：「[经上]记着说：『人活着不是单靠食物，[乃是靠　神口里所出的一切话]。』」"},{"start":5,"end":5,"text":"魔鬼又领他上了[高山]，霎时间把天下的万国都指给他看，"},{"start":6,"end":6,"text":"对他说：「这一切权柄、荣华，我都要给你，因为这原是交付我的，我愿意给谁就给谁。"},{"start":7,"end":7,"text":"你若在我面前下拜，这都要归你。」"},{"start":8,"end":8,"text":"耶稣说：「[经上]记着说： 当拜主—你的　神， 单要事奉他。」"},{"start":9,"end":9,"text":"魔鬼又领他到耶路撒冷去，叫他站在殿顶上，对他说：「你若是　神的儿子，可以从这里跳下去；"},{"start":10,"end":10,"text":"因为[经上]记着说： 主要为你吩咐他的使者保护你；"},{"start":11,"end":11,"text":"他们要用手托着你， 免得你的脚碰在石头上。」"},{"start":12,"end":12,"text":"耶稣对他说：「[经上]说：『不可试探主—你的　神。』」"},{"start":13,"end":13,"text":"魔鬼用完了各样的试探，就暂时离开耶稣。"},{"start":14,"end":14,"text":"耶稣满有圣灵的能力，回到加利利；他的名声就传遍了四方。"},{"start":15,"end":15,"text":"他在各会堂里教训人，众人都称赞他。"},{"start":16,"end":16,"text":"耶稣来到拿撒勒，就是他长大的地方。在安息日，照他平常的规矩进了会堂，站起来要念[圣经]。"},{"start":17,"end":17,"text":"有人把先知以赛亚的书交给他，他就打开，找到一处写着说："},{"start":18,"end":18,"text":"主的灵在我身上， 因为他用膏膏我， 叫我传福音给贫穷的人； 差遣我报告： 被掳的得释放， 瞎眼的得看见， 叫那受压制的得自由，"},{"start":19,"end":19,"text":"报告　神悦纳人的禧年。"},{"start":20,"end":20,"text":"于是把书卷起来，交还执事，就坐下。会堂里的人都定睛看他。"},{"start":21,"end":21,"text":"耶稣对他们说：「今天这经应验在你们耳中了。」"},{"start":22,"end":22,"text":"众人都称赞他，并希奇他口中所出的恩言；又说：「这不是约瑟的儿子吗？」"},{"start":23,"end":23,"text":"耶稣对他们说：「你们必引这俗语向我说：『医生，你医治自己吧！我们听见你在迦百农所行的事，也当行在你自己家乡里』」；"},{"start":24,"end":24,"text":"又说：「我实在告诉你们，没有先知在自己家乡被人悦纳的。"},{"start":25,"end":25,"text":"我对你们说实话，当以利亚的时候，天闭塞了三年零六个月，遍地有大饥荒，那时，以色列中有许多寡妇，"},{"start":26,"end":26,"text":"以利亚并没有奉差往她们一个人那里去，只奉差往西顿的撒勒法一个寡妇那里去。"},{"start":27,"end":27,"text":"先知以利沙的时候，以色列中有许多长大麻风的，但内中除了叙利亚国的乃缦，没有一个得洁净的。」"},{"start":28,"end":28,"text":"会堂里的人听见这话，都怒气满胸，"},{"start":29,"end":29,"text":"就起来撵他出城（他们的城造在山上）；他们带他到山崖，要把他推下去。"},{"start":30,"end":30,"text":"他却从他们中间直行，过去了。"},{"start":31,"end":31,"text":"耶稣下到迦百农，就是加利利的一座城，在安息日教训众人。"},{"start":32,"end":32,"text":"他们很希奇他的教训，因为他的话里有权柄。"},{"start":33,"end":33,"text":"在会堂里有一个人，被污鬼的精气附着，大声喊叫说："},{"start":34,"end":34,"text":"「唉！拿撒勒的耶稣，我们与你有什么相干？你来灭我们吗？我知道你是谁，乃是　神的圣者。」"},{"start":35,"end":35,"text":"耶稣责备他说：「不要作声，从这人身上出来吧！」鬼把那人摔倒在众人中间，就出来了，却也没有害他。"},{"start":36,"end":36,"text":"众人都惊讶，彼此对问说：「这是什么道理呢？因为他用权柄能力吩咐污鬼，污鬼就出来。」"},{"start":37,"end":37,"text":"于是耶稣的名声传遍了周围地方。"},{"start":38,"end":38,"text":"耶稣出了会堂，进了西门的家。西门的岳母害热病甚重，有人为她求耶稣。"},{"start":39,"end":39,"text":"耶稣站在她旁边，斥责那热病，热就退了。她立刻起来服事他们。"},{"start":40,"end":40,"text":"日落的时候，凡有病人的，不论害什么病，都带到耶稣那里。耶稣按手在他们各人身上，医好他们。"},{"start":41,"end":41,"text":"又有鬼从好些人身上出来，喊着说：「你是　神的儿子。」耶稣斥责他们，不许他们说话，因为他们知道他是基督。"},{"start":42,"end":42,"text":"天亮的时候，耶稣出来，走到旷野地方。众人去找他，到了他那里，要留住他，不要他离开他们。"},{"start":43,"end":43,"text":"但耶稣对他们说：「我也必须在别城传　神国的福音，因我奉差原是为此。」"},{"start":44,"end":44,"text":"于是耶稣在加利利的各会堂传道。"}],"5":[{"start":1,"end":1,"text":"耶稣站在革尼撒勒湖边，众人拥挤他，要听　神的道。"},{"start":2,"end":2,"text":"他见有两只船湾在湖边；打鱼的人却离开船洗网去了。"},{"start":3,"end":3,"text":"有一只船是西门的，耶稣就上去，请他把船撑开，稍微离岸，就坐下，从船上教训众人。"},{"start":4,"end":4,"text":"讲完了，对西门说：「把船开到水深之处，下网打鱼。」"},{"start":5,"end":5,"text":"西门说：「夫子，我们整夜劳力，并没有打着什么。但依从你的话，我就下网。」"},{"start":6,"end":6,"text":"他们下了网，就圈住许多鱼，网险些裂开，"},{"start":7,"end":7,"text":"便招呼那只船上的同伴来帮助。他们就来，把鱼装满了两只船，甚至船要沉下去。"},{"start":8,"end":8,"text":"西门·彼得看见，就俯伏在耶稣膝前，说：「主啊，离开我，我是个罪人！」"},{"start":9,"end":9,"text":"他和一切同在的人都惊讶这一网所打的鱼。"},{"start":10,"end":10,"text":"他的伙伴西庇太的儿子雅各、约翰，也是这样。耶稣对西门说：「不要怕！从今以后，你要得人了。」"},{"start":11,"end":11,"text":"他们把两只船拢了岸，就撇下所有的，跟从了耶稣。"},{"start":12,"end":12,"text":"有一回，耶稣在一个城里，有人满身长了大麻风，看见他，就俯伏在地，求他说：「主若肯，必能叫我洁净了。」"},{"start":13,"end":13,"text":"耶稣伸手摸他，说：「我肯，你洁净了吧！」大麻风立刻就离了他的身。"},{"start":14,"end":14,"text":"耶稣嘱咐他：「你切不可告诉人，只要去把身体给祭司察看，又要为你得了洁净，照摩西所吩咐的献上[礼物]，对众人作证据。」"},{"start":15,"end":15,"text":"但耶稣的名声越发传扬出去。有极多的人聚集来听道，也指望医治他们的病。"},{"start":16,"end":16,"text":"耶稣却退到旷野去祷告。"},{"start":17,"end":17,"text":"有一天，耶稣教训人，有法利赛人和教法师在旁边坐着；他们是从加利利各乡村和犹太并耶路撒冷来的。主的能力与耶稣同在，使他能医治病人。"},{"start":18,"end":18,"text":"有人用褥子抬着一个瘫子，要抬进去放在耶稣面前，"},{"start":19,"end":19,"text":"却因人多，寻不出法子抬进去，就上了房顶，从瓦间把他连褥子缒到当中，正在耶稣面前。"},{"start":20,"end":20,"text":"耶稣见他们的信心，就对瘫子说：「你的罪赦了。」"},{"start":21,"end":21,"text":"文士和法利赛人就议论说：「这说僭妄话的是谁？除了　神以外，谁能赦罪呢？」"},{"start":22,"end":22,"text":"耶稣知道他们所议论的，就说：「你们心里议论的是什么呢？"},{"start":23,"end":23,"text":"或说『你的罪赦了』，或说『你起来行走』，哪一样容易呢？"},{"start":24,"end":24,"text":"但要叫你们知道，人子在地上有赦罪的权柄。」就对瘫子说：「我吩咐你，起来，拿你的褥子回家去吧！」"},{"start":25,"end":25,"text":"那人当众人面前立刻起来，拿着他所躺卧的[褥子]回家去，归荣耀与　神。"},{"start":26,"end":26,"text":"众人都惊奇，也归荣耀与　神，并且满心惧怕，说：「我们今日看见非常的事了。」"},{"start":27,"end":27,"text":"这事以后，耶稣出去，看见一个税吏，名叫利未，坐在税关上，就对他说：「你跟从我来。」"},{"start":28,"end":28,"text":"他就撇下所有的，起来，跟从了耶稣。"},{"start":29,"end":29,"text":"利未在自己家里为耶稣大摆筵席，有许多税吏和别人与他们一同坐席。"},{"start":30,"end":30,"text":"法利赛人和文士就向耶稣的门徒发怨言说：「你们为什么和税吏并罪人一同吃喝呢？」"},{"start":31,"end":31,"text":"耶稣对他们说：「无病的人用不着医生；有病的人才用得着。"},{"start":32,"end":32,"text":"我来本不是召义人悔改，乃是召罪人悔改。」"},{"start":33,"end":33,"text":"他们说：「约翰的门徒屡次禁食祈祷，法利赛人的[门徒]也是这样；惟独你的门徒又吃又喝。」"},{"start":34,"end":34,"text":"耶稣对他们说：「新郎和陪伴之人同在的时候，岂能叫陪伴之人禁食呢？"},{"start":35,"end":35,"text":"但日子将到，新郎要离开他们，那日他们就要禁食了。」"},{"start":36,"end":36,"text":"耶稣又设一个比喻，对他们说：「没有人把新衣服撕下一块来补在旧衣服上；若是这样，就把新的撕破了，并且所撕下来的那块新的和旧的也不相称。"},{"start":37,"end":37,"text":"也没有人把新酒装在旧皮袋里；若是这样，新酒必将皮袋裂开，酒便漏出来，皮袋也就坏了。"},{"start":38,"end":38,"text":"但新酒必须装在新皮袋里。"},{"start":39,"end":39,"text":"没有人喝了陈酒又想喝新的；他总说陈的好。」"}],"6":[{"start":1,"end":1,"text":"有一个安息日，耶稣从麦地经过。他的门徒掐了麦穗，用手搓着吃。"},{"start":2,"end":2,"text":"有几个法利赛人说：「你们为什么做安息日不可做的事呢？」"},{"start":3,"end":3,"text":"耶稣对他们说：「[经上记着]大卫和跟从他的人饥饿之时所做的事，连这个你们也没有念过吗？"},{"start":4,"end":4,"text":"他怎么进了　神的殿，拿陈设饼吃，又给跟从的人吃？这饼除了祭司以外，别人都不可吃。」"},{"start":5,"end":5,"text":"又对他们说：「人子是安息日的主。」"},{"start":6,"end":6,"text":"又有一个安息日，耶稣进了会堂教训人，在那里有一个人右手枯干了。"},{"start":7,"end":7,"text":"文士和法利赛人窥探耶稣，在安息日治病不治病，要得把柄去告他。"},{"start":8,"end":8,"text":"耶稣却知道他们的意念，就对那枯干一只手的人说：「起来！站在当中。」那人就起来，站着。"},{"start":9,"end":9,"text":"耶稣对他们说：「我问你们，在安息日行善行恶，救命害命，哪样是可以的呢？」"},{"start":10,"end":10,"text":"他就周围看着他们众人，对那人说：「伸出手来！」他把手一伸，手就复了原。"},{"start":11,"end":11,"text":"他们就满心大怒，彼此商议怎样处治耶稣。"},{"start":12,"end":12,"text":"那时，耶稣出去，上山祷告，整夜祷告　神；"},{"start":13,"end":13,"text":"到了天亮，叫他的门徒来，就从他们中间挑选十二个人，称他们为使徒。"},{"start":14,"end":14,"text":"[这十二个人]有西门（耶稣又给他起名叫彼得），还有他兄弟安得烈，又有雅各和约翰，腓力和巴多罗买，"},{"start":15,"end":15,"text":"马太和多马，亚勒腓的儿子雅各和奋锐党的西门，"},{"start":16,"end":16,"text":"雅各的儿子犹大，和卖主的加略人犹大。"},{"start":17,"end":17,"text":"耶稣和他们下了山，站在一块平地上；同站的有许多门徒，又有许多百姓，从犹太全地和耶路撒冷，并泰尔、西顿的海边来，都要听他[讲道]，又指望医治他们的病；"},{"start":18,"end":18,"text":"还有被污鬼缠磨的，也得了医治。"},{"start":19,"end":19,"text":"众人都想要摸他；因为有能力从他身上发出来，医好了他们。"},{"start":20,"end":20,"text":"耶稣举目看着门徒，说： 你们贫穷的人有福了！ 因为　神的国是你们的。"},{"start":21,"end":21,"text":"你们饥饿的人有福了！ 因为你们将要饱足。 你们哀哭的人有福了！ 因为你们将要喜笑。"},{"start":22,"end":22,"text":"「人为人子恨恶你们，拒绝你们，辱骂你们，弃掉你们的名，以为是恶，你们就有福了！"},{"start":23,"end":23,"text":"当那日，你们要[欢喜]跳跃，因为你们在天上的赏赐是大的。他们的祖宗待先知也是这样。"},{"start":24,"end":24,"text":"但你们富足的人有祸了！ 因为你们受过你们的安慰。"},{"start":25,"end":25,"text":"你们饱足的人有祸了！ 因为你们将要饥饿。 你们喜笑的人有祸了！ 因为你们将要哀恸哭泣。"},{"start":26,"end":26,"text":"「人都说你们好的时候，你们就有祸了！因为他们的祖宗待假先知也是这样。」"},{"start":27,"end":27,"text":"「只是我告诉你们这听道的人，你们的仇敌，要爱他！恨你们的，要待他好！"},{"start":28,"end":28,"text":"咒诅你们的，要为他祝福！凌辱你们的，要为他祷告！"},{"start":29,"end":29,"text":"有人打你这边的脸，连那边的脸也由他打。有人夺你的外衣，连里衣也由他拿去。"},{"start":30,"end":30,"text":"凡求你的，就给他。有人夺你的东西去，不用再要回来。"},{"start":31,"end":31,"text":"你们愿意人怎样待你们，你们也要怎样待人。"},{"start":32,"end":32,"text":"你们若单爱那爱你们的人，有什么可酬谢的呢？就是罪人也爱那爱他们的人。"},{"start":33,"end":33,"text":"你们若善待那善待你们的人，有什么可酬谢的呢？就是罪人也是这样行。"},{"start":34,"end":34,"text":"你们若借给人，指望从他收回，有什么可酬谢的呢？就是罪人也借给罪人，要如数收回。"},{"start":35,"end":35,"text":"你们倒要爱仇敌，也要善待他们，并要借给人不指望偿还，你们的赏赐就必大了，你们也必作至高者的儿子，因为他恩待那忘恩的和作恶的。"},{"start":36,"end":36,"text":"你们要慈悲，像你们的父慈悲一样。」"},{"start":37,"end":37,"text":"「你们不要论断人，就不被论断；你们不要定人的罪，就不被定罪；你们要饶恕人，就必蒙饶恕；"},{"start":38,"end":38,"text":"你们要给人，就必有给你们的，并且用十足的升斗，连摇带按，上尖下流地倒在你们怀里；因为你们用什么量器量给人，也必用什么量器量给你们。」"},{"start":39,"end":39,"text":"耶稣又用比喻对他们说：「瞎子岂能领瞎子，两个人不是都要掉在坑里吗？"},{"start":40,"end":40,"text":"学生不能高过先生；凡学成了的不过和先生一样。"},{"start":41,"end":41,"text":"为什么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？"},{"start":42,"end":42,"text":"你不见自己眼中有梁木，怎能对你弟兄说：『容我去掉你眼中的刺』呢？你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，去掉你弟兄眼中的刺。」"},{"start":43,"end":43,"text":"「因为，没有好树结坏果子，也没有坏树结好果子。"},{"start":44,"end":44,"text":"凡树木看果子，就可以认出它来。人不是从荆棘上摘无花果，也不是从蒺藜里摘葡萄。"},{"start":45,"end":45,"text":"善人从他心里所存的善就发出善来；恶人从他[心里]所存的恶就发出恶来；因为心里所充满的，口里就说出来。」"},{"start":46,"end":46,"text":"「你们为什么称呼我『主啊，主啊』却不遵我的话行呢？"},{"start":47,"end":47,"text":"凡到我这里来，听见我的话就去行的，我要告诉你们他像什么人："},{"start":48,"end":48,"text":"他像一个人盖房子，深深地挖地，把根基安在磐石上；到发大水的时候，水冲那房子，房子总不能摇动，因为根基立在磐石上。"},{"start":49,"end":49,"text":"惟有听见不去行的，就像一个人在土地上盖房子，没有根基；水一冲，随即倒塌了，并且那房子坏的很大。」"}],"7":[{"start":1,"end":1,"text":"耶稣对百姓讲完了这一切的话，就进了迦百农。"},{"start":2,"end":2,"text":"有一个百夫长所宝贵的仆人害病，快要死了。"},{"start":3,"end":3,"text":"百夫长风闻耶稣的事，就托犹太人的几个长老去求耶稣来救他的仆人。"},{"start":4,"end":4,"text":"他们到了耶稣那里，就切切地求他说：「你给他行这事是他所配得的；"},{"start":5,"end":5,"text":"因为他爱我们的百姓，给我们建造会堂。」"},{"start":6,"end":6,"text":"耶稣就和他们同去。离那家不远，百夫长托几个朋友去见耶稣，对他说：「主啊！不要劳动；因你到我舍下，我不敢当。"},{"start":7,"end":7,"text":"我也自以为不配去见你，只要你说一句话，我的仆人就必好了。"},{"start":8,"end":8,"text":"因为我在人的权下，也有兵在我以下，对这个说：『去！』他就去；对那个说：『来！』他就来；对我的仆人说：『你做这事！』他就去做。」"},{"start":9,"end":9,"text":"耶稣听见这话，就希奇他，转身对跟随的众人说：「我告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。」"},{"start":10,"end":10,"text":"那托来的人回到百夫长家里，看见仆人已经好了。"},{"start":11,"end":11,"text":"过了不多时，耶稣往一座城去，这城名叫拿因，他的门徒和极多的人与他同行。"},{"start":12,"end":12,"text":"将近城门，有一个死人被抬出来。这人是他母亲独生的儿子；他母亲又是寡妇。有城里的许多人同着寡妇送殡。"},{"start":13,"end":13,"text":"主看见那寡妇，就怜悯她，对她说：「不要哭！」"},{"start":14,"end":14,"text":"于是进前按着杠，抬的人就站住了。耶稣说：「少年人，我吩咐你，起来！」"},{"start":15,"end":15,"text":"那死人就坐起，并且说话。耶稣便把他交给他母亲。"},{"start":16,"end":16,"text":"众人都惊奇，归荣耀与　神，说：「有大先知在我们中间兴起来了！」又说：「　神眷顾了他的百姓！」"},{"start":17,"end":17,"text":"他这事的风声就传遍了犹太和周围地方。"},{"start":18,"end":18,"text":"约翰的门徒把这些事都告诉约翰。"},{"start":19,"end":19,"text":"他便叫了两个门徒来，打发他们到主那里去，说：「那将要来的是你吗？还是我们等候别人呢？」"},{"start":20,"end":20,"text":"那两个人来到耶稣那里，说：「施洗的约翰打发我们来问你：『那将要来的是你吗？还是我们等候别人呢？』」"},{"start":21,"end":21,"text":"正当那时候，耶稣治好了许多有疾病的，受灾患的，被恶鬼附着的，又开恩叫好些瞎子能看见。"},{"start":22,"end":22,"text":"耶稣回答说：「你们去，把所看见所听见的事告诉约翰，就是瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。"},{"start":23,"end":23,"text":"凡不因我跌倒的，就有福了！」"},{"start":24,"end":24,"text":"约翰所差来的人既走了，耶稣就对众人讲论约翰说：「你们从前出去到旷野，是要看什么呢？要看风吹动的芦苇吗？"},{"start":25,"end":25,"text":"你们出去，到底是要看什么？要看穿细软衣服的人吗？那穿华丽衣服、宴乐度日的人是在王宫里。"},{"start":26,"end":26,"text":"你们出去，究竟是要看什么？要看先知吗？我告诉你们，是的，他比先知大多了。"},{"start":27,"end":27,"text":"[经上]记着说：『我要差遣我的使者在你前面预备道路』，所说的就是这个人。"},{"start":28,"end":28,"text":"我告诉你们，凡妇人所生的，没有一个大过约翰的；然而　神国里最小的比他还大。」"},{"start":29,"end":29,"text":"众百姓和税吏既受过约翰的洗，听见这话，就以　神为义；"},{"start":30,"end":30,"text":"但法利赛人和律法师没有受过约翰的洗，竟为自己废弃了　神 的旨意。"},{"start":31,"end":31,"text":"[主又说]：「这样，我可用什么比这世代的人呢？他们好像什么呢？"},{"start":32,"end":32,"text":"好像孩童坐在街市上，彼此呼叫说： 我们向你们吹笛， 你们不跳舞； 我们向你们举哀， 你们不啼哭。"},{"start":33,"end":33,"text":"施洗的约翰来，不吃饼，不喝酒，你们说他是被鬼附着的。"},{"start":34,"end":34,"text":"人子来，也吃也喝，你们说他是贪食好酒的人，是税吏和罪人的朋友。"},{"start":35,"end":35,"text":"但智慧之子都以智慧为是。」"},{"start":36,"end":36,"text":"有一个法利赛人请耶稣和他吃饭；耶稣就到法利赛人家里去坐席。"},{"start":37,"end":37,"text":"那城里有一个女人，是个罪人，知道耶稣在法利赛人家里坐席，就拿着盛香膏的玉瓶，"},{"start":38,"end":38,"text":"站在耶稣背后，挨着他的脚哭，眼泪湿了耶稣的脚，就用自己的头发擦干，又用嘴连连亲他的脚，把香膏抹上。"},{"start":39,"end":39,"text":"请耶稣的法利赛人看见这事，心里说：「这人若是先知，必知道摸他的是谁，是个怎样的女人；乃是个罪人。」"},{"start":40,"end":40,"text":"耶稣对他说：「西门！我有句话要对你说。」西门说：「夫子，请说。」"},{"start":41,"end":41,"text":"[耶稣说]：「一个债主有两个人欠他的债；一个欠五十两银子，一个欠五两银子；"},{"start":42,"end":42,"text":"因为他们无力偿还，债主就开恩免了他们两个人的债。这两个人哪一个更爱他呢？」"},{"start":43,"end":43,"text":"西门回答说：「我想是那多得恩免的人。」耶稣说：「你断的不错。」"},{"start":44,"end":44,"text":"于是转过来向着那女人，便对西门说：「你看见这女人吗？我进了你的家，你没有给我水洗脚；但这女人用眼泪湿了我的脚，用头发擦干。"},{"start":45,"end":45,"text":"你没有与我亲嘴；但这女人从我进来的时候就不住地用嘴亲我的脚。"},{"start":46,"end":46,"text":"你没有用油抹我的头；但这女人用香膏抹我的脚。"},{"start":47,"end":47,"text":"所以我告诉你，她许多的罪都赦免了，因为她的爱多；但那赦免少的，他的爱就少。」"},{"start":48,"end":48,"text":"于是对那女人说：「你的罪赦免了。」"},{"start":49,"end":49,"text":"同席的人心里说：「这是什么人，竟赦免人的罪呢？」"},{"start":50,"end":50,"text":"耶稣对那女人说：「你的信救了你；平平安安回去吧！」"}],"8":[{"start":1,"end":1,"text":"过了不多日，耶稣周游各城各乡传道，宣讲　神国的福音。和他同去的有十二个门徒，"},{"start":2,"end":2,"text":"还有被恶鬼所附、被疾病所累、已经治好的几个妇女，内中有称为抹大拉的马利亚（曾有七个鬼从她身上赶出来），"},{"start":3,"end":3,"text":"又有希律的家宰苦撒的妻子约亚拿，并苏撒拿，和好些别的妇女，都是用自己的财物供给耶稣和门徒。"},{"start":4,"end":4,"text":"当许多人聚集、又有人从各城里出来见耶稣的时候，耶稣就用比喻说："},{"start":5,"end":5,"text":"「有一个撒种的出去撒种。撒的时候，有落在路旁的，被人践踏，天上的飞鸟又来吃尽了。"},{"start":6,"end":6,"text":"有落在磐石上的，一出来就枯干了，因为得不着滋润。"},{"start":7,"end":7,"text":"有落在荆棘里的，荆棘一同生长，把它挤住了。"},{"start":8,"end":8,"text":"又有落在好土里的，生长起来，结实百倍。」耶稣说了这些话，就大声说：「有耳可听的，就应当听！」"},{"start":9,"end":9,"text":"门徒问耶稣说：「这比喻是什么意思呢？」"},{"start":10,"end":10,"text":"他说：「　神国的奥秘只叫你们知道；至于别人，就用比喻，叫他们看也看不见，听也听不明。」"},{"start":11,"end":11,"text":"「这比喻乃是这样：种子就是　神的道。"},{"start":12,"end":12,"text":"那些在路旁的，就是人听了道，随后魔鬼来，从他们心里把道夺去，恐怕他们信了得救。"},{"start":13,"end":13,"text":"那些在磐石上的，就是人听道，欢喜领受，但心中没有根，不过暂时相信，及至遇见试炼就退后了。"},{"start":14,"end":14,"text":"那落在荆棘里的，就是人听了道，走开以后，被今生的思虑、钱财、宴乐挤住了，便结不出成熟的子粒来。"},{"start":15,"end":15,"text":"[那落]在好土里的，就是人听了道，持守在诚实善良的心里，并且忍耐着结实。」"},{"start":16,"end":16,"text":"「没有人点灯用器皿盖上，或放在床底下，乃是放在灯台上，叫进来的人看见亮光。"},{"start":17,"end":17,"text":"因为掩藏的事没有不显出来的；隐瞒的事没有不露出来被人知道的。"},{"start":18,"end":18,"text":"所以，你们应当小心怎样听；因为凡有的，还要加给他；凡没有的，连他自以为有的，也要夺去。」"},{"start":19,"end":19,"text":"耶稣的母亲和他弟兄来了，因为人多，不得到他跟前。"},{"start":20,"end":20,"text":"有人告诉他说：「你母亲和你弟兄站在外边，要见你。」"},{"start":21,"end":21,"text":"耶稣回答说：「听了　神之道而遵行的人就是我的母亲，我的弟兄了。」"},{"start":22,"end":22,"text":"有一天，耶稣和门徒上了船，对门徒说：「我们可以渡到湖那边去。」他们就开了船。"},{"start":23,"end":23,"text":"正行的时候，耶稣睡着了。湖上忽然起了暴风，船将满了[水]，甚是危险。"},{"start":24,"end":24,"text":"门徒来叫醒了他，说：「夫子！夫子！我们丧命啦！」耶稣醒了，斥责那狂风大浪；风浪就止住，平静了。"},{"start":25,"end":25,"text":"耶稣对他们说：「你们的信心在哪里呢？」他们又惧怕又希奇，彼此说：「这到底是谁？他吩咐风和水，连风和水也听从他了。」"},{"start":26,"end":26,"text":"他们到了格拉森人的地方，就是加利利的对面。"},{"start":27,"end":27,"text":"耶稣上了岸，就有城里一个被鬼附着的人迎面而来。这个人许久不穿衣服，不住房子，只住在坟茔里。"},{"start":28,"end":28,"text":"他见了耶稣，就俯伏在他面前，大声喊叫，说：「至高　神的儿子耶稣，我与你有什么相干？求你不要叫我受苦！」"},{"start":29,"end":29,"text":"是因耶稣曾吩咐污鬼从那人身上出来。原来这鬼屡次抓住他；他常被人看守，又被铁链和脚镣捆锁，他竟把锁链挣断，被鬼赶到旷野去。"},{"start":30,"end":30,"text":"耶稣问他说：「你名叫什么？」他说：「我名叫『群』」；这是因为附着他的鬼多。"},{"start":31,"end":31,"text":"鬼就央求耶稣，不要吩咐他们到无底坑里去。"},{"start":32,"end":32,"text":"那里有一大群猪在山上吃食。鬼央求耶稣，准他们进入猪里去。耶稣准了他们，"},{"start":33,"end":33,"text":"鬼就从那人出来，进入猪里去。于是那群猪闯下山崖，投在湖里淹死了。"},{"start":34,"end":34,"text":"放猪的看见这事就逃跑了，去告诉城里和乡下的人。"},{"start":35,"end":35,"text":"众人出来要看是什么事；到了耶稣那里，看见鬼所离开的那人，坐在耶稣脚前，穿着衣服，心里明白过来，他们就害怕。"},{"start":36,"end":36,"text":"看见这事的便将被鬼附着的人怎么得救告诉他们。"},{"start":37,"end":37,"text":"格拉森四围的人，因为害怕得很，都求耶稣离开他们；耶稣就上船回去了。"},{"start":38,"end":38,"text":"鬼所离开的那人恳求和耶稣同在；耶稣却打发他回去，说："},{"start":39,"end":39,"text":"「你回家去，传说　神为你做了何等大的事。」他就去，满城里传扬耶稣为他做了何等大的事。"},{"start":40,"end":40,"text":"耶稣回来的时候，众人迎接他，因为他们都等候他。"},{"start":41,"end":41,"text":"有一个管会堂的，名叫睚鲁，来俯伏在耶稣脚前，求耶稣到他家里去；"},{"start":42,"end":42,"text":"因他有一个独生女儿，约有十二岁，快要死了。 耶稣去的时候，众人拥挤他。"},{"start":43,"end":43,"text":"有一个女人，患了十二年的血漏，在医生手里花尽了她一切养生的，并没有一人能医好她。"},{"start":44,"end":44,"text":"她来到耶稣背后，摸他的衣裳 子，血漏立刻就止住了。"},{"start":45,"end":45,"text":"耶稣说：「摸我的是谁？」众人都不承认。彼得和同行的人都说：「夫子，众人拥拥挤挤紧靠着你。」"},{"start":46,"end":46,"text":"耶稣说：「总有人摸我，因我觉得有能力从我身上出去。」"},{"start":47,"end":47,"text":"那女人知道不能隐藏，就战战兢兢地来俯伏在耶稣脚前，把摸他的缘故和怎样立刻得好了，当着众人都说出来。"},{"start":48,"end":48,"text":"耶稣对她说：「女儿，你的信救了你；平平安安地去吧！」"},{"start":49,"end":49,"text":"还说话的时候，有人从管会堂的家里来，说：「你的女儿死了，不要劳动夫子。」"},{"start":50,"end":50,"text":"耶稣听见就对他说：「不要怕，只要信！你的女儿就必得救。」"},{"start":51,"end":51,"text":"耶稣到了他的家，除了彼得、约翰、雅各，和女儿的父母，不许别人同他进去。"},{"start":52,"end":52,"text":"众人都为这女儿哀哭捶胸。耶稣说：「不要哭！她不是死了，是睡着了。」"},{"start":53,"end":53,"text":"他们晓得女儿已经死了，就嗤笑耶稣。"},{"start":54,"end":54,"text":"耶稣拉着她的手，呼叫说：「女儿，起来吧！」"},{"start":55,"end":55,"text":"她的灵魂便回来，她就立刻起来了。耶稣吩咐给她东西吃。"},{"start":56,"end":56,"text":"她的父母惊奇得很；耶稣嘱咐他们，不要把所做的事告诉人。"}],"9":[{"start":1,"end":1,"text":"耶稣叫齐了十二个门徒，给他们能力、权柄，制伏一切的鬼，医治各样的病，"},{"start":2,"end":2,"text":"又差遣他们去宣传　神国[的道]，医治病人，"},{"start":3,"end":3,"text":"对他们说：「行路的时候，不要带拐杖和口袋，不要带食物和银子，也不要带两件褂子。"},{"start":4,"end":4,"text":"无论进哪一家，就住在那里，也从那里起行。"},{"start":5,"end":5,"text":"凡不接待你们的，你们离开那城的时候，要把脚上的尘土跺下去，见证他们的不是。」"},{"start":6,"end":6,"text":"门徒就出去，走遍各乡宣传福音，到处治病。"},{"start":7,"end":7,"text":"分封的王希律听见耶稣所做的一切事，就游移不定；因为有人说：「是约翰从死里复活」；"},{"start":8,"end":8,"text":"又有人说：「是以利亚显现」；还有人说：「是古时的一个先知又活了。」"},{"start":9,"end":9,"text":"希律说：「约翰我已经斩了，这却是什么人？我竟听见他这样的事呢？」就想要见他。"},{"start":10,"end":10,"text":"使徒回来，将所做的事告诉耶稣，耶稣就带他们暗暗地离开那里，往一座城去；那城名叫伯赛大。"},{"start":11,"end":11,"text":"但众人知道了，就跟着他去；耶稣便接待他们，对他们讲论　神国[的道]，医治那些需医的人。"},{"start":12,"end":12,"text":"日头快要平西，十二个门徒来对他说：「请叫众人散开，他们好往四面乡村里去借宿找吃的，因为我们这里是野地。」"},{"start":13,"end":13,"text":"耶稣说：「你们给他们吃吧！」门徒说：「我们不过有五个饼，两条鱼，若不去为这许多人买食物就不够。」"},{"start":14,"end":14,"text":"那时，人数约有五千。耶稣对门徒说：「叫他们一排一排地坐下，每排大约五十个人。」"},{"start":15,"end":15,"text":"门徒就如此行，叫众人都坐下。"},{"start":16,"end":16,"text":"耶稣拿着这五个饼，两条鱼，望着天祝福，擘开，递给门徒，摆在众人面前。"},{"start":17,"end":17,"text":"他们就吃，并且都吃饱了；把剩下的零碎收拾起来，装满了十二篮子。"},{"start":18,"end":18,"text":"耶稣自己祷告的时候，门徒也同他在那里。耶稣问他们说：「众人说我是谁？」"},{"start":19,"end":19,"text":"他们说：「有人说是施洗的约翰；有人说是以利亚；还有人说是古时的一个先知又活了。」"},{"start":20,"end":20,"text":"耶稣说：「你们说我是谁？」彼得回答说：「是　神所立的基督。」"},{"start":21,"end":21,"text":"耶稣切切地嘱咐他们，不可将这事告诉人，"},{"start":22,"end":22,"text":"又说：「人子必须受许多的苦，被长老、祭司长，和文士弃绝，并且被杀，第三日复活。」"},{"start":23,"end":23,"text":"耶稣又对众人说：「若有人要跟从我，就当舍己，天天背起他的十字架来跟从我。"},{"start":24,"end":24,"text":"因为，凡要救自己生命的，必丧掉生命；凡为我丧掉生命的，必救了生命。"},{"start":25,"end":25,"text":"人若赚得全世界，却丧了自己，赔上自己，有什么益处呢？"},{"start":26,"end":26,"text":"凡把我和我的道当作可耻的，人子在自己的荣耀里，并天父与圣天使的荣耀里降临的时候，也要把那人当作可耻的。"},{"start":27,"end":27,"text":"我实在告诉你们，站在这里的，有人在没尝死味以前，必看见　神的国。」"},{"start":28,"end":28,"text":"说了这话以后约有八天，耶稣带着彼得、约翰、雅各上山去祷告。"},{"start":29,"end":29,"text":"正祷告的时候，他的面貌就改变了，衣服洁白放光。"},{"start":30,"end":30,"text":"忽然有摩西、以利亚两个人同耶稣说话；"},{"start":31,"end":31,"text":"他们在荣光里显现，谈论耶稣去世的事，就是他在耶路撒冷将要成的事。"},{"start":32,"end":32,"text":"彼得和他的同伴都打盹，既清醒了，就看见耶稣的荣光，并同他站着的那两个人。"},{"start":33,"end":33,"text":"二人正要和耶稣分离的时候，彼得对耶稣说：「夫子，我们在这里真好！可以搭三座棚，一座为你，一座为摩西，一座为以利亚。」他却不知道所说的是什么。"},{"start":34,"end":34,"text":"说这话的时候，有一朵云彩来遮盖他们；他们进入云彩里就惧怕。"},{"start":35,"end":35,"text":"有声音从云彩里出来，说：「这是我的儿子，我所拣选的，你们要听他。」"},{"start":36,"end":36,"text":"声音住了，只见耶稣一人在那里。当那些日子，门徒不提所看见的事，一样也不告诉人。"},{"start":37,"end":37,"text":"第二天，他们下了山，就有许多人迎见耶稣。"},{"start":38,"end":38,"text":"其中有一人喊叫说：「夫子！求你看顾我的儿子，因为他是我的独生子。"},{"start":39,"end":39,"text":"他被鬼抓住就忽然喊叫；鬼又叫他抽风，口中流沫，并且重重地伤害他，难以离开他。"},{"start":40,"end":40,"text":"我求过你的门徒，把鬼赶出去，他们却是不能。」"},{"start":41,"end":41,"text":"耶稣说：「嗳！这又不信又悖谬的世代啊，我在你们这里，忍耐你们要到几时呢？将你的儿子带到这里来吧！」"},{"start":42,"end":42,"text":"正来的时候，鬼把他摔倒，叫他重重地抽风。耶稣就斥责那污鬼，把孩子治好了，交给他父亲。"},{"start":43,"end":43,"text":"众人都诧异　神的大能。 耶稣所做的一切事，众人正希奇的时候，耶稣对门徒说："},{"start":44,"end":44,"text":"「你们要把这些话存在耳中，因为人子将要被交在人手里。」"},{"start":45,"end":45,"text":"他们不明白这话，意思乃是隐藏的，叫他们不能明白，他们也不敢问这话的意思。"},{"start":46,"end":46,"text":"门徒中间起了议论，谁将为大。"},{"start":47,"end":47,"text":"耶稣看出他们心中的议论，就领一个小孩子来，叫他站在自己旁边，"},{"start":48,"end":48,"text":"对他们说：「凡为我名接待这小孩子的，就是接待我；凡接待我的，就是接待那差我来的。你们中间最小的，他便为大。」"},{"start":49,"end":49,"text":"约翰说：「夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不与我们一同跟从[你]。」"},{"start":50,"end":50,"text":"耶稣说：「不要禁止他；因为不敌挡你们的，就是帮助你们的。」"},{"start":51,"end":51,"text":"耶稣被接上升的日子将到，他就定意向耶路撒冷去，"},{"start":52,"end":52,"text":"便打发使者在他前头走。他们到了撒马利亚的一个村庄，要为他预备。"},{"start":53,"end":53,"text":"那里的人不接待他，因他面向耶路撒冷去。"},{"start":54,"end":54,"text":"他的门徒雅各、约翰看见了，就说：「主啊，你要我们吩咐火从天上降下来烧灭他们，像以利亚所做的吗？」"},{"start":55,"end":55,"text":"耶稣转身责备两个门徒，说：「你们的心如何，你们并不知道。"},{"start":56,"end":56,"text":"人子来不是要灭人的性命，是要救人的性命。」说着就往别的村庄去了。"},{"start":57,"end":57,"text":"他们走路的时候，有一人对耶稣说：「你无论往哪里去，我要跟从你。」"},{"start":58,"end":58,"text":"耶稣说：「狐狸有洞，天空的飞鸟有窝，只是人子没有枕头的地方。」"},{"start":59,"end":59,"text":"又对一个人说：「跟从我来！」那人说：「主，容我先回去埋葬我的父亲。」"},{"start":60,"end":60,"text":"耶稣说：「任凭死人埋葬他们的死人，你只管去传扬　神国[的道]。」"},{"start":61,"end":61,"text":"又有一人说：「主，我要跟从你，但容我先去辞别我家里的人。」"},{"start":62,"end":62,"text":"耶稣说：「手扶着犁向后看的，不配进　神的国。」"}],"10":[{"start":1,"end":1,"text":"这事以后，主又设立七十个人，差遣他们两个两个地在他前面，往自己所要到的各城各地方去，"},{"start":2,"end":2,"text":"就对他们说：「要收的庄稼多，做工的人少。所以，你们当求庄稼的主打发工人出去收他的庄稼。"},{"start":3,"end":3,"text":"你们去吧！我差你们出去，如同羊羔进入狼群。"},{"start":4,"end":4,"text":"不要带钱囊，不要带口袋，不要带鞋；在路上也不要问人的安。"},{"start":5,"end":5,"text":"无论进哪一家，先要说：『愿这一家平安。』"},{"start":6,"end":6,"text":"那里若有当得平安的人，你们所求的平安就必临到那家；不然，就归与你们了。"},{"start":7,"end":7,"text":"你们要住在那家，吃喝他们所供给的，因为工人得工价是应当的；不要从这家搬到那家。"},{"start":8,"end":8,"text":"无论进哪一城，人若接待你们，给你们摆上什么，你们就吃什么。"},{"start":9,"end":9,"text":"要医治那城里的病人，对他们说：『　神的国临近你们了。』"},{"start":10,"end":10,"text":"无论进哪一城，人若不接待你们，你们就到街上去，"},{"start":11,"end":11,"text":"说：『就是你们城里的尘土黏在我们的脚上，我们也当着你们擦去。虽然如此，你们该知道　神的国临近了。』"},{"start":12,"end":12,"text":"我告诉你们，当审判的日子，所多玛所受的，比那城还容易受呢！」"},{"start":13,"end":13,"text":"「哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能若行在泰尔、西顿，他们早已披麻蒙灰，坐在地上悔改了。"},{"start":14,"end":14,"text":"当审判的日子，泰尔、西顿所受的，比你们还容易受呢！"},{"start":15,"end":15,"text":"迦百农啊，你已经升到天上，将来必推下阴间。」"},{"start":16,"end":16,"text":"[又对门徒说]：「听从你们的就是听从我；弃绝你们的就是弃绝我；弃绝我的就是弃绝那差我来的。」"},{"start":17,"end":17,"text":"那七十个人欢欢喜喜地回来，说：「主啊！因你的名，就是鬼也服了我们。」"},{"start":18,"end":18,"text":"耶稣对他们说：「我曾看见撒但从天上坠落，像闪电一样。"},{"start":19,"end":19,"text":"我已经给你们权柄可以践踏蛇和蝎子，又胜过仇敌一切的能力，断没有什么能害你们。"},{"start":20,"end":20,"text":"然而，不要因鬼服了你们就欢喜，要因你们的名记录在天上欢喜。」"},{"start":21,"end":21,"text":"正当那时，耶稣被圣灵感动就欢乐，说：「父啊，天地的主，我感谢你！因为你将这些事向聪明通达人就藏起来，向婴孩就显出来。父啊！是的，因为你的美意本是如此。"},{"start":22,"end":22,"text":"一切所有的都是我父交付我的；除了父，没有人知道子是谁；除了子和子所愿意指示的，没有人知道父是谁。」"},{"start":23,"end":23,"text":"耶稣转身暗暗地对门徒说：「看见你们所看见的，那眼睛就有福了。"},{"start":24,"end":24,"text":"我告诉你们，从前有许多先知和君王要看你们所看的，却没有看见，要听你们所听的，却没有听见。」"},{"start":25,"end":25,"text":"有一个律法师起来试探耶稣， 说：「夫子！我该做什么才可以承受永生？」"},{"start":26,"end":26,"text":"耶稣对他说：「律法上写的是什么？你念的是怎样呢？」"},{"start":27,"end":27,"text":"他回答说：「你要尽心、尽性、尽力、尽意爱主—你的　神；又要爱邻舍如同自己。」"},{"start":28,"end":28,"text":"耶稣说：「你回答的是；你这样行，就必得[永]生。」"},{"start":29,"end":29,"text":"那人要显明自己有理，就对耶稣说：「谁是我的邻舍呢？」"},{"start":30,"end":30,"text":"耶稣回答说：「有一个人从耶路撒冷下耶利哥去，落在强盗手中。他们剥去他的衣裳，把他打个半死，就丢下他走了。"},{"start":31,"end":31,"text":"偶然有一个祭司从这条路下来，看见他就从那边过去了。"},{"start":32,"end":32,"text":"又有一个利未人来到这地方，看见他，也照样从那边过去了。"},{"start":33,"end":33,"text":"惟有一个撒马利亚人行路来到那里，看见他就动了慈心，"},{"start":34,"end":34,"text":"上前用油和酒倒在他的伤处，包裹好了，扶他骑上自己的牲口，带到店里去照应他。"},{"start":35,"end":35,"text":"第二天拿出二钱银子来，交给店主，说：『你且照应他；此外所费用的，我回来必还你。』"},{"start":36,"end":36,"text":"你想，这三个人哪一个是落在强盗手中的邻舍呢？」"},{"start":37,"end":37,"text":"他说：「是怜悯他的。」耶稣说：「你去照样行吧。」"},{"start":38,"end":38,"text":"他们走路的时候，耶稣进了一个村庄。有一个女人，名叫马大，接他到自己家里。"},{"start":39,"end":39,"text":"她有一个妹子，名叫马利亚，在耶稣脚前坐着听他的道。"},{"start":40,"end":40,"text":"马大伺候的事多，心里忙乱，就进前来，说：「主啊，我的妹子留下我一个人伺候，你不在意吗？请吩咐她来帮助我。」"},{"start":41,"end":41,"text":"耶稣回答说：「马大！马大！你为许多的事思虑烦扰，"},{"start":42,"end":42,"text":"但是不可少的只有一件；马利亚已经选择那上好的福分，是不能夺去的。」"}],"11":[{"start":1,"end":1,"text":"耶稣在一个地方祷告；祷告完了，有个门徒对他说：「求主教导我们祷告，像约翰教导他的门徒。」"},{"start":2,"end":2,"text":"耶稣说：「你们祷告的时候，要说： 我们在天上的父： 愿人都尊你的名为圣。 愿你的国降临； 愿你的旨意行在地上， 如同行在天上。"},{"start":3,"end":3,"text":"我们日用的饮食， 天天赐给我们。"},{"start":4,"end":4,"text":"赦免我们的罪， 因为我们也赦免凡亏欠我们的人。 不叫我们遇见试探； 救我们脱离凶恶。」"},{"start":5,"end":5,"text":"耶稣又说：「你们中间谁有一个朋友半夜到他那里去，说：『朋友！请借给我三个饼；"},{"start":6,"end":6,"text":"因为我有一个朋友行路，来到我这里，我没有什么给他摆上。』"},{"start":7,"end":7,"text":"那人在里面回答说：『不要搅扰我，门已经关闭，孩子们也同我在床上了，我不能起来给你。』"},{"start":8,"end":8,"text":"我告诉你们，虽不因他是朋友起来给他，但因他情词迫切地直求，就必起来照他所需用的给他。"},{"start":9,"end":9,"text":"我又告诉你们，你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。"},{"start":10,"end":10,"text":"因为，凡祈求的，就得着；寻找的，就寻见；叩门的，就给他开门。"},{"start":11,"end":11,"text":"你们中间作父亲的，谁有儿子求饼，反给他石头呢？求鱼，反拿蛇当鱼给他呢？"},{"start":12,"end":12,"text":"求[鸡]蛋，反给他蝎子呢？"},{"start":13,"end":13,"text":"你们虽然不好，尚且知道拿好东西给儿女；何况天父，岂不更将圣灵给求他的人吗？」"},{"start":14,"end":14,"text":"耶稣赶出一个叫人哑巴的鬼；鬼出去了，哑巴就说出话来；众人都希奇。"},{"start":15,"end":15,"text":"内中却有人说：「他是靠着鬼王别西卜赶鬼。」"},{"start":16,"end":16,"text":"又有人试探耶稣，向他求从天上来的神迹。"},{"start":17,"end":17,"text":"他晓得他们的意念，便对他们说：「凡一国自相纷争，就成为荒场；凡一家自相纷争，就必败落。"},{"start":18,"end":18,"text":"若撒但自相纷争，他的国怎能站得住呢？因为你们说我是靠着别西卜赶鬼。"},{"start":19,"end":19,"text":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们就要断定你们的是非。"},{"start":20,"end":20,"text":"我若靠着　神的能力赶鬼，这就是　神的国临到你们了。"},{"start":21,"end":21,"text":"壮士披挂整齐，看守自己的住宅，他所有的都平安无事；"},{"start":22,"end":22,"text":"但有一个比他更壮的来，胜过他，就夺去他所倚靠的盔甲兵器，又分了他的赃。"},{"start":23,"end":23,"text":"不与我相合的，就是敌我的；不同我收聚的，就是分散的。」"},{"start":24,"end":24,"text":"「污鬼离了人身，就在无水之地过来过去，寻求安歇[之处]；既寻不着，便说：『我要回到我所出来的屋里去。』"},{"start":25,"end":25,"text":"到了，就看见[里面]打扫干净，修饰好了，"},{"start":26,"end":26,"text":"便去另带了七个比自己更恶的鬼来，都进去住在那里。那人末后的景况比先前更不好了。」"},{"start":27,"end":27,"text":"耶稣正说这话的时候，众人中间有一个女人大声说：「怀你胎的和乳养你的有福了！」"},{"start":28,"end":28,"text":"耶稣说：「是，却还不如听　神之道而遵守的人有福。」"},{"start":29,"end":29,"text":"当众人聚集的时候，耶稣开讲说：「这世代是一个邪恶的世代。他们求看神迹，除了约拿的神迹以外，再没有神迹给他们看。"},{"start":30,"end":30,"text":"约拿怎样为尼尼微人成了神迹，人子也要照样为这世代的人成了神迹。"},{"start":31,"end":31,"text":"当审判的时候，南方的女王要起来定这世代的罪；因为她从地极而来，要听所罗门的智慧话。看哪，在这里有一人比所罗门更大。"},{"start":32,"end":32,"text":"当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，在这里有一人比约拿更大。」"},{"start":33,"end":33,"text":"「没有人点灯放在地窨子里，或是斗底下，总是放在灯台上，使进来的人得见亮光。"},{"start":34,"end":34,"text":"你眼睛就是身上的灯。你的眼睛若了亮，全身就光明；眼睛若昏花，全身就黑暗。"},{"start":35,"end":35,"text":"所以，你要省察，恐怕你里头的光或者黑暗了。"},{"start":36,"end":36,"text":"若是你全身光明，毫无黑暗，就必全然光明，如同灯的明光照亮你。」"},{"start":37,"end":37,"text":"说话的时候，有一个法利赛人请耶稣同他吃饭，耶稣就进去坐席。"},{"start":38,"end":38,"text":"这法利赛人看见耶稣饭前不洗[手]便诧异。"},{"start":39,"end":39,"text":"主对他说：「如今你们法利赛人洗净杯盘的外面，你们里面却满了勒索和邪恶。"},{"start":40,"end":40,"text":"无知的人哪，造外面的，不也造里面吗？"},{"start":41,"end":41,"text":"只要把里面的施舍给人，凡物于你们就都洁净了。"},{"start":42,"end":42,"text":"「你们法利赛人有祸了！因为你们将薄荷、芸香并各样菜蔬献上十分之一，那公义和爱　神的事反倒不行了。这原是你们当行的；那也是不可不行的。"},{"start":43,"end":43,"text":"你们法利赛人有祸了！因为你们喜爱会堂里的首位，又喜爱人在街市上问你们的安。"},{"start":44,"end":44,"text":"你们有祸了！因为你们如同不显露的坟墓，走在上面的人并不知道。」"},{"start":45,"end":45,"text":"律法师中有一个回答耶稣说：「夫子！你这样说也把我们糟蹋了。」"},{"start":46,"end":46,"text":"耶稣说：「你们律法师也有祸了！因为你们把难担的担子放在人身上，自己一个指头却不肯动。"},{"start":47,"end":47,"text":"你们有祸了！因为你们修造先知的坟墓，那先知正是你们的祖宗所杀的。"},{"start":48,"end":48,"text":"可见你们祖宗所做的事，你们又证明又喜欢；因为他们杀了先知，你们修造[先知的坟墓]。"},{"start":49,"end":49,"text":"所以　神用智慧曾说：『我要差遣先知和使徒到他们那里去，有的他们要杀害，有的他们要逼迫』，"},{"start":50,"end":50,"text":"使创世以来所流众先知血的罪都要问在这世代的人身上，"},{"start":51,"end":51,"text":"就是从亚伯的血起，直到被杀在坛和殿中间撒迦利亚的血为止。我实在告诉你们，这都要问在这世代的人身上。"},{"start":52,"end":52,"text":"你们律法师有祸了！因为你们把知识的钥匙夺了去，自己不进去，正要进去的人你们也阻挡他们。」"},{"start":53,"end":53,"text":"耶稣从那里出来，文士和法利赛人就极力地催逼他，引动他多说话，"},{"start":54,"end":54,"text":"私下窥听，要拿他的话柄。"}],"12":[{"start":1,"end":1,"text":"这时，有几万人聚集，甚至彼此践踏。耶稣开讲，先对门徒说：「你们要防备法利赛人的酵，就是假冒为善。"},{"start":2,"end":2,"text":"掩盖的事没有不露出来的；隐藏的事没有不被人知道的。"},{"start":3,"end":3,"text":"因此，你们在暗中所说的，将要在明处被人听见；在内室附耳所说的，将要在房上被人宣扬。」"},{"start":4,"end":4,"text":"「我的朋友，我对你们说，那杀身体以后不能再做什么的，不要怕他们。"},{"start":5,"end":5,"text":"我要指示你们当怕的是谁：当怕那杀了以后又有权柄丢在地狱里的。我实在告诉你们，正要怕他。"},{"start":6,"end":6,"text":"五个麻雀不是卖二分银子吗？但在　神面前，一个也不忘记；"},{"start":7,"end":7,"text":"就是你们的头发，也都被数过了。不要惧怕，你们比许多麻雀还贵重！」"},{"start":8,"end":8,"text":"「我又告诉你们，凡在人面前认我的，人子在　神的使者面前也必认他；"},{"start":9,"end":9,"text":"在人面前不认我的，人子在　神的使者面前也必不认他。"},{"start":10,"end":10,"text":"凡说话干犯人子的，还可得赦免；惟独亵渎圣灵的，总不得赦免。"},{"start":11,"end":11,"text":"人带你们到会堂，并官府和有权柄的人面前，不要思虑怎么分诉，说什么话；"},{"start":12,"end":12,"text":"因为正在那时候，圣灵要指教你们当说的话。」"},{"start":13,"end":13,"text":"众人中有一个人对耶稣说：「夫子！请你吩咐我的兄长和我分开家业。」"},{"start":14,"end":14,"text":"耶稣说：「你这个人！谁立我作你们断事的官，给你们分家业呢？」"},{"start":15,"end":15,"text":"于是对众人说：「你们要谨慎自守，免去一切的贪心，因为人的生命不在乎家道丰富。」"},{"start":16,"end":16,"text":"就用比喻对他们说：「有一个财主田产丰盛；"},{"start":17,"end":17,"text":"自己心里思想说：『我的出产没有地方收藏，怎么办呢？』"},{"start":18,"end":18,"text":"又说：『我要这么办：要把我的仓房拆了，另盖更大的，在那里好收藏我一切的粮食和财物，"},{"start":19,"end":19,"text":"然后要对我的灵魂说：灵魂哪，你有许多财物积存，可作多年的费用，只管安安逸逸地吃喝快乐吧！』"},{"start":20,"end":20,"text":"神却对他说：『无知的人哪，今夜必要你的灵魂；你所预备的要归谁呢？』"},{"start":21,"end":21,"text":"凡为自己积财，在　神面前却不富足的，也是这样。」"},{"start":22,"end":22,"text":"耶稣又对门徒说：「所以我告诉你们，不要为生命忧虑吃什么，为身体忧虑穿什么；"},{"start":23,"end":23,"text":"因为生命胜于饮食，身体胜于衣裳。"},{"start":24,"end":24,"text":"你想乌鸦，也不种也不收，又没有仓又没有库，　神尚且养活它。你们比飞鸟是何等地贵重呢！"},{"start":25,"end":25,"text":"你们哪一个能用思虑使寿数多加一刻呢？"},{"start":26,"end":26,"text":"这最小的事，你们尚且不能做，为什么还忧虑其余的事呢？"},{"start":27,"end":27,"text":"你想百合花怎么长起来；它也不劳苦，也不纺线。然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！"},{"start":28,"end":28,"text":"你们这小信的人哪，野地里的草今天还在，明天就丢在炉里，　神还给它这样的妆饰，何况你们呢！"},{"start":29,"end":29,"text":"你们不要求吃什么，喝什么，也不要挂心；"},{"start":30,"end":30,"text":"这都是外邦人所求的。你们必须用这些东西，你们的父是知道的。"},{"start":31,"end":31,"text":"你们只要求他的国，这些东西就必加给你们了。"},{"start":32,"end":32,"text":"你们这小群，不要惧怕，因为你们的父乐意把国赐给你们。"},{"start":33,"end":33,"text":"你们要变卖所有的周济人，为自己预备永不坏的钱囊，用不尽的财宝在天上，就是贼不能近、虫不能蛀的地方。"},{"start":34,"end":34,"text":"因为，你们的财宝在哪里，你们的心也在那里。」"},{"start":35,"end":35,"text":"「你们腰里要束上带，灯也要点着，"},{"start":36,"end":36,"text":"自己好像[仆]人等候主人从婚姻的筵席上回来。他来到，叩门，就立刻给他开门。"},{"start":37,"end":37,"text":"主人来了，看见仆人警醒，那仆人就有福了。我实在告诉你们，主人必叫他们坐席，自己束上带，进前伺候他们。"},{"start":38,"end":38,"text":"或是二更天来，或是三更天来，看见仆人这样，那仆人就有福了。"},{"start":39,"end":39,"text":"家主若知道贼什么时候来，就必警醒，不容贼挖透房屋，这是你们所知道的。"},{"start":40,"end":40,"text":"你们也要预备；因为你们想不到的时候，人子就来了。」"},{"start":41,"end":41,"text":"彼得说：「主啊，这比喻是为我们说的呢？还是为众人呢？」"},{"start":42,"end":42,"text":"主说：「谁是那忠心有见识的管家，主人派他管理家里的人，按时分粮给他们呢？"},{"start":43,"end":43,"text":"主人来到，看见仆人这样行，那仆人就有福了。"},{"start":44,"end":44,"text":"我实在告诉你们，主人要派他管理一切所有的。"},{"start":45,"end":45,"text":"那仆人若心里说：『我的主人必来得迟』，就动手打仆人和使女，并且吃喝醉酒；"},{"start":46,"end":46,"text":"在他想不到的日子，不知道的时辰，那仆人的主人要来，重重地处治他，定他和不忠心的人同罪。"},{"start":47,"end":47,"text":"仆人知道主人的意思，却不预备，又不顺他的意思行，那仆人必多受责打；"},{"start":48,"end":48,"text":"惟有那不知道的，做了当受责打的事，必少受责打；因为多给谁，就向谁多取；多托谁，就向谁多要。」"},{"start":49,"end":49,"text":"「我来要把火丢在地上，倘若已经着起来，不也是我所愿意的吗？"},{"start":50,"end":50,"text":"我有当受的洗还没有成就，我是何等地迫切呢？"},{"start":51,"end":51,"text":"你们以为我来，是叫地上太平吗？我告诉你们，不是，乃是叫人纷争。"},{"start":52,"end":52,"text":"从今以后，一家五个人将要纷争：三个人和两个人相争，两个人和三个人相争；"},{"start":53,"end":53,"text":"父亲和儿子相争， 儿子和父亲相争； 母亲和女儿相争， 女儿和母亲相争； 婆婆和媳妇相争， 媳妇和婆婆相争。」"},{"start":54,"end":54,"text":"耶稣又对众人说：「你们看见西边起了云彩，就说：『要下一阵雨』；果然就有。"},{"start":55,"end":55,"text":"起了南风，就说：『将要燥热』；也就有了。"},{"start":56,"end":56,"text":"假冒为善的人哪，你们知道分辨天地的气色，怎么不知道分辨这时候呢？」"},{"start":57,"end":57,"text":"「你们又为何不自己审量什么是合理的呢？"},{"start":58,"end":58,"text":"你同[告]你的对头去见官，还在路上，务要尽力地和他了结；恐怕他拉你到官面前，官交付差役，差役把你下在监里。"},{"start":59,"end":59,"text":"我告诉你，若有半文钱没有还清，你断不能从那里出来。」"}],"13":[{"start":1,"end":1,"text":"正当那时，有人将彼拉多使加利利人的血搀杂在他们祭物中的事告诉耶稣。"},{"start":2,"end":2,"text":"耶稣说：「你们以为这些加利利人比众加利利人更有罪，所以受这害吗？"},{"start":3,"end":3,"text":"我告诉你们，不是的！你们若不悔改，都要如此灭亡！"},{"start":4,"end":4,"text":"从前西罗亚楼倒塌了，压死十八个人；你们以为那些人比一切住在耶路撒冷的人更有罪吗？"},{"start":5,"end":5,"text":"我告诉你们，不是的！你们若不悔改，都要如此灭亡！」"},{"start":6,"end":6,"text":"于是用比喻说：「一个人有一棵无花果树栽在葡萄园里。他来到树前找果子，却找不着。"},{"start":7,"end":7,"text":"就对管园的说：『看哪，我这三年来到这无花果树前找果子，竟找不着。把它砍了吧，何必白占地土呢！』"},{"start":8,"end":8,"text":"管园的说：『主啊，今年且留着，等我周围掘开土，加上粪；"},{"start":9,"end":9,"text":"以后若结果子便罢，不然再把它砍了。』」"},{"start":10,"end":10,"text":"安息日，耶稣在会堂里教训人。"},{"start":11,"end":11,"text":"有一个女人被鬼附着，病了十八年，腰弯得一点直不起来。"},{"start":12,"end":12,"text":"耶稣看见，便叫过她来，对她说：「女人，你脱离这病了！」"},{"start":13,"end":13,"text":"于是用两只手按着她；她立刻直起腰来，就归荣耀与　神。"},{"start":14,"end":14,"text":"管会堂的因为耶稣在安息日治病，就气忿忿地对众人说：「有六日应当做工；那六日之内可以来求医，在安息日却不可。」"},{"start":15,"end":15,"text":"主说：「假冒为善的人哪，难道你们各人在安息日不解开槽上的牛、驴，牵去饮吗？"},{"start":16,"end":16,"text":"况且这女人本是亚伯拉罕的后裔，被撒但捆绑了这十八年，不当在安息日解开她的绑吗？」"},{"start":17,"end":17,"text":"耶稣说这话，他的敌人都惭愧了；众人因他所行一切荣耀的事，就都欢喜了。"},{"start":18,"end":18,"text":"耶稣说：「　神的国好像什么？我拿什么来比较呢？"},{"start":19,"end":19,"text":"好像一粒芥菜种，有人拿去种在园子里，长大成树，天上的飞鸟宿在它的枝上。」"},{"start":20,"end":20,"text":"又说：「我拿什么来比　神的国呢？"},{"start":21,"end":21,"text":"好比面酵，有妇人拿来藏在三斗面里，直等全团都发起来。」"},{"start":22,"end":22,"text":"耶稣往耶路撒冷去，在所经过的各城各乡教训人。"},{"start":23,"end":23,"text":"有一个人问他说：「主啊，得救的人少吗？」"},{"start":24,"end":24,"text":"耶稣对众人说：「你们要努力进窄门。我告诉你们，将来有许多人想要进去，却是不能。"},{"start":25,"end":25,"text":"及至家主起来关了门，你们站在外面叩门，说：『主啊，给我们开门！』他就回答说：『我不认识你们，不晓得你们是哪里来的！』"},{"start":26,"end":26,"text":"那时，你们要说：『我们在你面前吃过喝过，你也在我们的街上教训过人。』"},{"start":27,"end":27,"text":"他要说：『我告诉你们，我不晓得你们是哪里来的。你们这一切作恶的人，离开我去吧！』"},{"start":28,"end":28,"text":"你们要看见亚伯拉罕、以撒、雅各，和众先知都在　神的国里，你们却被赶到外面，在那里必要哀哭切齿了。"},{"start":29,"end":29,"text":"从东、从西、从南、从北将有人来，在　神的国里坐席。"},{"start":30,"end":30,"text":"只是有在后的，将要在前；有在前的，将要在后。」"},{"start":31,"end":31,"text":"正当那时，有几个法利赛人来对耶稣说：「离开这里去吧，因为希律想要杀你。」"},{"start":32,"end":32,"text":"耶稣说：「你们去告诉那个狐狸说：『今天、明天我赶鬼治病，第三天我的事就成全了。』"},{"start":33,"end":33,"text":"虽然这样，今天、明天、后天，我必须前行，因为先知在耶路撒冷之外丧命是不能的。"},{"start":34,"end":34,"text":"耶路撒冷啊！耶路撒冷啊！你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下；只是你们不愿意。"},{"start":35,"end":35,"text":"看哪，你们的家成为荒场留给你们。我告诉你们，[从今以后]你们不得再见我，直等到你们说：『奉主名来的是应当称颂的。』」"}],"14":[{"start":1,"end":1,"text":"安息日，耶稣到一个法利赛人的首领家里去吃饭，他们就窥探他。"},{"start":2,"end":2,"text":"在他面前有一个患水臌的人。"},{"start":3,"end":3,"text":"耶稣对律法师和法利赛人说：「安息日治病可以不可以？」"},{"start":4,"end":4,"text":"他们却不言语。耶稣就治好那人，叫他走了；"},{"start":5,"end":5,"text":"便对他们说：「你们中间谁有驴或有牛，在安息日掉在井里，不立时拉它上来呢？」"},{"start":6,"end":6,"text":"他们不能对答这话。"},{"start":7,"end":7,"text":"耶稣见所请的客拣择首位，就用比喻对他们说："},{"start":8,"end":8,"text":"「你被人请去赴婚姻的筵席，不要坐在首位上，恐怕有比你尊贵的客被他请来；"},{"start":9,"end":9,"text":"那请你们的人前来对你说：『让座给这一位吧！』你就羞羞惭惭地退到末位上去了。"},{"start":10,"end":10,"text":"你被请的时候，就去坐在末位上，好叫那请你的人来对你说：『朋友，请上座。』那时，你在同席的人面前就有光彩了。"},{"start":11,"end":11,"text":"因为，凡自高的，必降为卑；自卑的，必升为高。」"},{"start":12,"end":12,"text":"耶稣又对请他的人说：「你摆设午饭或晚饭，不要请你的朋友、弟兄、亲属，和富足的邻舍，恐怕他们也请你，你就得了报答。"},{"start":13,"end":13,"text":"你摆设筵席，倒要请那贫穷的、残废的、瘸腿的、瞎眼的，你就有福了！"},{"start":14,"end":14,"text":"因为他们没有什么可报答你。到义人复活的时候，你要得着报答。」"},{"start":15,"end":15,"text":"同席的有一人听见这话，就对耶稣说：「在　神国里吃饭的有福了！」"},{"start":16,"end":16,"text":"耶稣对他说：「有一人摆设大筵席，请了许多客。"},{"start":17,"end":17,"text":"到了坐席的时候，打发仆人去对所请的人说：『请来吧！样样都齐备了。』"},{"start":18,"end":18,"text":"众人一口同音地推辞。头一个说：『我买了一块地，必须去看看。请你准我辞了。』"},{"start":19,"end":19,"text":"又有一个说：『我买了五对牛，要去试一试。请你准我辞了。』"},{"start":20,"end":20,"text":"又有一个说：『我才娶了妻，所以不能去。』"},{"start":21,"end":21,"text":"那仆人回来，把这事都告诉了主人。家主就动怒，对仆人说：『快出去，到城里大街小巷，领那贫穷的、残废的、瞎眼的、瘸腿的来。』"},{"start":22,"end":22,"text":"仆人说：『主啊，你所吩咐的已经办了，还有空座。』"},{"start":23,"end":23,"text":"主人对仆人说：『你出去到路上和篱笆那里，勉强人进来，坐满我的屋子。"},{"start":24,"end":24,"text":"我告诉你们，先前所请的人没有一个得尝我的筵席。』」"},{"start":25,"end":25,"text":"有极多的人和耶稣同行。他转过来对他们说："},{"start":26,"end":26,"text":"「人到我这里来，若不爱我胜过爱自己的父 母、妻子、儿女、弟兄、姊妹，和自己的性命，就不能作我的门徒。"},{"start":27,"end":27,"text":"凡不背着自己十字架跟从我的，也不能作我的门徒。"},{"start":28,"end":28,"text":"你们哪一个要盖一座楼，不先坐下算计花费，能盖成不能呢？"},{"start":29,"end":29,"text":"恐怕安了地基，不能成功，看见的人都笑话他，说："},{"start":30,"end":30,"text":"『这个人开了工，却不能完工。』"},{"start":31,"end":31,"text":"或是一个王出去和别的王打仗，岂不先坐下酌量，能用一万兵去敌那领二万兵来攻打他的吗？"},{"start":32,"end":32,"text":"若是不能，就趁敌人还远的时候，派使者去求和息的条款。"},{"start":33,"end":33,"text":"这样，你们无论什么人，若不撇下一切所有的，就不能作我的门徒。」"},{"start":34,"end":34,"text":"「盐本是好的；盐若失了味，可用什么叫它再咸呢？"},{"start":35,"end":35,"text":"或用在田里，或堆在粪里，都不合式，只好丢在外面。有耳可听的，就应当听！」"}],"15":[{"start":1,"end":1,"text":"众税吏和罪人都挨近耶稣，要听他[讲道]。"},{"start":2,"end":2,"text":"法利赛人和文士私下议论说：「这个人接待罪人，又同他们吃饭。」"},{"start":3,"end":3,"text":"耶稣就用比喻说："},{"start":4,"end":4,"text":"「你们中间谁有一百只羊失去一只，不把这九十九只撇在旷野、去找那失去的羊，直到找着呢？"},{"start":5,"end":5,"text":"找着了，就欢欢喜喜地扛在肩上，回到家里，"},{"start":6,"end":6,"text":"就请朋友邻舍来，对他们说：『我失去的羊已经找着了，你们和我一同欢喜吧！』"},{"start":7,"end":7,"text":"我告诉你们，一个罪人悔改，在天上也要这样为他欢喜，较比为九十九个不用悔改的义人欢喜更大。」"},{"start":8,"end":8,"text":"「或是一个妇人有十块钱，若失落一块，岂不点上灯，打扫屋子，细细地找，直到找着吗？"},{"start":9,"end":9,"text":"找着了，就请朋友邻舍来，对他们说：『我失落的那块钱已经找着了，你们和我一同欢喜吧！』"},{"start":10,"end":10,"text":"我告诉你们，一个罪人悔改，在　神的使者面前也是这样为他欢喜。」"},{"start":11,"end":11,"text":"耶稣又说：「一个人有两个儿子。"},{"start":12,"end":12,"text":"小儿子对父亲说：『父亲，请你把我应得的家业分给我。』他父亲就把产业分给他们。"},{"start":13,"end":13,"text":"过了不多几日，小儿子就把他一切所有的都收拾起来，往远方去了。在那里任意放荡，浪费资财。"},{"start":14,"end":14,"text":"既耗尽了一切所有的，又遇着那地方大遭饥荒，就穷苦起来。"},{"start":15,"end":15,"text":"于是去投靠那地方的一个人；那人打发他到田里去放猪。"},{"start":16,"end":16,"text":"他恨不得拿猪所吃的豆荚充饥，也没有人给他。"},{"start":17,"end":17,"text":"他醒悟过来，就说：『我父亲有多少的雇工，口粮有余，我倒在这里饿死吗？"},{"start":18,"end":18,"text":"我要起来，到我父亲那里去，向他说：父亲！我得罪了天，又得罪了你；"},{"start":19,"end":19,"text":"从今以后，我不配称为你的儿子，把我当作一个雇工吧！』"},{"start":20,"end":20,"text":"于是起来，往他父亲那里去。相离还远，他父亲看见，就动了慈心，跑去抱着他的颈项，连连与他亲嘴。"},{"start":21,"end":21,"text":"儿子说：『父亲！我得罪了天，又得罪了你；从今以后，我不配称为你的儿子。』"},{"start":22,"end":22,"text":"父亲却吩咐仆人说：『把那上好的袍子快拿出来给他穿；把戒指戴在他指头上；把鞋穿在他脚上；"},{"start":23,"end":23,"text":"把那肥牛犊牵来宰了，我们可以吃喝快乐；"},{"start":24,"end":24,"text":"因为我这个儿子是死而复活，失而又得的。』他们就快乐起来。"},{"start":25,"end":25,"text":"那时，大儿子正在田里。他回来，离家不远，听见作乐跳舞的声音，"},{"start":26,"end":26,"text":"便叫过一个仆人来，问是什么事。"},{"start":27,"end":27,"text":"仆人说：『你兄弟来了；你父亲因为得他无灾无病地回来，把肥牛犊宰了。』"},{"start":28,"end":28,"text":"大儿子却生气，不肯进去；他父亲就出来劝他。"},{"start":29,"end":29,"text":"他对父亲说：『我服事你这多年，从来没有违背过你的命，你并没有给我一只山羊羔，叫我和朋友一同快乐。"},{"start":30,"end":30,"text":"但你这个儿子和娼妓吞尽了你的产业，他一来了，你倒为他宰了肥牛犊。』"},{"start":31,"end":31,"text":"父亲对他说：『儿啊！你常和我同在，我一切所有的都是你的；"},{"start":32,"end":32,"text":"只是你这个兄弟是死而复活、失而又得的，所以我们理当欢喜快乐。』」"}],"16":[{"start":1,"end":1,"text":"耶稣又对门徒说：「有一个财主的管家，别人向他主人告他浪费主人的财物。"},{"start":2,"end":2,"text":"主人叫他来，对他说：『我听见你这事怎么样呢？把你所经管的交代明白，因你不能再作[我的]管家。』"},{"start":3,"end":3,"text":"那管家心里说：『主人辞我，不用我再作管家，我将来做什么？锄地呢？无力；讨饭呢？怕羞。"},{"start":4,"end":4,"text":"我知道怎么行，好叫人在我不作管家之后，接我到他们家里去。』"},{"start":5,"end":5,"text":"于是把欠他主人债的，一个一个地叫了来，问头一个说：『你欠我主人多少？』"},{"start":6,"end":6,"text":"他说：『一百篓油。』管家说：『拿你的帐，快坐下，写五十。』"},{"start":7,"end":7,"text":"又问一个说：『你欠多少？』他说：『一百石麦子。』管家说：『拿你的帐，写八十。』"},{"start":8,"end":8,"text":"主人就夸奖这不义的管家做事聪明；因为今世之子，在世事之上，较比光明之子更加聪明。"},{"start":9,"end":9,"text":"我又告诉你们，要借着那不义的钱财结交朋友，到了钱财无用的时候，他们可以接你们到永存的帐幕里去。"},{"start":10,"end":10,"text":"人在最小的事上忠心，在大事上也忠心；在最小的事上不义，在大事上也不义。"},{"start":11,"end":11,"text":"倘若你们在不义的钱财上不忠心，谁还把那真实的[钱财]托付你们呢？"},{"start":12,"end":12,"text":"倘若你们在别人的东西上不忠心，谁还把你们自己的东西给你们呢？"},{"start":13,"end":13,"text":"一个仆人不能事奉两个主；不是恶这个爱那个，就是重这个轻那个。你们不能又事奉　神，又事奉玛门。」"},{"start":14,"end":14,"text":"法利赛人是贪爱钱财的；他们听见这一切话，就嗤笑耶稣。"},{"start":15,"end":15,"text":"耶稣对他们说：「你们是在人面前自称为义的，你们的心，　神却知道；因为人所尊贵的，是　神看为可憎恶的。"},{"start":16,"end":16,"text":"律法和先知到约翰为止，从此　神国的福音传开了，人人努力要进去。"},{"start":17,"end":17,"text":"天地废去较比律法的一点一画落空还容易。"},{"start":18,"end":18,"text":"凡休妻另娶的就是犯奸淫；娶被休之妻的也是犯奸淫。」"},{"start":19,"end":19,"text":"「有一个财主穿着紫色[袍]和细麻布衣服，天天奢华宴乐。"},{"start":20,"end":20,"text":"又有一个讨饭的，名叫拉撒路，浑身生疮，被人放在财主门口，"},{"start":21,"end":21,"text":"要得财主桌子上掉下来的[零碎]充饥，并且狗来舔他的疮。"},{"start":22,"end":22,"text":"后来那讨饭的死了，被天使带去放在亚伯拉罕的怀里。财主也死了，并且埋葬了。"},{"start":23,"end":23,"text":"他在阴间受痛苦，举目远远地望见亚伯拉罕，又望见拉撒路在他怀里，"},{"start":24,"end":24,"text":"就喊着说：『我祖亚伯拉罕哪，可怜我吧！打发拉撒路来，用指头尖蘸点水，凉凉我的舌头；因为我在这火焰里，极其痛苦。』"},{"start":25,"end":25,"text":"亚伯拉罕说：『儿啊，你该回想你生前享过福，拉撒路也受过苦；如今他在这里得安慰，你倒受痛苦。"},{"start":26,"end":26,"text":"不但这样，并且在你我之间，有深渊限定，以致人要从这边过到你们那边是不能的；要从那边过到我们这边也是不能的。』"},{"start":27,"end":27,"text":"财主说：『我祖啊！既是这样，求你打发拉撒路到我父家去；"},{"start":28,"end":28,"text":"因为我还有五个弟兄，他可以对他们作见证，免得他们也来到这痛苦的地方。』"},{"start":29,"end":29,"text":"亚伯拉罕说：『他们有摩西和先知[的话]可以听从。』"},{"start":30,"end":30,"text":"他说：『我祖亚伯拉罕哪，不是的，若有一个从死里[复活的]，到他们那里去的，他们必要悔改。』"},{"start":31,"end":31,"text":"亚伯拉罕说：『若不听从摩西和先知[的话]，就是有一个从死里复活的，他们也是不听劝。』」"}],"17":[{"start":1,"end":1,"text":"耶稣又对门徒说：「绊倒人的事是免不了的；但那绊倒人的有祸了。"},{"start":2,"end":2,"text":"就是把磨石拴在这人的颈项上，丢在海里，还强如他把这小子里的一个绊倒了。"},{"start":3,"end":3,"text":"你们要谨慎！若是你的弟兄得罪[你]，就劝戒他；他若懊悔，就饶恕他。"},{"start":4,"end":4,"text":"倘若他一天七次得罪你，又七次回转，说：『我懊悔了』，你总要饶恕他。」"},{"start":5,"end":5,"text":"使徒对主说：「[求主]加增我们的信心。」"},{"start":6,"end":6,"text":"主说：「你们若有信心像一粒芥菜种，就是对这棵桑树说：『你要拔起根来，栽在海里』，它也必听从你们。"},{"start":7,"end":7,"text":"你们谁有仆人耕地或是放羊，从田里回来，就对他说：『你快来坐下吃饭』呢？"},{"start":8,"end":8,"text":"岂不对他说：『你给我预备晚饭，束上带子伺候我，等我吃喝完了，你才可以吃喝』吗？"},{"start":9,"end":9,"text":"仆人照所吩咐的去做，主人还谢谢他吗？"},{"start":10,"end":10,"text":"这样，你们做完了一切所吩咐的，只当说：『我们是无用的仆人，所做的本是我们应分做的。』」"},{"start":11,"end":11,"text":"耶稣往耶路撒冷去，经过撒马利亚和加利利。"},{"start":12,"end":12,"text":"进入一个村子，有十个长大麻风的，迎面而来，远远地站着，"},{"start":13,"end":13,"text":"高声说：「耶稣，夫子，可怜我们吧！」"},{"start":14,"end":14,"text":"耶稣看见，就对他们说：「你们去把身体给祭司察看。」他们去的时候就洁净了。"},{"start":15,"end":15,"text":"内中有一个见自己已经好了，就回来大声归荣耀与　神，"},{"start":16,"end":16,"text":"又俯伏在耶稣脚前感谢他；这人是撒马利亚人。"},{"start":17,"end":17,"text":"耶稣说：「洁净了的不是十个人吗？那九个在哪里呢？"},{"start":18,"end":18,"text":"除了这外族人，再没有别人回来归荣耀与　神吗？」"},{"start":19,"end":19,"text":"就对那人说：「起来，走吧！你的信救了你了。」"},{"start":20,"end":20,"text":"法利赛人问：「　神的国几时来到？」耶稣回答说：「　神的国来到不是眼所能见的。"},{"start":21,"end":21,"text":"人也不得说：『看哪，在这里！看哪，在那里！』因为　神的国就在你们心里。」"},{"start":22,"end":22,"text":"他又对门徒说：「日子将到，你们巴不得看见人子的一个日子，却不得看见。"},{"start":23,"end":23,"text":"人将要对你们说：『看哪，在那里！看哪，在这里！』你们不要出去，也不要跟随他们！"},{"start":24,"end":24,"text":"因为人子在他[降临]的日子，好像闪电从天这边一闪直照到天那边。"},{"start":25,"end":25,"text":"只是他必须先受许多苦，又被这世代弃绝。"},{"start":26,"end":26,"text":"挪亚的日子怎样，人子的日子也要怎样。"},{"start":27,"end":27,"text":"那时候的人又吃又喝，又娶又嫁，到挪亚进方舟的那日，洪水就来，把他们全都灭了。"},{"start":28,"end":28,"text":"又好像罗得的日子；人又吃又喝，又买又卖，又耕种又盖造。"},{"start":29,"end":29,"text":"到罗得出所多玛的那日，就有火与硫磺从天上降下来，把他们全都灭了。"},{"start":30,"end":30,"text":"人子显现的日子也要这样。"},{"start":31,"end":31,"text":"当那日，人在房上，器具在屋里，不要下来拿；人在田里，也不要回家。"},{"start":32,"end":32,"text":"你们要回想罗得的妻子。"},{"start":33,"end":33,"text":"凡想要保全生命的，必丧掉生命；凡丧掉生命的，必救活生命。"},{"start":34,"end":34,"text":"我对你们说，当那一夜，两个人在一个床上，要取去一个，撇下一个。"},{"start":35,"end":35,"text":"两个女人一同推磨，要取去一个，撇下一个。」"},{"start":37,"end":37,"text":"门徒说：「主啊，在哪里[有这事]呢？」耶稣说：「尸首在哪里，鹰也必聚在那里。」"}],"18":[{"start":1,"end":1,"text":"耶稣设一个比喻，是要人常常祷告，不可灰心。"},{"start":2,"end":2,"text":"说：「某城里有一个官，不惧怕　神，也不尊重世人。"},{"start":3,"end":3,"text":"那城里有个寡妇，常到他那里，说：『我有一个对头，求你给我伸冤。』"},{"start":4,"end":4,"text":"他多日不准，后来心里说：『我虽不惧怕　神，也不尊重世人，"},{"start":5,"end":5,"text":"只因这寡妇烦扰我，我就给她伸冤吧，免得她常来缠磨我！』」"},{"start":6,"end":6,"text":"主说：「你们听这不义之官所说的话。"},{"start":7,"end":7,"text":"神的选民昼夜呼吁他，他纵然为他们忍了多时，岂不终久给他们伸冤吗？"},{"start":8,"end":8,"text":"我告诉你们，要快快地给他们伸冤了。然而，人子来的时候，遇得见世上有信德吗？」"},{"start":9,"end":9,"text":"耶稣向那些仗着自己是义人，藐视别人的，设一个比喻，"},{"start":10,"end":10,"text":"说：「有两个人上殿里去祷告：一个是法利赛人，一个是税吏。"},{"start":11,"end":11,"text":"法利赛人站着，自言自语地祷告说：『　神啊，我感谢你，我不像别人勒索、不义、奸淫，也不像这个税吏。"},{"start":12,"end":12,"text":"我一个礼拜禁食两次，凡我所得的都捐上十分之一。』"},{"start":13,"end":13,"text":"那税吏远远地站着，连举目望天也不敢，只捶着胸说：『　神啊，开恩可怜我这个罪人！』"},{"start":14,"end":14,"text":"我告诉你们，这人回家去比那人倒算为义了；因为，凡自高的，必降为卑；自卑的，必升为高。」"},{"start":15,"end":15,"text":"有人抱着自己的婴孩来见耶稣，要他摸他们；门徒看见就责备那些人。"},{"start":16,"end":16,"text":"耶稣却叫他们来，说：「让小孩子到我这里来，不要禁止他们，因为在　神国的正是这样的人。"},{"start":17,"end":17,"text":"我实在告诉你们，凡要承受　神国的，若不像小孩子，断不能进去。」"},{"start":18,"end":18,"text":"有一个官问耶稣说：「良善的夫子，我该做什么事才可以承受永生？」"},{"start":19,"end":19,"text":"耶稣对他说：「你为什么称我是良善的？除了　神一位之外，再没有良善的。"},{"start":20,"end":20,"text":"诫命你是晓得的：『不可奸淫；不可杀人；不可偷盗；不可作假见证；当孝敬父母。』」"},{"start":21,"end":21,"text":"那人说：「这一切我从小都遵守了。」"},{"start":22,"end":22,"text":"耶稣听见了，就说：「你还缺少一件：要变卖你一切所有的，分给穷人，就必有财宝在天上；你还要来跟从我。」"},{"start":23,"end":23,"text":"他听见这话，就甚忧愁，因为他很富足。"},{"start":24,"end":24,"text":"耶稣看见他，就说：「有钱财的人进　神的国是何等的难哪！"},{"start":25,"end":25,"text":"骆驼穿过针的眼比财主进　神的国还容易呢！」"},{"start":26,"end":26,"text":"听见的人说：「这样，谁能得救呢？」"},{"start":27,"end":27,"text":"耶稣说：「在人所不能的事，在　神却能。」"},{"start":28,"end":28,"text":"彼得说：「看哪，我们已经撇下自己所有的跟从你了。」"},{"start":29,"end":29,"text":"耶稣说：「我实在告诉你们，人为　神的国撇下房屋，或是妻子、弟兄、父母、儿女，"},{"start":30,"end":30,"text":"没有在今世不得百倍，在来世不得永生的。」"},{"start":31,"end":31,"text":"耶稣带着十二个门徒，对他们说：「看哪，我们上耶路撒冷去，先知所写的一切事都要成就在人子身上。"},{"start":32,"end":32,"text":"他将要被交给外邦人；他们要戏弄他，凌辱他，吐唾沫在他脸上，"},{"start":33,"end":33,"text":"并要鞭打他，杀害他；第三日他要复活。」"},{"start":34,"end":34,"text":"这些事门徒一样也不懂得，意思乃是隐藏的；他们不晓得所说的是什么。"},{"start":35,"end":35,"text":"耶稣将近耶利哥的时候，有一个瞎子坐在路旁讨饭。"},{"start":36,"end":36,"text":"听见许多人经过，就问是什么事。"},{"start":37,"end":37,"text":"他们告诉他，是拿撒勒人耶稣经过。"},{"start":38,"end":38,"text":"他就呼叫说：「大卫的子孙耶稣啊，可怜我吧！」"},{"start":39,"end":39,"text":"在前头走的人就责备他，不许他作声；他却越发喊叫说：「大卫的子孙，可怜我吧！」"},{"start":40,"end":40,"text":"耶稣站住，吩咐把他领过来，到了跟前，就问他说："},{"start":41,"end":41,"text":"「你要我为你做什么？」他说：「主啊，我要能看见。」"},{"start":42,"end":42,"text":"耶稣说：「你可以看见！你的信救了你了。」"},{"start":43,"end":43,"text":"瞎子立刻看见了，就跟随耶稣，[一路]归荣耀与　神。众人看见这事，也赞美　神。"}],"19":[{"start":1,"end":1,"text":"耶稣进了耶利哥，正经过的时候，"},{"start":2,"end":2,"text":"有一个人名叫撒该，作税吏长，是个财主。"},{"start":3,"end":3,"text":"他要看看耶稣是怎样的人；只因人多，他的身量又矮，所以不得看见，"},{"start":4,"end":4,"text":"就跑到前头，爬上桑树，要看耶稣，因为耶稣必从那里经过。"},{"start":5,"end":5,"text":"耶稣到了那里，抬头一看，对他说：「撒该，快下来！今天我必住在你家里。」"},{"start":6,"end":6,"text":"他就急忙下来，欢欢喜喜地接待耶稣。"},{"start":7,"end":7,"text":"众人看见，都私下议论说：「他竟到罪人家里去住宿。」"},{"start":8,"end":8,"text":"撒该站着对主说：「主啊，我把所有的一半给穷人；我若讹诈了谁，就还他四倍。」"},{"start":9,"end":9,"text":"耶稣说：「今天救恩到了这家，因为他也是亚伯拉罕的子孙。"},{"start":10,"end":10,"text":"人子来，为要寻找、拯救失丧的人。」"},{"start":11,"end":11,"text":"众人正在听见这些话的时候，耶稣因为将近耶路撒冷，又因他们以为　神的国快要显出来，就另设一个比喻，说："},{"start":12,"end":12,"text":"「有一个贵胄往远方去，要得国回来，"},{"start":13,"end":13,"text":"便叫了他的十个仆人来，交给他们十锭银子，说：『你们去做生意，直等我回来。』"},{"start":14,"end":14,"text":"他本国的人却恨他，打发使者随后去，说：『我们不愿意这个人作我们的王。』"},{"start":15,"end":15,"text":"他既得国回来，就吩咐叫那领银子的仆人来，要知道他们做生意赚了多少。"},{"start":16,"end":16,"text":"头一个上来，说：『主啊，你的一锭银子已经赚了十锭。』"},{"start":17,"end":17,"text":"主人说：『好！良善的仆人，你既在最小的事上有忠心，可以有权柄管十座城。』"},{"start":18,"end":18,"text":"第二个来，说：『主啊，你的一锭银子已经赚了五锭。』"},{"start":19,"end":19,"text":"主人说：『你也可以管五座城。』"},{"start":20,"end":20,"text":"又有一个来说：『主啊，看哪，你的一锭银子在这里，我把它包在手巾里存着。"},{"start":21,"end":21,"text":"我原是怕你，因为你是严厉的人；没有放下的，还要去拿，没有种下的，还要去收。』"},{"start":22,"end":22,"text":"主人对他说：『你这恶仆，我要凭你的口定你的罪。你既知道我是严厉的人，没有放下的，还要去拿，没有种下的，还要去收，"},{"start":23,"end":23,"text":"为什么不把我的银子交给银行，等我来的时候，连本带利都可以要回来呢？』"},{"start":24,"end":24,"text":"就对旁边站着的人说：『夺过他这一锭来，给那有十锭的。』"},{"start":25,"end":25,"text":"他们说：『主啊，他已经有十锭了。』"},{"start":26,"end":26,"text":"[主人说]：『我告诉你们，凡有的，还要加给他；没有的，连他所有的也要夺过来。"},{"start":27,"end":27,"text":"至于我那些仇敌，不要我作他们王的，把他们拉来，在我面前杀了吧！』」"},{"start":28,"end":28,"text":"耶稣说完了这话，就在前面走，上耶路撒冷去。"},{"start":29,"end":29,"text":"将近伯法其和伯大尼，在一座山名叫橄榄山那里，就打发两个门徒，说："},{"start":30,"end":30,"text":"「你们往对面村子里去，进去的时候，必看见一匹驴驹拴在那里，是从来没有人骑过的，可以解开牵来。"},{"start":31,"end":31,"text":"若有人问为什么解它，你们就说：『主要用它。』」"},{"start":32,"end":32,"text":"打发的人去了，所遇见的正如耶稣所说的。"},{"start":33,"end":33,"text":"他们解驴驹的时候，主人问他们说：「解驴驹做什么？」"},{"start":34,"end":34,"text":"他们说：「主要用它。」"},{"start":35,"end":35,"text":"他们牵到耶稣那里，把自己的衣服搭在上面，扶着耶稣骑上。"},{"start":36,"end":36,"text":"走的时候，众人把衣服铺在路上。"},{"start":37,"end":37,"text":"将近耶路撒冷，正下橄榄山的时候，众门徒因所见过的一切异能，都欢乐起来，大声赞美　神，"},{"start":38,"end":38,"text":"说： 奉主名来的王是应当称颂的！ 在天上有和平； 在至高之处有荣光。"},{"start":39,"end":39,"text":"众人中有几个法利赛人对耶稣说：「夫子，责备你的门徒吧！」"},{"start":40,"end":40,"text":"耶稣说：「我告诉你们，若是他们闭口不说，这些石头必要呼叫起来。」"},{"start":41,"end":41,"text":"耶稣快到耶路撒冷，看见城，就为它哀哭，"},{"start":42,"end":42,"text":"说：「巴不得你在这日子知道关系你平安的事；无奈这事现在是隐藏的，叫你的眼看不出来。"},{"start":43,"end":43,"text":"因为日子将到，你的仇敌必筑起土垒，周围环绕你，四面困住你，"},{"start":44,"end":44,"text":"并要扫灭你和你里头的儿女，连一块石头也不留在石头上，因你不知道眷顾你的时候。」"},{"start":45,"end":45,"text":"耶稣进了殿，赶出里头做买卖的人，"},{"start":46,"end":46,"text":"对他们说：「[经上]说： 我的殿必作祷告的殿， 你们倒使它成为贼窝了。」"},{"start":47,"end":47,"text":"耶稣天天在殿里教训人。祭司长和文士与百姓的尊长都想要杀他，"},{"start":48,"end":48,"text":"但寻不出法子来，因为百姓都侧耳听他。"}],"20":[{"start":1,"end":1,"text":"有一天，耶稣在殿里教训百姓，讲福音的时候，祭司长和文士并长老上前来，"},{"start":2,"end":2,"text":"问他说：「你告诉我们，你仗着什么权柄做这些事？给你这权柄的是谁呢？」"},{"start":3,"end":3,"text":"耶稣回答说：「我也要问你们一句话，你们且告诉我。"},{"start":4,"end":4,"text":"约翰的洗礼是从天上来的？是从人间来的呢？」"},{"start":5,"end":5,"text":"他们彼此商议说：「我们若说『从天上来』，他必说：『你们为什么不信他呢？』"},{"start":6,"end":6,"text":"若说『从人间来』，百姓都要用石头打死我们，因为他们信约翰是先知。」"},{"start":7,"end":7,"text":"于是回答说：「不知道是从哪里来的。」"},{"start":8,"end":8,"text":"耶稣说：「我也不告诉你们，我仗着什么权柄做这些事。」"},{"start":9,"end":9,"text":"耶稣就设比喻对百姓说：「有人栽了一个葡萄园，租给园户，就往外国去住了许久。"},{"start":10,"end":10,"text":"到了时候，打发一个仆人到园户那里去，叫他们把园中当纳的果子交给他；园户竟打了他，叫他空手回去。"},{"start":11,"end":11,"text":"又打发一个仆人去，他们也打了他，并且凌辱他，叫他空手回去。"},{"start":12,"end":12,"text":"又打发第三个仆人去，他们也打伤了他，把他推出去了。"},{"start":13,"end":13,"text":"园主说：『我怎么办呢？我要打发我的爱子去，或者他们尊敬他。』"},{"start":14,"end":14,"text":"不料，园户看见他，就彼此商量说：『这是承受产业的，我们杀他吧，使产业归于我们！』"},{"start":15,"end":15,"text":"于是把他推出葡萄园外，杀了。这样，葡萄园的主人要怎样处治他们呢？"},{"start":16,"end":16,"text":"他要来除灭这些园户，将葡萄园转给别人。」听见的人说：「这是万不可的！」"},{"start":17,"end":17,"text":"耶稣看着他们说：「[经上]记着： 匠人所弃的石头 已作了房角的头块石头。 这是什么意思呢？"},{"start":18,"end":18,"text":"凡掉在那石头上的，必要跌碎；那石头掉在谁的身上，就要把谁砸得稀烂。」"},{"start":19,"end":19,"text":"文士和祭司长看出这比喻是指着他们说的，当时就想要下手拿他，只是惧怕百姓。"},{"start":20,"end":20,"text":"于是窥探耶稣，打发奸细装作好人，要在他的话上得把柄，好将他交在巡抚的政权之下。"},{"start":21,"end":21,"text":"奸细就问耶稣说：「夫子，我们晓得你所讲所传都是正道，也不取人的外貌，乃是诚诚实实传　神的道。"},{"start":22,"end":22,"text":"我们纳税给凯撒，可以不可以？」"},{"start":23,"end":23,"text":"耶稣看出他们的诡诈，就对他们说："},{"start":24,"end":24,"text":"「拿一个银钱来给我看。这像和这号是谁的？」他们说：「是凯撒的。」"},{"start":25,"end":25,"text":"耶稣说：「这样，凯撒的物当归给凯撒，　神的物当归给　神。」"},{"start":26,"end":26,"text":"他们当着百姓，在这话上得不着把柄，又希奇他的应对，就闭口无言了。"},{"start":27,"end":27,"text":"撒都该人常说没有复活的事。有几个来问耶稣说："},{"start":28,"end":28,"text":"「夫子！摩西为我们写着说：『人若有妻无子就死了，他兄弟当娶他的妻，为哥哥生子立后。』"},{"start":29,"end":29,"text":"有弟兄七人，第一个娶了妻，没有孩子死了；"},{"start":30,"end":30,"text":"第二个、第三个也娶过她；"},{"start":31,"end":31,"text":"那七个人都娶过她，没有留下孩子就死了。"},{"start":32,"end":32,"text":"后来妇人也死了。"},{"start":33,"end":33,"text":"这样，当复活的时候，她是哪一个的妻子呢？因为他们七个人都娶过她。」"},{"start":34,"end":34,"text":"耶稣说：「这世界的人有娶有嫁；"},{"start":35,"end":35,"text":"惟有算为配得那世界，与从死里复活的人也不娶也不嫁；"},{"start":36,"end":36,"text":"因为他们不能再死，和天使一样；既是复活的人，就为　神的儿子。"},{"start":37,"end":37,"text":"至于死人复活，摩西在荆棘篇上，称主是亚伯拉罕的　神，以撒的　神，雅各的　神，就指示明白了。"},{"start":38,"end":38,"text":"神原不是死人的　神，乃是活人的　神；因为在他那里，人都是活的。」"},{"start":39,"end":39,"text":"有几个文士说：「夫子！你说得好。」"},{"start":40,"end":40,"text":"以后他们不敢再问他什么。"},{"start":41,"end":41,"text":"耶稣对他们说：「人怎么说基督是大卫的子孙呢？"},{"start":42,"end":42,"text":"诗篇上大卫自己说： 主对我主说： 你坐在我的右边，"},{"start":43,"end":43,"text":"等我使你仇敌作你的脚凳。"},{"start":44,"end":44,"text":"大卫既称他为主，他怎么又是大卫的子孙呢？」"},{"start":45,"end":45,"text":"众百姓听的时候，耶稣对门徒说："},{"start":46,"end":46,"text":"「你们要防备文士。他们好穿长衣游行，喜爱人在街市上问他们安，又喜爱会堂里的高位，筵席上的首座；"},{"start":47,"end":47,"text":"他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的刑罚！」"}],"21":[{"start":1,"end":1,"text":"耶稣抬头观看，见财主把捐项投在库里，"},{"start":2,"end":2,"text":"又见一个穷寡妇投了两个小钱，"},{"start":3,"end":3,"text":"就说：「我实在告诉你们，这穷寡妇所投的比众人还多；"},{"start":4,"end":4,"text":"因为众人都是自己有余，拿出来投在捐项里，但这寡妇是自己不足，把她一切养生的都投上了。」"},{"start":5,"end":5,"text":"有人谈论圣殿是用美石和供物妆饰的；"},{"start":6,"end":6,"text":"耶稣就说：「论到你们所看见的这一切，将来日子到了，在这里没有一块石头留在石头上，不被拆毁了。」"},{"start":7,"end":7,"text":"他们问他说：「夫子！什么时候有这事呢？这事将到的时候有什么预兆呢？」"},{"start":8,"end":8,"text":"耶稣说：「你们要谨慎，不要受迷惑；因为将来有好些人冒我的名来，说：『我是[基督]』，又说：『时候近了』，你们不要跟从他们！"},{"start":9,"end":9,"text":"你们听见打仗和扰乱的事，不要惊惶；因为这些事必须先有，只是末期不能立时就到。」"},{"start":10,"end":10,"text":"当时，耶稣对他们说：「民要攻打民，国要攻打国；"},{"start":11,"end":11,"text":"地要大大震动，多处必有饥荒、瘟疫，又有可怕的异象和大神迹从天上显现。"},{"start":12,"end":12,"text":"但这一切的事以先，人要下手拿住你们，逼迫你们，把你们交给会堂，并且收在监里，又为我的名拉你们到君王诸侯面前。"},{"start":13,"end":13,"text":"但这些事终必为你们的见证。"},{"start":14,"end":14,"text":"所以，你们当立定心意，不要预先思想怎样分诉；"},{"start":15,"end":15,"text":"因为我必赐你们口才、智慧，是你们一切敌人所敌不住、驳不倒的。"},{"start":16,"end":16,"text":"连你们的父母、弟兄、亲族、朋友也要把你们交官；你们也有被他们害死的。"},{"start":17,"end":17,"text":"你们要为我的名被众人恨恶，"},{"start":18,"end":18,"text":"然而，你们连一根头发也必不损坏。"},{"start":19,"end":19,"text":"你们常存忍耐，就必保全灵魂。」"},{"start":20,"end":20,"text":"「你们看见耶路撒冷被兵围困，就可知道它成荒场的日子近了。"},{"start":21,"end":21,"text":"那时，在犹太的应当逃到山上；在城里的应当出来；在乡下的不要进城；"},{"start":22,"end":22,"text":"因为这是报应的日子，使[经上]所写的都得应验。"},{"start":23,"end":23,"text":"当那些日子，怀孕的和奶孩子的有祸了！因为将有大灾难降在这地方，也有震怒临到这百姓。"},{"start":24,"end":24,"text":"他们要倒在刀下，又被掳到各国去。耶路撒冷要被外邦人践踏，直到外邦人的日期满了。」"},{"start":25,"end":25,"text":"「日、月、星辰要显出异兆，地上的邦国也有困苦；因海中波浪的响声，就慌慌不定。"},{"start":26,"end":26,"text":"天势都要震动，人想起那将要临到世界的事，就都吓得魂不附体。"},{"start":27,"end":27,"text":"那时，他们要看见人子有能力，有大荣耀驾云降临。"},{"start":28,"end":28,"text":"一有这些事，你们就当挺身昂首，因为你们得赎的日子近了。」"},{"start":29,"end":29,"text":"耶稣又设比喻对他们说：「你们看无花果树和各样的树；它发芽的时候，你们一看见，自然晓得夏天近了。"},{"start":31,"end":31,"text":"这样，你们看见这些事渐渐地成就，也该晓得　神的国近了。"},{"start":32,"end":32,"text":"我实在告诉你们，这世代还没有过去，这些事都要成就。"},{"start":33,"end":33,"text":"天地要废去，我的话却不能废去。」"},{"start":34,"end":34,"text":"「你们要谨慎，恐怕因贪食、醉酒，并今生的思虑累住你们的心，那日子就如同网罗忽然临到你们；"},{"start":35,"end":35,"text":"因为那日子要[这样]临到全地上一切居住的人。"},{"start":36,"end":36,"text":"你们要时时警醒，常常祈求，使你们能逃避这一切要来的事，得以站立在人子面前。」"},{"start":37,"end":37,"text":"耶稣每日在殿里教训人，每夜出城在一座山，名叫橄榄山住宿。"},{"start":38,"end":38,"text":"众百姓清早上[圣]殿，到耶稣那里，要听他讲道。"}],"22":[{"start":1,"end":1,"text":"除酵节（又名逾越[节]）近了。"},{"start":2,"end":2,"text":"祭司长和文士想法子怎么才能杀害耶稣，是因他们惧怕百姓。"},{"start":3,"end":3,"text":"这时，撒但入了那称为加略人犹大的心；他本是十二门徒里的一个。"},{"start":4,"end":4,"text":"他去和祭司长并守殿官商量，怎么可以把耶稣交给他们。"},{"start":5,"end":5,"text":"他们欢喜，就约定给他银子。"},{"start":6,"end":6,"text":"他应允了，就找机会，要趁众人不在跟前的时候把耶稣交给他们。"},{"start":7,"end":7,"text":"除酵[节]，须宰逾越[羊羔]的那一天到了。"},{"start":8,"end":8,"text":"耶稣打发彼得、约翰，说：「你们去为我们预备逾越[节的筵席]，好叫我们吃。」"},{"start":9,"end":9,"text":"他们问他说：「要我们在哪里预备？」"},{"start":10,"end":10,"text":"耶稣说：「你们进了城，必有人拿着一瓶水迎面而来，你们就跟着他，到他所进的房子里去，"},{"start":11,"end":11,"text":"对那家的主人说：『夫子说：客房在哪里？我与门徒好在那里吃逾越[节的筵席]。』"},{"start":12,"end":12,"text":"他必指给你们摆设整齐的一间大楼，你们就在那里预备。」"},{"start":13,"end":13,"text":"他们去了，所遇见的正如耶稣所说的；他们就预备了逾越[节的筵席]。"},{"start":14,"end":14,"text":"时候到了，耶稣坐席，使徒也和他同坐。"},{"start":15,"end":15,"text":"耶稣对他们说：「我很愿意在受害以先和你们吃这逾越[节的筵席]。"},{"start":16,"end":16,"text":"我告诉你们，我不[再]吃[这筵席]，直到成就在　神的国里。」"},{"start":17,"end":17,"text":"耶稣接过杯来，祝谢了，说：「你们拿这个，大家分着喝。"},{"start":18,"end":18,"text":"我告诉你们，从今以后，我不再喝这葡萄汁，直等　神的国来到。」"},{"start":19,"end":19,"text":"又拿起饼来，祝谢了，就擘开，递给他们，说：「这是我的身体，为你们舍的，你们也应当如此行，为的是记念我。」"},{"start":20,"end":20,"text":"饭后也照样拿起杯来，说：「这杯是用我血所立的新约，是为你们流出来的。"},{"start":21,"end":21,"text":"看哪，那卖我之人的手与我一同在桌子上。"},{"start":22,"end":22,"text":"人子固然要照所预定的去世，但卖人子的人有祸了！」"},{"start":23,"end":23,"text":"他们就彼此对问，是哪一个要做这事。"},{"start":24,"end":24,"text":"门徒起了争论，他们中间哪一个可算为大。"},{"start":25,"end":25,"text":"耶稣说：「外邦人有君王为主治理他们，那掌权管他们的称为恩主。"},{"start":26,"end":26,"text":"但你们不可这样；你们里头为大的，倒要像年幼的，为首领的，倒要像服事人的。"},{"start":27,"end":27,"text":"是谁为大？是坐席的呢？是服事人的呢？不是坐席的大吗？然而，我在你们中间如同服事人的。"},{"start":28,"end":28,"text":"我在磨炼之中，常和我同在的就是你们。"},{"start":29,"end":29,"text":"我将国赐给你们，正如我父赐给我一样，"},{"start":30,"end":30,"text":"叫你们在我国里，坐在我的席上吃喝，并且坐在宝座上，审判以色列十二个支派。」"},{"start":31,"end":31,"text":"[主又说]：「西门！西门！撒但想要得着你们，好筛你们像筛麦子一样；"},{"start":32,"end":32,"text":"但我已经为你祈求，叫你不至于失了信心。你回头以后，要坚固你的弟兄。」"},{"start":33,"end":33,"text":"彼得说：「主啊，我就是同你下监，同你受死，也是甘心！」"},{"start":34,"end":34,"text":"耶稣说：「彼得，我告诉你，今日鸡还没有叫，你要三次说不认得我。」"},{"start":35,"end":35,"text":"耶稣又对他们说：「我差你们出去的时候，没有钱囊，没有口袋，没有鞋，你们缺少什么没有？」他们说：「没有。」"},{"start":36,"end":36,"text":"耶稣说：「但如今有钱囊的可以带着，有口袋的也可以带着，没有刀的要卖衣服买刀。"},{"start":37,"end":37,"text":"我告诉你们，[经上]写着说：『他被列在罪犯之中。』这话必应验在我身上，因为那关系我的事必然成就。」"},{"start":38,"end":38,"text":"他们说：「主啊，请看！这里有两把刀。」耶稣说：「够了。」"},{"start":39,"end":39,"text":"耶稣出来，照常往橄榄山去，门徒也跟随他。"},{"start":40,"end":40,"text":"到了那地方，就对他们说：「你们要祷告，免得入了迷惑。」"},{"start":41,"end":41,"text":"于是离开他们约有扔一块石头那么远，跪下祷告，"},{"start":42,"end":42,"text":"说：「父啊！你若愿意，就把这杯撤去；然而，不要成就我的意思，只要成就你的意思。」"},{"start":43,"end":43,"text":"有一位天使从天上显现，加添他的力量。"},{"start":44,"end":44,"text":"耶稣极其伤痛，祷告更加恳切，汗珠如大血点滴在地上。"},{"start":45,"end":45,"text":"祷告完了，就起来，到门徒那里，见他们因为忧愁都睡着了，"},{"start":46,"end":46,"text":"就对他们说：「你们为什么睡觉呢？起来祷告，免得入了迷惑！」"},{"start":47,"end":47,"text":"说话之间，来了许多人。那十二个门徒里名叫犹大的，走在前头，就近耶稣，要与他亲嘴。"},{"start":48,"end":48,"text":"耶稣对他说：「犹大！你用亲嘴[的暗号]卖人子吗？」"},{"start":49,"end":49,"text":"左右的人见光景不好，就说：「主啊！我们拿刀砍可以不可以？」"},{"start":50,"end":50,"text":"内中有一个人把大祭司的仆人砍了一刀，削掉了他的右耳。"},{"start":51,"end":51,"text":"耶稣说：「到了这个地步，由他们吧！」就摸那人的耳朵，把他治好了。"},{"start":52,"end":52,"text":"耶稣对那些来拿他的祭司长和守殿官并长老说：「你们带着刀棒出来拿我，如同拿强盗吗？"},{"start":53,"end":53,"text":"我天天同你们在殿里，你们不下手拿我。现在却是你们的时候，黑暗掌权了。」"},{"start":54,"end":54,"text":"他们拿住耶稣，把他带到大祭司的宅里。彼得远远地跟着。"},{"start":55,"end":55,"text":"他们在院子里生了火，一同坐着；彼得也坐在他们中间。"},{"start":56,"end":56,"text":"有一个使女看见彼得坐在[火]光里，就定睛看他，说：「这个人素来也是同那人一伙的。」"},{"start":57,"end":57,"text":"彼得却不承认，说：「女子，我不认得他。」"},{"start":58,"end":58,"text":"过了不多的时候，又有一个人看见他，说：「你也是他们一党的。」彼得说：「你这个人！我不是。」"},{"start":59,"end":59,"text":"约过了一小时，又有一个人极力地说：「他实在是同那人一伙的，因为他也是加利利人。」"},{"start":60,"end":60,"text":"彼得说：「你这个人！我不晓得你说的是什么！」正说话之间，鸡就叫了。"},{"start":61,"end":61,"text":"主转过身来看彼得，彼得便想起主对他所说的话：「今日鸡叫以先，你要三次不认我。」"},{"start":62,"end":62,"text":"他就出去痛哭。"},{"start":63,"end":63,"text":"看守耶稣的人戏弄他，打他，"},{"start":64,"end":64,"text":"又蒙着他的眼，问他说：「你是先知，告诉我们打你的是谁？」"},{"start":65,"end":65,"text":"他们还用许多别的话辱骂他。"},{"start":66,"end":66,"text":"天一亮，民间的众长老连祭司长带文士都聚会，把耶稣带到他们的公会里，"},{"start":67,"end":67,"text":"说：「你若是基督，就告诉我们。」耶稣说：「我若告诉你们，你们也不信；"},{"start":68,"end":68,"text":"我若问你们，你们也不回答。"},{"start":69,"end":69,"text":"从今以后，人子要坐在　神权能的右边。」"},{"start":70,"end":70,"text":"他们都说：「这样，你是　神的儿子吗？」耶稣说：「你们所说的是。」"},{"start":71,"end":71,"text":"他们说：「何必再用见证呢？他亲口所说的，我们都亲自听见了。」"}],"23":[{"start":1,"end":1,"text":"众人都起来，把耶稣解到彼拉多面前，"},{"start":2,"end":2,"text":"就告他说：「我们见这人诱惑国民，禁止纳税给凯撒，并说自己是基督，是王。」"},{"start":3,"end":3,"text":"彼拉多问耶稣说：「你是犹太人的王吗？」耶稣回答说：「你说的是。」"},{"start":4,"end":4,"text":"彼拉多对祭司长和众人说：「我查不出这人有什么罪来。」"},{"start":5,"end":5,"text":"但他们越发极力地说：「他煽惑百姓，在犹太遍地传道，从加利利起，直到这里了。」"},{"start":6,"end":6,"text":"彼拉多一听见，就问：「这人是加利利人吗？」"},{"start":7,"end":7,"text":"既晓得耶稣属希律所管，就把他送到希律那里去。那时希律正在耶路撒冷。"},{"start":8,"end":8,"text":"希律看见耶稣，就很欢喜；因为听见过他的事，久已想要见他，并且指望看他行一件神迹，"},{"start":9,"end":9,"text":"于是问他许多的话，耶稣却一言不答。"},{"start":10,"end":10,"text":"祭司长和文士都站着，极力地告他。"},{"start":11,"end":11,"text":"希律和他的兵丁就藐视耶稣，戏弄他，给他穿上华丽衣服，把他送回彼拉多那里去。"},{"start":12,"end":12,"text":"从前希律和彼拉多彼此有仇，在那一天就成了朋友。"},{"start":13,"end":13,"text":"彼拉多传齐了祭司长和官府并百姓，"},{"start":14,"end":14,"text":"就对他们说：「你们解这人到我这里，说他是诱惑百姓的。看哪，我也曾将你们告他的事，在你们面前审问他，并没有查出他什么罪来；"},{"start":15,"end":15,"text":"就是希律也是如此，所以把他送回来。可见他没有做什么该死的事。"},{"start":16,"end":16,"text":"故此，我要责打他，把他释放了。」"},{"start":18,"end":18,"text":"众人却一齐喊着说：「除掉这个人！释放巴拉巴给我们！」"},{"start":19,"end":19,"text":"这巴拉巴是因在城里作乱杀人，下在监里的。"},{"start":20,"end":20,"text":"彼拉多愿意释放耶稣，就又劝解他们。"},{"start":21,"end":21,"text":"无奈他们喊着说：「钉他十字架！钉他十字架！」"},{"start":22,"end":22,"text":"彼拉多第三次对他们说：「为什么呢？这人做了什么恶事呢？我并没有查出他什么该死的罪来。所以，我要责打他，把他释放了。」"},{"start":23,"end":23,"text":"他们大声催逼彼拉多，求他把耶稣钉在十字架上。他们的声音就得了胜。"},{"start":24,"end":24,"text":"彼拉多这才照他们所求的定案，"},{"start":25,"end":25,"text":"把他们所求的那作乱杀人、下在监里的释放了，把耶稣交给他们，任凭他们的意思行。"},{"start":26,"end":26,"text":"带耶稣去的时候，有一个古利奈人西门，从乡下来；他们就抓住他，把十字架搁在他身上，叫他背着跟随耶稣。"},{"start":27,"end":27,"text":"有许多百姓跟随耶稣，内中有好些妇女；妇女们为他号咷痛哭。"},{"start":28,"end":28,"text":"耶稣转身对她们说：「耶路撒冷的女子，不要为我哭，当为自己和自己的儿女哭。"},{"start":29,"end":29,"text":"因为日子要到，人必说：『不生育的，和未曾怀胎的，未曾乳养婴孩的，有福了！』"},{"start":30,"end":30,"text":"那时，人要向大山说： 倒在我们身上！ 向小山说： 遮盖我们！"},{"start":31,"end":31,"text":"「这些事既行在有汁水的树上，那枯干的树将来怎么样呢？」"},{"start":32,"end":32,"text":"又有两个犯人，和耶稣一同带来处死。"},{"start":33,"end":33,"text":"到了一个地方，名叫「髑髅地」，就在那里把耶稣钉在十字架上，又钉了两个犯人：一个在左边，一个在右边。"},{"start":34,"end":34,"text":"当下耶稣说：「父啊！赦免他们；因为他们所做的，他们不晓得。」[兵丁]就拈阄分他的衣服。"},{"start":35,"end":35,"text":"百姓站在那里观看。官府也嗤笑他，说：「他救了别人；他若是基督，　神所拣选的，可以救自己吧！」"},{"start":36,"end":36,"text":"兵丁也戏弄他，上前拿醋送给他喝，"},{"start":37,"end":37,"text":"说：「你若是犹太人的王，可以救自己吧！」"},{"start":38,"end":38,"text":"在耶稣以上有一个牌子写着：「这是犹太人的王。」"},{"start":39,"end":39,"text":"那同钉的两个犯人有一个讥笑他，说：「你不是基督吗？可以救自己和我们吧！」"},{"start":40,"end":40,"text":"那一个就应声责备他，说：「你既是一样受刑的，还不怕　神吗？"},{"start":41,"end":41,"text":"我们是应该的，因我们所受的与我们所做的相称，但这个人没有做过一件不好的事。」"},{"start":42,"end":42,"text":"就说：「耶稣啊，你得国降临的时候，求你记念我！」"},{"start":43,"end":43,"text":"耶稣对他说：「我实在告诉你，今日你要同我在乐园里了。」"},{"start":44,"end":44,"text":"那时约有午正，遍地都黑暗了，直到申初，"},{"start":45,"end":45,"text":"日头变黑了；殿里的幔子从当中裂为两半。"},{"start":46,"end":46,"text":"耶稣大声喊着说：「父啊！我将我的灵魂交在你手里。」说了这话，气就断了。"},{"start":47,"end":47,"text":"百夫长看见所成的事，就归荣耀与　神，说：「这真是个义人！」"},{"start":48,"end":48,"text":"聚集观看的众人见了这所成的事都捶着胸回去了。"},{"start":49,"end":49,"text":"还有一切与耶稣熟识的人，和从加利利跟着他来的妇女们，都远远地站着看这些事。"},{"start":50,"end":50,"text":"有一个人名叫约瑟，是个议士，为人善良公义；"},{"start":51,"end":51,"text":"众人所谋所为，他并没有附从。他本是犹太、亚利马太城里素常盼望　神国的人。"},{"start":52,"end":52,"text":"这人去见彼拉多，求耶稣的身体，"},{"start":53,"end":53,"text":"就取下来，用细麻布裹好，安放在石头凿成的坟墓里；那里头从来没有葬过人。"},{"start":54,"end":54,"text":"那日是预备日，安息日也快到了。"},{"start":55,"end":55,"text":"那些从加利利和耶稣同来的妇女跟在后面，看见了坟墓和他的身体怎样安放。"},{"start":56,"end":56,"text":"她们就回去，预备了香料香膏。她们在安息日，便遵着诫命安息了。"}],"24":[{"start":1,"end":1,"text":"七日的头一日，黎明的时候，那些妇女带着所预备的香料来到坟墓前，"},{"start":2,"end":2,"text":"看见石头已经从坟墓滚开了，"},{"start":3,"end":3,"text":"她们就进去，只是不见主耶稣的身体。"},{"start":4,"end":4,"text":"正在猜疑之间，忽然有两个人站在旁边，衣服放光。"},{"start":5,"end":5,"text":"妇女们惊怕，将脸伏地。那两个人就对她们说：「为什么在死人中找活人呢？"},{"start":6,"end":6,"text":"他不在这里，已经复活了。当记念他还在加利利的时候怎样告诉你们，"},{"start":7,"end":7,"text":"说：『人子必须被交在罪人手里，钉在十字架上，第三日复活。』」"},{"start":8,"end":8,"text":"她们就想起耶稣的话来，"},{"start":9,"end":9,"text":"便从坟墓那里回去，把这一切的事告诉十一个使徒和其余的人。"},{"start":10,"end":10,"text":"那告诉使徒的就是抹大拉的马利亚和约亚拿，并雅各的母亲马利亚，还有与她们在一处的妇女。"},{"start":11,"end":11,"text":"她们这些话，使徒以为是胡言，就不相信。"},{"start":12,"end":12,"text":"彼得起来，跑到坟墓前，低头往里看，见细麻布独在一处，就回去了，心里希奇所成的事。"},{"start":13,"end":13,"text":"正当那日，门徒中有两个人往一个村子去；这村子名叫以马忤斯，离耶路撒冷约有二十五里。"},{"start":14,"end":14,"text":"他们彼此谈论所遇见的这一切事。"},{"start":15,"end":15,"text":"正谈论相问的时候，耶稣亲自就近他们，和他们同行；"},{"start":16,"end":16,"text":"只是他们的眼睛迷糊了，不认识他。"},{"start":17,"end":17,"text":"耶稣对他们说：「你们走路彼此谈论的是什么事呢？」他们就站住，脸上带着愁容。"},{"start":18,"end":18,"text":"二人中有一个名叫革流巴的回答说：「你在耶路撒冷作客，还不知道这几天在那里所出的事吗？」"},{"start":19,"end":19,"text":"耶稣说：「什么事呢？」他们说：「就是拿撒勒人耶稣的事。他是个先知，在　神和众百姓面前，说话行事都有大能。"},{"start":20,"end":20,"text":"祭司长和我们的官府竟把他解去，定了死罪，钉在十字架上。"},{"start":21,"end":21,"text":"但我们素来所盼望、要赎以色列民的就是他！不但如此，而且这事成就，现在已经三天了。"},{"start":22,"end":22,"text":"再者，我们中间有几个妇女使我们惊奇；她们清早到了坟墓那里，"},{"start":23,"end":23,"text":"不见他的身体，就回来告诉我们，说看见了天使显现，说他活了。"},{"start":24,"end":24,"text":"又有我们的几个人往坟墓那里去，所遇见的正如妇女们所说的，只是没有看见他。」"},{"start":25,"end":25,"text":"耶稣对他们说：「无知的人哪，先知所说的一切话，你们的心信得太迟钝了。"},{"start":26,"end":26,"text":"基督这样受害，又进入他的荣耀，岂不是应当的吗？」"},{"start":27,"end":27,"text":"于是从摩西和众先知起，凡经上所指着自己的话都给他们讲解明白了。"},{"start":28,"end":28,"text":"将近他们所去的村子，耶稣好像还要往前行，"},{"start":29,"end":29,"text":"他们却强留他，说：「时候晚了，日头已经平西了，请你同我们住下吧！」耶稣就进去，要同他们住下。"},{"start":30,"end":30,"text":"到了坐席的时候，耶稣拿起饼来，祝谢了，擘开，递给他们。"},{"start":31,"end":31,"text":"他们的眼睛明亮了，这才认出他来。忽然耶稣不见了。"},{"start":32,"end":32,"text":"他们彼此说：「在路上，他和我们说话，给我们讲解圣经的时候，我们的心岂不是火热的吗？」"},{"start":33,"end":33,"text":"他们就立时起身，回耶路撒冷去，正遇见十一个使徒和他们的同人聚集在一处，"},{"start":34,"end":34,"text":"说：「主果然复活，已经现给西门看了。」"},{"start":35,"end":35,"text":"两个人就把路上[所遇见]，和擘饼的时候怎么被他们认出来的事，都述说了一遍。"},{"start":36,"end":36,"text":"正说这话的时候，耶稣亲自站在他们当中，说：「愿你们平安！」"},{"start":37,"end":37,"text":"他们却惊慌害怕，以为所看见的是魂。"},{"start":38,"end":38,"text":"耶稣说：「你们为什么愁烦？为什么心里起疑念呢？"},{"start":39,"end":39,"text":"你们看我的手，我的脚，就[知道]实在是我了。摸我看看！魂无骨无肉，你们看，我是有的。」"},{"start":40,"end":40,"text":"说了这话，就把手和脚给他们看。"},{"start":41,"end":41,"text":"他们正喜得不敢信，并且希奇；耶稣就说：「你们这里有什么吃的没有？」"},{"start":42,"end":42,"text":"他们便给他一片烧鱼。"},{"start":43,"end":43,"text":"他接过来，在他们面前吃了。"},{"start":44,"end":44,"text":"耶稣对他们说：「这就是我从前与你们同在之时所告诉你们的话说：摩西的律法、先知的书，和诗篇上所记的，凡指着我的话都必须应验。」"},{"start":45,"end":45,"text":"于是耶稣开他们的心窍，使他们能明白圣经，"},{"start":46,"end":46,"text":"又对他们说：「照[经上]所写的，基督必受害，第三日从死里复活，"},{"start":47,"end":47,"text":"并且人要奉他的名传悔改、赦罪的道，从耶路撒冷起直传到万邦。"},{"start":48,"end":48,"text":"你们就是这些事的见证。"},{"start":49,"end":49,"text":"我要将我父所应许的降在你们身上，你们要在城里等候，直到你们领受从上头来的能力。」"},{"start":50,"end":50,"text":"耶稣领他们到伯大尼的对面，就举手给他们祝福。"},{"start":51,"end":51,"text":"正祝福的时候，他就离开他们，被带到天上去了。"},{"start":52,"end":52,"text":"他们就拜他，大大地欢喜，回耶路撒冷去，"},{"start":53,"end":53,"text":"常在殿里称颂　神。"}]},"ACT":{"1":[{"start":1,"end":1,"text":"提阿非罗啊，我已经作了前书，论到耶稣开头一切所行所教训的，"},{"start":2,"end":2,"text":"直到他借着圣灵吩咐所拣选的使徒，以后被接上升的日子为止。"},{"start":3,"end":3,"text":"他受害之后，用许多的凭据将自己活活地显给使徒看，四十天之久向他们显现，讲说　神国的事。"},{"start":4,"end":4,"text":"耶稣和他们聚集的时候，嘱咐他们说：「不要离开耶路撒冷，要等候父所应许的，就是你们听见我说过的。"},{"start":5,"end":5,"text":"约翰是用水施洗，但不多几日，你们要受圣灵的洗。」"},{"start":6,"end":6,"text":"他们聚集的时候，问耶稣说：「主啊，你复兴以色列国就在这时候吗？」"},{"start":7,"end":7,"text":"耶稣对他们说：「父凭着自己的权柄所定的时候、日期，不是你们可以知道的。"},{"start":8,"end":8,"text":"但圣灵降临在你们身上，你们就必得着能力，并要在耶路撒冷、犹太全地，和撒马利亚，直到地极，作我的见证。」"},{"start":9,"end":9,"text":"说了这话，他们正看的时候，他就被取上升，有一朵云彩把他接去，便看不见他了。"},{"start":10,"end":10,"text":"当他往上去，他们定睛望天的时候，忽然有两个人身穿白衣，站在旁边，说："},{"start":11,"end":11,"text":"「加利利人哪，你们为什么站着望天呢？这离开你们被接升天的耶稣，你们见他怎样往天上去，他还要怎样来。」"},{"start":12,"end":12,"text":"有一座山，名叫橄榄山，离耶路撒冷不远，约有安息日可走的路程。当下，门徒从那里回耶路撒冷去，"},{"start":13,"end":13,"text":"进了城，就上了所住的一间楼房；在那里有彼得、约翰、雅各、安得烈、腓力、多马、巴多罗买、马太、亚勒腓的儿子雅各、奋锐党的西门，和雅各的儿子犹大。"},{"start":14,"end":14,"text":"这些人同着几个妇人和耶稣的母亲马利亚，并耶稣的弟兄，都同心合意地恒切祷告。"},{"start":15,"end":15,"text":"那时，有许多人[聚会]，约有一百二十名，彼得就在弟兄中间站起来，"},{"start":16,"end":16,"text":"说：「弟兄们！圣灵借大卫的口，在圣经上预言领人捉拿耶稣的犹大，这话是必须应验的。"},{"start":17,"end":17,"text":"他本来列在我们数中，并且在[使徒的]职任上得了一分。"},{"start":18,"end":18,"text":"这人用他作恶的工价买了一块田，以后身子仆倒，肚腹崩裂，肠子都流出来。"},{"start":19,"end":19,"text":"住在耶路撒冷的众人都知道这事，所以按着他们那里的话给那块田起名叫亚革大马，就是「血田」的意思。"},{"start":20,"end":20,"text":"因为诗篇上写着，说： 愿他的住处变为荒场， 无人在内居住； 又说： 愿别人得他的职分。"},{"start":21,"end":21,"text":"所以，主耶稣在我们中间始终出入的时候，"},{"start":22,"end":22,"text":"就是从约翰施洗起，直到主离开我们被接上升的日子为止，必须从那常与我们作伴的人中立一位与我们同作耶稣复活的见证。」"},{"start":23,"end":23,"text":"于是选举两个人，就是那叫做巴撒巴，又称呼犹士都的约瑟，和马提亚。"},{"start":24,"end":24,"text":"众人就祷告说：「主啊，你知道万人的心，求你从这两个人中，指明你所拣选的是谁，叫他得这使徒的位分。这位分犹大已经丢弃，往自己的地方去了。」"},{"start":26,"end":26,"text":"于是众人为他们摇签，摇出马提亚来；他就和十一个使徒同列。"}],"2":[{"start":1,"end":1,"text":"五旬节到了，门徒都聚集在一处。"},{"start":2,"end":2,"text":"忽然，从天上有响声下来，好像一阵大风吹过，充满了他们所坐的屋子，"},{"start":3,"end":3,"text":"又有舌头如火焰显现出来，分开落在他们各人头上。"},{"start":4,"end":4,"text":"他们就都被圣灵充满，按着[圣]灵所赐的口才说起别国的话来。"},{"start":5,"end":5,"text":"那时，有虔诚的犹太人从天下各国来，住在耶路撒冷。"},{"start":6,"end":6,"text":"这声音一响，众人都来聚集，各人听见门徒用众人的乡谈说话，就甚纳闷；"},{"start":7,"end":7,"text":"都惊讶希奇说：「看哪，这说话的不都是加利利人吗？"},{"start":8,"end":8,"text":"我们各人怎么听见他们说我们生来所用的乡谈呢？"},{"start":9,"end":9,"text":"我们帕提亚人、米底亚人、以拦人，和住在美索不达米亚、犹太、加帕多家、本都、亚细亚、"},{"start":10,"end":10,"text":"弗吕家、旁非利亚、埃及的人，并靠近古利奈的利比亚一带地方的人，从罗马来的客旅中，或是犹太人，或是进[犹太]教的人，"},{"start":11,"end":11,"text":"克里特和阿拉伯人，都听见他们用我们的乡谈，讲说　神的大作为。」"},{"start":12,"end":12,"text":"众人就都惊讶猜疑，彼此说：「这是什么意思呢？」"},{"start":13,"end":13,"text":"还有人讥诮说：「他们无非是新酒灌满了。」"},{"start":14,"end":14,"text":"彼得和十一个使徒站起，高声说：「犹太人和一切住在耶路撒冷的人哪，这件事你们当知道，也当侧耳听我的话。"},{"start":15,"end":15,"text":"你们想这些人是醉了；其实不是醉了，因为时候刚到巳初。"},{"start":16,"end":16,"text":"这正是先知约珥所说的："},{"start":17,"end":17,"text":"神说：在末后的日子， 我要将我的灵浇灌凡有血气的。 你们的儿女要说预言； 你们的少年人要见异象； 老年人要做异梦。"},{"start":18,"end":18,"text":"在那些日子， 我要将我的灵浇灌我的仆人和使女， 他们就要说预言。"},{"start":19,"end":19,"text":"在天上，我要显出奇事； 在地下，我要显出神迹； 有血，有火，有烟雾。"},{"start":20,"end":20,"text":"日头要变为黑暗， 月亮要变为血； 这都在主大而明显的日子未到以前。"},{"start":21,"end":21,"text":"到那时候， 凡求告主名的，就必得救。"},{"start":22,"end":22,"text":"「以色列人哪，请听我的话：　神借着拿撒勒人耶稣在你们中间施行异能、奇事、神迹，将他证明出来，这是你们自己知道的。"},{"start":23,"end":23,"text":"他既按着　神的定旨先见被交与人，你们就借着无法之人的手，把他钉在十字架上，杀了。"},{"start":24,"end":24,"text":"神却将死的痛苦解释了，叫他复活，因为他原不能被死拘禁。"},{"start":25,"end":25,"text":"大卫指着他说： 我看见主常在我眼前； 他在我右边，叫我不至于摇动。"},{"start":26,"end":26,"text":"所以，我心里欢喜， 我的灵快乐； 并且我的肉身要安居在指望中。"},{"start":27,"end":27,"text":"因你必不将我的灵魂撇在阴间， 也不叫你的圣者见朽坏。"},{"start":28,"end":28,"text":"你已将生命的道路指示我， 必叫我因见你的面 得着满足的快乐。"},{"start":29,"end":29,"text":"「弟兄们！先祖大卫的事，我可以明明地对你们说：他死了，也葬埋了，并且他的坟墓直到今日还在我们这里。"},{"start":30,"end":30,"text":"大卫既是先知，又晓得　神曾向他起誓，要从他的后裔中立一位坐在他的宝座上，"},{"start":31,"end":31,"text":"就预先看明这事，讲论基督复活说： 他的灵魂不撇在阴间； 他的肉身也不见朽坏。"},{"start":32,"end":32,"text":"这耶稣，　神已经叫他复活了，我们都为这事作见证。"},{"start":33,"end":33,"text":"他既被　神的右手高举，又从父受了所应许的圣灵，就把你们所看见所听见的，浇灌下来。"},{"start":34,"end":34,"text":"大卫并没有升到天上，但自己说： 主对我主说： 你坐在我的右边，"},{"start":35,"end":35,"text":"等我使你仇敌作你的脚凳。"},{"start":36,"end":36,"text":"「故此，以色列全家当确实地知道，你们钉在十字架上的这位耶稣，　神已经立他为主，为基督了。」"},{"start":37,"end":37,"text":"众人听见这话，觉得扎心，就对彼得和其余的使徒说：「弟兄们，我们当怎样行？」"},{"start":38,"end":38,"text":"彼得说：「你们各人要悔改，奉耶稣基督的名受洗，叫你们的罪得赦，就必领受所赐的圣灵；"},{"start":39,"end":39,"text":"因为这应许是给你们和你们的儿女，并一切在远方的人，就是主—我们　神所召来的。」"},{"start":40,"end":40,"text":"彼得还用许多话作见证，劝勉他们说：「你们当救自己脱离这弯曲的世代。」"},{"start":41,"end":41,"text":"于是领受他话的人就受了洗。那一天，[门徒]约添了三千人，"},{"start":42,"end":42,"text":"都恒心遵守使徒的教训，彼此交接，擘饼，祈祷。"},{"start":43,"end":43,"text":"众人都惧怕；使徒又行了许多奇事神迹。"},{"start":44,"end":44,"text":"信的人都在一处，凡物公用，"},{"start":45,"end":45,"text":"并且卖了田产、家业，照各人所需用的分给各人。"},{"start":46,"end":46,"text":"他们天天同心合意恒切地在殿里，且在家中擘饼，存着欢喜、诚实的心用饭，"},{"start":47,"end":47,"text":"赞美　神，得众民的喜爱。主将得救的人天天加给他们。"}],"4":[{"start":7,"end":7,"text":"叫使徒站在当中，就问他们说：「你们用什么能力，奉谁的名做这事呢？」"},{"start":8,"end":8,"text":"那时彼得被圣灵充满，对他们说："},{"start":9,"end":9,"text":"「治民的官府和长老啊，倘若今日因为在残疾人身上所行的善事查问我们他是怎么得了痊愈，"},{"start":10,"end":10,"text":"你们众人和以色列百姓都当知道，站在你们面前的这人得痊愈是因你们所钉十字架、　神叫他从死里复活的拿撒勒人耶稣基督的名。"},{"start":11,"end":11,"text":"他是 你们匠人所弃的石头， 已成了房角的头块石头。"},{"start":12,"end":12,"text":"除他以外，别无拯救；因为在天下人间，没有赐下别的名，我们可以靠着得救。」"},{"start":13,"end":13,"text":"他们见彼得、约翰的胆量，又看出他们原是没有学问的小民，就希奇，认明他们是跟过耶稣的；"},{"start":14,"end":14,"text":"又看见那治好了的人和他们一同站着，就无话可驳。"},{"start":15,"end":15,"text":"于是吩咐他们从公会出去，就彼此商议说："},{"start":16,"end":16,"text":"「我们当怎样办这两个人呢？因为他们诚然行了一件明显的神迹，凡住耶路撒冷的人都知道，我们也不能说没有。"},{"start":17,"end":17,"text":"惟恐这事越发传扬在民间，我们必须恐吓他们，叫他们不再奉这名对人讲论。」"},{"start":18,"end":18,"text":"于是叫了他们来，禁止他们总不可奉耶稣的名讲论教训人。"},{"start":19,"end":19,"text":"彼得、约翰说：「听从你们，不听从　神，这在　神面前合理不合理，你们自己酌量吧！"},{"start":20,"end":20,"text":"我们所看见所听见的，不能不说。」"},{"start":25,"end":25,"text":"你曾借着圣灵，[托]你仆人—我们祖宗大卫的口，说： 外邦为什么争闹？ 万民为什么谋算虚妄的事？"},{"start":26,"end":26,"text":"世上的君王一齐起来， 臣宰也聚集， 要敌挡主， 并主的受膏者。"},{"start":27,"end":27,"text":"希律和本丢·彼拉多，外邦人和以色列民，果然在这城里聚集，要攻打你所膏的圣仆耶稣，"},{"start":28,"end":28,"text":"成就你手和你意旨所预定必有的事。"},{"start":29,"end":29,"text":"他们恐吓我们，现在求主鉴察，一面叫你仆人大放胆量讲你的道，一面伸出你的手来医治疾病，并且使神迹奇事因着你圣仆耶稣的名行出来。」"}],"5":[{"start":29,"end":29,"text":"彼得和众使徒回答说：「顺从　神，不顺从人，是应当的。"},{"start":30,"end":30,"text":"你们挂在木头上杀害的耶稣，我们祖宗的　神已经叫他复活。"},{"start":31,"end":31,"text":"神且用右手将他高举，叫他作君王，作救主，将悔改的心和赦罪的恩赐给以色列人。"},{"start":32,"end":32,"text":"我们为这事作见证；　神赐给顺从之人的圣灵也为这事作见证。」"},{"start":33,"end":33,"text":"公会的人听见就极其恼怒，想要杀他们。"},{"start":34,"end":34,"text":"但有一个法利赛人，名叫迦玛列，是众百姓所敬重的教法师，在公会中站起来，吩咐人把使徒暂且带到外面去，"},{"start":35,"end":35,"text":"就对众人说：「以色列人哪，论到这些人，你们应当小心怎样办理。"},{"start":36,"end":36,"text":"从前杜达起来，自夸为大，附从他的人约有四百，他被杀后，附从他的全都散了，归于无有。"},{"start":37,"end":37,"text":"此后，报名上册的时候，又有加利利的犹大起来，引诱些百姓跟从他；他也灭亡，附从他的人也都四散了。"},{"start":38,"end":38,"text":"现在，我劝你们不要管这些人，任凭他们吧！他们所谋的、所行的，若是出于人，必要败坏；"},{"start":39,"end":39,"text":"若是出于　神，你们就不能败坏他们，恐怕你们倒是攻击　神了。」"},{"start":40,"end":40,"text":"公会的人听从了他，便叫使徒来，把他们打了，又吩咐他们不可奉耶稣的名讲道，就把他们释放了。"},{"start":41,"end":41,"text":"他们离开公会，心里欢喜，因被算是配为这名受辱。"},{"start":42,"end":42,"text":"他们就每日在殿里、在家里不住地教训人，传耶稣是基督。"}],"6":[{"start":1,"end":1,"text":"那时，门徒增多，有说希腊话的犹太人向希伯来人发怨言，因为在天天的供给上忽略了他们的寡妇。"},{"start":2,"end":2,"text":"十二使徒叫众门徒来，对他们说：「我们撇下　神的道去管理饭食，原是不合宜的。"},{"start":3,"end":3,"text":"所以弟兄们，当从你们中间选出七个有好名声、被[圣]灵充满、智慧充足的人，我们就派他们管理这事。"},{"start":4,"end":4,"text":"但我们要专心以祈祷、传道为事。」"},{"start":5,"end":5,"text":"大众都喜悦这话，就拣选了司提反，乃是大有信心、圣灵充满的人，又拣选腓利、伯罗哥罗、尼迦挪、提门、巴米拿，并进[犹太]教的安提阿人尼哥拉，"},{"start":6,"end":6,"text":"叫他们站在使徒面前。使徒祷告了，就按手在他们头上。"},{"start":7,"end":7,"text":"神的道兴旺起来；在耶路撒冷门徒数目加增的甚多，也有许多祭司信从了这道。"},{"start":8,"end":8,"text":"司提反满得恩惠、能力，在民间行了大奇事和神迹。"},{"start":9,"end":9,"text":"当时有称利百地拿会堂的几个人，并有古利奈、亚历山大、基利家、亚细亚各处会堂的几个人，都起来和司提反辩论。"},{"start":10,"end":10,"text":"司提反是以智慧和[圣]灵说话，众人敌挡不住，"},{"start":11,"end":11,"text":"就买出人来说：「我们听见他说谤 摩西和　神的话。」"},{"start":12,"end":12,"text":"他们又耸动了百姓、长老，并文士，就忽然来捉拿他，把他带到公会去，"},{"start":13,"end":13,"text":"设下假见证，说：「这个人说话，不住地糟践圣所和律法。"},{"start":14,"end":14,"text":"我们曾听见他说，这拿撒勒人耶稣要毁坏此地，也要改变摩西所交给我们的规条。」"},{"start":15,"end":15,"text":"在公会里坐着的人都定睛看他，见他的面貌，好像天使的面貌。"}],"7":[{"start":48,"end":48,"text":"其实，至高者并不住人手所造的，就如先知所言："},{"start":49,"end":49,"text":"主说：天是我的座位， 地是我的脚凳； 你们要为我造何等的殿宇？ 哪里是我安息的地方呢？"},{"start":50,"end":50,"text":"这一切不都是我手所造的吗？"}],"8":[{"start":26,"end":26,"text":"有主的一个使者对腓利说：「起来！向南走，往那从耶路撒冷下迦萨的路上去。」那路是旷野。"},{"start":27,"end":27,"text":"腓利就起身去了，不料，有一个衣索匹亚人，是个有大权的太监，在衣索匹亚女王甘大基的手下总管银库，他上耶路撒冷礼拜去了。"},{"start":28,"end":28,"text":"现在回来，在车上坐着，念先知以赛亚的书。"},{"start":29,"end":29,"text":"圣灵对腓利说：「你去！贴近那车走。」"},{"start":30,"end":30,"text":"腓利就跑到太监那里，听见他念先知以赛亚的书，便问他说：「你所念的，你明白吗？」"},{"start":31,"end":31,"text":"他说：「没有人指教我，怎能明白呢？」于是请腓利上车，与他同坐。"},{"start":32,"end":32,"text":"他所念的那段经，说： 他像羊被牵到宰杀之地， 又像羊羔在剪毛的人手下无声； 他也是这样不开口。"},{"start":33,"end":33,"text":"他卑微的时候， 人不按公义审判他； 谁能述说他的世代？ 因为他的生命从地上夺去。"},{"start":34,"end":34,"text":"太监对腓利说：「请问，先知说这话是指着谁？是指着自己呢？是指着别人呢？」"},{"start":35,"end":35,"text":"腓利就开口从这经上起，对他传讲耶稣。"}],"13":[{"start":2,"end":2,"text":"他们事奉主、禁食的时候，圣灵说：「要为我分派巴拿巴和扫罗，去做我召他们所做的工。」"},{"start":3,"end":3,"text":"于是禁食祷告，按手在他们[头]上，就打发他们去了。"},{"start":24,"end":24,"text":"在他没有出来以先，约翰向以色列众民宣讲悔改的洗礼。"},{"start":25,"end":25,"text":"约翰将行尽他的程途说：『你们以为我是谁？我不是[基督]；只是有一位在我以后来的，我解他脚上的鞋带也是不配的。』"},{"start":46,"end":46,"text":"保罗和巴拿巴放胆说：「　神的道先讲给你们原是应当的；只因你们弃绝这道，断定自己不配得永生，我们就转向外邦人去。"},{"start":47,"end":47,"text":"因为主曾这样吩咐我们说： 我已经立你作外邦人的光， 叫你施行救恩，直到地极。」"},{"start":48,"end":48,"text":"外邦人听见这话，就欢喜了，赞美　神的道；凡预定得永生的人都信了。"},{"start":49,"end":49,"text":"于是主的道传遍了那一带地方。"},{"start":50,"end":50,"text":"但犹太人挑唆虔敬、尊贵的妇女和城内有名望的人，逼迫保罗、巴拿巴，将他们赶出境外。"},{"start":51,"end":51,"text":"二人对着众人跺下脚上的尘土，就往以哥念去了。"},{"start":52,"end":52,"text":"门徒满心喜乐，又被圣灵充满。"}],"16":[{"start":16,"end":16,"text":"后来，我们往那祷告的地方去。有一个使女迎着面来，她被巫鬼所附，用法术，叫她主人们大得财利。"},{"start":17,"end":17,"text":"她跟随保罗和我们，喊着说：「这些人是至高　神的仆人，对你们传说救人的道。」"},{"start":18,"end":18,"text":"她一连多日这样喊叫，保罗就心中厌烦，转身对那鬼说：「我奉耶稣基督的名，吩咐你从她身上出来！」那鬼当时就出来了。"}],"22":[{"start":3,"end":3,"text":"保罗说：「我原是犹太人，生在基利家的大数，长在这城里，在迦玛列门下，按着我们祖宗严紧的律法受教，热心事奉　神，像你们众人今日一样。"},{"start":4,"end":4,"text":"我也曾逼迫奉这道的人，直到死地，无论男女都锁拿下监。"},{"start":5,"end":5,"text":"这是大祭司和众长老都可以给我作见证的。我又领了他们达与弟兄的书信，往大马士革去，要把在那里[奉这道]的人锁拿，带到耶路撒冷受刑。」"},{"start":6,"end":6,"text":"「我将到大马士革，正走的时候，约在晌午，忽然从天上发大光，四面照着我。"},{"start":7,"end":7,"text":"我就仆倒在地，听见有声音对我说：『扫罗！扫罗！你为什么逼迫我？』"},{"start":8,"end":8,"text":"我回答说：『主啊，你是谁？』他说：『我就是你所逼迫的拿撒勒人耶稣。』"},{"start":9,"end":9,"text":"与我同行的人看见了那光，却没有听明那位对我说话的声音。"},{"start":10,"end":10,"text":"我说：『主啊，我当做什么？』主说：『起来，进大马士革去，在那里，要将所派你做的一切事告诉你。』"},{"start":11,"end":11,"text":"我因那光的荣耀不能看见，同行的人就拉着我手进了大马士革。"},{"start":12,"end":12,"text":"那[里]有一个人，名叫亚拿尼亚，按着律法是虔诚人，为一切住在那里的犹太人所称赞。"},{"start":13,"end":13,"text":"他来见我，站在旁边，对我说：『兄弟扫罗，你可以看见。』我当时往上一看，就看见了他。"},{"start":14,"end":14,"text":"他又说：『我们祖宗的　神拣选了你，叫你明白他的旨意，又得见那义者，听他口中所出的声音。"},{"start":15,"end":15,"text":"因为你要将所看见的，所听见的，对着万人为他作见证。"},{"start":16,"end":16,"text":"现在你为什么耽延呢？起来，求告他的名受洗，洗去你的罪。』」"},{"start":17,"end":17,"text":"「后来，我回到耶路撒冷，在殿里祷告的时候，魂游象外，"},{"start":18,"end":18,"text":"看见主向我说：『你赶紧地离开耶路撒冷，不可迟延；因你为我作的见证，这里的人必不领受。』"},{"start":19,"end":19,"text":"我就说：『主啊，他们知道我从前把信你的人收在监里，又在各会堂里鞭打他们。"},{"start":20,"end":20,"text":"并且你的见证人司提反被害流血的时候，我也站在旁边欢喜；又看守害死他之人的衣裳。』"},{"start":21,"end":21,"text":"主向我说：『你去吧！我要差你远远地往外邦人那里去。』」"},{"start":22,"end":22,"text":"众人听他说到这句话，就高声说：「这样的人，从世上除掉他吧！他是不当活着的。」"},{"start":23,"end":23,"text":"众人喧嚷，摔掉衣裳，把尘土向空中扬起来。"},{"start":24,"end":24,"text":"千夫长就吩咐将保罗带进营楼去，叫人用鞭子拷问他，要知道他们向他这样喧嚷是为什么缘故。"},{"start":25,"end":25,"text":"刚用皮条捆上，保罗对旁边站着的百夫长说：「人是罗马人，又没有定罪，你们就鞭打他，有这个例吗？」"},{"start":26,"end":26,"text":"百夫长听见这话，就去见千夫长，告诉他说：「你要做什么？这人是罗马人。」"},{"start":27,"end":27,"text":"千夫长就来问保罗说：「你告诉我，你是罗马人吗？」保罗说：「是。」"},{"start":28,"end":28,"text":"千夫长说：「我用许多银子才入了罗马的民籍。」保罗说：「我生来就是。」"},{"start":29,"end":29,"text":"于是那些要拷问保罗的人就离开他去了。千夫长既知道他是罗马人，又因为捆绑了他，也害怕了。"},{"start":30,"end":30,"text":"第二天，千夫长为要知道犹太人控告保罗的实情，便解开他，吩咐祭司长和全公会的人都聚集，将保罗带下来，叫他站在他们面前。"}]},"DEU":{"5":[{"start":12,"end":12,"text":"「『当照耶和华—你　神所吩咐的守安息日为圣日。"},{"start":13,"end":13,"text":"六日要劳碌做你一切的工，"},{"start":14,"end":14,"text":"但第七日是向耶和华—你　神当守的安息日。[这一日]，你和你的儿女、仆婢、牛、驴、牲畜，并在你城里寄居的客旅，无论何工都不可做，使你的仆婢可以和你一样安息。"},{"start":15,"end":15,"text":"你也要记念你在埃及地作过奴仆；耶和华—你　神用大能的手和伸出来的膀臂将你从那里领出来。因此，耶和华—你的　神吩咐你守安息日。"}],"6":[{"start":1,"end":1,"text":"「这是耶和华—你们　神所吩咐教训你们的诫命、律例、典章，使你们在所要过去得为业的地上遵行，"},{"start":2,"end":2,"text":"好叫你和你子子孙孙一生敬畏耶和华—你的　神，谨守他的一切律例诫命，就是我所吩咐你的，使你的日子得以长久。"},{"start":3,"end":3,"text":"以色列啊，你要听，要谨守遵行，使你可以在那流奶与蜜之地得以享福，人数极其增多，正如耶和华—你列祖的　神所应许你的。"},{"start":4,"end":4,"text":"「以色列啊，你要听！耶和华—我们　神是独一的主。"},{"start":5,"end":5,"text":"你要尽心、尽性、尽力爱耶和华—你的　神。"},{"start":6,"end":6,"text":"我今日所吩咐你的话都要记在心上，"},{"start":7,"end":7,"text":"也要殷勤教训你的儿女。无论你坐在家里，行在路上，躺下，起来，都要谈论。"},{"start":8,"end":8,"text":"也要系在手上为记号，戴在额上为经文；"},{"start":9,"end":9,"text":"又要写在你房屋的门框上，并你的城门上。」"},{"start":10,"end":10,"text":"「耶和华—你的　神领你进他向你列祖亚伯拉罕、以撒、雅各起誓应许给你的地。那里有城邑，又大又美，非你所建造的；"},{"start":11,"end":11,"text":"有房屋，装满各样美物，非你所装满的；有凿成的水井，非你所凿成的；还有葡萄园、橄榄园，非你所栽种的；你吃了而且饱足。"},{"start":12,"end":12,"text":"那时你要谨慎，免得你忘记将你从埃及地、为奴之家领出来的耶和华。"},{"start":13,"end":13,"text":"你要敬畏耶和华—你的　神，事奉他，指着他的名起誓。"},{"start":14,"end":14,"text":"不可随从别神，就是你们四围国民的神；"},{"start":15,"end":15,"text":"因为在你们中间的耶和华—你　神是忌邪的　神，惟恐耶和华—你　神的怒气向你发作，就把你从地上除灭。"},{"start":16,"end":16,"text":"「你们不可试探耶和华—你们的　神，像你们在玛撒那样试探他。"},{"start":17,"end":17,"text":"要留意遵守耶和华—你们　神所吩咐的诫命、法度、律例。"},{"start":18,"end":18,"text":"耶和华眼中看为正、看为善的，你都要遵行，使你可以享福，并可以进去得耶和华向你列祖起誓应许的那美地，"},{"start":19,"end":19,"text":"照耶和华所说的，从你面前撵出你的一切仇敌。"},{"start":20,"end":20,"text":"「日后，你的儿子问你说：『耶和华—我们　神吩咐你们的这些法度、律例、典章是什么意思呢？』"},{"start":21,"end":21,"text":"你就告诉你的儿子说：『我们在埃及作过法老的奴仆；耶和华用大能的手将我们从埃及领出来，"},{"start":22,"end":22,"text":"在我们眼前，将重大可怕的神迹奇事施行在埃及地和法老并他全家的身上，"},{"start":23,"end":23,"text":"将我们从那里领出来，要领我们进入他向我们列祖起誓应许之地，把这地赐给我们。"},{"start":24,"end":24,"text":"耶和华又吩咐我们遵行这一切律例，要敬畏耶和华—我们的　神，使我们常得好处，蒙他保全我们的生命，像今日一样。"},{"start":25,"end":25,"text":"我们若照耶和华—我们　神所吩咐的一切诫命谨守遵行，这就是我们的义了。』」"}],"8":[{"start":2,"end":2,"text":"你也要记念耶和华—你的　神在旷野引导你这四十年，是要苦炼你，试验你，要知道你心内如何，肯守他的诫命不肯。"},{"start":3,"end":3,"text":"他苦炼你，任你饥饿，将你和你列祖所不认识的吗哪赐给你吃，使你知道，人活着不是单靠食物，乃是靠耶和华口里所出的一切话。"},{"start":4,"end":4,"text":"这四十年，你的衣服没有穿破，你的脚也没有肿。"},{"start":5,"end":5,"text":"你当心里思想，耶和华—你　神管教你，好像人管教儿子一样。"},{"start":10,"end":10,"text":"你吃得饱足，就要称颂耶和华—你的　神，因他将那美地赐给你了。」"},{"start":11,"end":11,"text":"「你要谨慎，免得忘记耶和华—你的　神，不守他的诫命、典章、律例，就是我今日所吩咐你的；"},{"start":12,"end":12,"text":"恐怕你吃得饱足，建造美好的房屋居住，"},{"start":13,"end":13,"text":"你的牛羊加多，你的金银增添，并你所有的全都加增，"},{"start":14,"end":14,"text":"你就心高气傲，忘记耶和华—你的　神，就是将你从埃及地为奴之家领出来的，"},{"start":15,"end":15,"text":"引你经过那大而可怕的旷野，[那里]有火蛇、蝎子、干旱无水之地。他曾为你使水从坚硬的磐石中流出来，"},{"start":16,"end":16,"text":"又在旷野将你列祖所不认识的吗哪赐给你吃，是要苦炼你，试验你，叫你终久享福；"},{"start":17,"end":17,"text":"[恐怕]你心里说：『这货财是我力量、我能力得来的。』"},{"start":18,"end":18,"text":"你要记念耶和华—你的　神，因为得货财的力量是他给你的，为要坚定他向你列祖起誓所立的约，像今日一样。"}],"10":[{"start":17,"end":17,"text":"因为耶和华—你们的　神—他是万神之神，万主之主，至大的　神，大有能力，大而可畏，不以貌取人，也不受贿赂。"},{"start":18,"end":18,"text":"他为孤儿寡妇伸冤，又怜爱寄居的，赐给他衣食。"}],"15":[{"start":7,"end":7,"text":"「在耶和华—你　神所赐你的地上，无论哪一座城里，你弟兄中若有一个穷人，你不可忍着心、揝着手不帮补你穷乏的弟兄。"},{"start":8,"end":8,"text":"总要向他松开手，照他所缺乏的借给他，补他的不足。"},{"start":9,"end":9,"text":"你要谨慎，不可心里起恶念，说：『第七年的豁免年快到了』，你便恶眼看你穷乏的弟兄，什么都不给他，以致他因你求告耶和华，罪便归于你了。"},{"start":10,"end":10,"text":"你总要给他，给他的时候心里不可愁烦；因耶和华—你的　神必在你这一切所行的，并你手里所办的事上，赐福与你。"},{"start":11,"end":11,"text":"原来那地上的穷人永不断绝；所以我吩咐你说：『总要向你地上困苦穷乏的弟兄松开手。』」"}],"19":[{"start":15,"end":15,"text":"「人无论犯什么罪，作什么恶，不可凭一个人的口作见证，总要凭两三个人的口作见证才可定案。"},{"start":16,"end":16,"text":"若有凶恶的见证人起来，见证某人作恶，"},{"start":17,"end":17,"text":"这两个争讼的人就要站在耶和华面前，和当时的祭司，并审判官面前，"},{"start":18,"end":18,"text":"审判官要细细地查究，若见证人果然是作假见证的，以假见证陷害弟兄，"},{"start":19,"end":19,"text":"你们就要待他如同他想要待的弟兄。这样，就把那恶从你们中间除掉。"},{"start":20,"end":20,"text":"别人听见都要害怕，就不敢在你们中间再行这样的恶了。"},{"start":21,"end":21,"text":"你眼不可顾惜，要以命偿命，以眼还眼，以牙还牙，以手还手，以脚还脚。」"}],"21":[{"start":22,"end":22,"text":"「人若犯该死的罪，被治死了，你将他挂在木头上，"},{"start":23,"end":23,"text":"他的尸首不可留在木头上过夜，必要当日将他葬埋，免得玷污了耶和华—你　神所赐你为业之地。因为被挂的人是在　神面前受咒诅的。"}],"24":[{"start":17,"end":17,"text":"「你不可向寄居的和孤儿屈枉正直，也不可拿寡妇的衣裳作当头。"},{"start":18,"end":18,"text":"要记念你在埃及作过奴仆。耶和华—你的　神从那里将你救赎，所以我吩咐你这样行。"},{"start":19,"end":19,"text":"「你在田间收割庄稼，若忘下一捆，不可回去再取，要留给寄居的与孤儿寡妇。这样，耶和华—你　神必在你手里所办的一切事上赐福与你。"},{"start":20,"end":20,"text":"你打橄榄树，枝上剩下的，不可再打；要留给寄居的与孤儿寡妇。"},{"start":21,"end":21,"text":"你摘葡萄园的[葡萄]，所剩下的，不可再摘；要留给寄居的与孤儿寡妇。"},{"start":22,"end":22,"text":"你也要记念你在埃及地作过奴仆，所以我吩咐你这样行。"}],"25":[{"start":5,"end":5,"text":"「弟兄同居，若死了一个，没有儿子，死人的妻不可出嫁外人，她丈夫的兄弟当尽弟兄的本分，娶她为妻，与她同房。"},{"start":6,"end":6,"text":"妇人生的长子必归死兄的名下，免得他的名在以色列中涂抹了。"},{"start":7,"end":7,"text":"那人若不愿意娶她哥哥的妻，他哥哥的妻就要到城门长老那里，说：『我丈夫的兄弟不肯在以色列中兴起他哥哥的名字，不给我尽弟兄的本分。』"},{"start":8,"end":8,"text":"本城的长老就要召那人来问他，他若执意说：『我不愿意娶她』，"},{"start":9,"end":9,"text":"他哥哥的妻就要当着长老到那人的跟前，脱了他的鞋，吐唾沫在他脸上，说：『凡不为哥哥建立家室的都要这样待他。』"},{"start":10,"end":10,"text":"在以色列中，他的名必称为脱鞋之家。」"}],"30":[{"start":11,"end":11,"text":"「我今日所吩咐你的诫命不是你难行的，也不是离你远的；"},{"start":12,"end":12,"text":"不是在天上，使你说：『谁替我们上天取下来，使我们听见可以遵行呢？』"},{"start":13,"end":13,"text":"也不是在海外，使你说：『谁替我们过海取了来，使我们听见可以遵行呢？』"},{"start":14,"end":14,"text":"这话却离你甚近，就在你口中，在你心里，使你可以遵行。"}],"32":[{"start":11,"end":11,"text":"又如鹰搅动巢窝， 在雏鹰以上两翅搧展， 接取雏鹰，背在两翼之上。"},{"start":12,"end":12,"text":"这样，耶和华独自引导他， 并无外邦神与他同在。"},{"start":13,"end":13,"text":"耶和华使他乘驾地的高处， 得吃田间的土产； 又使他从磐石中咂蜜， 从坚石中吸油；"},{"start":14,"end":14,"text":"也吃牛的奶油， 羊的奶，羊羔的脂油， 巴珊所出的公绵羊和山羊， 与上好的麦子， 也喝葡萄汁酿的酒。"},{"start":15,"end":15,"text":"但耶书 渐渐肥胖，粗壮， 光润，踢跳，[奔跑]， 便离弃造他的　神， 轻看救他的磐石；"},{"start":16,"end":16,"text":"敬拜别[神]，触动　神的愤恨， 行可憎恶的事，惹了他的怒气。"},{"start":17,"end":17,"text":"所祭祀的鬼魔并非真神， 乃是素不认识的神， 是近来新兴的， 是你列祖所不畏惧的。"},{"start":18,"end":18,"text":"你轻忽生你的磐石， 忘记产你的　神。"},{"start":19,"end":19,"text":"耶和华看见他的儿女惹动他， 就厌恶[他们]，说："},{"start":20,"end":20,"text":"我要向他们掩面， 看他们的结局如何。 他们本是极乖僻的族类， 心中无诚实的儿女。"},{"start":21,"end":21,"text":"他们以那「不算为神」的触动我的愤恨， 以虚无[的神]惹了我的怒气。 我也要以那「不成子民」的触动他们的愤恨， 以愚昧的国民惹了他们的怒气。"},{"start":22,"end":22,"text":"因为在我怒中有火烧起， 直烧到极深的阴间， 把地和地的出产尽都焚烧， 山的根基也烧着了。"},{"start":23,"end":23,"text":"我要将祸患堆在他们身上， 把我的箭向他们射尽。"},{"start":24,"end":24,"text":"[他们必]因饥饿消瘦， 被炎热苦毒吞灭。 我要打发野兽用牙齿咬他们， 并土中腹行的，用毒气害他们。"},{"start":25,"end":25,"text":"外头有刀剑，内室有惊恐， 使人丧亡，使少男、童女、 吃奶的、白发的，[尽都灭绝]。"},{"start":26,"end":26,"text":"我说，我必将他们分散远方， 使他们的名号从人间除灭。"},{"start":27,"end":27,"text":"惟恐仇敌惹动我， 只怕敌人错看，说：是我们手的能力， 并非耶和华所行的。"},{"start":28,"end":28,"text":"因为以色列民毫无计谋， 心中没有聪明。"},{"start":29,"end":29,"text":"惟愿他们有智慧， 能明白这事，肯思念他们的结局。"},{"start":30,"end":30,"text":"若不是他们的磐石卖了他们， 若不是耶和华交出他们， 一人焉能追赶他们千人？ 二人焉能使万人逃跑呢？"},{"start":31,"end":31,"text":"据我们的仇敌自己断定， 他们的磐石不如我们的磐石。"},{"start":32,"end":32,"text":"他们的葡萄树是所多玛的葡萄树， 蛾摩拉田园所生的； 他们的葡萄是毒葡萄， 全挂都是苦的。"},{"start":33,"end":33,"text":"他们的酒是大蛇的毒气， 是虺蛇残害的恶毒。"},{"start":34,"end":34,"text":"这不都是积蓄在我这里， 封锁在我府库中吗？"},{"start":35,"end":35,"text":"他们失脚的时候，伸冤报应在我； 因他们遭灾的日子近了； 那要临在他们身上的必速速来到。"},{"start":36,"end":36,"text":"耶和华见他百姓毫无能力， 无论困住的、自由的都没有[剩下]， 就必为他们伸冤， 为他的仆人后悔。"},{"start":37,"end":37,"text":"他必说：他们的神， 他们所投靠的磐石，"},{"start":38,"end":38,"text":"就是向来吃他们祭牲的脂油， 喝他们奠祭之酒的，在哪里呢？ 他可以兴起帮助你们， 护卫你们。"},{"start":39,"end":39,"text":"你们如今要知道： 我，惟有我是　神； 在我以外并无别神。 我使人死，我使人活； 我损伤，我也医治， 并无人能从我手中救出来。"},{"start":40,"end":40,"text":"我向天举手说： 我凭我的永生起誓："},{"start":41,"end":41,"text":"我若磨我闪亮的刀， 手掌审判之权， 就必报复我的敌人， 报应恨我的人。"},{"start":42,"end":42,"text":"我要使我的箭饮血饮醉， 就是被杀被掳之人的血。 我的刀要吃肉， 乃是仇敌中首领之头的肉。"},{"start":43,"end":43,"text":"你们外邦人当与主的百姓一同欢呼； 因他要伸他仆人流血的冤， 报应他的敌人， 洁净他的地，救赎他的百姓。"},{"start":44,"end":44,"text":"摩西和嫩的儿子约书亚去将这歌的一切话说给百姓听。"},{"start":45,"end":45,"text":"摩西向以色列众人说完了这一切的话，"},{"start":46,"end":46,"text":"又说：「我今日所警教你们的，你们都要放在心上；要吩咐你们的子孙谨守遵行这律法上的话。"},{"start":47,"end":47,"text":"因为这不是虚空、与你们无关的事，乃是你们的生命；在你们过约旦河要得为业的地上必因这事日子得以长久。」"},{"start":48,"end":48,"text":"当日，耶和华吩咐摩西说："},{"start":49,"end":49,"text":"「你上这亚巴琳山中的尼波山去，在摩押地与耶利哥相对，观看我所要赐给以色列人为业的迦南地。"},{"start":50,"end":50,"text":"你必死在你所登的山上，归你列祖去，像你哥哥亚伦死在何珥山上，归他的列祖一样。"},{"start":51,"end":51,"text":"因为你们在寻的旷野，加低斯的米利巴水，在以色列人中没有尊我为圣，得罪了我。"},{"start":52,"end":52,"text":"我所赐给以色列人的地，你可以远远地观看，却不得进去。」"}]},"MAL":{"3":[{"start":1,"end":1,"text":"万军之耶和华说：「我要差遣我的使者在我前面预备道路。你们所寻求的主必忽然进入他的殿；立约的使者，就是你们所仰慕的，快要来到。」"},{"start":2,"end":2,"text":"他来的日子，谁能当得起呢？他显现的时候，谁能立得住呢？因为他如炼[金]之人的火，如漂布之人的硷。"},{"start":3,"end":3,"text":"他必坐下如炼净银子的，必洁净利未人，熬炼他们像金银一样；他们就凭公义献供物给耶和华。"},{"start":4,"end":4,"text":"那时，犹大和耶路撒冷所献的供物必蒙耶和华悦纳，仿佛古时之日、上古之年。"},{"start":5,"end":5,"text":"万军之耶和华说：「我必临近你们，施行审判。我必速速作见证，警戒行邪术的、犯奸淫的、起假誓的、亏负人之工价的、欺压寡妇孤儿的、屈枉寄居的，和不敬畏我的。」"},{"start":6,"end":6,"text":"「因我—耶和华是不改变的，所以你们雅各之子没有灭亡。"},{"start":7,"end":7,"text":"万军之耶和华说：从你们列祖的日子以来，你们常常偏离我的典章而不遵守。现在你们要转向我，我就转向你们。你们却问说：『我们如何才是转向呢？』"},{"start":8,"end":8,"text":"人岂可夺取　神之物呢？你们竟夺取我[的供物]。你们却说：『我们在何事上夺取你[的供物]呢？』就是你们在当纳的十分之一和当献的供物上。"},{"start":9,"end":9,"text":"因你们通国的人都夺取我[的供物]，咒诅就临到你们身上。"},{"start":10,"end":10,"text":"万军之耶和华说：你们要将当纳的十分之一全然送入仓库，使我家有粮，以此试试我，是否为你们敞开天上的窗户，倾福与你们，甚至无处可容。"},{"start":11,"end":11,"text":"万军之耶和华说：我必为你们斥责蝗虫，不容它毁坏你们的土产。你们田间的葡萄树在未熟之先也不掉果子。"},{"start":12,"end":12,"text":"万军之耶和华说：万国必称你们为有福的，因你们的地必成为喜乐之地。」"},{"start":13,"end":13,"text":"耶和华说：「你们用话顶撞我，你们还说：『我们用什么话顶撞了你呢？』"},{"start":14,"end":14,"text":"你们说：『事奉　神是徒然的，遵守　神所吩咐的，在万军之耶和华面前苦苦斋戒，有什么益处呢？"},{"start":15,"end":15,"text":"如今我们称狂傲的人为有福，并且行恶的人得建立；他们虽然试探　神，却得脱离[灾难]。』」"},{"start":16,"end":16,"text":"那时，敬畏耶和华的彼此谈论，耶和华侧耳而听，且有纪念册在他面前，记录那敬畏耶和华、思念他名的人。"},{"start":17,"end":17,"text":"万军之耶和华说：「在我所定的日子，他们必属我，特特归我。我必怜恤他们，如同人怜恤服事自己的儿子。"},{"start":18,"end":18,"text":"那时你们必归回，将善人和恶人，事奉　神的和不事奉　神的，分别出来。」"}],"4":[{"start":4,"end":4,"text":"「你们当记念我仆人摩西的律法，就是我在何烈[山]为以色列众人所吩咐他的律例典章。"},{"start":5,"end":5,"text":"「看哪，耶和华大而可畏之日未到以前，我必差遣先知以利亚到你们那里去。"},{"start":6,"end":6,"text":"他必使父亲的心转向儿女，儿女的心转向父亲，免得我来咒诅遍地。」"}]},"ISA":{"1":[{"start":10,"end":10,"text":"你们这所多玛的官长啊， 要听耶和华的话！ 你们这蛾摩拉的百姓啊， 要侧耳听我们　神的训诲！"},{"start":11,"end":11,"text":"耶和华说： 你们所献的许多祭物与我何益呢？ 公绵羊的燔祭和肥畜的脂油， 我已经够了； 公牛的血，羊羔的血，公山羊的血， 我都不喜悦。"},{"start":12,"end":12,"text":"你们来朝见我， 谁向你们讨这些， 使你们践踏我的院宇呢？"},{"start":13,"end":13,"text":"你们不要再献虚浮的供物。 香品是我所憎恶的； 月朔和安息日，并宣召的大会， 也是我所憎恶的； 作罪孽，又守严肃会， 我也不能容忍。"},{"start":14,"end":14,"text":"你们的月朔和节期，我心里恨恶， 我都以为麻烦； 我担当，便不耐烦。"},{"start":15,"end":15,"text":"你们举手祷告，我必遮眼不看； 就是你们多多地祈祷，我也不听。 你们的手都满了[杀人的]血。"},{"start":16,"end":16,"text":"你们要洗濯、自洁， 从我眼前除掉你们的恶行， 要止住作恶，"},{"start":17,"end":17,"text":"学习行善， 寻求公平， 解救受欺压的； 给孤儿伸冤， 为寡妇辨屈。"}],"4":[{"start":5,"end":5,"text":"耶和华也必在锡安全山，并各会众以上，使白日有烟云，黑夜有火焰的光。因为在全荣耀之上必有遮蔽。"},{"start":6,"end":6,"text":"必有亭子，白日可以得荫避暑，也可以作为藏身之处，躲避狂风暴雨。"}],"5":[{"start":1,"end":1,"text":"我要为我所亲爱的唱歌， 是我所爱者的歌，论他葡萄园的事： 我所亲爱的有葡萄园在肥美的山冈上。"},{"start":2,"end":2,"text":"他刨挖园子，捡去石头， 栽种上等的葡萄树， 在园中盖了一座楼， 又凿出压酒池； 指望结[好]葡萄， 反倒结了野葡萄。"},{"start":3,"end":3,"text":"耶路撒冷的居民和犹大人哪， 请你们现今在我与我的葡萄园中，断定是非。"},{"start":4,"end":4,"text":"我为我葡萄园所做之外， 还有什么可做的呢？ 我指望结[好]葡萄， 怎么倒结了野葡萄呢？"},{"start":5,"end":5,"text":"现在我告诉你们， 我要向我葡萄园怎样行： 我必撤去篱笆，使它被吞灭， 拆毁墙垣，使它被践踏。"},{"start":6,"end":6,"text":"我必使它荒废，不再修理， 不再锄刨，荆棘蒺藜倒要生长。 我也必命云不降雨在其上。"},{"start":7,"end":7,"text":"万军之耶和华的葡萄园就是以色列家； 他所喜爱的树就是犹大人。 他指望的是公平， 谁知倒有暴虐； 指望的是公义， 谁知倒有冤声。"}],"8":[{"start":12,"end":12,"text":"「这百姓说同谋背叛，你们不要说同谋背叛。他们所怕的，你们不要怕，也不要畏惧。"},{"start":13,"end":13,"text":"但要尊万军之耶和华为圣，以他为你们所当怕的，所当畏惧的。"}],"9":[{"start":2,"end":2,"text":"在黑暗中行走的百姓看见了大光； 住在死荫之地的人有光照耀他们。"},{"start":3,"end":3,"text":"你使这国民繁多， 加增他们的喜乐； 他们在你面前欢喜， 好像收割的欢喜， 像人分掳物那样的快乐。"},{"start":4,"end":4,"text":"因为他们所负的重轭 和肩头上的杖， 并欺压他们人的棍， 你都已经折断， 好像在米甸的日子一样。"},{"start":5,"end":5,"text":"战士在乱杀之间所穿戴的盔甲， 并那滚在血中的衣服， 都必作为可烧的， 当作火柴。"},{"start":6,"end":6,"text":"因有一婴孩为我们而生； 有一子赐给我们。 政权必担在他的肩头上； 他名称为「奇妙策士、全能的　神、永在的父、和平的君」。"},{"start":7,"end":7,"text":"他的政权与平安必加增无穷。 他必在大卫的宝座上治理他的国， 以公平公义使国坚定稳固， 从今直到永远。 万军之耶和华的热心必成就这事。"},{"start":8,"end":8,"text":"主使一言入于雅各[家]， 落于以色列[家]。"},{"start":9,"end":9,"text":"这众百姓，就是以法莲 和撒马利亚的居民，都要知道； 他们凭骄傲自大的心说："},{"start":10,"end":10,"text":"砖[墙]塌了，我们却要凿石头建筑； 桑树砍了，我们却要换香柏树。"},{"start":11,"end":11,"text":"因此，耶和华要高举利汛的敌人 来攻击以色列， 并要激动以色列的仇敌。"},{"start":12,"end":12,"text":"东有亚兰人，西有非利士人； 他们张口要吞吃以色列。 虽然如此，耶和华的怒气还未转消； 他的手仍伸不缩。"},{"start":13,"end":13,"text":"这百姓还没有归向击打他们的主， 也没有寻求万军之耶和华。"},{"start":14,"end":14,"text":"因此，耶和华一日之间 必从以色列中剪除头与尾， 棕枝与芦苇—"},{"start":15,"end":15,"text":"长老和尊贵人就是头， 以谎言教人的先知就是尾。"},{"start":16,"end":16,"text":"因为，引导这百姓的使他们走错了路； 被引导的都必败亡。"},{"start":17,"end":17,"text":"所以，主必不喜悦他们的少年人， 也不怜恤他们的孤儿寡妇； 因为，各人是亵渎的，是行恶的， 并且各人的口都说愚妄的话。 虽然如此，耶和华的怒气还未转消； 他的手仍伸不缩。"},{"start":18,"end":18,"text":"邪恶像火焚烧， 烧灭荆棘和蒺藜， 在稠密的树林中着起来， 就成为烟柱，旋转上腾。"},{"start":19,"end":19,"text":"因万军之耶和华的烈怒，地都烧遍； 百姓成为火柴； 无人怜爱弟兄。"},{"start":20,"end":20,"text":"有人右边抢夺，仍受饥饿， 左边吞吃，仍不饱足； 各人吃自己膀臂上的肉。"},{"start":21,"end":21,"text":"玛拿西[吞吃]以法莲； 以法莲[吞吃]玛拿西， 又一同攻击犹大。 虽然如此，耶和华的怒气还未转消； 他的手仍伸不缩。"}],"13":[{"start":9,"end":9,"text":"耶和华的日子临到， 必有残忍、忿恨、烈怒， 使这地荒凉， 从其中除灭罪人。"},{"start":10,"end":10,"text":"天上的众星群宿都不发光； 日头一出就变黑暗； 月亮也不放光。"},{"start":11,"end":11,"text":"我必因邪恶刑罚世界， 因罪孽刑罚恶人， 使骄傲人的狂妄止息， 制伏强暴人的狂傲。"},{"start":12,"end":12,"text":"我必使人比精金还少， 使人比俄斐纯金更少。"},{"start":13,"end":13,"text":"我—万军之耶和华在忿恨中发烈怒的日子， 必使天震动， 使地摇撼，离其本位。"}],"25":[{"start":6,"end":6,"text":"在这山上，万军之耶和华必为万民用肥甘设摆筵席，用陈酒和满髓的肥甘，并澄清的陈酒，设摆筵席。"},{"start":7,"end":7,"text":"他又必在这山上除灭遮盖万民之物和遮蔽万国蒙脸的帕子。"},{"start":8,"end":8,"text":"他已经吞灭死亡直到永远。主耶和华必擦去各人脸上的眼泪，又除掉普天下他百姓的羞辱，因为这是耶和华说的。"},{"start":9,"end":9,"text":"到那日，人必说：「看哪，这是我们的　神；我们素来等候他，他必拯救我们。这是耶和华，我们素来等候他，我们必因他的救恩欢喜快乐。」"}],"29":[{"start":14,"end":14,"text":"所以，我在这百姓中要行奇妙的事， 就是奇妙又奇妙的事。 他们智慧人的智慧必然消灭， 聪明人的聪明必然隐藏。"},{"start":15,"end":15,"text":"祸哉！那些向耶和华深藏谋略的， 又在暗中行事，说： 谁看见我们呢？ 谁知道我们呢？"},{"start":16,"end":16,"text":"你们把事颠倒了， 岂可看窑匠如泥吗？ 被制作的物岂可论制作物的说： 他没有制作我？ 或是被创造的物论造物的说： 他没有聪明？"},{"start":17,"end":17,"text":"黎巴嫩变为肥田， 肥田看如树林， 不是只有一点点时候吗？"},{"start":18,"end":18,"text":"那时，聋子必听见这书上的话； 瞎子的眼必从迷蒙黑暗中得以看见。"},{"start":19,"end":19,"text":"谦卑人必因耶和华增添欢喜； 人间贫穷的必因以色列的圣者快乐。"},{"start":20,"end":20,"text":"因为，强暴人已归无有， 亵慢人已经灭绝， 一切找机会作孽的都被剪除。"},{"start":21,"end":21,"text":"他们在争讼的事上定[无罪的]为有罪， 为城门口责备人的设下网罗， 用虚无的事屈枉义人。"},{"start":22,"end":22,"text":"所以，救赎亚伯拉罕的耶和华 论雅各家如此说： 雅各必不再羞愧， 面容也不致变色。"},{"start":23,"end":23,"text":"但他看见他的众子， 就是我手的工作在他那里， 他们必尊我的名为圣， 必尊雅各的圣者为圣， 必敬畏以色列的　神。"},{"start":24,"end":24,"text":"心中迷糊的必得明白； 发怨言的必受训诲。"}],"35":[{"start":5,"end":5,"text":"那时，瞎子的眼必睁开； 聋子的耳必开通。"},{"start":6,"end":6,"text":"那时，瘸子必跳跃像鹿； 哑巴的舌头必能歌唱。 在旷野必有水发出； 在沙漠必有河涌流。"}],"40":[{"start":3,"end":3,"text":"有人声喊着说： 在旷野预备耶和华的路， 在沙漠地修平我们　神的道。"},{"start":4,"end":4,"text":"一切山洼都要填满， 大小山冈都要削平； 高高低低的要改为平坦， 崎崎岖岖的必成为平原。"},{"start":5,"end":5,"text":"耶和华的荣耀必然显现； 凡有血气的必一同看见； 因为这是耶和华亲口说的。"},{"start":6,"end":6,"text":"有人声说：你喊叫吧！ 有一个说：我喊叫什么呢？ [说]：凡有血气的尽都如草； 他的美容都像野地的花。"},{"start":7,"end":7,"text":"草必枯干，花必凋残， 因为耶和华的气吹在其上； 百姓诚然是草。"},{"start":8,"end":8,"text":"草必枯干，花必凋残， 惟有我们　神的话必永远立定。"},{"start":9,"end":9,"text":"报好信息给锡安的啊， 你要登高山； 报好信息给耶路撒冷的啊， 你要极力扬声。 扬声不要惧怕， 对犹大的城邑说： 看哪，你们的　神！"},{"start":10,"end":10,"text":"主耶和华必像大能者临到； 他的膀臂必为他掌权。 他的赏赐在他那里； 他的报应在他面前。"},{"start":11,"end":11,"text":"他必像牧人牧养自己的羊群， 用膀臂聚集羊羔抱在怀中， 慢慢引导那乳养小羊的。"},{"start":12,"end":12,"text":"谁曾用手心量诸水， 用手虎口量苍天， 用升斗盛大地的尘土， 用秤称山岭， 用天平平冈陵呢？"},{"start":13,"end":13,"text":"谁曾测度耶和华的心， 或作他的谋士指教他呢？"},{"start":14,"end":14,"text":"他与谁商议，谁教导他， 谁将公平的路指示他， 又将知识教训他， 将通达的道指教他呢？"},{"start":15,"end":15,"text":"看哪，万民都像水桶的一滴， 又算如天平上的微尘； 他举起众海岛，好像极微之物。"},{"start":16,"end":16,"text":"黎巴嫩[的树林]不够当柴烧； 其中的走兽也不够作燔祭。"},{"start":17,"end":17,"text":"万民在他面前好像虚无， 被他看为不及虚无，乃为虚空。"},{"start":18,"end":18,"text":"你们究竟将谁比　神， 用什么形象与　神比较呢？"},{"start":19,"end":19,"text":"偶像是匠人铸造， 银匠用金包裹， [为它]铸造银链。"},{"start":20,"end":20,"text":"穷乏献不起[这样]供物的， 就拣选不能朽坏的树木， 为自己寻找巧匠， 立起不能摇动的偶像。"},{"start":21,"end":21,"text":"你们岂不曾知道吗？ 你们岂不曾听见吗？ 从起初岂没有人告诉你们吗？ 自从立地的根基， 你们岂没有明白吗？"},{"start":22,"end":22,"text":"神坐在地球大圈之上； 地上的居民好像蝗虫。 他铺张穹苍如幔子， 展开诸天如可住的帐棚。"},{"start":23,"end":23,"text":"他使君王归于虚无， 使地上的审判官成为虚空。"},{"start":24,"end":24,"text":"他们是刚才栽上， 刚才种上， 根也刚才扎在地里， 他一吹在其上，便都枯干； 旋风将他们吹去，像碎秸一样。"},{"start":25,"end":25,"text":"那圣者说：你们将谁比我， 叫他与我相等呢？"},{"start":26,"end":26,"text":"你们向上举目， 看谁创造这万象， 按数目领出， 他一一称其名； 因他的权能， 又因他的大能大力， 连一个都不缺。"},{"start":27,"end":27,"text":"雅各啊，你为何说， 我的道路向耶和华隐藏？ 以色列啊，你为何言， 我的冤屈　神并不查问？"},{"start":28,"end":28,"text":"你岂不曾知道吗？ 你岂不曾听见吗？ 永在的　神耶和华，创造地极的[主]， 并不疲乏，也不困倦； 他的智慧无法测度。"},{"start":29,"end":29,"text":"疲乏的，他赐能力； 软弱的，他加力量。"},{"start":30,"end":30,"text":"就是少年人也要疲乏困倦； 强壮的也必全然跌倒。"},{"start":31,"end":31,"text":"但那等候耶和华的必从新得力。 他们必如鹰展翅上腾； 他们奔跑却不困倦， 行走却不疲乏。"}],"42":[{"start":1,"end":1,"text":"看哪，我的仆人— 我所扶持所拣选、心里所喜悦的！ 我已将我的灵赐给他； 他必将公理传给外邦。"},{"start":2,"end":2,"text":"他不喧嚷，不扬声， 也不使街上听见他的声音。"},{"start":3,"end":3,"text":"压伤的芦苇，他不折断； 将残的灯火，他不吹灭。 他凭真实将公理传开。"},{"start":4,"end":4,"text":"他不灰心，也不丧胆， 直到他在地上设立公理； 海岛都等候他的训诲。"},{"start":5,"end":5,"text":"创造诸天，铺张穹苍， 将地和地所出的一并铺开， 赐气息给地上的众人， 又赐灵性给行在其上之人的　神耶和华， 他如此说："},{"start":6,"end":6,"text":"我—耶和华凭公义召你， 必搀扶你的手，保守你， 使你作众民的中保， 作外邦人的光，"},{"start":7,"end":7,"text":"开瞎子的眼， 领被囚的出牢狱， 领坐黑暗的出监牢。"},{"start":8,"end":8,"text":"我是耶和华，这是我的名； 我必不将我的荣耀归给假神， 也不将我的称赞归给雕刻的偶像。"},{"start":9,"end":9,"text":"看哪，先前的事已经成就， 现在我将新事说明， 这事未发以先，我就说给你们听。"},{"start":10,"end":10,"text":"航海的和海中所有的， 海岛和其上的居民， 都当向耶和华唱新歌， 从地极赞美他。"},{"start":11,"end":11,"text":"旷野和其中的城邑， 并基达人居住的村庄都当扬声； 西拉的居民当欢呼， 在山顶上呐喊。"},{"start":12,"end":12,"text":"他们当将荣耀归给耶和华， 在海岛中传扬他的颂赞。"},{"start":13,"end":13,"text":"耶和华必像勇士出去， 必像战士激动热心， 要喊叫，大声呐喊， 要用大力攻击仇敌。"},{"start":14,"end":14,"text":"我许久闭口不言，静默不语； [现在]我要喊叫，像产难的妇人； 我要急气而喘哮。"},{"start":15,"end":15,"text":"我要使大山小冈变为荒场， 使其上的花草都枯干； 我要使江河变为洲岛， 使水池都干涸。"},{"start":16,"end":16,"text":"我要引瞎子行不认识的道， 领他们走不知道的路； 在他们面前使黑暗变为光明， 使弯曲变为平直。 这些事我都要行， 并不离弃他们。"},{"start":17,"end":17,"text":"倚靠雕刻的偶像， 对铸造的偶像说： 你是我们的神； 这等人要退后，全然蒙羞。"},{"start":18,"end":18,"text":"你们这耳聋的，听吧！ 你们这眼瞎的，看吧！ 使你们能看见。"},{"start":19,"end":19,"text":"谁比我的仆人眼瞎呢？ 谁比我差遣的使者耳聋呢？ 谁瞎眼像那[与我]和好的？ 谁瞎眼像耶和华的仆人呢？"},{"start":20,"end":20,"text":"你看见许多事却不领会， 耳朵开通却不听见。"},{"start":21,"end":21,"text":"耶和华因自己公义的缘故， 喜欢使律法为大，为尊。"},{"start":22,"end":22,"text":"但这百姓是被抢被夺的， 都牢笼在坑中，隐藏在狱里； 他们作掠物，无人拯救， 作掳物，无人说交还。"},{"start":23,"end":23,"text":"你们中间谁肯侧耳听此， 谁肯留心而听，以防将来呢？"},{"start":24,"end":24,"text":"谁将雅各交出当作掳物， 将以色列交给抢夺的呢？ 岂不是耶和华吗？ 就是我们所得罪的那位。 他们不肯遵行他的道， 也不听从他的训诲。"},{"start":25,"end":25,"text":"所以，他将猛烈的怒气和争战的勇力 倾倒在以色列的身上。 在他四围如火着起，他还不知道， 烧着他，他也不介意。"}],"43":[{"start":1,"end":1,"text":"雅各啊，创造你的耶和华， 以色列啊，造成你的那位， 现在如此说： 你不要害怕！因为我救赎了你。 我曾提你的名召你，你是属我的。"},{"start":2,"end":2,"text":"你从水中经过，我必与你同在； 你趟过江河，水必不漫过你； 你从火中行过，必不被烧， 火焰也不着在你身上。"},{"start":3,"end":3,"text":"因为我是耶和华—你的　神， 是以色列的圣者—你的救主； 我已经使埃及作你的赎价， 使古实和西巴代替你。"},{"start":4,"end":4,"text":"因我看你为宝为尊； 又因我爱你， 所以我使人代替你， 使列邦人替换你的生命。"},{"start":5,"end":5,"text":"不要害怕，因我与你同在； 我必领你的后裔从东方来， 又从西方招聚你。"},{"start":6,"end":6,"text":"我要对北方说，交出来！ 对南方说，不要拘留！ 将我的众子从远方带来， 将我的众女从地极领回，"},{"start":7,"end":7,"text":"就是凡称为我名下的人， 是我为自己的荣耀创造的， 是我所做成，所造作的。"},{"start":25,"end":25,"text":"惟有我为自己的缘故涂抹你的过犯； 我也不记念你的罪恶。"},{"start":26,"end":26,"text":"你要提醒我，你我可以一同辩论； 你可以将[你的理]陈明，自显为义。"},{"start":27,"end":27,"text":"你的始祖犯罪； 你的师傅违背我。"},{"start":28,"end":28,"text":"所以，我要辱没圣所的首领， 使雅各成为咒诅， 使以色列成为辱骂。"}],"49":[{"start":6,"end":6,"text":"现在他说：你作我的仆人， 使雅各众支派复兴， 使以色列中得保全的归回尚为小事， 我还要使你作外邦人的光， 叫你施行我的救恩，直到地极。"},{"start":7,"end":7,"text":"救赎主—以色列的圣者耶和华 对那被人所藐视、本国所憎恶、 官长所虐待的如此说： 君王要看见就站起， 首领也要下拜； 都因信实的耶和华， 就是拣选你—以色列的圣者。"},{"start":8,"end":8,"text":"耶和华如此说： 在悦纳的时候，我应允了你； 在拯救的日子，我济助了你。 我要保护你， 使你作众民的中保； 复兴遍地， 使人承受荒凉之地为业。"},{"start":9,"end":9,"text":"对那被捆绑的人说：出来吧！ 对那在黑暗的人说：显露吧！ 他们在路上必得饮食， 在一切净光的高处必有食物。"},{"start":10,"end":10,"text":"不饥不渴， 炎热和烈日必不伤害他们； 因为怜恤他们的必引导他们， 领他们到水泉旁边。"},{"start":11,"end":11,"text":"我必使我的众山成为大道； 我的大路也被修高。"},{"start":12,"end":12,"text":"看哪，这些从远方来； 这些从北方、从西方来； 这些从秦国来。"},{"start":13,"end":13,"text":"诸天哪，应当欢呼！ 大地啊，应当快乐！ 众山哪，应当发声歌唱！ 因为耶和华已经安慰他的百姓， 也要怜恤他困苦之民。"},{"start":14,"end":14,"text":"锡安说：耶和华离弃了我； 主忘记了我。"},{"start":15,"end":15,"text":"妇人焉能忘记她吃奶的婴孩， 不怜恤她所生的儿子？ 即或有忘记的， 我却不忘记你。"},{"start":16,"end":16,"text":"看哪，我将你铭刻在我掌上； 你的墙垣常在我眼前。"},{"start":17,"end":17,"text":"你的儿女必急速[归回]； 毁坏你的，使你荒废的，必都离你出去，"},{"start":18,"end":18,"text":"你举目向四方观看； 他们都聚集来到你这里。 耶和华说：我指着我的永生起誓： 你必要以他们为妆饰佩戴， 以他们为华带束腰，像新妇一样。"},{"start":19,"end":19,"text":"至于你荒废凄凉之处， 并你被毁坏之地， 现今众民居住必显为太窄； 吞灭你的必离你遥远。"},{"start":20,"end":20,"text":"你必听见丧子之后所生的儿女说： 这地方我居住太窄， 求你给我地方居住。"},{"start":21,"end":21,"text":"那时你心里必说：我既丧子独居， 是被掳的，漂流在外。 谁给我生这些？ 谁将这些养大呢？ 撇下我一人独居的时候， 这些在哪里呢？"},{"start":22,"end":22,"text":"主耶和华如此说： 我必向列国举手， 向万民竖立大旗； 他们必将你的众子怀中抱来， 将你的众女肩上扛来。"},{"start":23,"end":23,"text":"列王必作你的养父； 王后必作你的乳母。 他们必将脸伏地，向你下拜， 并舔你脚上的尘土。 你便知道我是耶和华； 等候我的必不致羞愧。"},{"start":24,"end":24,"text":"勇士抢去的岂能夺回？ 该掳掠的岂能解救吗？"},{"start":25,"end":25,"text":"但耶和华如此说： 就是勇士所掳掠的，也可以夺回； 强暴人所抢的，也可以解救。 与你相争的，我必与他相争； 我要拯救你的儿女。"},{"start":26,"end":26,"text":"并且我必使那欺压你的吃自己的肉， 也要以自己的血喝醉，好像喝甜酒一样。 凡有血气的必都知道我—耶和华是你的救主， 是你的救赎主，是雅各的大能者。"}],"50":[{"start":4,"end":4,"text":"主耶和华赐我受教者的舌头， 使我知道怎样用言语扶助疲乏的人。 主每早晨提醒， 提醒我的耳朵， 使我能听，像受教者一样。"},{"start":5,"end":5,"text":"主耶和华开通我的耳朵； 我并没有违背，也没有退后。"},{"start":6,"end":6,"text":"人打我的背，我任他打； 人拔我腮颊的胡须，我由他拔； 人辱我，吐我，我并不掩面。"},{"start":7,"end":7,"text":"主耶和华必帮助我， 所以我不抱愧。 我硬着脸面好像坚石； 我也知道我必不致蒙羞。"},{"start":8,"end":8,"text":"称我为义的与我相近； 谁与我争论， 可以与我一同站立； 谁与我作对， 可以就近我来。"},{"start":9,"end":9,"text":"主耶和华要帮助我； 谁能定我有罪呢？ 他们都像衣服渐渐旧了， 为蛀虫所咬。"}],"51":[{"start":17,"end":17,"text":"耶路撒冷啊，兴起！ 兴起！站起来！ 你从耶和华手中喝了他忿怒之杯， 喝了那使人东倒西歪的爵，以致喝尽。"},{"start":18,"end":18,"text":"她所生育的诸子中，没有一个引导她的； 她所养大的诸子中，没有一个搀扶她的。"},{"start":19,"end":19,"text":"荒凉、毁灭、饥荒、刀兵， 这几样临到你， 谁为你举哀？ 我如何能安慰你呢？"},{"start":20,"end":20,"text":"你的众子发昏， 在各市口上躺卧， 好像黄羊在网罗之中， 都满了耶和华的忿怒 —你　神的斥责。"},{"start":21,"end":21,"text":"因此，你这困苦却非因酒而醉的， 要听我言。"},{"start":22,"end":22,"text":"你的主耶和华— 就是为他百姓辨屈的　神如此说： 看哪，我已将那使人东倒西歪的杯， 就是我忿怒的爵， 从你手中接过来； 你必不致再喝。"},{"start":23,"end":23,"text":"我必将这杯递在苦待你的人手中； 他们曾对你说：你屈身， 由我们践踏过去吧！ 你便以背为地， 好像街市，任人经过。"}],"52":[{"start":7,"end":7,"text":"那报佳音，传平安， 报好信，传救恩的， 对锡安说：你的　神作王了！ 这人的脚登山何等佳美！"},{"start":8,"end":8,"text":"听啊，你守望之人的声音， 他们扬起声来，一同歌唱； 因为耶和华归回锡安的时候， 他们必亲眼看见。"},{"start":9,"end":9,"text":"耶路撒冷的荒场啊， 要发起欢声，一同歌唱； 因为耶和华安慰了他的百姓， 救赎了耶路撒冷。"},{"start":10,"end":10,"text":"耶和华在万国眼前露出圣臂； 地极的人都看见我们　神的救恩了。"},{"start":11,"end":11,"text":"你们离开吧！离开吧！ 从巴比伦出来。 不要沾不洁净的物； 要从其中出来。 你们扛抬耶和华器皿的人哪， 务要自洁。"},{"start":12,"end":12,"text":"你们出来必不致急忙， 也不致奔逃。 因为，耶和华必在你们前头行； 以色列的　神必作你们的后盾。"},{"start":13,"end":13,"text":"我的仆人行事必有智慧， 必被高举上升， 且成为至高。"},{"start":14,"end":14,"text":"许多人因他惊奇； 他的面貌比别人憔悴； 他的形容比世人枯槁。"},{"start":15,"end":15,"text":"这样，他必洗净许多国民； 君王要向他闭口。 因所未曾传与他们的，他们必看见； 未曾听见的，他们要明白。"}],"53":[{"start":1,"end":1,"text":"我们所传的有谁信呢？ 耶和华的膀臂向谁显露呢？"},{"start":2,"end":2,"text":"他在耶和华面前生长如嫩芽， 像根出于干地。 他无佳形美容； 我们看见他的时候， 也无美貌使我们羡慕他。"},{"start":3,"end":3,"text":"他被藐视，被人厌弃； 多受痛苦，常经忧患。 他被藐视， 好像被人掩面不看的一样； 我们也不尊重他。"},{"start":4,"end":4,"text":"他诚然担当我们的忧患， 背负我们的痛苦； 我们却以为他受责罚， 被　神击打苦待了。"},{"start":5,"end":5,"text":"哪知他为我们的过犯受害， 为我们的罪孽压伤。 因他受的刑罚，我们得平安； 因他受的鞭伤，我们得医治。"},{"start":6,"end":6,"text":"我们都如羊走迷； 各人偏行己路； 耶和华使我们众人的罪孽都归在他身上。"},{"start":7,"end":7,"text":"他被欺压， 在受苦的时候却不开口 ； 他像羊羔被牵到宰杀之地， 又像羊在剪毛的人手下无声， 他也是这样不开口。"},{"start":8,"end":8,"text":"因受欺压和审判，他被夺去， 至于他同世的人，谁想他受鞭打、 从活人之地被剪除， 是因我百姓的罪过呢？"},{"start":9,"end":9,"text":"他虽然未行强暴， 口中也没有诡诈， 人还使他与恶人同埋； 谁知死的时候与财主同葬。"},{"start":10,"end":10,"text":"耶和华却定意将他压伤， 使他受痛苦。 耶和华以他为赎罪祭。 他必看见后裔，并且延长年日。 耶和华所喜悦的事必在他手中亨通。"},{"start":11,"end":11,"text":"他必看见自己劳苦的功效， 便心满意足。 有许多人因认识我的义仆得称为义； 并且他要担当他们的罪孽。"},{"start":12,"end":12,"text":"所以，我要使他与位大的同分， 与强盛的均分掳物。 因为他将命倾倒，以致于死； 他也被列在罪犯之中。 他却担当多人的罪， 又为罪犯代求。"}],"55":[{"start":10,"end":10,"text":"雨雪从天而降，并不返回， 却滋润地土，使地上发芽结实， 使撒种的有种，使要吃的有粮。"},{"start":11,"end":11,"text":"我口所出的话也必如此， 决不徒然返回， 却要成就我所喜悦的， 在我发他去成就的事上必然亨通。"}],"56":[{"start":6,"end":6,"text":"还有那些与耶和华联合的外邦人， 要事奉他，要爱耶和华的名， 要作他的仆人— 就是凡守安息日不干犯， 又持守他约的人。"},{"start":7,"end":7,"text":"我必领他们到我的圣山， 使他们在祷告我的殿中喜乐。 他们的燔祭和[平安]祭， 在我坛上必蒙悦纳， 因我的殿必称为万民祷告的殿。"}],"57":[{"start":15,"end":15,"text":"因为那至高至上、永远长存 名为圣者的如此说： 我住在至高至圣的所在， 也与心灵痛悔谦卑的人同居； 要使谦卑人的灵苏醒， 也使痛悔人的心苏醒。"},{"start":16,"end":16,"text":"我必不永远相争，也不长久发怒， 恐怕我所造的人与灵性都必发昏。"},{"start":17,"end":17,"text":"因他贪婪的罪孽，我就发怒击打他； 我向他掩面发怒， 他却仍然随心背道。"},{"start":18,"end":18,"text":"我看见他所行的道，也要医治他； 又要引导他， 使他和那一同伤心的人再得安慰。"},{"start":19,"end":19,"text":"我造就嘴唇的果子； 愿平安康泰归与远处的人， 也归与近处的人； 并且我要医治他。 这是耶和华说的。"},{"start":20,"end":20,"text":"惟独恶人，好像翻腾的海， 不得平静； 其中的水常涌出污秽和淤泥来。"},{"start":21,"end":21,"text":"我的　神说：恶人必不得平安！"}],"58":[{"start":6,"end":6,"text":"我所拣选的禁食不是要松开凶恶的绳， 解下轭上的索， 使被欺压的得自由， 折断一切的轭吗？"},{"start":7,"end":7,"text":"不是要把你的饼分给饥饿的人， 将飘流的穷人接到你家中， 见赤身的给他[衣服]遮体， 顾恤自己的骨肉而不掩藏吗？"},{"start":8,"end":8,"text":"这样，你的光就必发现如早晨的光； 你所得的医治要速速发明。 你的公义必在你前面行； 耶和华的荣光必作你的后盾。"},{"start":9,"end":9,"text":"那时你求告，耶和华必应允； 你呼求，他必说：我在这里。 你若从你中间除掉[重]轭 和指摘人的指头，并发恶言的事，"},{"start":10,"end":10,"text":"你心若向饥饿的人发怜悯， 使困苦的人得满足， 你的光就必在黑暗中发现； 你的幽暗必变如正午。"},{"start":11,"end":11,"text":"耶和华也必时常引导你， 在干旱之地使你心满意足， 骨头强壮。 你必像浇灌的园子， 又像水流不绝的泉源。"},{"start":12,"end":12,"text":"那些出于你的人必修造久已荒废之处； 你要建立[拆毁]累代的根基。 你必称为补破口的， 和重修路径与人居住的。"},{"start":13,"end":13,"text":"你若在安息日掉转你的脚步， 在我圣日不以[操作]为喜乐， 称安息日为可喜乐的， 称耶和华的圣日为可尊重的； 而且尊敬这日， 不办自己的私事， 不随自己的私意， 不说自己的私话，"},{"start":14,"end":14,"text":"你就以耶和华为乐。 耶和华要使你乘驾地的高处， 又以你祖雅各的产业养育你。 这是耶和华亲口说的。"}],"61":[{"start":1,"end":1,"text":"主耶和华的灵在我身上； 因为耶和华用膏膏我， 叫我传好信息给谦卑的人， 差遣我医好伤心的人， 报告被掳的得释放， 被囚的出[监牢]；"},{"start":2,"end":2,"text":"报告耶和华的恩年， 和我们　神报仇的日子； 安慰一切悲哀的人，"},{"start":3,"end":3,"text":"赐华冠与锡安悲哀的人，代替灰尘； 喜乐油代替悲哀； 赞美衣代替忧伤之灵； 使他们称为「公义树」， 是耶和华所栽的，叫他得荣耀。"}],"62":[{"start":4,"end":4,"text":"你必不再称为「撇弃的」； 你的地也不再称为「荒凉的」。 你却要称为「我所喜悦的」； 你的地也必称为「有夫之妇」。 因为耶和华喜悦你， 你的地也必归他。"},{"start":5,"end":5,"text":"少年人怎样娶处女， 你的众民也要照样娶你； 新郎怎样喜悦新妇， 你的　神也要照样喜悦你。"}],"65":[{"start":1,"end":1,"text":"素来没有访问[我的]，现在求问我； 没有寻找我的，我叫他们遇见； 没有称为我名下的，我对他们说： 我在这里！我在这里！"},{"start":2,"end":2,"text":"我整天伸手招呼那悖逆的百姓； 他们随自己的意念行不善之道。"},{"start":3,"end":3,"text":"这百姓时常当面惹我发怒； 在园中献祭， 在坛上烧香；"},{"start":4,"end":4,"text":"在坟墓间坐着， 在隐密处住宿， 吃猪肉； 他们器皿中有可憎之物做的汤；"},{"start":5,"end":5,"text":"且对人说：你站开吧！ 不要挨近我，因为我比你圣洁。 [主说]：这些人是我鼻中的烟， 是整天烧着的火。"}]},"REV":{"1":[{"start":7,"end":7,"text":"看哪，他驾云降临！ 众目要看见他， 连刺他的人也要看见他； 地上的万族都要因他哀哭。 这话是真实的。阿们！"},{"start":8,"end":8,"text":"主　神说：「我是阿拉法，我是俄梅戛，是昔在、今在、以后[永]在的全能者。」"},{"start":9,"end":9,"text":"我—约翰就是你们的弟兄，和你们在耶稣的患难、国度、忍耐里一同有分，为　神的道，并为给耶稣作的见证，曾在那名叫拔摩的海岛上。"},{"start":10,"end":10,"text":"当主日，我被[圣]灵感动，听见在我后面有大声音如吹号，说："},{"start":11,"end":11,"text":"「你所看见的当写在书上，达与以弗所、士每拿、别迦摩、推雅推喇、撒狄、非拉铁非、老底嘉那七个教会。」"},{"start":12,"end":12,"text":"我转过身来，要看是谁发声与我说话；既转过来，就看见七个金灯台。"},{"start":13,"end":13,"text":"灯台中间有一位好像人子，身穿长衣，直垂到脚，胸间束着金带。"},{"start":14,"end":14,"text":"他的头与发皆白，如白羊毛，如雪；眼目如同火焰；"},{"start":15,"end":15,"text":"脚好像在炉中锻炼光明的铜；声音如同众水的声音。"},{"start":16,"end":16,"text":"他右手拿着七星，从他口中出来一把两刃的利剑；面貌如同烈日放光。"},{"start":17,"end":17,"text":"我一看见，就仆倒在他脚前，像死了一样。他用右手按着我，说：「不要惧怕！我是首先的，我是末后的，"},{"start":18,"end":18,"text":"又是那存活的；我曾死过，现在又活了，直活到永永远远；并且拿着死亡和阴间的钥匙。"},{"start":19,"end":19,"text":"所以你要把所看见的，和现在的事，并将来必成的事，都写出来。"},{"start":20,"end":20,"text":"论到你所看见、在我右手中的七星和七个金灯台的奥秘，那七星就是七个教会的使者，七灯台就是七个教会。」"}],"3":[{"start":5,"end":5,"text":"凡得胜的必这样穿白衣，我也必不从生命册上涂抹他的名；且要在我父面前，和我父众使者面前，认他的名。"},{"start":6,"end":6,"text":"[圣]灵向众教会所说的话，凡有耳的，就应当听！』」"},{"start":7,"end":7,"text":"「你要写信给非拉铁非教会的使者，说：『那圣洁、真实、拿着大卫的钥匙、开了就没有人能关、关了就没有人能开的，说："},{"start":8,"end":8,"text":"我知道你的行为，你略有一点力量，也曾遵守我的道，没有弃绝我的名。看哪，我在你面前给你一个敞开的门，是无人能关的。"},{"start":9,"end":9,"text":"那撒但一会的，自称是犹太人，其实不是犹太人，乃是说谎话的，我要使他们来，在你脚前下拜，也使他们知道我是已经爱你了。"},{"start":10,"end":10,"text":"你既遵守我忍耐的道，我必在普天下人受试炼的时候，保守你免去你的试炼。"},{"start":11,"end":11,"text":"我必快来，你要持守你所有的，免得人夺去你的冠冕。"},{"start":12,"end":12,"text":"得胜的，我要叫他在我　神殿中作柱子，他也必不再从那里出去。我又要将我　神的名和我　神城的名（这城就是从天上、从我　神那里降下来的新耶路撒冷），并我的新名，都写在他上面。"},{"start":13,"end":13,"text":"[圣]灵向众教会所说的话，凡有耳的，就应当听！』」"},{"start":14,"end":14,"text":"「你要写信给老底嘉教会的使者，说：『那为阿们的，为诚信真实见证的，在　神创造万物之上为元首的，说："},{"start":15,"end":15,"text":"我知道你的行为，你也不冷也不热；我巴不得你或冷或热。"},{"start":16,"end":16,"text":"你既[如]温[水]，也不冷也不热，所以我必从我口中把你吐出去。"},{"start":17,"end":17,"text":"你说：我是富足，已经发了财，一样都不缺；却不知道你是那困苦、可怜、贫穷、瞎眼、赤身的。"},{"start":18,"end":18,"text":"我劝你向我买火炼的金子，叫你富足；又买白衣穿上，叫你赤身的羞耻不露出来；又买眼药擦你的眼睛，使你能看见。"},{"start":19,"end":19,"text":"凡我所疼爱的，我就责备管教他；所以你要发热心，也要悔改。"},{"start":20,"end":20,"text":"看哪，我站在门外叩门，若有听见我声音就开门的，我要进到他那里去，我与他，他与我一同坐席。"},{"start":21,"end":21,"text":"得胜的，我要赐他在我宝座上与我同坐，就如我得了胜，在我父的宝座上与他同坐一般。"},{"start":22,"end":22,"text":"[圣]灵向众教会所说的话，凡有耳的，就应当听！』」"}],"6":[{"start":9,"end":9,"text":"揭开第五印的时候，我看见在祭坛底下，有为　神的道、并为作见证被杀之人的灵魂，"},{"start":10,"end":10,"text":"大声喊着说：「圣洁真实的主啊，你不审判住在地上的人，给我们伸流血的冤，要等到几时呢？」"},{"start":11,"end":11,"text":"于是有白衣赐给他们各人；又有话对他们说，还要安息片时，等着一同作仆人的和他们的弟兄也像他们被杀，满足了数目。"}],"7":[{"start":9,"end":9,"text":"此后，我观看，见有许多的人，没有人能数过来，是从各国、各族、各民、各方来的，站在宝座和羔羊面前，身穿白衣，手拿棕树枝，"},{"start":10,"end":10,"text":"大声喊着说：「愿救恩归与坐在宝座上我们的　神，也归与羔羊！」"},{"start":11,"end":11,"text":"众天使都站在宝座和众长老并四活物的周围，在宝座前，面伏于地，敬拜　神，"},{"start":12,"end":12,"text":"说： 阿们！颂赞、荣耀、智慧、 感谢、尊贵、权柄、大力 都归与我们的　神， 直到永永远远。阿们！"},{"start":13,"end":13,"text":"长老中有一位问我说：「这些穿白衣的是谁？是从哪里来的？」"},{"start":14,"end":14,"text":"我对他说：「我主，你知道。」他向我说：「这些人是从大患难中出来的，曾用羔羊的血把衣裳洗白净了。"},{"start":15,"end":15,"text":"所以，他们在　神宝座前，昼夜在他殿中事奉他。坐宝座的要用帐幕覆庇他们。"},{"start":16,"end":16,"text":"他们不再饥，不再渴；日头和炎热也必不伤害他们。"},{"start":17,"end":17,"text":"因为宝座中的羔羊必牧养他们，领他们到生命水的泉源；　神也必擦去他们一切的眼泪。」"}],"8":[{"start":3,"end":3,"text":"另有一位天使，拿着金香炉来，站在祭坛旁边。有许多香赐给他，要和众圣徒的祈祷一同献在宝座前的金坛上。"},{"start":4,"end":4,"text":"那香的烟和众圣徒的祈祷从天使的手中一同升到　神面前。"}],"11":[{"start":15,"end":15,"text":"第七位天使吹号，天上就有大声音说： 世上的国成了我主和主基督的国； 他要作王，直到永永远远。"},{"start":16,"end":16,"text":"在　神面前，坐在自己位上的二十四位长老，就面伏于地，敬拜　神，"},{"start":17,"end":17,"text":"说： 昔在、今在的主　神— 全能者啊，我们感谢你！ 因你执掌大权作王了。"},{"start":18,"end":18,"text":"外邦发怒，你的忿怒也临到了； 审判死人的时候也到了。 你的仆人众先知和众圣徒， 凡敬畏你名的人， 连大带小得赏赐的时候也到了。 你败坏那些败坏世界之人的时候也就到了。"},{"start":19,"end":19,"text":"当时，　神天上的殿开了，在他殿中现出他的约柜。随后有闪电、声音、雷轰、地震、大雹。"}],"19":[{"start":6,"end":6,"text":"我听见好像群众的声音，众水的声音，大雷的声音，说： 哈利路亚！ 因为主—我们的　神、 全能者作王了。"},{"start":7,"end":7,"text":"我们要欢喜快乐， 将荣耀归给他。 因为，羔羊婚娶的时候到了； 新妇也自己预备好了，"},{"start":8,"end":8,"text":"就蒙恩得穿光明洁白的细麻衣。 （这细麻衣就是圣徒所行的义。）"},{"start":9,"end":9,"text":"天使吩咐我说：「你要写上：凡被请赴羔羊之婚筵的有福了！」又对我说：「这是　神真实的话。」"}],"21":[{"start":1,"end":1,"text":"我又看见一个新天新地；因为先前的天地已经过去了，海也不再有了。"},{"start":2,"end":2,"text":"我又看见圣城新耶路撒冷由　神那里从天而降，预备好了，就如新妇妆饰整齐，等候丈夫。"},{"start":3,"end":3,"text":"我听见有大声音从宝座出来说：「看哪，　神的帐幕在人间。他要与人同住，他们要作他的子民。　神要亲自与他们同在，作他们的　神。"},{"start":4,"end":4,"text":"神要擦去他们一切的眼泪；不再有死亡，也不再有悲哀、哭号、疼痛，因为以前的事都过去了。」"},{"start":5,"end":5,"text":"坐宝座的说：「看哪，我将一切都更新了！」又说：「你要写上；因这些话是可信的，是真实的。」"}]},"2SA":{"7":[{"start":8,"end":8,"text":"「现在，你要告诉我仆人大卫，说万军之耶和华如此说：『我从羊圈中将你召来，叫你不再跟从羊群，立你作我民以色列的君。"},{"start":9,"end":9,"text":"你无论往哪里去，我常与你同在，剪除你的一切仇敌。我必使你得大名，好像世上大大有名的人一样。"},{"start":10,"end":10,"text":"我必为我民以色列选定一个地方，栽培他们，使他们住自己的地方，不再迁移；凶恶之子也不像从前扰害他们，"},{"start":11,"end":11,"text":"并不像我命士师治理我民以色列的时候一样。我必使你安靖，不被一切仇敌扰乱，并且我—耶和华应许你，必为你建立家室。"},{"start":12,"end":12,"text":"你寿数满足、与你列祖同睡的时候，我必使你的后裔接续你的位；我也必坚定他的国。"},{"start":13,"end":13,"text":"他必为我的名建造殿宇；我必坚定他的国位，直到永远。"},{"start":14,"end":14,"text":"我要作他的父，他要作我的子；他若犯了罪，我必用人的杖责打他，用人的鞭责罚他。"},{"start":15,"end":15,"text":"但我的慈爱仍不离开他，像离开在你面前所废弃的扫罗一样。"},{"start":16,"end":16,"text":"你的家和你的国必在我面前永远坚立。你的国位也必坚定，直到永远。』」"}],"12":[{"start":1,"end":1,"text":"耶和华差遣拿单去见大卫。拿单到了大卫那里，对他说：「在一座城里有两个人：一个是富户，一个是穷人。"},{"start":2,"end":2,"text":"富户有许多牛群羊群；"},{"start":3,"end":3,"text":"穷人除了所买来养活的一只小母羊羔之外，别无所有。羊羔在他家里和他儿女一同长大，吃他所吃的，喝他所喝的，睡在他怀中，在他看来如同女儿一样。"},{"start":4,"end":4,"text":"有一客人来到这富户家里；富户舍不得从自己的牛群羊群中取一只预备给客人吃，却取了那穷人的羊羔，预备给客人吃。」"},{"start":5,"end":5,"text":"大卫就甚恼怒那人，对拿单说：「我指着永生的耶和华起誓，行这事的人该死！"},{"start":6,"end":6,"text":"他必偿还羊羔四倍；因为他行这事，没有怜恤的心。」"},{"start":7,"end":7,"text":"拿单对大卫说：「你就是那人！耶和华—以色列的　神如此说：『我膏你作以色列的王，救你脱离扫罗的手。"}]},"PSA":{"1":[{"start":1,"end":1,"text":"不从恶人的计谋， 不站罪人的道路， 不坐亵慢人的座位，"},{"start":2,"end":2,"text":"惟喜爱耶和华的律法， 昼夜思想， 这人便为有福！"},{"start":3,"end":3,"text":"他要像一棵树栽在溪水旁， 按时候结果子， 叶子也不枯干。 凡他所做的尽都顺利。"},{"start":4,"end":4,"text":"恶人并不是这样， 乃像糠秕被风吹散。"},{"start":5,"end":5,"text":"因此，当审判的时候、恶人必站立不住； 罪人在义人的会中也是如此。"},{"start":6,"end":6,"text":"因为耶和华知道义人的道路； 恶人的道路却必灭亡。"}],"2":[{"start":1,"end":1,"text":"外邦为什么争闹？ 万民为什么谋算虚妄的事？"},{"start":2,"end":2,"text":"世上的君王一齐起来， 臣宰一同商议， 要敌挡耶和华并他的受膏者，"},{"start":3,"end":3,"text":"说：我们要挣开他们的捆绑， 脱去他们的绳索。"},{"start":4,"end":4,"text":"那坐在天上的必发笑； 主必嗤笑他们。"},{"start":5,"end":5,"text":"那时，他要在怒中责备他们， 在烈怒中惊吓他们，"},{"start":6,"end":6,"text":"说：我已经立我的君 在锡安—我的圣山上了。"},{"start":7,"end":7,"text":"[受膏者说]：我要传[圣]旨。 耶和华曾对我说：你是我的儿子， 我今日生你。"},{"start":8,"end":8,"text":"你求我，我就将列国赐你为基业， 将地极赐你为田产。"},{"start":9,"end":9,"text":"你必用铁杖打破他们； 你必将他们如同窑匠的瓦器摔碎。"},{"start":10,"end":10,"text":"现在，你们君王应当省悟！ 你们世上的审判官该受管教！"},{"start":11,"end":11,"text":"当存畏惧事奉耶和华， 又当存战兢而快乐。"},{"start":12,"end":12,"text":"当以嘴亲子，恐怕他发怒， 你们便在道中灭亡， 因为他的怒气快要发作。 凡投靠他的，都是有福的。"}],"8":[{"start":2,"end":2,"text":"你因敌人的缘故， 从婴孩和吃奶的口中， 建立了能力， 使仇敌和报仇的闭口无言。"},{"start":3,"end":3,"text":"我观看你指头所造的天， 并你所陈设的月亮星宿，"},{"start":4,"end":4,"text":"[便说]：人算什么，你竟顾念他！ 世人算什么，你竟眷顾他！"},{"start":5,"end":5,"text":"你叫他比天使微小一点， 并赐他荣耀尊贵为冠冕。"},{"start":6,"end":6,"text":"你派他管理你手所造的， 使万物，就是一切的牛羊、 田野的兽、空中的鸟、海里的鱼， 凡经行海道的，都服在他的脚下。"},{"start":9,"end":9,"text":"耶和华—我们的主啊， 你的名在全地何其美！"}],"10":[{"start":17,"end":17,"text":"耶和华啊，谦卑人的心愿， 你早已知道。 你必预备他们的心， 也必侧耳听他们[的祈求]，"},{"start":18,"end":18,"text":"为要给孤儿和受欺压的人伸冤， 使强横的人不再威吓他们。"}],"16":[{"start":9,"end":9,"text":"因此，我的心欢喜，我的灵快乐； 我的肉身也要安然居住。"},{"start":10,"end":10,"text":"因为你必不将我的灵魂撇在阴间， 也不叫你的圣者见朽坏。"}],"22":[{"start":1,"end":1,"text":"大卫的诗，交与伶长。调用朝鹿。 我的　神，我的　神！为什么离弃我？ [为什么]远离不救我？不听我唉哼的言语？"},{"start":2,"end":2,"text":"我的　神啊，我白日呼求，你不应允， 夜间呼求，并不住声。"},{"start":3,"end":3,"text":"但你是圣洁的， 是用以色列的赞美为宝座的。"},{"start":4,"end":4,"text":"我们的祖宗倚靠你； 他们倚靠你，你便解救他们。"},{"start":5,"end":5,"text":"他们哀求你，便蒙解救； 他们倚靠你，就不羞愧。"},{"start":6,"end":6,"text":"但我是虫，不是人， 被众人羞辱，被百姓藐视。"},{"start":7,"end":7,"text":"凡看见我的都嗤笑我； 他们撇嘴摇头，[说]："},{"start":8,"end":8,"text":"他把[自己]交托耶和华，耶和华可以救他吧！ 耶和华既喜悦他，可以搭救他吧！"},{"start":9,"end":9,"text":"但你是叫我出母腹的； 我在母怀里，你就使我有倚靠的心。"},{"start":10,"end":10,"text":"我自出母胎就被交在你手里； 从我母亲生我，你就是我的　神。"},{"start":11,"end":11,"text":"求你不要远离我！ 因为急难临近了，没有人帮助我。"},{"start":12,"end":12,"text":"有许多公牛围绕我， 巴珊大力的公牛四面困住我。"},{"start":13,"end":13,"text":"它们向我张口， 好像抓撕吼叫的狮子。"},{"start":14,"end":14,"text":"我如水被倒出来； 我的骨头都脱了节； 我心在我里面如蜡熔化。"},{"start":15,"end":15,"text":"我的精力枯干，如同瓦片； 我的舌头贴在我牙床上。 你将我安置在死地的尘土中。"},{"start":16,"end":16,"text":"犬类围着我，恶党环绕我； 他们扎了我的手，我的脚。"},{"start":17,"end":17,"text":"我的骨头，我都能数过； 他们瞪着眼看我。"},{"start":18,"end":18,"text":"他们分我的外衣， 为我的里衣拈阄。"},{"start":19,"end":19,"text":"耶和华啊，求你不要远离我！ 我的救主啊，求你快来帮助我！"},{"start":20,"end":20,"text":"求你救我的灵魂脱离刀剑， 救我的生命脱离犬类，"},{"start":21,"end":21,"text":"救我脱离狮子的口； 你已经应允我，使我脱离野牛的角。"},{"start":22,"end":22,"text":"我要将你的名传与我的弟兄， 在会中我要赞美你。"},{"start":23,"end":23,"text":"你们敬畏耶和华的人要赞美他！ 雅各的后裔都要荣耀他！ 以色列的后裔都要惧怕他！"},{"start":24,"end":24,"text":"因为他没有藐视憎恶受苦的人， 也没有向他掩面； 那受苦之人呼吁的时候，他就垂听。"},{"start":25,"end":25,"text":"我在大会中赞美你的话是从你而来的； 我要在敬畏耶和华的人面前还我的愿。"},{"start":26,"end":26,"text":"谦卑的人必吃得饱足； 寻求耶和华的人必赞美他。 愿你们的心永远活着！"},{"start":27,"end":27,"text":"地的四极都要想念耶和华，并且归顺他； 列国的万族都要在你面前敬拜。"},{"start":28,"end":28,"text":"因为国权是耶和华的； 他是管理万国的。"},{"start":29,"end":29,"text":"地上一切丰肥的人必吃喝而敬拜； 凡下到尘土中—不能存活自己性命的人 —都要在他面前下拜。"},{"start":30,"end":30,"text":"他必有后裔事奉他； 主所行的事必传与后代。"},{"start":31,"end":31,"text":"他们必来把他的公义传给将要生的民， 言明这事是他所行的。"}],"23":[{"start":1,"end":1,"text":"大卫的诗。 耶和华是我的牧者， 我必不致缺乏。"},{"start":2,"end":2,"text":"他使我躺卧在青草地上， 领我在可安歇的水边。"},{"start":3,"end":3,"text":"他使我的灵魂苏醒， 为自己的名引导我走义路。"},{"start":4,"end":4,"text":"我虽然行过死荫的[幽]谷， 也不怕遭害， 因为你与我同在； 你的杖，你的竿，都安慰我。"},{"start":5,"end":5,"text":"在我敌人面前，你为我摆设筵席； 你用油膏了我的头，使我的[福]杯满溢。"},{"start":6,"end":6,"text":"我一生一世必有恩惠慈爱随着我； 我且要住在耶和华的殿中，直到永远。"}],"27":[{"start":4,"end":4,"text":"有一件事，我曾求耶和华，我仍要寻求： 就是一生一世住在耶和华的殿中， 瞻仰他的荣美，在他的殿里求问。"},{"start":5,"end":5,"text":"因为我遭遇患难，他必暗暗地保守我； 在他亭子里，把我藏在他帐幕的隐密处， 将我高举在磐石上。"},{"start":6,"end":6,"text":"现在我得以昂首，高过四面的仇敌。 我要在他的帐幕里欢然献祭； 我要唱诗歌颂耶和华。"},{"start":7,"end":7,"text":"耶和华啊，我用声音呼吁的时候，求你垂听； 并求你怜恤我，应允我。"},{"start":8,"end":8,"text":"[你说]：你们当寻求我的面。 那时我心向你说：耶和华啊， 你的面我正要寻求。"},{"start":9,"end":9,"text":"不要向我掩面。 不要发怒赶逐仆人， 你向来是帮助我的。 救我的　神啊，不要丢掉我， 也不要离弃我。"},{"start":10,"end":10,"text":"我父母离弃我， 耶和华必收留我。"},{"start":11,"end":11,"text":"耶和华啊，求你将你的道指教我， 因我仇敌的缘故引导我走平坦的路。"},{"start":12,"end":12,"text":"求你不要把我交给敌人，遂其所愿； 因为妄作见证的和口吐凶言的，起来攻击我。"},{"start":13,"end":13,"text":"我若不信在活人之地得见耶和华的恩惠， [就早已丧胆了]。"},{"start":14,"end":14,"text":"要等候耶和华！ 当壮胆，坚固你的心！ 我再说，要等候耶和华！"}],"31":[{"start":5,"end":5,"text":"我将我的灵魂交在你手里； 耶和华诚实的　神啊，你救赎了我。"},{"start":6,"end":6,"text":"我恨恶那信奉虚无[之神]的人； 我却倚靠耶和华。"},{"start":7,"end":7,"text":"我要为你的慈爱高兴欢喜； 因为你见过我的困苦，知道我心中的艰难。"},{"start":8,"end":8,"text":"你未曾把我交在仇敌手里； 你使我的脚站在宽阔之处。"},{"start":9,"end":9,"text":"耶和华啊，求你怜恤我， 因为我在急难之中； 我的眼睛因忧愁而干瘪， 连我的身心也不安舒。"},{"start":10,"end":10,"text":"我的生命为愁苦所消耗； 我的年岁为叹息所旷废。 我的力量因我的罪孽衰败； 我的骨头也枯干。"},{"start":11,"end":11,"text":"我因一切敌人成了羞辱， 在我的邻舍跟前更甚； 那认识我的都惧怕我， 在外头看见我的都躲避我。"},{"start":12,"end":12,"text":"我被人忘记，如同死人，无人记念； 我好像破碎的器皿。"},{"start":13,"end":13,"text":"我听见了许多人的谗谤， 四围都是惊吓； 他们一同商议攻击我的时候， 就图谋要害我的性命。"},{"start":14,"end":14,"text":"耶和华啊，我仍旧倚靠你； 我说：你是我的　神。"},{"start":15,"end":15,"text":"我终身的事在你手中； 求你救我脱离仇敌的手和那些逼迫我的人。"},{"start":16,"end":16,"text":"求你使你的脸光照仆人， 凭你的慈爱拯救我。"},{"start":17,"end":17,"text":"耶和华啊，求你叫我不致羞愧， 因为我曾呼吁你； 求你使恶人羞愧， 使他们在阴间缄默无声。"},{"start":18,"end":18,"text":"那撒谎的人逞骄傲轻慢， 出狂妄的话攻击义人； 愿他的嘴哑而无言。"},{"start":19,"end":19,"text":"敬畏你、投靠你的人，你为他们所积存的， 在世人面前所施行的恩惠是何等大呢！"},{"start":20,"end":20,"text":"你必把他们藏在你面前的隐密处， 免得遇见人的计谋； 你必暗暗地保守他们在亭子里， 免受口舌的争闹。"},{"start":21,"end":21,"text":"耶和华是应当称颂的， 因为他在坚固城里向我施展奇妙的慈爱。"},{"start":22,"end":22,"text":"至于我，我曾急促地说： 我从你眼前被隔绝。 然而，我呼求你的时候， 你仍听我恳求的声音。"},{"start":23,"end":23,"text":"耶和华的圣民哪，你们都要爱他！ 耶和华保护诚实人， 足足报应行事骄傲的人。"},{"start":24,"end":24,"text":"凡仰望耶和华的人， 你们都要壮胆，坚固你们的心！"}],"37":[{"start":16,"end":16,"text":"一个义人所有的虽少， 强过许多恶人的富余。"},{"start":17,"end":17,"text":"因为恶人的膀臂必被折断； 但耶和华是扶持义人。"},{"start":18,"end":18,"text":"耶和华知道完全人的日子； 他们的产业要存到永远。"},{"start":19,"end":19,"text":"他们在急难的时候不致羞愧， 在饥荒的日子必得饱足。"}],"41":[{"start":9,"end":9,"text":"连我知己的朋友， 我所倚靠、吃过我饭的也用脚踢我。"},{"start":10,"end":10,"text":"耶和华啊，求你怜恤我， 使我起来，好报复他们！"},{"start":11,"end":11,"text":"因我的仇敌不得向我夸胜， 我从此便知道你喜爱我。"},{"start":12,"end":12,"text":"你因我纯正就扶持我， 使我永远站在你的面前。"},{"start":13,"end":13,"text":"耶和华—以色列的　神是应当称颂的， 从亘古直到永远。阿们！阿们！"}],"42":[{"start":5,"end":5,"text":"我的心哪，你为何忧闷？ 为何在我里面烦躁？ 应当仰望　神，因他笑脸帮助我； 我还要称赞他。"},{"start":6,"end":6,"text":"我的　神啊，我的心在我里面忧闷， 所以我从约旦地， 从黑门岭，从米萨山记念你。"},{"start":7,"end":7,"text":"你的瀑布发声，深渊就与深渊响应； 你的波浪洪涛漫过我身。"},{"start":8,"end":8,"text":"白昼，耶和华必向我施慈爱； 黑夜，我要歌颂祷告赐我生命的　神。"},{"start":9,"end":9,"text":"我要对　神—我的磐石说： 你为何忘记我呢？ 我为何因仇敌的欺压时常哀痛呢？"},{"start":10,"end":10,"text":"我的敌人辱骂我， 好像打碎我的骨头， 不住地对我说： 你的　神在哪里呢？"},{"start":11,"end":11,"text":"我的心哪，你为何忧闷？ 为何在我里面烦躁？ 应当仰望　神，因我还要称赞他。 他是我脸上的光荣，是我的　神。"}],"51":[{"start":1,"end":1,"text":"大卫与拔示巴同室以后，先知拿单来见他；他作这诗，交与伶长。 　神啊，求你按你的慈爱怜恤我！ 按你丰盛的慈悲涂抹我的过犯！"},{"start":2,"end":2,"text":"求你将我的罪孽洗除净尽， 并洁除我的罪！"},{"start":3,"end":3,"text":"因为，我知道我的过犯； 我的罪常在我面前。"},{"start":4,"end":4,"text":"我向你犯罪，惟独得罪了你； 在你眼前行了这恶， 以致你责备我的时候显为公义， 判断我的时候显为清正。"},{"start":5,"end":5,"text":"我是在罪孽里生的， 在我母亲怀胎的时候就有了罪。"},{"start":6,"end":6,"text":"你所喜爱的是内里诚实； 你在我隐密处，必使我得智慧。"},{"start":7,"end":7,"text":"求你用牛膝草洁净我，我就干净； 求你洗涤我，我就比雪更白。"},{"start":8,"end":8,"text":"求你使我得听欢喜快乐[的声音]， 使你所压伤的骨头可以踊跃。"},{"start":9,"end":9,"text":"求你掩面不看我的罪， 涂抹我一切的罪孽。"},{"start":10,"end":10,"text":"神啊，求你为我造清洁的心， 使我里面重新有正直的灵。"},{"start":11,"end":11,"text":"不要丢弃我，使我离开你的面； 不要从我收回你的圣灵。"},{"start":12,"end":12,"text":"求你使我仍得救恩之乐， 赐我乐意的灵扶持我，"},{"start":13,"end":13,"text":"我就把你的道指教有过犯的人， 罪人必归顺你。"},{"start":14,"end":14,"text":"神啊，你是拯救我的　神； 求你救我脱离流人血的罪！ 我的舌头就高声歌唱你的公义。"},{"start":15,"end":15,"text":"主啊，求你使我嘴唇张开， 我的口便传扬赞美你的话！"},{"start":16,"end":16,"text":"你本不喜爱祭物，若喜爱，我就献上； 燔祭，你也不喜悦。"},{"start":17,"end":17,"text":"[神所要]的祭就是忧伤的灵； 　神啊，忧伤痛悔的心，你必不轻看。"},{"start":18,"end":18,"text":"求你随你的美意善待锡安， 建造耶路撒冷的城墙。"},{"start":19,"end":19,"text":"那时，你必喜爱公义的祭 和燔祭并全牲的燔祭； 那时，人必将公牛献在你坛上。"}],"55":[{"start":22,"end":22,"text":"你要把你的重担卸给耶和华， 他必抚养你； 他永不叫义人动摇。"},{"start":23,"end":23,"text":"神啊，你必使恶人下入灭亡的坑； 流人血、行诡诈的人必活不到半世， 但我要倚靠你。"}],"56":[{"start":3,"end":3,"text":"我惧怕的时候要倚靠你。"},{"start":4,"end":4,"text":"我倚靠　神，我要赞美他的话； 我倚靠　神，必不惧怕。 血气之辈能把我怎么样呢？"}],"68":[{"start":18,"end":18,"text":"你已经升上高天，掳掠仇敌； 你在人间，就是在悖逆的人间，受了供献， 叫耶和华　神可以与他们同住。"},{"start":19,"end":19,"text":"天天背负我们重担的主， 就是拯救我们的　神， 是应当称颂的！ （细拉）"},{"start":20,"end":20,"text":"神是为我们施行诸般救恩的　神； 人能脱离死亡是在乎主耶和华。"},{"start":21,"end":21,"text":"但　神要打破他仇敌的头， 就是那常犯罪之人的发顶。"},{"start":22,"end":22,"text":"主说：我要使众民从巴珊而归， 使他们从深海而回，"},{"start":23,"end":23,"text":"使你打碎仇敌，你的脚踹在血中， 使你狗的舌头从其中得分。"},{"start":24,"end":24,"text":"神啊，你是我的　神，我的王； 人已经看见你行走，进入圣所。"},{"start":25,"end":25,"text":"歌唱的行在前，作乐的随在后， 都在击鼓的童女中间。"},{"start":26,"end":26,"text":"从以色列源头而来的， 当在各会中称颂主　神！"},{"start":27,"end":27,"text":"在那里，有统管他们的小便雅悯， 有犹大的首领和他们的群众， 有西布伦的首领， 有拿弗他利的首领。"},{"start":28,"end":28,"text":"以色列的能力是　神所赐的； 　神啊，求你坚固你为我们所成全的事！"},{"start":29,"end":29,"text":"因你耶路撒冷的殿， 列王必带贡物献给你。"},{"start":30,"end":30,"text":"求你叱喝芦苇中的野兽和群公牛， 并列邦中的牛犊。 把银块踹在脚下； 　神已经赶散好争战的列邦。"},{"start":31,"end":31,"text":"埃及的公侯要出来朝见　神； 古实人要急忙举手[祷告]。"},{"start":32,"end":32,"text":"世上的列国啊，你们要向　神歌唱； 愿你们歌颂主！"},{"start":33,"end":33,"text":"歌颂那自古驾行在诸天以上的[主]！ 他发出声音，是极大的声音。"},{"start":34,"end":34,"text":"你们要将能力归给　神。 他的威荣在以色列之上； 他的能力是在穹苍。"},{"start":35,"end":35,"text":"神啊，你从圣所显为可畏； 以色列的　神是那将力量权能赐给他百姓的。 　神是应当称颂的！"}],"78":[{"start":23,"end":23,"text":"他却吩咐天空， 又敞开天上的门，"},{"start":24,"end":24,"text":"降吗哪，像雨给他们吃， 将天上的粮食赐给他们。"},{"start":25,"end":25,"text":"各人吃大能者的食物； 他赐下粮食，使他们饱足。"},{"start":26,"end":26,"text":"他领东风起在天空， 又用能力引了南风来。"},{"start":27,"end":27,"text":"他降肉，像雨在他们当中，多如尘土， 又降飞鸟，多如海沙，"},{"start":28,"end":28,"text":"落在他们的营中， 在他们住处的四面。"},{"start":29,"end":29,"text":"他们吃了，而且饱足； 这样就随了他们所欲的。"}],"89":[{"start":9,"end":9,"text":"你管辖海的狂傲； 波浪翻腾，你就使它平静了。"},{"start":10,"end":10,"text":"你打碎了拉哈伯，似乎是已杀的人； 你用有能的膀臂打散了你的仇敌。"},{"start":11,"end":11,"text":"天属你，地也属你； 世界和其中所充满的都为你所建立。"},{"start":12,"end":12,"text":"南北为你所创造； 他泊和黑门都因你的名欢呼。"},{"start":13,"end":13,"text":"你有大能的膀臂； 你的手有力，你的右手也高举。"},{"start":14,"end":14,"text":"公义和公平是你宝座的根基； 慈爱和诚实行在你前面。"},{"start":15,"end":15,"text":"知道[向你]欢呼的，那民是有福的！ 耶和华啊，他们在你脸上的光里行走。"},{"start":16,"end":16,"text":"他们因你的名终日欢乐， 因你的公义得以高举。"},{"start":17,"end":17,"text":"你是他们力量的荣耀； 因为你喜悦我们，我们的角必被高举。"},{"start":18,"end":18,"text":"我们的盾牌属耶和华； 我们的王属以色列的圣者。"},{"start":19,"end":19,"text":"当时，你在异象中晓谕你的圣民，说： 我已把救助之力加在那有能者的身上； 我高举那从民中所拣选的。"},{"start":20,"end":20,"text":"我寻得我的仆人大卫， 用我的圣膏膏他。"},{"start":21,"end":21,"text":"我的手必使他坚立； 我的膀臂也必坚固他。"},{"start":22,"end":22,"text":"仇敌必不勒索他； 凶恶之子也不苦害他。"},{"start":23,"end":23,"text":"我要在他面前打碎他的敌人， 击杀那恨他的人。"},{"start":24,"end":24,"text":"只是我的信实和我的慈爱要与他同在； 因我的名，他的角必被高举。"},{"start":25,"end":25,"text":"我要使他的[左]手伸到海上， 右手伸到河上。"},{"start":26,"end":26,"text":"他要称呼我说：你是我的父， 是我的　神，是拯救我的磐石。"},{"start":27,"end":27,"text":"我也要立他为长子， 为世上最高的君王。"},{"start":28,"end":28,"text":"我要为他存留我的慈爱，直到永远； 我与他立的约必要坚定。"},{"start":29,"end":29,"text":"我也要使他的后裔存到永远， 使他的宝座如天之久。"},{"start":30,"end":30,"text":"倘若他的子孙离弃我的律法， 不照我的典章行，"},{"start":31,"end":31,"text":"背弃我的律例， 不遵守我的诫命，"},{"start":32,"end":32,"text":"我就要用杖责罚他们的过犯， 用鞭责罚他们的罪孽。"},{"start":33,"end":33,"text":"只是我必不将我的慈爱全然收回， 也必不叫我的信实废弃。"},{"start":34,"end":34,"text":"我必不背弃我的约， 也不改变我口中所出的。"},{"start":35,"end":35,"text":"我一次指着自己的圣洁起誓： 我决不向大卫说谎！"},{"start":36,"end":36,"text":"他的后裔要存到永远； 他的宝座在我面前如日之恒一般，"},{"start":37,"end":37,"text":"又如月亮永远坚立， 如天上确实的见证。 （细拉）"},{"start":38,"end":38,"text":"但你恼怒你的受膏者， 就丢掉弃绝他。"},{"start":39,"end":39,"text":"你厌恶了与仆人所立的约， 将他的冠冕践踏于地。"},{"start":40,"end":40,"text":"你拆毁了他一切的篱笆， 使他的保障变为荒场。"},{"start":41,"end":41,"text":"凡过路的人都抢夺他； 他成为邻邦的羞辱。"},{"start":42,"end":42,"text":"你高举了他敌人的右手； 你叫他一切的仇敌欢喜。"},{"start":43,"end":43,"text":"你叫他的刀剑卷刃， 叫他在争战之中站立不住。"},{"start":44,"end":44,"text":"你使他的光辉止息， 将他的宝座推倒于地。"},{"start":45,"end":45,"text":"你减少他青年的日子， 又使他蒙羞。 （细拉）"},{"start":46,"end":46,"text":"耶和华啊，这要到几时呢？ 你要将自己隐藏到永远吗？ 你的忿怒如火焚烧要到几时呢？"},{"start":47,"end":47,"text":"求你想念我的时候是何等的短少； 你创造世人，要使他们归何等的虚空呢？"},{"start":48,"end":48,"text":"谁能常活免死、 救他的灵魂脱离阴间的权柄呢？ （细拉）"},{"start":49,"end":49,"text":"主啊，你从前凭你的信实 向大卫立誓要施行的慈爱在哪里呢？"},{"start":50,"end":50,"text":"主啊，求你记念仆人们所受的羞辱， 记念我怎样将一切强盛民的[羞辱]存在我怀里。"},{"start":51,"end":51,"text":"耶和华啊，你的仇敌用这羞辱羞辱了你的仆人， 羞辱了你受膏者的脚踪。"},{"start":52,"end":52,"text":"耶和华是应当称颂的，直到永远。 阿们！阿们！"}],"91":[{"start":4,"end":4,"text":"他必用自己的翎毛遮蔽你； 你要投靠在他的翅膀底下； 他的诚实是大小的盾牌。"},{"start":5,"end":5,"text":"你必不怕黑夜的惊骇， 或是白日飞的箭，"},{"start":6,"end":6,"text":"也不怕黑夜行的瘟疫， 或是午间灭人的毒病。"},{"start":7,"end":7,"text":"虽有千人仆倒在你旁边， 万人仆倒在你右边， 这灾却不得临近你。"},{"start":8,"end":8,"text":"你惟亲眼观看， 见恶人遭报。"},{"start":9,"end":9,"text":"耶和华是我的避难所； 你已将至高者当你的居所，"},{"start":10,"end":10,"text":"祸患必不临到你， 灾害也不挨近你的帐棚。"},{"start":11,"end":11,"text":"因他要为你吩咐他的使者， 在你行的一切道路上保护你。"},{"start":12,"end":12,"text":"他们要用手托着你， 免得你的脚碰在石头上。"},{"start":13,"end":13,"text":"你要踹在狮子和虺蛇的身上， 践踏少壮狮子和大蛇。"},{"start":14,"end":14,"text":"神[说]：因为他专心爱我，我就要搭救他； 因为他知道我的名，我要把他安置在高处。"},{"start":15,"end":15,"text":"他若求告我，我就应允他； 他在急难中，我要与他同在； 我要搭救他，使他尊贵。"},{"start":16,"end":16,"text":"我要使他足享长寿， 将我的救恩显明给他。"}],"98":[{"start":2,"end":2,"text":"耶和华发明了他的救恩， 在列邦人眼前显出公义；"},{"start":3,"end":3,"text":"记念他向以色列家所发的慈爱，所凭的信实。 地的四极都看见我们　神的救恩。"}],"103":[{"start":1,"end":1,"text":"大卫的诗。 我的心哪，你要称颂耶和华！ 凡在我里面的，也要称颂他的圣名！"},{"start":2,"end":2,"text":"我的心哪，你要称颂耶和华！ 不可忘记他的一切恩惠！"},{"start":3,"end":3,"text":"他赦免你的一切罪孽， 医治你的一切疾病。"},{"start":4,"end":4,"text":"他救赎你的命脱离死亡， 以仁爱和慈悲为你的冠冕。"},{"start":5,"end":5,"text":"他用美物使你所愿的得以知足， 以致你如鹰返老还童。"},{"start":8,"end":8,"text":"耶和华有怜悯，有恩典， 不轻易发怒，且有丰盛的慈爱。"},{"start":9,"end":9,"text":"他不长久责备， 也不永远怀[怒]。"},{"start":10,"end":10,"text":"他没有按我们的罪过待我们， 也没有照我们的罪孽报应我们。"},{"start":11,"end":11,"text":"天离地何等的高， 他的慈爱向敬畏他的人也是何等的大！"},{"start":12,"end":12,"text":"东离西有多远， 他叫我们的过犯离我们也有多远！"},{"start":13,"end":13,"text":"父亲怎样怜恤他的儿女， 耶和华也怎样怜恤敬畏他的人！"}],"107":[{"start":2,"end":2,"text":"愿耶和华的赎民说这话， 就是他从敌人手中所救赎的，"},{"start":3,"end":3,"text":"从各地，从东从西， 从南从北，所招聚来的。"},{"start":10,"end":10,"text":"那些坐在黑暗中、死荫里的人 被困苦和铁[链]捆锁，"},{"start":11,"end":11,"text":"是因他们违背　神的话语， 藐视至高者的旨意。"},{"start":12,"end":12,"text":"所以，他用劳苦治服他们的心； 他们仆倒，无人扶助。"},{"start":13,"end":13,"text":"于是，他们在苦难中哀求耶和华； 他从他们的祸患中拯救他们。"},{"start":14,"end":14,"text":"他从黑暗中和死荫里领他们出来， 折断他们的绑索。"},{"start":15,"end":15,"text":"但愿人因耶和华的慈爱 和他向人所行的奇事都称赞他；"},{"start":16,"end":16,"text":"因为他打破了铜门， 砍断了铁闩。"},{"start":20,"end":20,"text":"他发命医治他们， 救他们脱离死亡。"},{"start":21,"end":21,"text":"但愿人因耶和华的慈爱 和他向人所行的奇事都称赞他。"},{"start":22,"end":22,"text":"愿他们以感谢为祭献给他， 欢呼述说他的作为！"},{"start":23,"end":23,"text":"在海上坐船， 在大水中经理事务的，"},{"start":24,"end":24,"text":"他们看见耶和华的作为， 并他在深水中的奇事。"},{"start":25,"end":25,"text":"因他一吩咐，狂风就起来， 海中的波浪也扬起。"},{"start":26,"end":26,"text":"他们上到天空，下到海底； 他们的心因患难便消化。"},{"start":27,"end":27,"text":"他们摇摇晃晃，东倒西歪，好像醉酒的人； 他们的智慧无法可施。"},{"start":28,"end":28,"text":"于是，他们在苦难中哀求耶和华， 他从他们的祸患中领出他们来。"},{"start":29,"end":29,"text":"他使狂风止息， 波浪就平静。"},{"start":30,"end":30,"text":"风息浪静，他们便欢喜； 他就引他们到所愿去的海口。"},{"start":31,"end":31,"text":"但愿人因耶和华的慈爱 和他向人所行的奇事都称赞他。"},{"start":32,"end":32,"text":"愿他们在民的会中尊崇他， 在长老的位上赞美他！"},{"start":33,"end":33,"text":"他使江河变为旷野， 叫水泉变为干渴之地，"},{"start":34,"end":34,"text":"使肥地变为硷地； 这都因其间居民的罪恶。"},{"start":35,"end":35,"text":"他使旷野变为水潭， 叫旱地变为水泉。"},{"start":36,"end":36,"text":"他使饥饿的人住在那里， 好建造可住的城邑，"},{"start":37,"end":37,"text":"又种田地，栽葡萄园， 得享所出的土产。"},{"start":38,"end":38,"text":"他又赐福给他们，叫他们生养众多， 也不叫他们的牲畜减少。"},{"start":39,"end":39,"text":"他们又因暴虐、患难、愁苦， 就减少且卑下。"},{"start":40,"end":40,"text":"他使君王蒙羞被辱， 使他们在荒废无路之地漂流。"},{"start":41,"end":41,"text":"他却将穷乏人安置在高处，脱离苦难， 使他的家属多如羊群。"},{"start":42,"end":42,"text":"正直人看见就欢喜； 罪孽之辈必塞口无言。"},{"start":43,"end":43,"text":"凡有智慧的，必在这些事上留心， 也必思想耶和华的慈爱。"}],"110":[{"start":1,"end":1,"text":"大卫的诗。 耶和华对我主说： 你坐在我的右边， 等我使你仇敌作你的脚凳。"},{"start":2,"end":2,"text":"耶和华必使你从锡安伸出能力的杖来； 你要在你仇敌中掌权。"},{"start":3,"end":3,"text":"当你掌权的日子， 你的民要以圣洁的妆饰为衣， 甘心牺牲自己； 你的民多如清晨的甘露。"},{"start":4,"end":4,"text":"耶和华起了誓，决不后悔，[说]： 你是照着麦基洗德的等次永远为祭司。"},{"start":5,"end":5,"text":"在你右边的主， 当他发怒的日子，必打伤列王。"},{"start":6,"end":6,"text":"他要在列邦中刑罚[恶人]， 尸首就遍满[各处]； 他要在许多国中打破[仇敌的]头。"},{"start":7,"end":7,"text":"他要喝路旁的河水， 因此必抬起头来。"}],"113":[{"start":5,"end":5,"text":"谁像耶和华—我们的　神呢？ 他坐在至高之处，"},{"start":6,"end":6,"text":"自己谦卑， 观看天上地下的事。"},{"start":7,"end":7,"text":"他从灰尘里抬举贫寒人， 从粪堆中提拔穷乏人，"},{"start":8,"end":8,"text":"使他们与王子同坐， 就是与本国的王子同坐。"},{"start":9,"end":9,"text":"他使不能生育的妇人安居家中， 为多子的乐母。 你们要赞美耶和华！"}],"118":[{"start":22,"end":22,"text":"匠人所弃的石头 已成了房角的头块石头。"},{"start":23,"end":23,"text":"这是耶和华所做的， 在我们眼中看为希奇。"},{"start":25,"end":25,"text":"耶和华啊，求你拯救！ 耶和华啊，求你使我们亨通！"},{"start":26,"end":26,"text":"奉耶和华名来的是应当称颂的！ 我们从耶和华的殿中为你们祝福！"},{"start":27,"end":27,"text":"耶和华是　神； 他光照了我们。 理当用绳索把祭牲拴住， [牵]到坛角那里。"},{"start":28,"end":28,"text":"你是我的　神，我要称谢你！ 你是我的　神，我要尊崇你！"},{"start":29,"end":29,"text":"你们要称谢耶和华，因他本为善； 他的慈爱永远长存！"}],"119":[{"start":89,"end":89,"text":"耶和华啊，你的话安定在天， 直到永远。"},{"start":90,"end":90,"text":"你的诚实存到万代； 你坚定了地，地就长存。"},{"start":91,"end":91,"text":"天地照你的安排存到今日； 万物都是你的仆役。"},{"start":92,"end":92,"text":"我若不是喜爱你的律法， 早就在苦难中灭绝了！"},{"start":93,"end":93,"text":"我永不忘记你的训词， 因你用这训词将我救活了。"},{"start":94,"end":94,"text":"我是属你的，求你救我， 因我寻求了你的训词。"},{"start":95,"end":95,"text":"恶人等待我，要灭绝我， 我却要揣摩你的法度。"},{"start":96,"end":96,"text":"我看万事尽都有限， 惟有你的命令极其宽广。"},{"start":97,"end":97,"text":"我何等爱慕你的律法， 终日不住地思想。"},{"start":98,"end":98,"text":"你的命令常存在我心里， 使我比仇敌有智慧。"},{"start":99,"end":99,"text":"我比我的师傅更通达， 因我思想你的法度。"},{"start":100,"end":100,"text":"我比年老的更明白， 因我守了你的训词。"},{"start":101,"end":101,"text":"我禁止我脚走一切的邪路， 为要遵守你的话。"},{"start":102,"end":102,"text":"我没有偏离你的典章， 因为你教训了我。"},{"start":103,"end":103,"text":"你的言语在我上膛何等甘美， 在我口中比蜜更甜！"},{"start":104,"end":104,"text":"我借着你的训词得以明白， 所以我恨一切的假道。"},{"start":105,"end":105,"text":"你的话是我脚前的灯， 是我路上的光。"},{"start":106,"end":106,"text":"你公义的典章，我曾起誓遵守， 我必按誓而行。"},{"start":107,"end":107,"text":"我甚是受苦； 耶和华啊，求你照你的话将我救活！"},{"start":108,"end":108,"text":"耶和华啊，求你悦纳我口中的赞美为供物， 又将你的典章教训我！"},{"start":109,"end":109,"text":"我的性命常在危险之中， 我却不忘记你的律法。"},{"start":110,"end":110,"text":"恶人为我设下网罗， 我却没有偏离你的训词。"},{"start":111,"end":111,"text":"我以你的法度为永远的产业， 因这是我心中所喜爱的。"},{"start":112,"end":112,"text":"我的心专向你的律例， 永远遵行，一直到底。"},{"start":113,"end":113,"text":"心怀二意的人为我所恨； 但你的律法为我所爱。"},{"start":114,"end":114,"text":"你是我藏身之处，又是我的盾牌； 我甚仰望你的话语。"},{"start":115,"end":115,"text":"作恶的人哪，你们离开我吧！ 我好遵守我　神的命令。"},{"start":116,"end":116,"text":"求你照你的话扶持我，使我存活， 也不叫我因失望而害羞。"},{"start":117,"end":117,"text":"求你扶持我，我便得救， 时常看重你的律例。"},{"start":118,"end":118,"text":"凡偏离你律例的人，你都轻弃他们， 因为他们的诡诈必归虚空。"},{"start":119,"end":119,"text":"凡地上的恶人，你除掉他，好像除掉渣滓； 因此我爱你的法度。"},{"start":120,"end":120,"text":"我因惧怕你，肉就发抖； 我也怕你的判语。"},{"start":121,"end":121,"text":"我行过公平和公义， 求你不要撇下我给欺压我的人！"},{"start":122,"end":122,"text":"求你为仆人作保，使我得好处， 不容骄傲人欺压我！"},{"start":123,"end":123,"text":"我因盼望你的救恩 和你公义的话眼睛失明。"},{"start":124,"end":124,"text":"求你照你的慈爱待仆人， 将你的律例教训我。"},{"start":125,"end":125,"text":"我是你的仆人，求你赐我悟性， 使我得知你的法度。"},{"start":126,"end":126,"text":"这是耶和华降罚的时候， 因人废了你的律法。"},{"start":127,"end":127,"text":"所以，我爱你的命令胜于金子， 更胜于精金。"},{"start":128,"end":128,"text":"你一切的训词，在万事上我都以为正直； 我却恨恶一切假道。"},{"start":129,"end":129,"text":"你的法度奇妙， 所以我一心谨守。"},{"start":130,"end":130,"text":"你的言语一解开就发出亮光， 使愚人通达。"},{"start":131,"end":131,"text":"我张口而气喘， 因我切慕你的命令。"},{"start":132,"end":132,"text":"求你转向我，怜悯我， 好像你素常待那些爱你名的人。"},{"start":133,"end":133,"text":"求你用你的话使我脚步稳当， 不许什么罪孽辖制我。"},{"start":134,"end":134,"text":"求你救我脱离人的欺压， 我要遵守你的训词。"},{"start":135,"end":135,"text":"求你用脸光照仆人， 又将你的律例教训我。"},{"start":136,"end":136,"text":"我的眼泪下流成河， 因为他们不守你的律法。"},{"start":137,"end":137,"text":"耶和华啊，你是公义的； 你的判语也是正直的！"},{"start":138,"end":138,"text":"你所命定的法度是凭公义和至诚。"},{"start":139,"end":139,"text":"我心焦急，如同火烧， 因我敌人忘记你的言语。"},{"start":140,"end":140,"text":"你的话极其精炼， 所以你的仆人喜爱。"},{"start":141,"end":141,"text":"我微小，被人藐视， 却不忘记你的训词。"},{"start":142,"end":142,"text":"你的公义永远长存； 你的律法尽都真实。"},{"start":143,"end":143,"text":"我遭遇患难愁苦， 你的命令却是我所喜爱的。"},{"start":144,"end":144,"text":"你的法度永远是公义的； 求你赐我悟性，我就活了。"},{"start":145,"end":145,"text":"耶和华啊，我一心呼吁你； 求你应允我，我必谨守你的律例！"},{"start":146,"end":146,"text":"我向你呼吁，求你救我！ 我要遵守你的法度。"},{"start":147,"end":147,"text":"我趁天未亮呼求； 我仰望了你的言语。"},{"start":148,"end":148,"text":"我趁夜更未换将眼睁开， 为要思想你的话语。"},{"start":149,"end":149,"text":"求你照你的慈爱听我的声音； 耶和华啊，求你照你的典章将我救活！"},{"start":150,"end":150,"text":"追求奸恶的人临近了； 他们远离你的律法。"},{"start":151,"end":151,"text":"耶和华啊，你与我相近； 你一切的命令尽都真实！"},{"start":152,"end":152,"text":"我因[学]你的法度， 久已知道是你永远立定的。"},{"start":153,"end":153,"text":"求你看顾我的苦难，搭救我， 因我不忘记你的律法。"},{"start":154,"end":154,"text":"求你为我辨屈，救赎我， 照你的话将我救活。"},{"start":155,"end":155,"text":"救恩远离恶人， 因为他们不寻求你的律例。"},{"start":156,"end":156,"text":"耶和华啊，你的慈悲本为大； 求你照你的典章将我救活。"},{"start":157,"end":157,"text":"逼迫我的，抵挡我的，很多， 我却没有偏离你的法度。"},{"start":158,"end":158,"text":"我看见奸恶的人就甚憎恶， 因为他们不遵守你的话。"},{"start":159,"end":159,"text":"你看我怎样爱你的训词！ 耶和华啊，求你照你的慈爱将我救活！"},{"start":160,"end":160,"text":"你话的总纲是真实； 你一切公义的典章是永远长存。"},{"start":161,"end":161,"text":"首领无故地逼迫我， 但我的心畏惧你的言语。"},{"start":162,"end":162,"text":"我喜爱你的话， 好像人得了许多掳物。"},{"start":163,"end":163,"text":"谎话是我所恨恶所憎嫌的； 惟你的律法是我所爱的。"},{"start":164,"end":164,"text":"我因你公义的典章一天七次赞美你。"},{"start":165,"end":165,"text":"爱你律法的人有大平安， 什么都不能使他们绊脚。"},{"start":166,"end":166,"text":"耶和华啊，我仰望了你的救恩， 遵行了你的命令。"},{"start":167,"end":167,"text":"我心里守了你的法度； 这法度我甚喜爱。"},{"start":168,"end":168,"text":"我遵守了你的训词和法度， 因我一切所行的都在你面前。"},{"start":169,"end":169,"text":"耶和华啊，愿我的呼吁达到你面前， 照你的话赐我悟性。"},{"start":170,"end":170,"text":"愿我的恳求达到你面前， 照你的话搭救我。"},{"start":171,"end":171,"text":"愿我的嘴发出赞美的话， 因为你将律例教训我。"},{"start":172,"end":172,"text":"愿我的舌头歌唱你的话， 因你一切的命令尽都公义。"},{"start":173,"end":173,"text":"愿你用手帮助我， 因我拣选了你的训词。"},{"start":174,"end":174,"text":"耶和华啊，我切慕你的救恩！ 你的律法也是我所喜爱的。"},{"start":175,"end":175,"text":"愿我的性命存活，得以赞美你！ 愿你的典章帮助我！"},{"start":176,"end":176,"text":"我如亡羊走迷了路，求你寻找仆人， 因我不忘记你的命令。"}],"127":[{"start":3,"end":3,"text":"儿女是耶和华所赐的产业； 所怀的胎是他所给的赏赐。"},{"start":4,"end":4,"text":"少年时[所生]的儿女 好像勇士手中的箭。"},{"start":5,"end":5,"text":"箭袋充满的人便为有福； 他们在城门口和仇敌说话的时候， 必不至于羞愧。"}],"132":[{"start":17,"end":17,"text":"我要叫大卫的角在那里发生； 我为我的受膏者预备明灯。"},{"start":18,"end":18,"text":"我要使他的仇敌披上羞耻； 但他的冠冕要在头上发光。"}],"146":[{"start":5,"end":5,"text":"以雅各的　神为帮助、 仰望耶和华—他　神的，这人便为有福！"},{"start":6,"end":6,"text":"耶和华造天、地、海，和其中的万物； 他守诚实，直到永远。"},{"start":7,"end":7,"text":"他为受屈的伸冤， 赐食物与饥饿的。 耶和华释放被囚的；"},{"start":8,"end":8,"text":"耶和华开了瞎子的[眼睛]； 耶和华扶起被压下的人。 耶和华喜爱义人。"},{"start":9,"end":9,"text":"耶和华保护寄居的， 扶持孤儿和寡妇， 却使恶人的道路弯曲。"},{"start":10,"end":10,"text":"耶和华要作王，直到永远！ 锡安哪，你的　神要作王，直到万代！ 你们要赞美耶和华！"}]},"MAT":{"1":[{"start":18,"end":18,"text":"耶稣基督降生的事记在下面：他母亲马利亚已经许配了约瑟，还没有迎娶，马利亚就从圣灵怀了孕。"},{"start":19,"end":19,"text":"她丈夫约瑟是个义人，不愿意明明地羞辱她，想要暗暗地把她休了。"},{"start":20,"end":20,"text":"正思念这事的时候，有主的使者向他梦中显现，[说]：「大卫的子孙约瑟，不要怕！只管娶过你的妻子马利亚来，因她所怀的孕是从圣灵来的。"},{"start":21,"end":21,"text":"她将要生一个儿子，你要给他起名叫耶稣，因他要将自己的百姓从罪恶里救出来。」"},{"start":22,"end":22,"text":"这一切的事成就是要应验主借先知所说的话，"},{"start":23,"end":23,"text":"说： 必有童女怀孕生子； 人要称他的名为以马内利。 （以马内利翻出来就是「　神与我们同在」。）"},{"start":24,"end":24,"text":"约瑟醒了，起来，就遵着主使者的吩咐把妻子娶过来；"},{"start":25,"end":25,"text":"只是没有和她同房，等她生了儿子，就给他起名叫耶稣。"}],"3":[{"start":13,"end":13,"text":"当下，耶稣从加利利来到约旦河，见了约翰，要受他的洗。"},{"start":14,"end":14,"text":"约翰想要拦住他，说：「我当受你的洗，你反倒上我这里来吗？」"},{"start":15,"end":15,"text":"耶稣回答说：「你暂且许我，因为我们理当这样尽诸般的义。」于是约翰许了他。"},{"start":16,"end":16,"text":"耶稣受了洗，随即从水里上来。天忽然为他开了，他就看见　神的灵仿佛鸽子降下，落在他身上。"},{"start":17,"end":17,"text":"从天上有声音说：「这是我的爱子，我所喜悦的。」"}],"5":[{"start":17,"end":17,"text":"「莫想我来要废掉律法和先知。我来不是要废掉，乃是要成全。"},{"start":18,"end":18,"text":"我实在告诉你们，就是到天地都废去了，律法的一点一画也不能废去，都要成全。"},{"start":19,"end":19,"text":"所以，无论何人废掉这诫命中最小的一条，又教训人这样做，他在天国要称为最小的。但无论何人遵行这诫命，又教训人遵行，他在天国要称为大的。"},{"start":20,"end":20,"text":"我告诉你们，你们的义若不胜于文士和法利赛人的义，断不能进天国。」"}],"6":[{"start":9,"end":9,"text":"所以，你们祷告要这样说： 我们在天上的父： 愿人都尊你的名为圣。"},{"start":10,"end":10,"text":"愿你的国降临； 愿你的旨意行在地上， 如同行在天上。"},{"start":11,"end":11,"text":"我们日用的饮食，今日赐给我们。"},{"start":12,"end":12,"text":"免我们的债， 如同我们免了人的债。"},{"start":13,"end":13,"text":"不叫我们遇见试探； 救我们脱离凶恶。 因为国度、权柄、荣耀，全是你的， 直到永远。阿们！"},{"start":25,"end":25,"text":"「所以我告诉你们，不要为生命忧虑吃什么，喝什么；为身体忧虑穿什么。生命不胜于饮食吗？身体不胜于衣裳吗？"},{"start":26,"end":26,"text":"你们看那天上的飞鸟，也不种，也不收，也不积蓄在仓里，你们的天父尚且养活它。你们不比飞鸟贵重得多吗？"},{"start":27,"end":27,"text":"你们哪一个能用思虑使寿数多加一刻呢？"},{"start":28,"end":28,"text":"何必为衣裳忧虑呢？你想野地里的百合花怎么长起来；它也不劳苦，也不纺线。"},{"start":29,"end":29,"text":"然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！"},{"start":30,"end":30,"text":"你们这小信的人哪！野地里的草今天还在，明天就丢在炉里，　神还给它这样的妆饰，何况你们呢！"},{"start":31,"end":31,"text":"所以，不要忧虑说，吃什么？喝什么？穿什么？"},{"start":32,"end":32,"text":"这都是外邦人所求的。你们需用的这一切东西，你们的天父是知道的。"},{"start":33,"end":33,"text":"你们要先求他的国和他的义，这些东西都要加给你们了。"},{"start":34,"end":34,"text":"所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就够了。」"}],"7":[{"start":13,"end":13,"text":"「你们要进窄门。因为引到灭亡，那门是宽的，路是大的，进去的人也多；"},{"start":14,"end":14,"text":"引到[永]生，那门是窄的，路是小的，找着的人也少。」"}],"8":[{"start":5,"end":5,"text":"耶稣进了迦百农，有一个百夫长进前来，求他说："},{"start":6,"end":6,"text":"「主啊，我的仆人害瘫痪病，躺在家里，甚是疼苦。」"},{"start":7,"end":7,"text":"耶稣说：「我去医治他。」"},{"start":8,"end":8,"text":"百夫长回答说：「主啊，你到我舍下，我不敢当；只要你说一句话，我的仆人就必好了。"},{"start":9,"end":9,"text":"因为我在人的权下，也有兵在我以下；对这个说『去！』他就去；对那个说『来！』他就来；对我的仆人说：『你做这事！』他就去做。」"},{"start":10,"end":10,"text":"耶稣听见就希奇，对跟从的人说：「我实在告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。"},{"start":11,"end":11,"text":"我又告诉你们，从东从西，将有许多人来，在天国里与亚伯拉罕、以撒、雅各一同坐席；"},{"start":12,"end":12,"text":"惟有本国的子民竟被赶到外边黑暗里去，在那里必要哀哭切齿了。」"},{"start":13,"end":13,"text":"耶稣对百夫长说：「你回去吧！照你的信心，给你成全了。」那时，他的仆人就好了。"}],"9":[{"start":9,"end":9,"text":"耶稣从那里往前走，看见一个人名叫马太，坐在税关上，就对他说：「你跟从我来。」他就起来跟从了耶稣。"},{"start":10,"end":10,"text":"耶稣在屋里坐席的时候，有好些税吏和罪人来，与耶稣和他的门徒一同坐席。"},{"start":11,"end":11,"text":"法利赛人看见，就对耶稣的门徒说：「你们的先生为什么和税吏并罪人一同吃饭呢？」"},{"start":12,"end":12,"text":"耶稣听见，就说：「康健的人用不着医生，有病的人才用得着。"},{"start":13,"end":13,"text":"[经上说]：『我喜爱怜恤，不喜爱祭祀。』这句话的意思，你们且去揣摩。我来本不是召义人，乃是召罪人。」"}],"10":[{"start":26,"end":26,"text":"「所以，不要怕他们；因为掩盖的事没有不露出来的，隐藏的事没有不被人知道的。"},{"start":27,"end":27,"text":"我在暗中告诉你们的，你们要在明处说出来；你们耳中所听的，要在房上宣扬出来。"},{"start":28,"end":28,"text":"那杀身体、不能杀灵魂的，不要怕他们；惟有能把身体和灵魂都灭在地狱里的，正要怕他。"},{"start":29,"end":29,"text":"两个麻雀不是卖一分银子吗？若是你们的父不许，一个也不能掉在地上；"},{"start":30,"end":30,"text":"就是你们的头发也都被数过了。"},{"start":31,"end":31,"text":"所以，不要惧怕，你们比许多麻雀还贵重！」"},{"start":32,"end":32,"text":"「凡在人面前认我的，我在我天上的父面前也必认他；"},{"start":33,"end":33,"text":"凡在人面前不认我的，我在我天上的父面前也必不认他。」"},{"start":34,"end":34,"text":"「你们不要想我来是叫地上太平；我来并不是叫地上太平，乃是叫地上动刀兵。"},{"start":35,"end":35,"text":"因为我来是叫 人与父亲生疏， 女儿与母亲生疏， 媳妇与婆婆生疏。"},{"start":36,"end":36,"text":"人的仇敌就是自己家里的人。"},{"start":37,"end":37,"text":"「爱父母过于爱我的，不配作我的门徒；爱儿女过于爱我的，不配作我的门徒；"},{"start":38,"end":38,"text":"不背着他的十字架跟从我的，也不配作我的门徒。"},{"start":39,"end":39,"text":"得着生命的，将要失丧生命；为我失丧生命的，将要得着生命。」"},{"start":40,"end":40,"text":"「人接待你们就是接待我；接待我就是接待那差我来的。"},{"start":41,"end":41,"text":"人因为先知的名接待先知，必得先知所得的赏赐；人因为义人的名接待义人，必得义人所得的赏赐。"},{"start":42,"end":42,"text":"无论何人，因为门徒的名，只把一杯凉水给这小子里的一个喝，我实在告诉你们，这人不能不得赏赐。」"}],"11":[{"start":2,"end":2,"text":"约翰在监里听见基督所做的事，就打发[两个]门徒去，"},{"start":3,"end":3,"text":"问他说：「那将要来的是你吗？还是我们等候别人呢？」"},{"start":4,"end":4,"text":"耶稣回答说：「你们去，把所听见、所看见的事告诉约翰。"},{"start":5,"end":5,"text":"就是瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。"},{"start":6,"end":6,"text":"凡不因我跌倒的就有福了！」"}],"12":[{"start":1,"end":1,"text":"那时，耶稣在安息日从麦地经过。他的门徒饿了，就掐起麦穗来吃。"},{"start":2,"end":2,"text":"法利赛人看见，就对耶稣说：「看哪，你的门徒做安息日不可做的事了！」"},{"start":3,"end":3,"text":"耶稣对他们说：「[经上记着]大卫和跟从他的人饥饿之时所做的事，你们没有念过吗？"},{"start":4,"end":4,"text":"他怎么进了　神的殿，吃了陈设饼，这饼不是他和跟从他的人可以吃得，惟独祭司才可以吃。"},{"start":5,"end":5,"text":"再者，律法上所记的，当安息日，祭司在殿里犯了安息日还是没有罪，你们没有念过吗？"},{"start":6,"end":6,"text":"但我告诉你们，在这里有一人比殿更大。"},{"start":7,"end":7,"text":"『我喜爱怜恤，不喜爱祭祀。』你们若明白这话的意思，就不将无罪的当作有罪的了。"},{"start":8,"end":8,"text":"因为人子是安息日的主。」"},{"start":9,"end":9,"text":"耶稣离开那地方，进了一个会堂。"},{"start":10,"end":10,"text":"那里有一个人枯干了一只手。有人问耶稣说：「安息日治病可以不可以？」意思是要控告他。"},{"start":11,"end":11,"text":"耶稣说：「你们中间谁有一只羊，当安息日掉在坑里，不把它抓住、拉上来呢？"},{"start":12,"end":12,"text":"人比羊何等贵重呢！所以，在安息日做善事是可以的。」"},{"start":13,"end":13,"text":"于是对那人说：「伸出手来！」他把手一伸，手就复了原，和那只手一样。"},{"start":14,"end":14,"text":"法利赛人出去，商议怎样可以除灭耶稣。"},{"start":22,"end":22,"text":"当下，有人将一个被鬼附着、又瞎又哑的人带到耶稣那里，耶稣就医治他，甚至那哑巴又能说话，又能看见。"},{"start":23,"end":23,"text":"众人都惊奇，说：「这不是大卫的子孙吗？」"},{"start":24,"end":24,"text":"但法利赛人听见，就说：「这个人赶鬼，无非是靠着鬼王别西卜啊。」"},{"start":25,"end":25,"text":"耶稣知道他们的意念，就对他们说：「凡一国自相纷争，就成为荒场；一城一家自相纷争，必站立不住；"},{"start":26,"end":26,"text":"若撒但赶逐撒但，就是自相纷争，他的国怎能站得住呢？"},{"start":27,"end":27,"text":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们就要断定你们的是非。"},{"start":28,"end":28,"text":"我若靠着　神的灵赶鬼，这就是　神的国临到你们了。"},{"start":29,"end":29,"text":"人怎能进壮士家里，抢夺他的家具呢？除非先捆住那壮士，才可以抢夺他的[家财]。"},{"start":30,"end":30,"text":"不与我相合的，就是敌我的；不同我收聚的，就是分散的。」"},{"start":31,"end":31,"text":"所以我告诉你们：「人一切的罪和亵渎的话都可得赦免，惟独亵渎圣灵，总不得赦免。"},{"start":32,"end":32,"text":"凡说话干犯人子的，还可得赦免；惟独说话干犯圣灵的，今世来世总不得赦免。」"},{"start":38,"end":38,"text":"当时，有几个文士和法利赛人对耶稣说：「夫子，我们愿意你显个神迹给我们看。」"},{"start":39,"end":39,"text":"耶稣回答说：「一个邪恶淫乱的世代求看神迹，除了先知约拿的神迹以外，再没有神迹给他们看。"},{"start":40,"end":40,"text":"约拿三日三夜在大鱼肚腹中，人子也要这样三日三夜在地里头。"},{"start":41,"end":41,"text":"当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，在这里有一人比约拿更大！"},{"start":42,"end":42,"text":"当审判的时候，南方的女王要起来定这世代的罪；因为她从地极而来，要听所罗门的智慧话。看哪，在这里有一人比所罗门更大！」"}],"13":[{"start":31,"end":31,"text":"他又设个比喻对他们说：「天国好像一粒芥菜种，有人拿去种在田里。"},{"start":32,"end":32,"text":"这原是百种里最小的，等到长起来，却比各样的菜都大，且成了树，天上的飞鸟来宿在它的枝上。」"},{"start":33,"end":33,"text":"他又对他们讲个比喻说：「天国好像面酵，有妇人拿来，藏在三斗面里，直等全团都发起来。」"}],"18":[{"start":1,"end":1,"text":"当时，门徒进前来，问耶稣说：「天国里谁是最大的？」"},{"start":2,"end":2,"text":"耶稣便叫一个小孩子来，使他站在他们当中，"},{"start":3,"end":3,"text":"说：「我实在告诉你们，你们若不回转，变成小孩子的样式，断不得进天国。"},{"start":4,"end":4,"text":"所以，凡自己谦卑像这小孩子的，他在天国里就是最大的。"},{"start":5,"end":5,"text":"凡为我的名接待一个像这小孩子的，就是接待我。」"},{"start":6,"end":6,"text":"「凡使这信我的一个小子跌倒的，倒不如把大磨石拴在这人的颈项上，沉在深海里。"},{"start":7,"end":7,"text":"这世界有祸了，因为将人绊倒；绊倒人的事是免不了的，但那绊倒人的有祸了！"},{"start":8,"end":8,"text":"倘若你一只手，或是一只脚，叫你跌倒，就砍下来丢掉。你缺一只手，或是一只脚，进入永生，强如有两手两脚被丢在永火里。"},{"start":9,"end":9,"text":"倘若你一只眼叫你跌倒，就把它剜出来丢掉。你只有一只眼进入[永]生，强如有两只眼被丢在地狱的火里。」"},{"start":10,"end":10,"text":"「你们要小心，不可轻看这小子里的一个；我告诉你们，他们的使者在天上，常见我天父的面。"},{"start":12,"end":12,"text":"一个人若有一百只羊，一只走迷了路，你们的意思如何？他岂不撇下这九十九只，往山里去找那只迷路的羊吗？"},{"start":13,"end":13,"text":"若是找着了，我实在告诉你们，他为这一只羊欢喜，比为那没有迷路的九十九只欢喜还大呢！"},{"start":14,"end":14,"text":"你们在天上的父也是这样，不愿意这小子里失丧一个。」"},{"start":15,"end":15,"text":"「倘若你的弟兄得罪你，你就去，趁着只有他和你在一处的时候，指出他的错来。他若听你，你便得了你的弟兄；"},{"start":16,"end":16,"text":"他若不听，你就另外带一两个人同去，要凭两三个人的口作见证，句句都可定准。"},{"start":17,"end":17,"text":"若是不听他们，就告诉教会；若是不听教会，就看他像外邦人和税吏一样。"},{"start":18,"end":18,"text":"「我实在告诉你们，凡你们在地上所捆绑的，在天上也要捆绑；凡你们在地上所释放的，在天上也要释放。"},{"start":19,"end":19,"text":"我又告诉你们，若是你们中间有两个人在地上同心合意地求什么事，我在天上的父必为他们成全。"},{"start":20,"end":20,"text":"因为无论在哪里，有两三个人奉我的名聚会，那里就有我在他们中间。」"},{"start":21,"end":21,"text":"那时，彼得进前来，对耶稣说：「主啊，我弟兄得罪我，我当饶恕他几次呢？到七次可以吗？」"},{"start":22,"end":22,"text":"耶稣说：「我对你说，不是到七次，乃是到七十个七次。"},{"start":23,"end":23,"text":"天国好像一个王要和他仆人算帐。"},{"start":24,"end":24,"text":"才算的时候，有人带了一个欠一千万银子的来。"},{"start":25,"end":25,"text":"因为他没有什么偿还之物，主人吩咐把他和他妻子儿女，并一切所有的都卖了偿还。"},{"start":26,"end":26,"text":"那仆人就俯伏拜他，说：『主啊，宽容我，将来我都要还清。』"},{"start":27,"end":27,"text":"那仆人的主人就动了慈心，把他释放了，并且免了他的债。"},{"start":28,"end":28,"text":"「那仆人出来，遇见他的一个同伴欠他十两银子，便揪着他，掐住他的喉咙，说：『你把所欠的还我！』"},{"start":29,"end":29,"text":"他的同伴就俯伏央求他，说：『宽容我吧，将来我必还清。』"},{"start":30,"end":30,"text":"他不肯，竟去把他下在监里，等他还了所欠的债。"},{"start":31,"end":31,"text":"众同伴看见他所做的事就甚忧愁，去把这事都告诉了主人。"},{"start":32,"end":32,"text":"于是主人叫了他来，对他说：『你这恶奴才！你央求我，我就把你所欠的都免了，"},{"start":33,"end":33,"text":"你不应当怜恤你的同伴，像我怜恤你吗？』"},{"start":34,"end":34,"text":"主人就大怒，把他交给掌刑的，等他还清了所欠的债。"},{"start":35,"end":35,"text":"你们各人若不从心里饶恕你的弟兄，我天父也要这样待你们了。」"}],"19":[{"start":16,"end":16,"text":"有一个人来见耶稣，说：「夫子，我该做什么善事才能得永生？」"},{"start":17,"end":17,"text":"耶稣对他说：「你为什么以善事问我呢？只有一位是善的。你若要进入[永]生，就当遵守诫命。」"},{"start":18,"end":18,"text":"他说：「什么诫命？」耶稣说：「就是不可杀人；不可奸淫；不可偷盗；不可作假见证；"},{"start":19,"end":19,"text":"当孝敬父母；又当爱人如己。」"},{"start":20,"end":20,"text":"那少年人说：「这一切我都遵守了，还缺少什么呢？」"},{"start":21,"end":21,"text":"耶稣说：「你若愿意作完全人，可去变卖你所有的，分给穷人，就必有财宝在天上；你还要来跟从我。」"},{"start":22,"end":22,"text":"那少年人听见这话，就忧忧愁愁地走了，因为他的产业很多。"},{"start":23,"end":23,"text":"耶稣对门徒说：「我实在告诉你们，财主进天国是难的。"},{"start":24,"end":24,"text":"我又告诉你们，骆驼穿过针的眼，比财主进　神的国还容易呢！」"},{"start":25,"end":25,"text":"门徒听见这话，就希奇得很，说：「这样谁能得救呢？」"},{"start":26,"end":26,"text":"耶稣看着他们，说：「在人这是不能的，在　神凡事都能。」"},{"start":27,"end":27,"text":"彼得就对他说：「看哪，我们已经撇下所有的跟从你，将来我们要得什么呢？」"},{"start":28,"end":28,"text":"耶稣说：「我实在告诉你们，你们这跟从我的人，到复兴的时候，人子坐在他荣耀的宝座上，你们也要坐在十二个宝座上，审判以色列十二个支派。"},{"start":29,"end":29,"text":"凡为我的名撇下房屋，或是弟兄、姊妹、父亲、母亲、 儿女、田地的，必要得着百倍，并且承受永生。"},{"start":30,"end":30,"text":"然而，有许多在前的，将要在后；在后的，将要在前。」"}],"20":[{"start":1,"end":1,"text":"「因为天国好像家主清早去雇人进他的葡萄园做工，"},{"start":2,"end":2,"text":"和工人讲定一天一钱银子，就打发他们进葡萄园去。"},{"start":3,"end":3,"text":"约在巳初出去，看见市上还有闲站的人，"},{"start":4,"end":4,"text":"就对他们说：『你们也进葡萄园去，所当给的，我必给你们。』他们也进去了。"},{"start":5,"end":5,"text":"约在午正和申初又出去，也是这样行。"},{"start":6,"end":6,"text":"约在酉初出去，看见还有人站在那里，就问他们说：『你们为什么整天在这里闲站呢？』"},{"start":7,"end":7,"text":"他们说：『因为没有人雇我们。』他说：『你们也进葡萄园去。』"},{"start":8,"end":8,"text":"到了晚上，园主对管事的说：『叫工人都来，给他们工钱，从后来的起，到先来的为止。"},{"start":9,"end":9,"text":"约在酉初雇的人来了，各人得了一钱银子。"},{"start":10,"end":10,"text":"及至那先雇的来了，他们以为必要多得；谁知也是各得一钱。"},{"start":11,"end":11,"text":"他们得了，就埋怨家主说："},{"start":12,"end":12,"text":"『我们整天劳苦受热，那后来的只做了一小时，你竟叫他们和我们一样吗？』"},{"start":13,"end":13,"text":"家主回答其中的一人说：『朋友，我不亏负你，你与我讲定的不是一钱银子吗？"},{"start":14,"end":14,"text":"拿你的走吧！我给那后来的和给你一样，这是我愿意的。"},{"start":15,"end":15,"text":"我的东西难道不可随我的意思用吗？因为我作好人，你就红了眼吗？』"},{"start":16,"end":16,"text":"这样，那在后的，将要在前；在前的，将要在后了。」"}],"22":[{"start":1,"end":1,"text":"耶稣又用比喻对他们说："},{"start":2,"end":2,"text":"「天国好比一个王为他儿子摆设娶亲的筵席，"},{"start":3,"end":3,"text":"就打发仆人去，请那些被召的人来赴席，他们却不肯来。"},{"start":4,"end":4,"text":"王又打发别的仆人，说：『你们告诉那被召的人，我的筵席已经预备好了，牛和肥畜已经宰了，各样都齐备，请你们来赴席。』"},{"start":5,"end":5,"text":"那些人不理就走了；一个到自己田里去；一个做买卖去；"},{"start":6,"end":6,"text":"其余的拿住仆人，凌辱他们，把他们杀了。"},{"start":7,"end":7,"text":"王就大怒，发兵除灭那些凶手，烧毁他们的城。"},{"start":8,"end":8,"text":"于是对仆人说：『喜筵已经齐备，只是所召的人不配。"},{"start":9,"end":9,"text":"所以你们要往岔路口上去，凡遇见的，都召来赴席。』"},{"start":10,"end":10,"text":"那些仆人就出去，到大路上，凡遇见的，不论善恶都召聚了来，筵席上就坐满了客。"},{"start":11,"end":11,"text":"王进来观看宾客，见那里有一个没有穿礼服的，"},{"start":12,"end":12,"text":"就对他说：『朋友，你到这里来怎么不穿礼服呢？』那人无言可答。"},{"start":13,"end":13,"text":"于是王对使唤的人说：『捆起他的手脚来，把他丢在外边的黑暗里；在那里必要哀哭切齿了。』"},{"start":14,"end":14,"text":"因为被召的人多，选上的人少。」"}],"23":[{"start":1,"end":1,"text":"那时，耶稣对众人和门徒讲论，"},{"start":2,"end":2,"text":"说：「文士和法利赛人坐在摩西的位上，"},{"start":3,"end":3,"text":"凡他们所吩咐你们的，你们都要谨守遵行。但不要效法他们的行为；因为他们能说，不能行。"},{"start":4,"end":4,"text":"他们把难担的重担捆起来，搁在人的肩上，但自己一个指头也不肯动。"},{"start":5,"end":5,"text":"他们一切所做的事都是要叫人看见，所以将佩戴的经文做宽了，[衣裳的] 子做长了，"},{"start":6,"end":6,"text":"喜爱筵席上的首座，会堂里的高位，"},{"start":7,"end":7,"text":"又喜爱人在街市上问他安，称呼他拉比。"},{"start":8,"end":8,"text":"但你们不要受拉比的称呼，因为只有一位是你们的夫子；你们都是弟兄。"},{"start":9,"end":9,"text":"也不要称呼地上的人为父，因为只有一位是你们的父，就是在天上的父。"},{"start":10,"end":10,"text":"也不要受师尊的称呼，因为只有一位是你们的师尊，就是基督。"},{"start":11,"end":11,"text":"你们中间谁为大，谁就要作你们的用人。"},{"start":12,"end":12,"text":"凡自高的，必降为卑；自卑的，必升为高。"},{"start":13,"end":13,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们正当人前，把天国[的门]关了，自己不进去，正要进去的人，你们也不容他们进去。"},{"start":15,"end":15,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们走遍洋海陆地，勾引一个人入教，既入了教，却使他作地狱之子，比你们还加倍。"},{"start":16,"end":16,"text":"「你们这瞎眼领路的有祸了！你们说：『凡指着殿起誓的，这算不得什么；只是凡指着殿中金子起誓的，他就该谨守。』"},{"start":17,"end":17,"text":"你们这无知瞎眼的人哪，什么是大的？是金子呢？还是叫金子成圣的殿呢？"},{"start":18,"end":18,"text":"你们又说：『凡指着坛起誓的，这算不得什么；只是凡指着坛上礼物起誓的，他就该谨守。』"},{"start":19,"end":19,"text":"你们这瞎眼的人哪，什么是大的？是礼物呢？还是叫礼物成圣的坛呢？"},{"start":20,"end":20,"text":"所以，人指着坛起誓，就是指着坛和坛上一切所有的起誓；"},{"start":21,"end":21,"text":"人指着殿起誓，就是指着殿和那住在殿里的起誓；"},{"start":22,"end":22,"text":"人指着天起誓，就是指着　神的宝座和那坐在上面的起誓。"},{"start":23,"end":23,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们将薄荷、茴香、芹菜献上十分之一，那律法上更重的事，就是公义、怜悯、信实，反倒不行了。这[更重的]是你们当行的；那也是不可不行的。"},{"start":24,"end":24,"text":"你们这瞎眼领路的，蠓虫你们就滤出来，骆驼你们倒吞下去。"},{"start":25,"end":25,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们洗净杯盘的外面，里面却盛满了勒索和放荡。"},{"start":26,"end":26,"text":"你这瞎眼的法利赛人，先洗净杯盘的里面，好叫外面也干净了。"},{"start":27,"end":27,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们好像粉饰的坟墓，外面好看，里面却装满了死人的骨头和一切的污秽。"},{"start":28,"end":28,"text":"你们也是如此，在人前，外面显出公义来，里面却装满了假善和不法的事。"},{"start":29,"end":29,"text":"「你们这假冒为善的文士和法利赛人有祸了！因为你们建造先知的坟，修饰义人的墓，说："},{"start":30,"end":30,"text":"『若是我们在我们祖宗的时候，必不和他们同流先知的血。』"},{"start":31,"end":31,"text":"这就是你们自己证明是杀害先知者的子孙了。"},{"start":32,"end":32,"text":"你们去充满你们祖宗的恶贯吧！"},{"start":33,"end":33,"text":"你们这些蛇类、毒蛇之种啊，怎能逃脱地狱的刑罚呢？"},{"start":34,"end":34,"text":"所以我差遣先知和智慧人并文士到你们这里来，有的你们要杀害，要钉十字架；有的你们要在会堂里鞭打，从这城追逼到那城，"},{"start":35,"end":35,"text":"叫世上所流义人的血都归到你们身上，从义人亚伯的血起，直到你们在殿和坛中间所杀的巴拉加的儿子撒迦利亚的血为止。"},{"start":36,"end":36,"text":"我实在告诉你们，这一切的罪都要归到这世代了。」"},{"start":37,"end":37,"text":"「耶路撒冷啊，耶路撒冷啊，你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，只是你们不愿意。"},{"start":38,"end":38,"text":"看哪，你们的家成为荒场留给你们。"},{"start":39,"end":39,"text":"我告诉你们，从今以后，你们不得再见我，直等到你们说：『奉主名来的是应当称颂的。』」"}],"24":[{"start":32,"end":32,"text":"「你们可以从无花果树学个比方：当树枝发嫩长叶的时候，你们就知道夏天近了。"},{"start":33,"end":33,"text":"这样，你们看见这一切的事，也该知道人子近了，正在门口了。"},{"start":34,"end":34,"text":"我实在告诉你们，这世代还没有过去，这些事都要成就。"},{"start":35,"end":35,"text":"天地要废去，我的话却不能废去。」"},{"start":36,"end":36,"text":"「但那日子，那时辰，没有人知道，连天上的使者也不知道，子也不知道，惟独父知道。"},{"start":37,"end":37,"text":"挪亚的日子怎样，人子降临也要怎样。"},{"start":38,"end":38,"text":"当洪水以前的日子，人照常吃喝嫁娶，直到挪亚进方舟的那日；"},{"start":39,"end":39,"text":"不知不觉洪水来了，把他们全都冲去。人子降临也要这样。"},{"start":40,"end":40,"text":"那时，两个人在田里，取去一个，撇下一个。"},{"start":41,"end":41,"text":"两个女人推磨，取去一个，撇下一个。"},{"start":42,"end":42,"text":"所以，你们要警醒，因为不知道你们的主是哪一天来到。"},{"start":43,"end":43,"text":"家主若知道几更天有贼来，就必警醒，不容人挖透房屋；这是你们所知道的。"},{"start":44,"end":44,"text":"所以，你们也要预备，因为你们想不到的时候，人子就来了。」"},{"start":45,"end":45,"text":"「谁是忠心有见识的仆人，为主人所派，管理家里的人，按时分粮给他们呢？"},{"start":46,"end":46,"text":"主人来到，看见他这样行，那仆人就有福了。"},{"start":47,"end":47,"text":"我实在告诉你们，主人要派他管理一切所有的。"},{"start":48,"end":48,"text":"倘若那恶仆心里说：『我的主人必来得迟』，"},{"start":49,"end":49,"text":"就动手打他的同伴，又和酒醉的人一同吃喝。"},{"start":50,"end":50,"text":"在想不到的日子，不知道的时辰，那仆人的主人要来，"},{"start":51,"end":51,"text":"重重地处治他，定他和假冒为善的人同罪；在那里必要哀哭切齿了。」"}],"25":[{"start":14,"end":14,"text":"「[天国]又好比一个人要往外国去，就叫了仆人来，把他的家业交给他们，"},{"start":15,"end":15,"text":"按着各人的才干给他们银子：一个给了五千，一个给了二千，一个给了一千，就往外国去了。"},{"start":16,"end":16,"text":"那领五千的随即拿去做买卖，另外赚了五千。"},{"start":17,"end":17,"text":"那领二千的也照样另赚了二千。"},{"start":18,"end":18,"text":"但那领一千的去掘开地，把主人的银子埋藏了。"},{"start":19,"end":19,"text":"过了许久，那些仆人的主人来了，和他们算帐。"},{"start":20,"end":20,"text":"那领五千银子的又带着那另外的五千来，说：『主啊，你交给我五千银子。请看，我又赚了五千。』"},{"start":21,"end":21,"text":"主人说：『好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。』"},{"start":22,"end":22,"text":"那领二千的也来，说：『主啊，你交给我二千银子。请看，我又赚了二千。』"},{"start":23,"end":23,"text":"主人说：『好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。』"},{"start":24,"end":24,"text":"那领一千的也来，说：『主啊，我知道你是忍心的人，没有种的地方要收割，没有散的地方要聚敛，"},{"start":25,"end":25,"text":"我就害怕，去把你的一千银子埋藏在地里。请看，你的原银子在这里。』"},{"start":26,"end":26,"text":"主人回答说：『你这又恶又懒的仆人，你既知道我没有种的地方要收割，没有散的地方要聚敛，"},{"start":27,"end":27,"text":"就当把我的银子放给兑换银钱的人，到我来的时候，可以连本带利收回。"},{"start":28,"end":28,"text":"夺过他这一千来，给那有一万的。"},{"start":29,"end":29,"text":"因为凡有的，还要加给他，叫他有余；没有的，连他所有的也要夺过来。"},{"start":30,"end":30,"text":"把这无用的仆人丢在外面黑暗里；在那里必要哀哭切齿了。』」"}],"26":[{"start":36,"end":36,"text":"耶稣同门徒来到一个地方，名叫客西马尼，就对他们说：「你们坐在这里，等我到那边去祷告。」"},{"start":37,"end":37,"text":"于是带着彼得和西庇太的两个儿子同去，就忧愁起来，极其难过，"},{"start":38,"end":38,"text":"便对他们说：「我心里甚是忧伤，几乎要死；你们在这里等候，和我一同警醒。」"},{"start":39,"end":39,"text":"他就稍往前走，俯伏在地，祷告说：「我父啊，倘若可行，求你叫这杯离开我。然而，不要照我的意思，只要照你的意思。」"},{"start":40,"end":40,"text":"来到门徒那里，见他们睡着了，就对彼得说：「怎么样？你们不能同我警醒片时吗？"},{"start":41,"end":41,"text":"总要警醒祷告，免得入了迷惑。你们心灵固然愿意，肉体却软弱了。」"},{"start":42,"end":42,"text":"第二次又去祷告说：「我父啊，这杯若不能离开我，必要我喝，就愿你的意旨成全。」"},{"start":43,"end":43,"text":"又来，见他们睡着了，因为他们的眼睛困倦。"},{"start":44,"end":44,"text":"耶稣又离开他们去了。第三次祷告，说的话还是与先前一样。"},{"start":45,"end":45,"text":"于是来到门徒那里，对他们说：「现在你们仍然睡觉安歇吧！时候到了，人子被卖在罪人手里了。"},{"start":46,"end":46,"text":"起来！我们走吧。看哪，卖我的人近了！」"}]},"GEN":{"1":[{"start":1,"end":1,"text":"起初，　神创造天地。"},{"start":2,"end":2,"text":"地是空虚混沌，渊面黑暗；　神的灵运行在水面上。"},{"start":3,"end":3,"text":"神说：「要有光」，就有了光。"},{"start":4,"end":4,"text":"神看光是好的，就把光暗分开了。"},{"start":5,"end":5,"text":"神称光为「昼」，称暗为「夜」。有晚上，有早晨，这是头一日。"},{"start":6,"end":6,"text":"神说：「诸水之间要有空气，将水分为上下。」"},{"start":7,"end":7,"text":"神就造出空气，将空气以下的水、空气以上的水分开了。事就这样成了。"},{"start":8,"end":8,"text":"神称空气为「天」。有晚上，有早晨，是第二日。"},{"start":9,"end":9,"text":"神说：「天下的水要聚在一处，使旱地露出来。」事就这样成了。"},{"start":10,"end":10,"text":"神称旱地为「地」，称水的聚处为「海」。　神看着是好的。"},{"start":11,"end":11,"text":"神说：「地要发生青草和结种子的菜蔬，并结果子的树木，各从其类，果子都包着核。」事就这样成了。"},{"start":12,"end":12,"text":"于是地发生了青草和结种子的菜蔬，各从其类；并结果子的树木，各从其类；果子都包着核。　神看着是好的。"},{"start":13,"end":13,"text":"有晚上，有早晨，是第三日。"},{"start":14,"end":14,"text":"神说：「天上要有光体，可以分昼夜，作记号，定节令、日子、年岁，"},{"start":15,"end":15,"text":"并要发光在天空，普照在地上。」事就这样成了。"},{"start":16,"end":16,"text":"于是　神造了两个大光，大的管昼，小的管夜，又[造]众星，"},{"start":17,"end":17,"text":"就把这些光摆列在天空，普照在地上，"},{"start":18,"end":18,"text":"管理昼夜，分别明暗。　神看着是好的。"},{"start":19,"end":19,"text":"有晚上，有早晨，是第四日。"},{"start":20,"end":20,"text":"神说：「水要多多滋生有生命的物；要有雀鸟飞在地面以上，天空之中。」"},{"start":21,"end":21,"text":"神就造出大鱼和水中所滋生各样有生命的动物，各从其类；又造出各样飞鸟，各从其类。　神看着是好的。"},{"start":22,"end":22,"text":"神就赐福给这一切，说：「滋生繁多，充满海中的水；雀鸟也要多生在地上。」"},{"start":23,"end":23,"text":"有晚上，有早晨，是第五日。"},{"start":24,"end":24,"text":"神说：「地要生出活物来，各从其类；牲畜、昆虫、野兽，各从其类。」事就这样成了。"},{"start":25,"end":25,"text":"于是　神造出野兽，各从其类；牲畜，各从其类；地上一切昆虫，各从其类。　神看着是好的。"},{"start":26,"end":26,"text":"神说：「我们要照着我们的形象、按着我们的样式造人，使他们管理海里的鱼、空中的鸟、地上的牲畜，和全地，并地上所爬的一切昆虫。」"},{"start":27,"end":27,"text":"神就照着自己的形象造人，乃是照着他的形象造男造女。"},{"start":28,"end":28,"text":"神就赐福给他们，又对他们说：「要生养众多，遍满地面，治理这地，也要管理海里的鱼、空中的鸟，和地上各样行动的活物。」"},{"start":29,"end":29,"text":"神说：「看哪，我将遍地上一切结种子的菜蔬和一切树上所结有核的果子全赐给你们作食物。"},{"start":30,"end":30,"text":"至于地上的走兽和空中的飞鸟，并各样爬在地上有生命的物，[我将]青草[赐给]它们作食物。」事就这样成了。"},{"start":31,"end":31,"text":"神看着一切所造的都甚好。有晚上，有早晨，是第六日。"}],"3":[{"start":1,"end":1,"text":"耶和华　神所造的，惟有蛇比田野一切的活物更狡猾。蛇对女人说：「　神岂是真说不许你们吃园中所有树上的果子吗？」"},{"start":2,"end":2,"text":"女人对蛇说：「园中树上的果子，我们可以吃，"},{"start":3,"end":3,"text":"惟有园当中那棵树上的果子，　神曾说：『你们不可吃，也不可摸，免得你们死。』」"},{"start":4,"end":4,"text":"蛇对女人说：「你们不一定死；"},{"start":5,"end":5,"text":"因为　神知道，你们吃的日子眼睛就明亮了，你们便如　神能知道善恶。」"},{"start":6,"end":6,"text":"于是女人见那棵树[的果子]好作食物，也悦人的眼目，且是可喜爱的，能使人有智慧，就摘下果子来吃了，又给她丈夫，她丈夫也吃了。"},{"start":7,"end":7,"text":"他们二人的眼睛就明亮了，才知道自己是赤身露体，便拿无花果树的叶子为自己编做裙子。"},{"start":8,"end":8,"text":"天起了凉风，耶和华　神在园中行走。那人和他妻子听见　神的声音，就藏在园里的树木中，躲避耶和华　神的面。"},{"start":9,"end":9,"text":"耶和华　神呼唤那人，对他说：「你在哪里？」"},{"start":10,"end":10,"text":"他说：「我在园中听见你的声音，我就害怕；因为我赤身露体，我便藏了。」"},{"start":11,"end":11,"text":"耶和华说：「谁告诉你赤身露体呢？莫非你吃了我吩咐你不可吃的那树上的果子吗？」"},{"start":12,"end":12,"text":"那人说：「你所赐给我、与我同居的女人，她把那树上的果子给我，我就吃了。」"},{"start":13,"end":13,"text":"耶和华　神对女人说：「你做的是什么事呢？」女人说：「那蛇引诱我，我就吃了。」"},{"start":14,"end":14,"text":"耶和华　神对蛇说： 你既做了这事，就必受咒诅， 比一切的牲畜野兽更甚； 你必用肚子行走， 终身吃土。"},{"start":15,"end":15,"text":"我又要叫你和女人彼此为仇； 你的后裔和女人的后裔也彼此为仇。 女人的后裔要伤你的头； 你要伤他的脚跟。"},{"start":16,"end":16,"text":"又对女人说： 我必多多加增你怀胎的苦楚； 你生产儿女必多受苦楚。 你必恋慕你丈夫； 你丈夫必管辖你。"},{"start":17,"end":17,"text":"又对亚当说： 你既听从妻子的话， 吃了我所吩咐你不可吃的那树上的果子， 地必为你的缘故受咒诅； 你必终身劳苦才能从地里得吃的。"},{"start":18,"end":18,"text":"地必给你长出荆棘和蒺藜来； 你也要吃田间的菜蔬。"},{"start":19,"end":19,"text":"你必汗流满面才得糊口， 直到你归了土， 因为你是从土而出的。 你本是尘土，仍要归于尘土。"},{"start":20,"end":20,"text":"亚当给他妻子起名叫夏娃，因为她是众生之母。"},{"start":21,"end":21,"text":"耶和华　神为亚当和他妻子用皮子做衣服给他们穿。"},{"start":22,"end":22,"text":"耶和华　神说：「那人已经与我们相似，能知道善恶；现在恐怕他伸手又摘生命树的果子吃，就永远活着。」"},{"start":23,"end":23,"text":"耶和华　神便打发他出伊甸园去，耕种他所自出之土。"},{"start":24,"end":24,"text":"于是把他赶出去了；又在伊甸园的东边安设基路伯和四面转动发火焰的剑，要把守生命树的道路。"}],"4":[{"start":1,"end":1,"text":"有一日，那人和他妻子夏娃同房，夏娃就怀孕，生了该隐，便说：「耶和华使我得了一个男子。」"},{"start":2,"end":2,"text":"又生了该隐的兄弟亚伯。亚伯是牧羊的；该隐是种地的。"},{"start":3,"end":3,"text":"有一日，该隐拿地里的出产为供物献给耶和华；"},{"start":4,"end":4,"text":"亚伯也将他羊群中头生的和羊的脂油献上。耶和华看中了亚伯和他的供物，"},{"start":5,"end":5,"text":"只是看不中该隐和他的供物。该隐就大大地发怒，变了脸色。"},{"start":6,"end":6,"text":"耶和华对该隐说：「你为什么发怒呢？你为什么变了脸色呢？"},{"start":7,"end":7,"text":"你若行得好，岂不蒙悦纳？你若行得不好，罪就伏在门前。它必恋慕你，你却要制伏它。」"},{"start":8,"end":8,"text":"该隐与他兄弟亚伯说话；二人正在田间。该隐起来打他兄弟亚伯，把他杀了。"},{"start":9,"end":9,"text":"耶和华对该隐说：「你兄弟亚伯在哪里？」他说：「我不知道！我岂是看守我兄弟的吗？」"},{"start":10,"end":10,"text":"耶和华说：「你做了什么事呢？你兄弟的血有声音从地里向我哀告。"},{"start":11,"end":11,"text":"地开了口，从你手里接受你兄弟的血。现在你必从这地受咒诅。"},{"start":12,"end":12,"text":"你种地，地不再给你效力；你必流离飘荡在地上。」"},{"start":13,"end":13,"text":"该隐对耶和华说：「我的刑罚太重，过于我所能当的。"},{"start":14,"end":14,"text":"你如今赶逐我离开这地，以致不见你面；我必流离飘荡在地上，凡遇见我的必杀我。」"},{"start":15,"end":15,"text":"耶和华对他说：「凡杀该隐的，必遭报七倍。」耶和华就给该隐立一个记号，免得人遇见他就杀他。"},{"start":16,"end":16,"text":"于是该隐离开耶和华的面，去住在伊甸东边挪得之地。"},{"start":23,"end":23,"text":"拉麦对他两个妻子说： 亚大、洗拉，听我的声音； 拉麦的妻子，细听我的话语： 壮年人伤我，我把他杀了； 少年人损我，我把他害了。"},{"start":24,"end":24,"text":"若杀该隐，遭报七倍， 杀拉麦，必遭报七十七倍。"}],"6":[{"start":5,"end":5,"text":"耶和华见人在地上罪恶很大，终日所思想的尽都是恶，"},{"start":6,"end":6,"text":"耶和华就后悔造人在地上，心中忧伤。"},{"start":7,"end":7,"text":"耶和华说：「我要将所造的人和走兽，并昆虫，以及空中的飞鸟，都从地上除灭，因为我造他们后悔了。」"},{"start":8,"end":8,"text":"惟有挪亚在耶和华眼前蒙恩。"},{"start":9,"end":9,"text":"挪亚的后代记在下面。挪亚是个义人，在当时的世代是个完全人。挪亚与　神同行。"},{"start":10,"end":10,"text":"挪亚生了三个儿子，就是闪、含、雅弗。"},{"start":11,"end":11,"text":"世界在　神面前败坏，地上满了强暴。"},{"start":12,"end":12,"text":"神观看世界，见是败坏了；凡有血气的人在地上都败坏了行为。"},{"start":13,"end":13,"text":"神就对挪亚说：「凡有血气的人，他的尽头已经来到我面前；因为地上满了他们的强暴，我要把他们和地一并毁灭。"}],"10":[{"start":1,"end":1,"text":"挪亚的儿子闪、含、雅弗的后代记在下面。洪水以后，他们都生了儿子。"},{"start":2,"end":2,"text":"雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。"},{"start":3,"end":3,"text":"歌篾的儿子是亚实基拿、利法、陀迦玛。"},{"start":4,"end":4,"text":"雅完的儿子是以利沙、他施、基提、多单。"},{"start":5,"end":5,"text":"这些人的后裔将各国的地土、海岛分开居住，各随各的方言、宗族立国。"},{"start":6,"end":6,"text":"含的儿子是古实、麦西、弗、迦南。"},{"start":7,"end":7,"text":"古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。"},{"start":8,"end":8,"text":"古实又生宁录，他为世上英雄之首。"},{"start":9,"end":9,"text":"他在耶和华面前是个英勇的猎户，所以俗语说：「像宁录在耶和华面前是个英勇的猎户。」"},{"start":10,"end":10,"text":"他国的起头是巴别、以力、亚甲、甲尼，都在示拿地。"},{"start":11,"end":11,"text":"他从那地出来往亚述去，建造尼尼微、利河伯、迦拉，"},{"start":12,"end":12,"text":"和尼尼微、迦拉中间的利鲜，这就是那大城。"},{"start":13,"end":13,"text":"麦西生路低人、亚拿米人、利哈比人、拿弗土希人、"},{"start":14,"end":14,"text":"帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的有非利士人。"},{"start":15,"end":15,"text":"迦南生长子西顿，又生赫"},{"start":16,"end":16,"text":"和耶布斯人、亚摩利人、革迦撒人、"},{"start":17,"end":17,"text":"希未人、亚基人、西尼人、"},{"start":18,"end":18,"text":"亚瓦底人、洗玛利人、哈马人，后来迦南的诸族分散了。"},{"start":19,"end":19,"text":"迦南的境界是从西顿向基拉耳的路上，直到迦萨，又向所多玛、蛾摩拉、押玛、洗扁的路上，直到拉沙。"},{"start":20,"end":20,"text":"这就是含的后裔，各随他们的宗族、方言，所住的地土、邦国。"},{"start":21,"end":21,"text":"雅弗的哥哥闪，是希伯子孙之祖，他也生了儿子。"},{"start":22,"end":22,"text":"闪的儿子是以拦、亚述、亚法撒、路德、亚兰。"},{"start":23,"end":23,"text":"亚兰的儿子是乌斯、户勒、基帖、玛施。"},{"start":24,"end":24,"text":"亚法撒生沙拉；沙拉生希伯。"},{"start":25,"end":25,"text":"希伯生了两个儿子，一个名叫法勒，因为那时人就分地居住；法勒的兄弟名叫约坍。"},{"start":26,"end":26,"text":"约坍生亚摩答、沙列、哈萨玛非、耶拉、"},{"start":27,"end":27,"text":"哈多兰、乌萨、德拉、"},{"start":28,"end":28,"text":"俄巴路、亚比玛利、示巴、"},{"start":29,"end":29,"text":"阿斐、哈腓拉、约巴，这都是约坍的儿子。"},{"start":30,"end":30,"text":"他们所住的地方是从米沙直到西发东边的山。"},{"start":31,"end":31,"text":"这就是闪的子孙，各随他们的宗族、方言，所住的地土、邦国。"},{"start":32,"end":32,"text":"这些都是挪亚三个儿子的宗族，各随他们的支派立国。洪水以后，他们在地上分为邦国。"}],"12":[{"start":3,"end":3,"text":"为你祝福的，我必赐福与他；那咒诅你的，我必咒诅他。地上的万族都要因你得福。」"},{"start":4,"end":4,"text":"亚伯兰就照着耶和华的吩咐去了；罗得也和他同去。亚伯兰出哈兰的时候年七十五岁。"},{"start":5,"end":5,"text":"亚伯兰将他妻子撒莱和侄儿罗得，连他们在哈兰所积蓄的财物、所得的人口，都带往迦南地去。他们就到了迦南地。"},{"start":6,"end":6,"text":"亚伯兰经过那地，到了示剑地方、摩利橡树那里。那时迦南人住在那地。"},{"start":7,"end":7,"text":"耶和华向亚伯兰显现，说：「我要把这地赐给你的后裔。」亚伯兰就在那里为向他显现的耶和华筑了一座坛。"},{"start":8,"end":8,"text":"从那里他又迁到伯特利东边的山，支搭帐棚；西边是伯特利，东边是艾。他在那里又为耶和华筑了一座坛，求告耶和华的名。"},{"start":9,"end":9,"text":"后来亚伯兰又渐渐迁往南地去。"},{"start":10,"end":10,"text":"那地遭遇饥荒。因饥荒甚大，亚伯兰就下埃及去，要在那里暂居。"},{"start":11,"end":11,"text":"将近埃及，就对他妻子撒莱说：「我知道你是容貌俊美的妇人。"},{"start":12,"end":12,"text":"埃及人看见你必说：『这是他的妻子』，他们就要杀我，却叫你存活。"},{"start":13,"end":13,"text":"求你说，你是我的妹子，使我因你得平安，我的命也因你存活。」"},{"start":14,"end":14,"text":"及至亚伯兰到了埃及，埃及人看见那妇人极其美貌。"},{"start":15,"end":15,"text":"法老的臣宰看见了她，就在法老面前夸奖她。那妇人就被带进法老的宫去。"},{"start":16,"end":16,"text":"法老因这妇人就厚待亚伯兰，亚伯兰得了许多牛、羊、骆驼、公驴、母驴、仆婢。"},{"start":17,"end":17,"text":"耶和华因亚伯兰妻子撒莱的缘故，降大灾与法老和他的全家。"},{"start":18,"end":18,"text":"法老就召了亚伯兰来，说：「你这向我做的是什么事呢？为什么没有告诉我她是你的妻子？"},{"start":19,"end":19,"text":"为什么说她是你的妹子，以致我把她取来要作我的妻子？现在你的妻子在这里，可以带她走吧。」"},{"start":20,"end":20,"text":"于是法老吩咐人将亚伯兰和他妻子，并他所有的都送走了。"}],"18":[{"start":1,"end":1,"text":"耶和华在幔利橡树那里向亚伯拉罕显现出来。那时正热，亚伯拉罕坐在帐棚门口，"},{"start":2,"end":2,"text":"举目观看，见有三个人在对面站着。他一见，就从帐棚门口跑去迎接他们，俯伏在地，"},{"start":3,"end":3,"text":"说：「我主，我若在你眼前蒙恩，求你不要离开仆人往前去。"},{"start":4,"end":4,"text":"容我拿点水来，你们洗洗脚，在树下歇息歇息。"},{"start":5,"end":5,"text":"我再拿一点饼来，你们可以加添心力，然后往前去。你们既到仆人这里来，理当如此。」他们说：「就照你说的行吧。」"},{"start":6,"end":6,"text":"亚伯拉罕急忙进帐棚见撒拉，说：「你速速拿三细亚细面调和做饼。」"},{"start":7,"end":7,"text":"亚伯拉罕又跑到牛群里，牵了一只又嫩又好的牛犊来，交给仆人，仆人急忙预备好了。"},{"start":8,"end":8,"text":"亚伯拉罕又取了奶油和奶，并预备好的牛犊来，摆在他们面前，自己在树下站在旁边，他们就吃了。"},{"start":9,"end":9,"text":"他们问亚伯拉罕说：「你妻子撒拉在哪里？」他说：「在帐棚里。」"},{"start":10,"end":10,"text":"三人中有一位说：「到明年这时候，我必要回到你这里；你的妻子撒拉必生一个儿子。」撒拉在那人后边的帐棚门口也听见了这话。"},{"start":11,"end":11,"text":"亚伯拉罕和撒拉年纪老迈，撒拉的月经已断绝了。"},{"start":12,"end":12,"text":"撒拉心里暗笑，说：「我既已衰败，我主也老迈，岂能有这喜事呢？」"},{"start":13,"end":13,"text":"耶和华对亚伯拉罕说：「撒拉为什么暗笑，说：『我既已年老，果真能生养吗？』"},{"start":14,"end":14,"text":"耶和华岂有难成的事吗？到了日期，明年这时候，我必回到你这里，撒拉必生一个儿子。」"},{"start":15,"end":15,"text":"撒拉就害怕，不承认，说：「我没有笑。」那位说：「不然，你实在笑了。」"},{"start":16,"end":16,"text":"三人就从那里起行，向所多玛观看，亚伯拉罕也与他们同行，要送他们一程。"},{"start":17,"end":17,"text":"耶和华说：「我所要做的事岂可瞒着亚伯拉罕呢？"},{"start":18,"end":18,"text":"亚伯拉罕必要成为强大的国；地上的万国都必因他得福。"},{"start":19,"end":19,"text":"我眷顾他，为要叫他吩咐他的众子和他的眷属遵守我的道，秉公行义，使我所应许亚伯拉罕的话都成就了。」"},{"start":20,"end":20,"text":"耶和华说：「所多玛和蛾摩拉的罪恶甚重，声闻于我。"},{"start":21,"end":21,"text":"我现在要下去，察看他们所行的，果然尽像那达到我耳中的声音一样吗？若是不然，我也必知道。」"},{"start":22,"end":22,"text":"二人转身离开那里，向所多玛去；但亚伯拉罕仍旧站在耶和华面前。"},{"start":23,"end":23,"text":"亚伯拉罕近前来，说：「无论善恶，你都要剿灭吗？"},{"start":24,"end":24,"text":"假若那城里有五十个义人，你还剿灭那地方吗？不为城里这五十个义人饶恕其中的人吗？"},{"start":25,"end":25,"text":"将义人与恶人同杀，将义人与恶人一样看待，这断不是你所行的。审判全地的主岂不行公义吗？」"},{"start":26,"end":26,"text":"耶和华说：「我若在所多玛城里见有五十个义人，我就为他们的缘故饶恕那地方的众人。」"},{"start":27,"end":27,"text":"亚伯拉罕说：「我虽然是灰尘，还敢对主说话。"},{"start":28,"end":28,"text":"假若这五十个义人短了五个，你就因为短了五个毁灭全城吗？」他说：「我在那里若见有四十五个，也不毁灭那城。」"},{"start":29,"end":29,"text":"亚伯拉罕又对他说：「假若在那里见有四十个怎么样呢？」他说：「为这四十个的缘故，我也不做这事。」"},{"start":30,"end":30,"text":"亚伯拉罕说：「求主不要动怒，容我说，假若在那里见有三十个怎么样呢？」他说：「我在那里若见有三十个，我也不做这事。」"},{"start":31,"end":31,"text":"亚伯拉罕说：「我还敢对主说话，假若在那里见有二十个怎么样呢？」他说：「为这二十个的缘故，我也不毁灭那城。」"},{"start":32,"end":32,"text":"亚伯拉罕说：「求主不要动怒，我再说这一次，假若在那里见有十个呢？」他说：「为这十个的缘故，我也不毁灭那城。」"},{"start":33,"end":33,"text":"耶和华与亚伯拉罕说完了话就走了；亚伯拉罕也回到自己的地方去了。"}],"21":[{"start":1,"end":1,"text":"耶和华按着先前的话眷顾撒拉，便照他所说的给撒拉成就。"},{"start":2,"end":2,"text":"当亚伯拉罕年老的时候，撒拉怀了孕；到　神所说的日期，就给亚伯拉罕生了一个儿子。"},{"start":3,"end":3,"text":"亚伯拉罕给撒拉所生的儿子起名叫以撒。"},{"start":4,"end":4,"text":"以撒生下来第八日，亚伯拉罕照着　神所吩咐的，给以撒行了割礼。"},{"start":5,"end":5,"text":"他儿子以撒生的时候，亚伯拉罕年一百岁。"},{"start":6,"end":6,"text":"撒拉说：「　神使我喜笑，凡听见的必与我一同喜笑」；"},{"start":7,"end":7,"text":"又说：「谁能预先对亚伯拉罕说『撒拉要乳养婴孩』呢？因为在他年老的时候，我给他生了一个儿子。」"}],"22":[{"start":2,"end":2,"text":"神说：「你带着你的儿子，就是你独生的儿子，你所爱的以撒，往摩利亚地去，在我所要指示你的山上，把他献为燔祭。」"},{"start":3,"end":3,"text":"亚伯拉罕清早起来，备上驴，带着两个仆人和他儿子以撒，也劈好了燔祭的柴，就起身往　神所指示他的地方去了。"},{"start":4,"end":4,"text":"到了第三日，亚伯拉罕举目远远地看见那地方。"},{"start":5,"end":5,"text":"亚伯拉罕对他的仆人说：「你们和驴在此等候，我与童子往那里去拜一拜，就回到你们这里来。」"},{"start":6,"end":6,"text":"亚伯拉罕把燔祭的柴放在他儿子以撒身上，自己手里拿着火与刀；于是二人同行。"},{"start":7,"end":7,"text":"以撒对他父亲亚伯拉罕说：「父亲哪！」亚伯拉罕说：「我儿，我在这里。」以撒说：「请看，火与柴都有了，但燔祭的羊羔在哪里呢？」"},{"start":8,"end":8,"text":"亚伯拉罕说：「我儿，　神必自己预备作燔祭的羊羔。」于是二人同行。"},{"start":9,"end":9,"text":"他们到了　神所指示的地方，亚伯拉罕在那里筑坛，把柴摆好，捆绑他的儿子以撒，放在坛的柴上。"},{"start":10,"end":10,"text":"亚伯拉罕就伸手拿刀，要杀他的儿子。"},{"start":11,"end":11,"text":"耶和华的使者从天上呼叫他说：「亚伯拉罕！亚伯拉罕！」他说：「我在这里。」"},{"start":12,"end":12,"text":"天使说：「你不可在这童子身上下手。一点不可害他！现在我知道你是敬畏　神的了；因为你没有将你的儿子，就是你独生的儿子，留下不给我。」"},{"start":13,"end":13,"text":"亚伯拉罕举目观看，不料，有一只公羊，两角扣在稠密的小树中，亚伯拉罕就取了那只公羊来，献为燔祭，代替他的儿子。"},{"start":14,"end":14,"text":"亚伯拉罕给那地方起名叫「耶和华以勒」，直到今日人还说：「在耶和华的山上必有预备。」"},{"start":15,"end":15,"text":"耶和华的使者第二次从天上呼叫亚伯拉罕说："},{"start":16,"end":16,"text":"「耶和华说：『你既行了这事，不留下你的儿子，就是你独生的儿子，我便指着自己起誓说："},{"start":17,"end":17,"text":"论福，我必赐大福给你；论子孙，我必叫你的子孙多起来，如同天上的星，海边的沙。你子孙必得着仇敌的城门，"},{"start":18,"end":18,"text":"并且地上万国都必因你的后裔得福，因为你听从了我的话。』」"},{"start":19,"end":19,"text":"于是亚伯拉罕回到他仆人那里，他们一同起身往别是巴去，亚伯拉罕就住在别是巴。"},{"start":20,"end":20,"text":"这事以后，有人告诉亚伯拉罕说：「密迦给你兄弟拿鹤生了几个儿子，"},{"start":21,"end":21,"text":"长子是乌斯，他的兄弟是布斯和亚兰的父亲基母利，"},{"start":22,"end":22,"text":"并基薛、哈琐、必达、益拉、彼土利（彼土利生利百加）。」"},{"start":23,"end":23,"text":"这八个人都是密迦给亚伯拉罕的兄弟拿鹤生的。"},{"start":24,"end":24,"text":"拿鹤的妾名叫流玛，生了提八、迦含、他辖，和玛迦。"}],"45":[{"start":1,"end":1,"text":"约瑟在左右站着的人面前情不自禁，吩咐一声说：「人都要离开我出去！」约瑟和弟兄们相认的时候并没有一人站在他面前。"},{"start":2,"end":2,"text":"他就放声大哭；埃及人和法老家中的人都听见了。"},{"start":3,"end":3,"text":"约瑟对他弟兄们说：「我是约瑟。我的父亲还在吗？」他弟兄不能回答，因为在他面前都惊惶。"},{"start":4,"end":4,"text":"约瑟又对他弟兄们说：「请你们近前来。」他们就近前来。他说：「我是你们的兄弟约瑟，就是你们所卖到埃及的。"},{"start":5,"end":5,"text":"现在，不要因为把我卖到这里自忧自恨。这是　神差我在你们以先来，为要保全生命。"},{"start":6,"end":6,"text":"现在这地的饥荒已经二年了，还有五年不能耕种，不能收成。"},{"start":7,"end":7,"text":"神差我在你们以先来，为要给你们存留余种在世上，又要大施拯救，保全你们的生命。"},{"start":8,"end":8,"text":"这样看来，差我到这里来的不是你们，乃是　神。他又使我如法老的父，作他全家的主，并埃及全地的宰相。"},{"start":9,"end":9,"text":"你们要赶紧上到我父亲那里，对他说：『你儿子约瑟这样说：　神使我作全埃及的主，请你下到我这里来，不要耽延。"},{"start":10,"end":10,"text":"你和你的儿子孙子，连牛群羊群，并一切所有的，都可以住在歌珊地，与我相近。"},{"start":11,"end":11,"text":"我要在那里奉养你；因为还有五年的饥荒，免得你和你的眷属，并一切所有的，都败落了。』"},{"start":12,"end":12,"text":"况且你们的眼和我兄弟便雅悯的眼都看见是我亲口对你们说话。"},{"start":13,"end":13,"text":"你们也要将我在埃及一切的荣耀和你们所看见的事都告诉我父亲，又要赶紧地将我父亲搬到我这里来。」"},{"start":14,"end":14,"text":"于是约瑟伏在他兄弟便雅悯的颈项上哭，便雅悯也在他的颈项上哭。"},{"start":15,"end":15,"text":"他又与众弟兄亲嘴，抱着他们哭，随后他弟兄们就和他说话。"}]},"1SA":{"1":[{"start":1,"end":1,"text":"以法莲山地的拉玛·琐非有一个以法莲人，名叫以利加拿，是苏弗的玄孙，托户的曾孙，以利户的孙子，耶罗罕的儿子。"},{"start":2,"end":2,"text":"他有两个妻：一名哈拿，一名毗尼拿。毗尼拿有儿女，哈拿没有儿女。"},{"start":3,"end":3,"text":"这人每年从本城上到示罗，敬拜祭祀万军之耶和华；在那里有以利的两个儿子何弗尼、非尼哈当耶和华的祭司。"},{"start":4,"end":4,"text":"以利加拿每逢献祭的日子，将[祭肉]分给他的妻毗尼拿和毗尼拿所生的儿女；"},{"start":5,"end":5,"text":"给哈拿的却是双分，因为他爱哈拿。无奈耶和华不使哈拿生育。"},{"start":6,"end":6,"text":"毗尼拿见耶和华不使哈拿生育，就作她的对头，大大激动她，要使她生气。"},{"start":7,"end":7,"text":"每年上到耶和华殿的时候，以利加拿都以双分给哈拿；毗尼拿仍是激动她，以致她哭泣不吃饭。"},{"start":8,"end":8,"text":"她丈夫以利加拿对她说：「哈拿啊，你为何哭泣，不吃饭，心里愁闷呢？有我不比十个儿子还好吗？」"},{"start":9,"end":9,"text":"他们在示罗吃喝完了，哈拿就站起来。祭司以利在耶和华殿的门框旁边，坐在自己的位上。"},{"start":10,"end":10,"text":"哈拿心里愁苦，就痛痛哭泣，祈祷耶和华，"},{"start":11,"end":11,"text":"许愿说：「万军之耶和华啊，你若垂顾婢女的苦情，眷念不忘婢女，赐我一个儿子，我必使他终身归与耶和华，不用剃头刀剃他的头。」"},{"start":12,"end":12,"text":"哈拿在耶和华面前不住地祈祷，以利定睛看她的嘴。（"},{"start":13,"end":13,"text":"原来哈拿心中默祷，只动嘴唇，不出声音，因此以利以为她喝醉了。）"},{"start":14,"end":14,"text":"以利对她说：「你要醉到几时呢？你不应该喝酒。」"},{"start":15,"end":15,"text":"哈拿回答说：「主啊，不是这样。我是心里愁苦的妇人，清酒浓酒都没有喝，但在耶和华面前倾心吐意。"},{"start":16,"end":16,"text":"不要将婢女看作不正经的女子。我因被人激动，愁苦太多，所以祈求到如今。」"},{"start":17,"end":17,"text":"以利说：「你可以平平安安地回去。愿以色列的　神允准你向他所求的！」"},{"start":18,"end":18,"text":"哈拿说：「愿婢女在你眼前蒙恩。」于是妇人走去吃饭，面上再不带愁容了。"},{"start":19,"end":19,"text":"次日清早，他们起来，在耶和华面前敬拜，就回拉玛。到了家里，以利加拿和妻哈拿同房，耶和华顾念哈拿，"},{"start":20,"end":20,"text":"哈拿就怀孕。日期满足，生了一个儿子，给他起名叫撒母耳，[说]：「这是我从耶和华那里求来的。」"},{"start":21,"end":21,"text":"以利加拿和他全家都上示罗去，要向耶和华献年祭，并还所许的愿。"},{"start":22,"end":22,"text":"哈拿却没有上去，对丈夫说：「等孩子断了奶，我便带他上去朝见耶和华，使他永远住在那里。」"},{"start":23,"end":23,"text":"她丈夫以利加拿说：「就随你的意行吧！可以等儿子断了奶。但愿耶和华应验他的话。」于是妇人在家里乳养儿子，直到断了奶；"},{"start":24,"end":24,"text":"既断了奶，就把孩子带上示罗，到了耶和华的殿；又带了三只公牛，一伊法细面，一皮袋酒。（那时，孩子还小。）"},{"start":25,"end":25,"text":"宰了一只公牛，就领孩子到以利面前。"},{"start":26,"end":26,"text":"妇人说：「主啊，我敢在你面前起誓，从前在你这里站着祈求耶和华的那妇人，就是我。"},{"start":27,"end":27,"text":"我祈求为要得这孩子；耶和华已将我所求的赐给我了。"},{"start":28,"end":28,"text":"所以，我将这孩子归与耶和华，使他终身归与耶和华。」 于是在那里敬拜耶和华。"}],"2":[{"start":1,"end":1,"text":"哈拿祷告说： 我的心因耶和华快乐； 我的角因耶和华高举。 我的口向仇敌张开； 我因耶和华的救恩欢欣。"},{"start":2,"end":2,"text":"只有耶和华为圣； 除他以外没有可比的， 也没有磐石像我们的　神。"},{"start":3,"end":3,"text":"人不要夸口说骄傲的话， 也不要出狂妄的言语； 因耶和华是大有智识的　神， 人的行为被他衡量。"},{"start":4,"end":4,"text":"勇士的弓都已折断； 跌倒的人以力量束腰。"},{"start":5,"end":5,"text":"素来饱足的，反作用人求食； 饥饿的，再不饥饿。 不生育的，生了七个儿子； 多有儿女的，反倒衰微。"},{"start":6,"end":6,"text":"耶和华使人死，也使人活， 使人下阴间，也使人往上升。"},{"start":7,"end":7,"text":"他使人贫穷，也使人富足， 使人卑微，也使人高贵。"},{"start":8,"end":8,"text":"他从灰尘里抬举贫寒人， 从粪堆中提拔穷乏人， 使他们与王子同坐， 得着荣耀的座位。 地的柱子属于耶和华； 他将世界立在其上。"},{"start":9,"end":9,"text":"他必保护圣民的脚步， 使恶人在黑暗中寂然不动； 人都不能靠力量得胜。"},{"start":10,"end":10,"text":"与耶和华争竞的，必被打碎； 耶和华必从天上以雷攻击他， 必审判地极的人， 将力量赐与所立的王， 高举受膏者的角。"},{"start":26,"end":26,"text":"孩子撒母耳渐渐长大，耶和华与人越发喜爱他。"},{"start":27,"end":27,"text":"有神人来见以利，对他说：「耶和华如此说：『你祖父在埃及法老家[作奴仆]的时候，我不是向他们显现吗？"},{"start":28,"end":28,"text":"在以色列众支派中，我不是拣选人作我的祭司，使他烧香，在我坛上献祭，在我面前穿以弗得，又将以色列人所献的火祭都赐给你父家吗？"},{"start":29,"end":29,"text":"我所吩咐献在我居所的祭物，你们为何践踏？尊重你的儿子过于尊重我，将我民以色列所献美好的祭物肥己呢？』"},{"start":30,"end":30,"text":"因此，耶和华—以色列的　神说：『我曾说，你和你父家必永远行在我面前；现在我却说，决不容你们这样行。因为尊重我的，我必重看他；藐视我的，他必被轻视。"},{"start":31,"end":31,"text":"日子必到，我要折断你的膀臂和你父家的膀臂，使你家中没有一个老年人。"},{"start":32,"end":32,"text":"在　[神]使以色列人享福的时候，你必看见我居所的败落。在你家中必永远没有一个老年人。"},{"start":33,"end":33,"text":"我必不从我坛前灭尽你家中的人；那未灭的必使你眼目干瘪、心中忧伤。你家中所生的人都必死在中年。"},{"start":34,"end":34,"text":"你的两个儿子何弗尼、非尼哈所遭遇的事可作你的证据：他们二人必一日同死。"},{"start":35,"end":35,"text":"我要为自己立一个忠心的祭司；他必照我的心意而行。我要为他建立坚固的家；他必永远行在我的受膏者面前。"},{"start":36,"end":36,"text":"你家所剩下的人都必来叩拜他，求块银子，求个饼，说：求你赐我祭司的职分，好叫我得点饼吃。』」"}],"8":[{"start":10,"end":10,"text":"撒母耳将耶和华的话都传给求他立王的百姓，说："},{"start":11,"end":11,"text":"「管辖你们的王必这样行：他必派你们的儿子为他赶车、跟马，奔走在车前；"},{"start":12,"end":12,"text":"又派他们作千夫长、五十夫长，为他耕种田地，收割庄稼，打造军器和车上的器械；"},{"start":13,"end":13,"text":"必取你们的女儿为他制造香膏，做饭烤饼；"},{"start":14,"end":14,"text":"也必取你们最好的田地、葡萄园、橄榄园赐给他的臣仆。"},{"start":15,"end":15,"text":"你们的粮食和葡萄园所出的，他必取十分之一给他的太监和臣仆；"},{"start":16,"end":16,"text":"又必取你们的仆人婢女，健壮的少年人和你们的驴，供他的差役。"},{"start":17,"end":17,"text":"你们的羊群他必取十分之一，你们也必作他的仆人。"},{"start":18,"end":18,"text":"那时你们必因所选的王哀求耶和华，耶和华却不应允你们。」"}],"10":[{"start":1,"end":1,"text":"撒母耳拿瓶膏油倒在扫罗的头上，与他亲嘴，说：「这不是耶和华膏你作他产业的君吗？"},{"start":2,"end":2,"text":"你今日与我离别之后，在便雅悯境内的泄撒，靠近拉结的坟墓，要遇见两个人。他们必对你说：『你去找的那几头驴已经找着了。现在你父亲不为驴挂心，反为你担忧，说：我为儿子怎么才好呢？』"},{"start":3,"end":3,"text":"你从那里往前行，到了他泊的橡树那里，必遇见三个往伯特利去拜　神的人：一个带着三只山羊羔，一个带着三个饼，一个带着一皮袋酒。"},{"start":4,"end":4,"text":"他们必问你安，给你两个饼，你就从他们手中接过来。"},{"start":5,"end":5,"text":"此后你到　神的山，在那里有非利士人的防兵。你到了城的时候，必遇见一班先知从邱坛下来，前面有鼓瑟的、击鼓的、吹笛的、弹琴的，他们都受感说话。"},{"start":6,"end":6,"text":"耶和华的灵必大大感动你，你就与他们一同受感说话；你要变为新人。"},{"start":7,"end":7,"text":"这兆头临到你，你就可以趁时而做，因为　神与你同在。"},{"start":8,"end":8,"text":"你当在我以先下到吉甲，我也必下到那里献燔祭和平安祭。你要等候七日，等我到了那里，指示你当行的事。」"},{"start":9,"end":9,"text":"扫罗转身离别撒母耳，　神就赐他一个新心。当日这一切兆头都应验了。"},{"start":10,"end":10,"text":"扫罗到了那山，有一班先知遇见他，　神的灵大大感动他，他就在先知中受感说话。"},{"start":11,"end":11,"text":"素来认识扫罗的，看见他和先知一同受感说话，就彼此说：「基士的儿子遇见什么了？扫罗也列在先知中吗？」"},{"start":12,"end":12,"text":"那地方有一个人说：「这些人的父亲是谁呢？」此后有句俗语说：「扫罗也列在先知中吗？」"},{"start":13,"end":13,"text":"扫罗受感说话已毕，就上邱坛去了。"},{"start":14,"end":14,"text":"扫罗的叔叔问扫罗和他仆人说：「你们往哪里去了？」回答说：「找驴去了。我们见没有驴，就到了撒母耳那里。」"},{"start":15,"end":15,"text":"扫罗的叔叔说：「请将撒母耳向你们所说的话告诉我。」"},{"start":16,"end":16,"text":"扫罗对他叔叔说：「他明明地告诉我们驴已经找着了。」至于撒母耳所说的国事，扫罗却没有告诉叔叔。"},{"start":17,"end":17,"text":"撒母耳将百姓招聚到米斯巴耶和华那里，"},{"start":18,"end":18,"text":"对他们说：「耶和华—以色列的　神如此说：『我领你们以色列人出埃及，救你们脱离埃及人的手，又救你们脱离欺压你们各国之人的手。』"},{"start":19,"end":19,"text":"你们今日却厌弃了救你们脱离一切灾难的　神，说：『求你立一个王治理我们。』现在你们应当按着支派、宗族都站在耶和华面前。」"},{"start":20,"end":20,"text":"于是，撒母耳使以色列众支派近前来掣签，就掣出便雅悯支派来；"},{"start":21,"end":21,"text":"又使便雅悯支派按着宗族近前来，就掣出玛特利族，从其中又掣出基士的儿子扫罗。众人寻找他却寻不着，"},{"start":22,"end":22,"text":"就问耶和华说：「那人到这里来了没有？」耶和华说：「他藏在器具中了。」"},{"start":23,"end":23,"text":"众人就跑去从那里领出他来。他站在百姓中间，身体比众民高过一头。"},{"start":24,"end":24,"text":"撒母耳对众民说：「你们看耶和华所拣选的人，众民中有可比他的吗？」众民就大声欢呼说：「愿王万岁！」"},{"start":25,"end":25,"text":"撒母耳将国法对百姓说明，又记在书上，放在耶和华面前，然后遣散众民，各回各家去了。"},{"start":26,"end":26,"text":"扫罗往基比亚回家去，有　神感动的一群人跟随他。"},{"start":27,"end":27,"text":"但有些匪徒说：「这人怎能救我们呢？」就藐视他，没有送他礼物；扫罗却不理会。"}],"15":[{"start":22,"end":22,"text":"撒母耳说： 耶和华喜悦燔祭和[平安]祭， 岂如喜悦人听从他的话呢？ 听命胜于献祭； 顺从胜于公羊的脂油。"},{"start":23,"end":23,"text":"悖逆的罪与行邪术的罪相等； 顽梗的罪与拜虚神和偶像的罪相同。 你既厌弃耶和华的命令， 耶和华也厌弃你作王。"}]},"JDG":{"13":[{"start":2,"end":2,"text":"那时，有一个琐拉人，是属但族的，名叫玛挪亚。他的妻不怀孕，不生育。"},{"start":3,"end":3,"text":"耶和华的使者向那妇人显现，对她说：「向来你不怀孕，不生育，如今你必怀孕生一个儿子。"},{"start":4,"end":4,"text":"所以你当谨慎，清酒浓酒都不可喝，一切不洁之物也不可吃。"},{"start":5,"end":5,"text":"你必怀孕生一个儿子，不可用剃头刀剃他的头，因为这孩子一出胎就归　神作拿细耳人。他必起首拯救以色列人脱离非利士人的手。」"},{"start":6,"end":6,"text":"妇人就回去对丈夫说：「有一个神人到我面前来，他的相貌如　神使者的相貌，甚是可畏。我没有问他从哪里来，他也没有将他的名告诉我，"},{"start":7,"end":7,"text":"却对我说：『你要怀孕生一个儿子，所以清酒浓酒都不可喝，一切不洁之物也不可吃；因为这孩子从出胎一直到死，必归　神作拿细耳人。』」"},{"start":8,"end":8,"text":"玛挪亚就祈求耶和华说：「主啊，求你再差遣那神人到我们这里来，好指教我们怎样待这将要生的孩子。」"},{"start":9,"end":9,"text":"神应允玛挪亚的话；妇人正坐在田间的时候，　神的使者又到她那里，她丈夫玛挪亚却没有同她在一处。"},{"start":10,"end":10,"text":"妇人急忙跑去告诉丈夫说：「那日到我面前来的人，又向我显现。」"},{"start":11,"end":11,"text":"玛挪亚起来跟随他的妻来到那人面前，对他说：「与这妇人说话的就是你吗？」他说：「是我。」"},{"start":12,"end":12,"text":"玛挪亚说：「愿你的话应验！我们当怎样待这孩子，他后来当怎样呢？」"},{"start":13,"end":13,"text":"耶和华的使者对玛挪亚说：「我告诉妇人的一切事，她都当谨慎。"},{"start":14,"end":14,"text":"葡萄树所结的都不可吃，清酒浓酒都不可喝，一切不洁之物也不可吃。凡我所吩咐的，她都当遵守。」"}]},"GAL":{"1":[{"start":15,"end":15,"text":"然而，那把我从母腹里分别出来、又施恩召我的　神，"},{"start":16,"end":16,"text":"既然乐意将他儿子启示在我心里，叫我把他传在外邦人中，我就没有与属血气的人商量，"},{"start":17,"end":17,"text":"也没有上耶路撒冷去见那些比我先作使徒的，惟独往阿拉伯去，后又回到大马士革。"},{"start":18,"end":18,"text":"过了三年，才上耶路撒冷去见矶法，和他同住了十五天。"}],"2":[{"start":20,"end":20,"text":"我已经与基督同钉十字架，现在活着的不再是我，乃是基督在我里面活着；并且我如今在肉身活着，是因信　神的儿子而活；他是爱我，为我舍己。"},{"start":21,"end":21,"text":"我不废掉　神的恩；义若是借着律法得的，基督就是徒然死了。"}],"3":[{"start":7,"end":7,"text":"所以，你们要知道：那以信为本的人，就是亚伯拉罕的子孙。"},{"start":8,"end":8,"text":"并且圣经既然预先看明，　神要叫外邦人因信称义，就早已传福音给亚伯拉罕，[说]：「万国都必因你得福。」"},{"start":9,"end":9,"text":"可见那以信为本的人和有信心的亚伯拉罕一同得福。"},{"start":10,"end":10,"text":"凡以行律法为本的，都是被咒诅的；因为[经上]记着：「凡不常照律法书上所记一切之事去行的，就被咒诅。」"},{"start":11,"end":11,"text":"没有一个人靠着律法在　神面前称义，这是明显的；因为[经上]说：「义人必因信得生。」"},{"start":12,"end":12,"text":"律法原不本乎信，只[说]：「行这些事的，就必因此活着。」"},{"start":13,"end":13,"text":"基督既为我们受了咒诅，就赎出我们脱离律法的咒诅；因为[经上]记着：「凡挂在木头上都是被咒诅的。」"},{"start":14,"end":14,"text":"这便叫亚伯拉罕的福，因基督耶稣可以临到外邦人，使我们因信得着所应许的[圣]灵。"},{"start":15,"end":15,"text":"弟兄们，我且照着人的常话说：虽然是人的文约，若已经立定了，就没有能废弃或加增的。"},{"start":16,"end":16,"text":"所应许的原是向亚伯拉罕和他子孙说的。　神并不是说「众子孙」，指着许多人，乃是说「你那一个子孙」，指着一个人，就是基督。"},{"start":17,"end":17,"text":"我是这么说，　神预先所立的约，不能被那四百三十年以后的律法废掉，叫应许归于虚空。"},{"start":18,"end":18,"text":"因为承受产业，若本乎律法，就不本乎应许；但　神是凭着应许把产业赐给亚伯拉罕。"},{"start":19,"end":19,"text":"这样说来，律法是为什么有的呢？原是为过犯添上的，等候那蒙应许的子孙来到，并且是借天使经中保之手设立的。"},{"start":20,"end":20,"text":"但中保本不是为一面作的；　神却是一位。"},{"start":21,"end":21,"text":"这样，律法是与　神的应许反对吗？断乎不是！若曾传一个能叫人得生的律法，义就诚然本乎律法了。"},{"start":22,"end":22,"text":"但圣经把众人都圈在罪里，使所应许的[福]因信耶稣基督，归给那信的人。"},{"start":23,"end":23,"text":"但这[因]信[得救的理]还未来以先，我们被看守在律法之下，直圈到那将来的真道显明出来。"},{"start":24,"end":24,"text":"这样，律法是我们训蒙的师傅，[引我们]到基督那里，使我们因信称义。"},{"start":25,"end":25,"text":"但这[因]信[得救的理]既然来到，我们从此就不在师傅的手下了。"},{"start":26,"end":26,"text":"所以，你们因信基督耶稣都是　神的儿子。"},{"start":27,"end":27,"text":"你们受洗归入基督的都是披戴基督了。"},{"start":28,"end":28,"text":"并不分犹太人、希腊人，自主的、为奴的，或男或女，因为你们在基督耶稣里都成为一了。"},{"start":29,"end":29,"text":"你们既属乎基督，就是亚伯拉罕的后裔，是照着应许承受产业的了。"}],"4":[{"start":4,"end":4,"text":"及至时候满足，　神就差遣他的儿子，为女子所生，且生在律法以下，"},{"start":5,"end":5,"text":"要把律法以下的人赎出来，叫我们得着儿子的名分。"}],"5":[{"start":9,"end":9,"text":"一点面酵能使全团都发起来。"},{"start":10,"end":10,"text":"我在主里很信你们必不怀别样的心；但搅扰你们的，无论是谁，必担当他的罪名。"},{"start":11,"end":11,"text":"弟兄们，我若仍旧传割礼，为什么还受逼迫呢？若是这样，那十字架讨厌的地方就没有了。"},{"start":12,"end":12,"text":"恨不得那搅乱你们的人把自己割绝了。"},{"start":13,"end":13,"text":"弟兄们，你们蒙召是要得自由，只是不可将你们的自由当作放纵情欲的机会，总要用爱心互相服事。"},{"start":14,"end":14,"text":"因为全律法都包在「爱人如己」这一句话之内了。"},{"start":15,"end":15,"text":"你们要谨慎，若相咬相吞，只怕要彼此消灭了。"},{"start":16,"end":16,"text":"我说，你们当顺着[圣]灵而行，就不放纵肉体的情欲了。"},{"start":17,"end":17,"text":"因为情欲和[圣]灵相争，[圣]灵和情欲相争，这两个是彼此相敌，使你们不能做所愿意做的。"},{"start":18,"end":18,"text":"但你们若被[圣]灵引导，就不在律法以下。"},{"start":19,"end":19,"text":"情欲的事都是显而易见的，就如奸淫、污秽、邪荡、"},{"start":20,"end":20,"text":"拜偶像、邪术、仇恨、争竞、忌恨、恼怒、结党、纷争、异端、"},{"start":21,"end":21,"text":"嫉妒、醉酒、荒宴等类。我从前告诉你们，现在又告诉你们，行这样事的人必不能承受　神的国。"},{"start":22,"end":22,"text":"圣灵所结的果子，就是仁爱、喜乐、和平、忍耐、恩慈、良善、信实、"},{"start":23,"end":23,"text":"温柔、节制。这样的事没有律法禁止。"},{"start":24,"end":24,"text":"凡属基督耶稣的人，是已经把肉体连肉体的邪情私欲同钉在十字架上了。"},{"start":25,"end":25,"text":"我们若是靠[圣]灵得生，就当靠[圣]灵行事。"},{"start":26,"end":26,"text":"不要贪图虚名，彼此惹气，互相嫉妒。"}],"6":[{"start":1,"end":1,"text":"弟兄们，若有人偶然被过犯所胜，你们属灵的人就当用温柔的心把他挽回过来；又当自己小心，恐怕也被引诱。"},{"start":2,"end":2,"text":"你们各人的重担要互相担当，如此，就完全了基督的律法。"}]},"MIC":{"3":[{"start":9,"end":9,"text":"雅各家的首领、以色列家的官长啊， 当听我的话！ 你们厌恶公平， 在一切事上屈枉正直；"},{"start":10,"end":10,"text":"以人血建立锡安， 以罪孽建造耶路撒冷。"},{"start":11,"end":11,"text":"首领为贿赂行审判； 祭司为雇价施训诲； 先知为银钱行占卜。 他们却倚赖耶和华，说： 耶和华不是在我们中间吗？ 灾祸必不临到我们。"},{"start":12,"end":12,"text":"所以因你们的缘故， 锡安必被耕种像一块田， 耶路撒冷必变为乱堆； 这殿的山必像丛林的高处。"}],"5":[{"start":2,"end":2,"text":"伯利恒的以法他啊， 你在犹大诸城中为小， 将来必有一位从你那里出来， 在以色列中为我作掌权的； 他的根源从亘古，从太初就有。"},{"start":3,"end":3,"text":"耶和华必将以色列人交付[敌人]， 直等那生产的妇人生下子来。 那时掌权者其余的弟兄 必归到以色列人那里。"},{"start":4,"end":4,"text":"他必起来，倚靠耶和华的大能， 并耶和华—他　神之名的威严， 牧养[他的羊群]。 他们要[安然]居住； 因为他必日见尊大，直到地极。"},{"start":5,"end":5,"text":"这位必作[我们的]平安。 当亚述人进入我们的地境， 践踏宫殿的时候， 我们就立起七个牧者， 八个首领攻击他。"},{"start":6,"end":6,"text":"他们必用刀剑毁坏亚述地 和宁录地的关口。 亚述人进入我们的地境践踏的时候， 他必拯救我们。"},{"start":7,"end":7,"text":"雅各余剩的人必在多国的民中， 如从耶和华那里降下的露水， 又如甘霖降在草上； 不仗赖人[力]，也不等候世人[之功]。"},{"start":8,"end":8,"text":"雅各余剩的人必在多国多民中， 如林间百兽中的狮子， 又如少壮狮子在羊群中。 他若经过就必践踏撕裂， 无人搭救。"},{"start":9,"end":9,"text":"愿你的手举起，高过敌人！ 愿你的仇敌都被剪除！"},{"start":10,"end":10,"text":"耶和华说：到那日， 我必从你中间剪除马匹， 毁坏车辆，"},{"start":11,"end":11,"text":"也必从你国中除灭城邑， 拆毁一切的保障，"},{"start":12,"end":12,"text":"又必除掉你手中的邪术； 你那里也不再有占卜的。"},{"start":13,"end":13,"text":"我必从你中间除灭雕刻的偶像和柱像， 你就不再跪拜自己手所造的。"},{"start":14,"end":14,"text":"我必从你中间拔出木偶， 又毁灭你的城邑。"},{"start":15,"end":15,"text":"我也必在怒气和忿怒中向那不听从的列国施报。"}],"6":[{"start":6,"end":6,"text":"我朝见耶和华， 在至高　神面前跪拜，当献上什么呢？ 岂可献一岁的牛犊为燔祭吗？"},{"start":7,"end":7,"text":"耶和华岂喜悦千千的公羊， 或是万万的油河吗？ 我岂可为自己的罪过献我的长子吗？ 为心中的罪恶献我身所生的吗？"},{"start":8,"end":8,"text":"世人哪，耶和华已指示你何为善。 他向你所要的是什么呢？ 只要你行公义，好怜悯， 存谦卑的心，与你的　神同行。"},{"start":9,"end":9,"text":"耶和华向这城呼叫， 智慧人必敬畏他的名。 你们当听是谁派定刑杖的惩罚。"},{"start":10,"end":10,"text":"恶人家中不仍有非义之财 和可恶的小升斗吗？"},{"start":11,"end":11,"text":"我若用不公道的天平和囊中诡诈的法码， 岂可算为清洁呢？"},{"start":12,"end":12,"text":"城里的富户满行强暴； 其中的居民也说谎言， 口中的舌头是诡诈的。"},{"start":13,"end":13,"text":"因此，我击打你， 使你的伤痕甚重， 使你因你的罪恶荒凉。"},{"start":14,"end":14,"text":"你要吃，却吃不饱； 你的虚弱必显在你中间。 你必挪去，却不得救护； 所救护的，我必交给刀剑。"},{"start":15,"end":15,"text":"你必撒种，却不得收割； 踹橄榄，却不得油抹身； 踹葡萄，却不得酒喝。"},{"start":16,"end":16,"text":"因为你守暗利的恶规， 行亚哈家一切所行的， 顺从他们的计谋； 因此，我必使你荒凉， 使你的居民令人嗤笑， 你们也必担当我民的羞辱。"}],"7":[{"start":5,"end":5,"text":"不要倚赖邻舍； 不要信靠密友。 要守住你的口； 不要向你怀中的妻提说。"},{"start":6,"end":6,"text":"因为，儿子藐视父亲； 女儿抗拒母亲； 媳妇抗拒婆婆； 人的仇敌就是自己家里的人。"},{"start":7,"end":7,"text":"至于我，我要仰望耶和华， 要等候那救我的　神； 我的　神必应允我。"}]},"PHI":{"2":[{"start":3,"end":3,"text":"凡事不可结党，不可贪图虚浮的荣耀；只要存心谦卑，各人看别人比自己强。"},{"start":4,"end":4,"text":"各人不要单顾自己的事，也要顾别人的事。"},{"start":5,"end":5,"text":"你们当以基督耶稣的心为心："},{"start":6,"end":6,"text":"他本有　神的形象， 不以自己与　神同等为强夺的；"},{"start":7,"end":7,"text":"反倒虚己， 取了奴仆的形象， 成为人的样式；"},{"start":8,"end":8,"text":"既有人的样子，就自己卑微， 存心顺服，以至于死， 且死在十字架上。"},{"start":9,"end":9,"text":"所以，　神将他升为至高， 又赐给他那超乎万名之上的名，"},{"start":10,"end":10,"text":"叫一切在天上的、地上的，和地底下的， 因耶稣的名无不屈膝，"},{"start":11,"end":11,"text":"无不口称「耶稣基督为主」， 使荣耀归与父　神。"}],"3":[{"start":4,"end":4,"text":"其实，我也可以靠肉体；若是别人想他可以靠肉体，我更可以靠着了。"},{"start":5,"end":5,"text":"我第八天受割礼；我是以色列族、便雅悯支派的人，是希伯来人所生的希伯来人。就律法说，我是法利赛人；"},{"start":6,"end":6,"text":"就热心说，我是逼迫教会的；就律法上的义说，我是无可指摘的。"},{"start":7,"end":7,"text":"只是我先前以为与我有益的，我现在因基督都当作有损的。"},{"start":8,"end":8,"text":"不但如此，我也将万事当作有损的，因我以认识我主基督耶稣为至宝。我为他已经丢弃万事，看作粪土，为要得着基督；"},{"start":9,"end":9,"text":"并且得以在他里面，不是有自己因律法而得的义，乃是有信基督的义，就是因信　神而来的义，"},{"start":10,"end":10,"text":"使我认识基督，晓得他复活的大能，并且晓得和他一同受苦，效法他的死，"},{"start":11,"end":11,"text":"或者我也得以从死里复活。"},{"start":13,"end":13,"text":"弟兄们，我不是以为自己已经得着了；我只有一件事，就是忘记背后，努力面前的，"},{"start":14,"end":14,"text":"向着标竿直跑，要得　神在基督耶稣里从上面召我来得的奖赏。"}],"4":[{"start":2,"end":2,"text":"我劝友阿蝶和循都基，要在主里同心。"},{"start":3,"end":3,"text":"我也求你这真实同负一轭的，帮助这两个女人，因为她们在福音上曾与我一同劳苦；还有革利免，并其余和我一同做工的，他们的名字都在生命册上。"},{"start":6,"end":6,"text":"应当一无挂虑，只要凡事借着祷告、祈求，和感谢，将你们所要的告诉　神。"},{"start":7,"end":7,"text":"神所赐、出人意外的平安必在基督耶稣里保守你们的心怀意念。"}]},"EZE":{"17":[{"start":22,"end":22,"text":"主耶和华如此说：「我要将香柏树梢拧去栽上，就是从尽尖的嫩枝中折一嫩枝，栽于极高的山上；"},{"start":23,"end":23,"text":"在以色列高处的山栽上。它就生枝子，结果子，成为佳美的香柏树，各类飞鸟都必宿在其下，就是宿在枝子的荫下。"},{"start":24,"end":24,"text":"田野的树木都必知道我—耶和华使高树矮小，矮树高大；青树枯干，枯树发旺。我—耶和华如此说，也如此行了。」"}],"18":[{"start":1,"end":1,"text":"耶和华的话又临到我说："},{"start":2,"end":2,"text":"「你们在以色列地怎么用这俗语说『父亲吃了酸葡萄，儿子的牙酸倒了』呢？」"},{"start":3,"end":3,"text":"主耶和华说：「我指着我的永生起誓，你们在以色列中，必不再有用这俗语的[因由]。"},{"start":4,"end":4,"text":"看哪，世人都是属我的；为父的怎样属我，为子的也照样属我；犯罪的，他必死亡。"},{"start":5,"end":5,"text":"「人若是公义，且行正直与合理的事："},{"start":6,"end":6,"text":"未曾在山上吃过[祭偶像之物]，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，未曾在妇人的经期内亲近她，"},{"start":7,"end":7,"text":"未曾亏负人，乃将欠债之人的当头还给他；未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿；"},{"start":8,"end":8,"text":"未曾向借钱的[弟兄]取利，也未曾向借粮的[弟兄]多要，缩手不作罪孽，在两人之间，按至理判断；"},{"start":9,"end":9,"text":"遵行我的律例，谨守我的典章，按诚实行事—这人是公义的，必定存活。这是主耶和华说的。"},{"start":10,"end":10,"text":"「他若生一个儿子，作强盗，是流人血的，不行以上所说之善，反行其中之恶，乃在山上吃过[祭偶像之物]，并玷污邻舍的妻，"},{"start":12,"end":12,"text":"亏负困苦和穷乏的人，抢夺人的物，未曾将当头还给人，仰望偶像，并行可憎的事，"},{"start":13,"end":13,"text":"向借钱的[弟兄]取利，向借粮的弟兄多要—这人岂能存活呢？他必不能存活。他行这一切可憎的事，必要死亡，他的罪必归到他身上。"},{"start":14,"end":14,"text":"「他若生一个儿子，见父亲所犯的一切罪便惧怕，不照样去做；"},{"start":15,"end":15,"text":"未曾在山上吃过[祭偶像之物]，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，"},{"start":16,"end":16,"text":"未曾亏负人，未曾取人的当头，未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿，"},{"start":17,"end":17,"text":"缩手不害贫穷人，未曾向借钱的[弟兄]取利，也未曾向借粮的[弟兄]多要；他顺从我的典章，遵行我的律例，就不因父亲的罪孽死亡，定要存活。"},{"start":18,"end":18,"text":"至于他父亲；因为欺人太甚，抢夺弟兄，在本国的民中行不善，他必因自己的罪孽死亡。"},{"start":19,"end":19,"text":"「你们还说：『儿子为何不担当父亲的罪孽呢？』儿子行正直与合理的事，谨守遵行我的一切律例，他必定存活。"},{"start":20,"end":20,"text":"惟有犯罪的，他必死亡。儿子必不担当父亲的罪孽，父亲也不担当儿子的罪孽。义人的善果必归自己，恶人的恶报也必归自己。"},{"start":21,"end":21,"text":"「恶人若回头离开所做的一切罪恶，谨守我一切的律例，行正直与合理的事，他必定存活，不致死亡。"},{"start":22,"end":22,"text":"他所犯的一切罪过都不被记念，因所行的义，他必存活。"},{"start":23,"end":23,"text":"主耶和华说：恶人死亡，岂是我喜悦的吗？不是喜悦他回头离开所行的道存活吗？"}],"21":[{"start":3,"end":3,"text":"对以色列地说，耶和华如此说：我与你为敌，并要拔刀出鞘，从你中间将义人和恶人一并剪除。"},{"start":4,"end":4,"text":"我既要从你中间剪除义人和恶人，所以我的刀要出鞘，自南至北攻击一切有血气的；"}],"33":[{"start":14,"end":14,"text":"再者，我对恶人说：『你必定死亡！』他若转离他的罪，行正直与合理的事："},{"start":15,"end":15,"text":"还人的当头和所抢夺的，遵行生命的律例，不作罪孽，他必定存活，不致死亡。"},{"start":16,"end":16,"text":"他所犯的一切罪必不被记念。他行了正直与合理的事，必定存活。"},{"start":30,"end":30,"text":"「人子啊，你本国的子民在墙垣旁边、在房屋门口谈论你。弟兄对弟兄彼此说：『来吧！听听有什么话从耶和华而出。』"},{"start":31,"end":31,"text":"他们来到你这里如同民来[聚会]，坐在你面前仿佛是我的民。他们听你的话却不去行；因为他们的口多显爱情，心却追随财利。"},{"start":32,"end":32,"text":"他们看你如善于奏乐、声音幽雅之人所唱的雅歌，他们听你的话却不去行。"}],"34":[{"start":1,"end":1,"text":"耶和华的话临到我说："},{"start":2,"end":2,"text":"「人子啊，你要向以色列的牧人发预言，攻击他们，说，主耶和华如此说：祸哉！以色列的牧人只知牧养自己。牧人岂不当牧养群羊吗？"},{"start":3,"end":3,"text":"你们吃脂油、穿羊毛、宰肥壮的，却不牧养群羊。"},{"start":4,"end":4,"text":"瘦弱的，你们没有养壮；有病的，你们没有医治；受伤的，你们没有缠裹；被逐的，你们没有领回；失丧的，你们没有寻找；但用强暴严严地辖制。"},{"start":5,"end":5,"text":"因无牧人，羊就分散；既分散，便作了一切野兽的食物。"},{"start":6,"end":6,"text":"我的羊在诸山间、在各高冈上流离，在全地上分散，无人去寻，无人去找。"},{"start":7,"end":7,"text":"「所以，你们这些牧人要听耶和华的话。"},{"start":8,"end":8,"text":"主耶和华说：我指着我的永生起誓，我的羊因无牧人就成为掠物，也作了一切野兽的食物。我的牧人不寻找我的羊；这些牧人只知牧养自己，并不牧养我的羊。"},{"start":9,"end":9,"text":"所以你们这些牧人要听耶和华的话。"},{"start":10,"end":10,"text":"主耶和华如此说：我必与牧人为敌，必向他们的手追讨我的羊，使他们不再牧放群羊；牧人也不再牧养自己。我必救我的羊脱离他们的口，不再作他们的食物。」"},{"start":11,"end":11,"text":"「主耶和华如此说：看哪，我必亲自寻找我的羊，将它们寻见。"},{"start":12,"end":12,"text":"牧人在羊群四散的日子怎样寻找他的羊，我必照样寻找我的羊。这些羊在密云黑暗的日子散到各处，我必从那里救回它们来。"},{"start":13,"end":13,"text":"我必从万民中领出它们，从各国内聚集它们，引导它们归回故土，也必在以色列山上—一切溪水旁边、境内一切可居之处—牧养它们。"},{"start":14,"end":14,"text":"我必在美好的草场牧养它们。它们的圈必在以色列高处的山上，它们必在佳美之圈中躺卧，也在以色列山肥美的草场吃草。"},{"start":15,"end":15,"text":"主耶和华说：我必亲自作我羊的牧人，使它们得以躺卧。"},{"start":16,"end":16,"text":"失丧的，我必寻找；被逐的，我必领回；受伤的，我必缠裹；有病的，我必医治；只是肥的壮的，我必除灭，也要秉公牧养它们。"}],"37":[{"start":21,"end":21,"text":"要对他们说，主耶和华如此说：我要将以色列人从他们所到的各国收取，又从四围聚集他们，引导他们归回本地。"},{"start":22,"end":22,"text":"我要使他们在那地，在以色列山上成为一国，有一王作他们众民的王。他们不再为二国，决不再分为二国；"}],"47":[{"start":9,"end":9,"text":"这河水所到之处，凡滋生的动物都必生活，并且因这流来的水必有极多的鱼，[海水]也变甜了。这河水所到之处，百物都必生活。"},{"start":10,"end":10,"text":"必有渔夫站在河边，从隐·基底直到隐·以革莲，都作晒网之处。那鱼各从其类，好像大海的鱼甚多。"}]},"JOH":{"1":[{"start":4,"end":4,"text":"生命在他里头，这生命就是人的光。"},{"start":5,"end":5,"text":"光照在黑暗里，黑暗却不接受光。"},{"start":6,"end":6,"text":"有一个人，是从　神那里差来的，名叫约翰。"},{"start":7,"end":7,"text":"这人来，为要作见证，就是为光作见证，叫众人因他可以信。"},{"start":8,"end":8,"text":"他不是那光，乃是要为光作见证。"},{"start":9,"end":9,"text":"那光是真光，照亮一切生在世上的人。"},{"start":11,"end":11,"text":"他到自己的地方来，自己的人倒不接待他。"},{"start":12,"end":12,"text":"凡接待他的，就是信他名的人，他就赐他们权柄作　神的儿女。"},{"start":13,"end":13,"text":"这等人不是从血气生的，不是从情欲生的，也不是从人意生的，乃是从　神生的。"},{"start":14,"end":14,"text":"道成了肉身，住在我们中间，充充满满地有恩典有真理。我们也见过他的荣光，正是父独生子的荣光。"},{"start":15,"end":15,"text":"约翰为他作见证，喊着说：「这就是我曾说：『那在我以后来的，反成了在我以前的，因他本来在我以前。』」"},{"start":16,"end":16,"text":"从他丰满[的恩典]里，我们都领受了，而且恩上加恩。"},{"start":17,"end":17,"text":"律法本是借着摩西传的；恩典和真理都是由耶稣基督来的。"},{"start":18,"end":18,"text":"从来没有人看见　神，只有在父怀里的独生子将他表明出来。"},{"start":19,"end":19,"text":"约翰所作的见证记在下面：犹太人从耶路撒冷差祭司和利未人到约翰那里，问他说：「你是谁？」"},{"start":20,"end":20,"text":"他就明说，并不隐瞒，明说：「我不是基督。」"},{"start":21,"end":21,"text":"他们又问他说：「这样，你是谁呢？是以利亚吗？」他说：「我不是。」「是那先知吗？」他回答说：「不是。」"},{"start":22,"end":22,"text":"于是他们说：「你到底是谁，叫我们好回复差我们来的人。你自己说，你是谁？」"},{"start":23,"end":23,"text":"他说：「我就是那在旷野有人声喊着说：『修直主的道路』，正如先知以赛亚所说的。」"},{"start":24,"end":24,"text":"那些人是法利赛人差来的；"},{"start":25,"end":25,"text":"他们就问他说：「你既不是基督，不是以利亚，也不是那先知，为什么施洗呢？」"},{"start":26,"end":26,"text":"约翰回答说：「我是用水施洗，但有一位站在你们中间，是你们不认识的，"},{"start":27,"end":27,"text":"就是那在我以后来的，我给他解鞋带也不配。」"},{"start":28,"end":28,"text":"这是在约旦河外伯大尼，约翰施洗的地方作的见证。"},{"start":29,"end":29,"text":"次日，约翰看见耶稣来到他那里，就说：「看哪，　神的羔羊，除去世人罪孽的！"},{"start":30,"end":30,"text":"这就是我曾说：『有一位在我以后来、反成了在我以前的，因他本来在我以前。』"},{"start":31,"end":31,"text":"我先前不认识他，如今我来用水施洗，为要叫他显明给以色列人。」"},{"start":32,"end":32,"text":"约翰又作见证说：「我曾看见圣灵，仿佛鸽子从天降下，住在他的身上。"},{"start":33,"end":33,"text":"我先前不认识他，只是那差我来用水施洗的、对我说：『你看见圣灵降下来，住在谁的身上，谁就是用圣灵施洗的。』"},{"start":34,"end":34,"text":"我看见了，就证明这是　神的儿子。」"},{"start":35,"end":35,"text":"再次日，约翰同两个门徒站在那里。"},{"start":36,"end":36,"text":"他见耶稣行走，就说：「看哪，这是　神的羔羊！」"},{"start":37,"end":37,"text":"两个门徒听见他的话，就跟从了耶稣。"},{"start":38,"end":38,"text":"耶稣转过身来，看见他们跟着，就问他们说：「你们要什么？」他们说：「拉比，在哪里住？」（拉比翻出来就是夫子。）"},{"start":39,"end":39,"text":"耶稣说：「你们来看。」他们就去看他在哪里住，这一天便与他同住；那时约有申正了。"},{"start":40,"end":40,"text":"听见约翰的话跟从耶稣的那两个人，一个是西门·彼得的兄弟安得烈。"},{"start":41,"end":41,"text":"他先找着自己的哥哥西门，对他说：「我们遇见弥赛亚了。」（弥赛亚翻出来就是基督。）"},{"start":42,"end":42,"text":"于是领他去见耶稣。耶稣看着他，说：「你是约翰的儿子西门，你要称为矶法。」（矶法翻出来就是彼得。）"},{"start":43,"end":43,"text":"又次日，耶稣想要往加利利去，遇见腓力，就对他说：「来跟从我吧。」"},{"start":44,"end":44,"text":"这腓力是伯赛大人，和安得烈、彼得同城。"},{"start":45,"end":45,"text":"腓力找着拿但业，对他说：「摩西在律法上所写的和众先知所记的那一位，我们遇见了，就是约瑟的儿子拿撒勒人耶稣。」"},{"start":46,"end":46,"text":"拿但业对他说：「拿撒勒还能出什么好的吗？」腓力说：「你来看！」"},{"start":47,"end":47,"text":"耶稣看见拿但业来，就指着他说：「看哪，这是个真以色列人，他心里是没有诡诈的。」"},{"start":48,"end":48,"text":"拿但业对耶稣说：「你从哪里知道我呢？」耶稣回答说：「腓力还没有招呼你，你在无花果树底下，我就看见你了。」"},{"start":49,"end":49,"text":"拿但业说：「拉比，你是　神的儿子，你是以色列的王！」"},{"start":50,"end":50,"text":"耶稣对他说：「因为我说『在无花果树底下看见你』，你就信吗？你将要看见比这更大的事」；"},{"start":51,"end":51,"text":"又说：「我实实在在地告诉你们，你们将要看见天开了，　神的使者上去下来在人子身上。」"}],"2":[{"start":13,"end":13,"text":"犹太人的逾越节近了，耶稣就上耶路撒冷去。"},{"start":14,"end":14,"text":"看见殿里有卖牛、羊、鸽子的，并有兑换银钱的人坐在那里，"},{"start":15,"end":15,"text":"耶稣就拿绳子做成鞭子，把牛羊都赶出殿去，倒出兑换银钱之人的银钱，推翻他们的桌子，"},{"start":16,"end":16,"text":"又对卖鸽子的说：「把这些东西拿去！不要将我父的殿当作买卖的地方。」"},{"start":17,"end":17,"text":"他的门徒就想起[经上]记着说：「我为你的殿心里焦急，如同火烧。」"},{"start":18,"end":18,"text":"因此犹太人问他说：「你既做这些事，还显什么神迹给我们看呢？」"},{"start":19,"end":19,"text":"耶稣回答说：「你们拆毁这殿，我三日内要再建立起来。」"},{"start":20,"end":20,"text":"犹太人便说：「这殿是四十六年才造成的，你三日内就再建立起来吗？」"},{"start":21,"end":21,"text":"但耶稣这话是以他的身体为殿。"},{"start":22,"end":22,"text":"所以到他从死里复活以后，门徒就想起他说过这话，便信了圣经和耶稣所说的。"}],"5":[{"start":1,"end":1,"text":"这事以后，到了犹太人的一个节期，耶稣就上耶路撒冷去。"},{"start":2,"end":2,"text":"在耶路撒冷，靠近羊[门]有一个池子，希伯来话叫作毕士大，[旁边]有五个廊子；"},{"start":3,"end":3,"text":"里面躺着瞎眼的、瘸腿的、血气枯干的许多病人。"},{"start":5,"end":5,"text":"在那里有一个人，病了三十八年。"},{"start":6,"end":6,"text":"耶稣看见他躺着，知道他病了许久，就问他说：「你要痊愈吗？」"},{"start":7,"end":7,"text":"病人回答说：「先生，水动的时候，没有人把我放在池子里；我正去的时候，就有别人比我先下去。」"},{"start":8,"end":8,"text":"耶稣对他说：「起来，拿你的褥子走吧！」"},{"start":9,"end":9,"text":"那人立刻痊愈，就拿起褥子来走了。"},{"start":10,"end":10,"text":"那天是安息日，所以犹太人对那医好的人说：「今天是安息日，你拿褥子是不可的。」"},{"start":11,"end":11,"text":"他却回答说：「那使我痊愈的，对我说：『拿你的褥子走吧。』」"},{"start":12,"end":12,"text":"他们问他说：「对你说『拿褥子走』的是什么人？」"},{"start":13,"end":13,"text":"那医好的人不知道是谁；因为那里的人多，耶稣已经躲开了。"},{"start":14,"end":14,"text":"后来耶稣在殿里遇见他，对他说：「你已经痊愈了，不要再犯罪，恐怕你遭遇的更加利害。」"},{"start":15,"end":15,"text":"那人就去告诉犹太人，使他痊愈的是耶稣。"},{"start":16,"end":16,"text":"所以犹太人逼迫耶稣，因为他在安息日做了这事。"},{"start":17,"end":17,"text":"耶稣就对他们说：「我父做事直到如今，我也做事。」"},{"start":18,"end":18,"text":"所以犹太人越发想要杀他；因他不但犯了安息日，并且称　神为他的父，将自己和　神当作平等。"},{"start":30,"end":30,"text":"「我凭着自己不能做什么，我怎么听见就怎么审判。我的审判也是公平的；因为我不求自己的意思，只求那差我来者的意思。」"},{"start":31,"end":31,"text":"「我若为自己作见证，我的见证就不真。"},{"start":32,"end":32,"text":"另有一位给我作见证，我也知道他给我作的见证是真的。"},{"start":33,"end":33,"text":"你们曾差人到约翰那里，他为真理作过见证。"},{"start":34,"end":34,"text":"其实，我所受的见证不是从人来的；然而，我说这些话，为要叫你们得救。"},{"start":35,"end":35,"text":"约翰是点着的明灯，你们情愿暂时喜欢他的光。"},{"start":36,"end":36,"text":"但我有比约翰更大的见证；因为父交给我要我成就的事，就是我所做的事，这便见证我是父所差来的。"},{"start":37,"end":37,"text":"差我来的父也为我作过见证。你们从来没有听见他的声音，也没有看见他的形象。"},{"start":38,"end":38,"text":"你们并没有他的道存在心里；因为他所差来的，你们不信。"},{"start":39,"end":39,"text":"你们查考圣经，因你们以为内中有永生；给我作见证的就是这经。"},{"start":40,"end":40,"text":"然而，你们不肯到我这里来得生命。"},{"start":41,"end":41,"text":"「我不受从人来的荣耀。"},{"start":42,"end":42,"text":"但我知道，你们心里没有　神的爱。"},{"start":43,"end":43,"text":"我奉我父的名来，你们并不接待我；若有别人奉自己的名来，你们倒要接待他。"},{"start":44,"end":44,"text":"你们互相受荣耀，却不求从独一之　神来的荣耀，怎能信[我]呢？"},{"start":45,"end":45,"text":"不要想我在父面前要告你们；有一位告你们的，就是你们所仰赖的摩西。"},{"start":46,"end":46,"text":"你们如果信摩西，也必信我，因为他[书上]有指着我写的话。"},{"start":47,"end":47,"text":"你们若不信他的书，怎能信我的话呢？」"}],"6":[{"start":1,"end":1,"text":"这事以后，耶稣渡过加利利海，就是提比哩亚海。"},{"start":2,"end":2,"text":"有许多人因为看见他在病人身上所行的神迹，就跟随他。"},{"start":3,"end":3,"text":"耶稣上了山，和门徒一同坐在那里。"},{"start":4,"end":4,"text":"那时犹太人的逾越节近了。"},{"start":5,"end":5,"text":"耶稣举目看见许多人来，就对腓力说：「我们从哪里买饼叫这些人吃呢？」（"},{"start":6,"end":6,"text":"他说这话是要试验腓力；他自己原知道要怎样行。）"},{"start":7,"end":7,"text":"腓力回答说：「就是二十两银子的饼，叫他们各人吃一点也是不够的。」"},{"start":8,"end":8,"text":"有一个门徒，就是西门·彼得的兄弟安得烈，对耶稣说："},{"start":9,"end":9,"text":"「在这里有一个孩童，带着五个大麦饼、两条鱼，只是分给这许多人还算什么呢？」"},{"start":10,"end":10,"text":"耶稣说：「你们叫众人坐下。」原来那地方的草多，众人就坐下，数目约有五千。"},{"start":11,"end":11,"text":"耶稣拿起饼来，祝谢了，就分给那坐着的人；分鱼也是这样，都随着他们所要的。"},{"start":12,"end":12,"text":"他们吃饱了，耶稣对门徒说：「把剩下的零碎收拾起来，免得有糟蹋的。」"},{"start":13,"end":13,"text":"他们便将那五个大麦饼的零碎，就是众人吃了剩下的，收拾起来，装满了十二个篮子。"},{"start":14,"end":14,"text":"众人看见耶稣所行的神迹，就说：「这真是那要到世间来的先知！」"},{"start":15,"end":15,"text":"耶稣既知道众人要来强逼他作王，就独自又退到山上去了。"},{"start":16,"end":16,"text":"到了晚上，他的门徒下海边去，"},{"start":17,"end":17,"text":"上了船，要过海往迦百农去。天已经黑了，耶稣还没有来到他们那里。"},{"start":18,"end":18,"text":"忽然狂风大作，海就翻腾起来。"},{"start":19,"end":19,"text":"门徒摇橹，约行了十里多路，看见耶稣在海面上走，渐渐近了船，他们就害怕。"},{"start":20,"end":20,"text":"耶稣对他们说：「是我，不要怕！」"},{"start":21,"end":21,"text":"门徒就喜欢接他上船，船立时到了他们所要去的地方。"},{"start":22,"end":22,"text":"第二日，站在海那边的众人知道那里没有别的船，只有一只小船，又知道耶稣没有同他的门徒上船，乃是门徒自己去的。"},{"start":23,"end":23,"text":"然而，有几只小船从提比哩亚来，靠近主祝谢后[分饼给人]吃的地方。"},{"start":24,"end":24,"text":"众人见耶稣和门徒都不在那里，就上了船，往迦百农去找耶稣。"},{"start":25,"end":25,"text":"既在海那边找着了，就对他说：「拉比，是几时到这里来的？」"},{"start":26,"end":26,"text":"耶稣回答说：「我实实在在地告诉你们，你们找我，并不是因见了神迹，乃是因吃饼得饱。"},{"start":27,"end":27,"text":"不要为那必坏的食物劳力，要为那存到永生的食物劳力，就是人子要赐给你们的，因为人子是父　神所印证的。」"},{"start":28,"end":28,"text":"众人问他说：「我们当行什么才算做　神的工呢？」"},{"start":29,"end":29,"text":"耶稣回答说：「信　神所差来的，这就是做　神的工。」"},{"start":30,"end":30,"text":"他们又说：「你行什么神迹，叫我们看见就信你；你到底做什么事呢？"},{"start":31,"end":31,"text":"我们的祖宗在旷野吃过吗哪，如[经上]写着说：『他从天上赐下粮来给他们吃。』」"},{"start":32,"end":32,"text":"耶稣说：「我实实在在地告诉你们，那从天上来的粮不是摩西赐给你们的，乃是我父将天上来的真粮赐给你们。"},{"start":33,"end":33,"text":"因为　神的粮就是那从天上降下来、赐生命给世界的。」"},{"start":34,"end":34,"text":"他们说：「主啊，常将这粮赐给我们！」"},{"start":35,"end":35,"text":"耶稣说：「我就是生命的粮。到我这里来的，必定不饿；信我的，永远不渴。"},{"start":36,"end":36,"text":"只是我对你们说过，你们已经看见我，还是不信。"},{"start":37,"end":37,"text":"凡父所赐给我的人必到我这里来；到我这里来的，我总不丢弃他。"},{"start":38,"end":38,"text":"因为我从天上降下来，不是要按自己的意思行，乃是要按那差我来者的意思行。"},{"start":39,"end":39,"text":"差我来者的意思就是：他所赐给我的，叫我一个也不失落，在末日却叫他复活。"},{"start":40,"end":40,"text":"因为我父的意思是叫一切见子而信的人得永生，并且在末日我要叫他复活。」"},{"start":41,"end":41,"text":"犹太人因为耶稣说「我是从天上降下来的粮」，就私下议论他，"},{"start":42,"end":42,"text":"说：「这不是约瑟的儿子耶稣吗？他的父母我们岂不认得吗？他如今怎么说『我是从天上降下来的』呢？」"},{"start":43,"end":43,"text":"耶稣回答说：「你们不要大家议论。"},{"start":44,"end":44,"text":"若不是差我来的父吸引人，就没有能到我这里来的；[到我这里来的]，在末日我要叫他复活。"},{"start":45,"end":45,"text":"在先知书上写着说：『他们都要蒙　神的教训。』凡听见父[之教训]又学习的，就到我这里来。"},{"start":46,"end":46,"text":"这不是说有人看见过父，惟独从　神来的，他看见过父。"},{"start":47,"end":47,"text":"我实实在在地告诉你们，信的人有永生。"},{"start":48,"end":48,"text":"我就是生命的粮。"},{"start":49,"end":49,"text":"你们的祖宗在旷野吃过吗哪，还是死了。"},{"start":50,"end":50,"text":"这是从天上降下来的粮，叫人吃了就不死。"},{"start":51,"end":51,"text":"我是从天上降下来生命的粮；人若吃这粮，就必永远活着。我所要赐的粮就是我的肉，为世人之生命所赐的。」"},{"start":52,"end":52,"text":"因此，犹太人彼此争论说：「这个人怎能把他的肉给我们吃呢？」"},{"start":53,"end":53,"text":"耶稣说：「我实实在在地告诉你们，你们若不吃人子的肉，不喝人子的血，就没有生命在你们里面。"},{"start":54,"end":54,"text":"吃我肉、喝我血的人就有永生，在末日我要叫他复活。"},{"start":55,"end":55,"text":"我的肉真是可吃的，我的血真是可喝的。"},{"start":56,"end":56,"text":"吃我肉、喝我血的人常在我里面，我也常在他里面。"},{"start":57,"end":57,"text":"永活的父怎样差我来，我又因父活着；照样，吃我[肉]的人也要因我活着。"},{"start":58,"end":58,"text":"这就是从天上降下来的粮。吃这粮的人就永远活着，不像[你们的]祖宗吃过[吗哪]还是死了。」"},{"start":59,"end":59,"text":"这些话是耶稣在迦百农会堂里教训人说的。"},{"start":60,"end":60,"text":"他的门徒中有好些人听见了，就说：「这话甚难，谁能听呢？」"},{"start":61,"end":61,"text":"耶稣心里知道门徒为这话议论，就对他们说：「这话是叫你们厌弃吗？"},{"start":62,"end":62,"text":"倘或你们看见人子升到他原来所在之处，怎么样呢？"},{"start":63,"end":63,"text":"叫人活着的乃是灵，肉体是无益的。我对你们所说的话就是灵，就是生命。"},{"start":64,"end":64,"text":"只是你们中间有不信的人。」耶稣从起头就知道谁不信他，谁要卖他。"},{"start":65,"end":65,"text":"耶稣又说：「所以我对你们说过，若不是蒙我父的恩赐，没有人能到我这里来。」"},{"start":66,"end":66,"text":"从此，他门徒中多有退去的，不再和他同行。"},{"start":67,"end":67,"text":"耶稣就对那十二个门徒说：「你们也要去吗？」"},{"start":68,"end":68,"text":"西门·彼得回答说：「主啊，你有永生之道，我们还归从谁呢？"},{"start":69,"end":69,"text":"我们已经信了，又知道你是　神的圣者。」"},{"start":70,"end":70,"text":"耶稣说：「我不是拣选了你们十二个门徒吗？但你们中间有一个是魔鬼。」"},{"start":71,"end":71,"text":"耶稣这话是指着加略人西门的儿子犹大说的；他本是十二个门徒里的一个，后来要卖耶稣的。"}],"8":[{"start":36,"end":36,"text":"所以[天父的]儿子若叫你们自由，你们就真自由了。"},{"start":37,"end":37,"text":"我知道你们是亚伯拉罕的子孙，你们却想要杀我，因为你们心里容不下我的道。"},{"start":38,"end":38,"text":"我所说的是在我父那里看见的；你们所行的是在你们的父那里听见的。」"},{"start":39,"end":39,"text":"他们说：「我们的父就是亚伯拉罕。」耶稣说：「你们若是亚伯拉罕的儿子，就必行亚伯拉罕所行的事。"},{"start":40,"end":40,"text":"我将在　神那里所听见的真理告诉了你们，现在你们却想要杀我，这不是亚伯拉罕所行的事。"},{"start":41,"end":41,"text":"你们是行你们父所行的事。」他们说：「我们不是从淫乱生的；我们只有一位父，就是　神。」"},{"start":42,"end":42,"text":"耶稣说：「倘若　神是你们的父，你们就必爱我；因为我本是出于　神，也是从　神而来，并不是由着自己来，乃是他差我来。"},{"start":43,"end":43,"text":"你们为什么不明白我的话呢？无非是因你们不能听我的道。"},{"start":44,"end":44,"text":"你们是出于你们的父魔鬼，你们父的私欲你们偏要行。他从起初是杀人的，不守真理，因他心里没有真理。他说谎是出于自己；因他本来是说谎的，也是说谎之人的父。"},{"start":45,"end":45,"text":"我将真理告诉你们，你们就因此不信我。"},{"start":46,"end":46,"text":"你们中间谁能指证我有罪呢？我既然将真理告诉你们，为什么不信我呢？"},{"start":47,"end":47,"text":"出于　神的，必听　神的话；你们不听，因为你们不是出于　神。」"},{"start":48,"end":48,"text":"犹太人回答说：「我们说你是撒马利亚人，并且是鬼附着的，这话岂不正对吗？」"},{"start":49,"end":49,"text":"耶稣说：「我不是鬼附着的；我尊敬我的父，你们倒轻慢我。"},{"start":50,"end":50,"text":"我不求自己的荣耀，有一位[为我]求[荣耀]、定是非的。"},{"start":51,"end":51,"text":"我实实在在地告诉你们，人若遵守我的道，就永远不见死。」"},{"start":52,"end":52,"text":"犹太人对他说：「现在我们知道你是鬼附着的。亚伯拉罕死了，众先知也死了，你还说：『人若遵守我的道，就永远不尝死味。』"},{"start":53,"end":53,"text":"难道你比我们的祖宗亚伯拉罕还大吗？他死了，众先知也死了，你将自己当作什么人呢？」"},{"start":54,"end":54,"text":"耶稣回答说：「我若荣耀自己，我的荣耀就算不得什么；荣耀我的乃是我的父，就是你们所说是你们的　神。"},{"start":55,"end":55,"text":"你们未曾认识他；我却认识他。我若说不认识他，我就是说谎的，像你们一样；但我认识他，也遵守他的道。"},{"start":56,"end":56,"text":"你们的祖宗亚伯拉罕欢欢喜喜地仰望我的日子，既看见了就快乐。」"},{"start":57,"end":57,"text":"犹太人说：「你还没有五十岁，岂见过亚伯拉罕呢？」"},{"start":58,"end":58,"text":"耶稣说：「我实实在在地告诉你们，还没有亚伯拉罕就有了我。」"},{"start":59,"end":59,"text":"于是他们拿石头要打他；耶稣却躲藏，从殿里出去了。"}],"9":[{"start":1,"end":1,"text":"耶稣过去的时候，看见一个人生来是瞎眼的。"},{"start":2,"end":2,"text":"门徒问耶稣说：「拉比，这人生来是瞎眼的，是谁犯了罪？是这人呢？是他父母呢？」"},{"start":3,"end":3,"text":"耶稣回答说：「也不是这人犯了罪，也不是他父母犯了罪，是要在他身上显出　神的作为来。"},{"start":4,"end":4,"text":"趁着白日，我们必须做那差我来者的工；黑夜将到，就没有人能做工了。"},{"start":5,"end":5,"text":"我在世上的时候，是世上的光。」"},{"start":6,"end":6,"text":"耶稣说了这话，就吐唾沫在地上，用唾沫和泥抹在瞎子的眼睛上，"},{"start":7,"end":7,"text":"对他说：「你往西罗亚池子里去洗。」（西罗亚翻出来就是「奉差遣」。）他去一洗，回头就看见了。"},{"start":8,"end":8,"text":"他的邻舍和那素常见他是讨饭的，就说：「这不是那从前坐着讨饭的人吗？」"},{"start":9,"end":9,"text":"有人说：「是他」；又有人说：「不是，却是像他。」他自己说：「是我。」"},{"start":10,"end":10,"text":"他们对他说：「你的眼睛是怎么开的呢？」"},{"start":11,"end":11,"text":"他回答说：「有一个人，名叫耶稣，他和泥抹我的眼睛，对我说：『你往西罗亚[池子]去洗。』我去一洗，就看见了。」"},{"start":12,"end":12,"text":"他们说：「那个人在哪里？」他说：「我不知道。」"},{"start":13,"end":13,"text":"他们把从前瞎眼的人带到法利赛人那里。"},{"start":14,"end":14,"text":"耶稣和泥开他眼睛的日子是安息日。"},{"start":15,"end":15,"text":"法利赛人也问他是怎么得看见的。瞎子对他们说：「他把泥抹在我的眼睛上，我去一洗，就看见了。」"},{"start":16,"end":16,"text":"法利赛人中有的说：「这个人不是从　神来的，因为他不守安息日。」又有人说：「一个罪人怎能行这样的神迹呢？」他们就起了纷争。"},{"start":17,"end":17,"text":"他们又对瞎子说：「他既然开了你的眼睛，你说他是怎样的人呢？」他说：「是个先知。」"},{"start":18,"end":18,"text":"犹太人不信他从前是瞎眼，后来能看见的，等到叫了他的父母来，"},{"start":19,"end":19,"text":"问他们说：「这是你们的儿子吗？你们说他生来是瞎眼的，如今怎么能看见了呢？」"},{"start":20,"end":20,"text":"他父母回答说：「他是我们的儿子，生来就瞎眼，这是我们知道的。"},{"start":21,"end":21,"text":"至于他如今怎么能看见，我们却不知道；是谁开了他的眼睛，我们也不知道。他已经成了人，你们问他吧，他自己必能说。」"},{"start":22,"end":22,"text":"他父母说这话，是怕犹太人；因为犹太人已经商议定了，若有认耶稣是基督的，要把他赶出会堂。"},{"start":23,"end":23,"text":"因此他父母说：「他已经成了人，你们问他吧。」"},{"start":24,"end":24,"text":"所以法利赛人第二次叫了那从前瞎眼的人来，对他说：「你该将荣耀归给　神，我们知道这人是个罪人。」"},{"start":25,"end":25,"text":"他说：「他是个罪人不是，我不知道；有一件事我知道，从前我是眼瞎的，如今能看见了。」"},{"start":26,"end":26,"text":"他们就问他说：「他向你做什么？是怎么开了你的眼睛呢？」"},{"start":27,"end":27,"text":"他回答说：「我方才告诉你们，你们不听，为什么又要听呢？莫非你们也要作他的门徒吗？」"},{"start":28,"end":28,"text":"他们就骂他说：「你是他的门徒；我们是摩西的门徒。"},{"start":29,"end":29,"text":"神对摩西说话是我们知道的；只是这个人，我们不知道他从哪里来！」"},{"start":30,"end":30,"text":"那人回答说：「他开了我的眼睛，你们竟不知道他从哪里来，这真是奇怪！"},{"start":31,"end":31,"text":"我们知道　神不听罪人，惟有敬奉　神、遵行他旨意的，　神才听他。"},{"start":32,"end":32,"text":"从创世以来，未曾听见有人把生来是瞎子的眼睛开了。"},{"start":33,"end":33,"text":"这人若不是从　神来的，什么也不能做。」"},{"start":34,"end":34,"text":"他们回答说：「你全然生在罪孽中，还要教训我们吗？」于是把他赶出去了。"},{"start":35,"end":35,"text":"耶稣听说他们把他赶出去，后来遇见他，就说：「你信　神的儿子吗？」"},{"start":36,"end":36,"text":"他回答说：「主啊，谁是　神的儿子，叫我信他呢？」"},{"start":37,"end":37,"text":"耶稣说：「你已经看见他，现在和你说话的就是他。」"},{"start":38,"end":38,"text":"他说：「主啊，我信！」就拜耶稣。"},{"start":39,"end":39,"text":"耶稣说：「我为审判到这世上来，叫不能看见的，可以看见；能看见的，反瞎了眼。」"},{"start":40,"end":40,"text":"同他在那里的法利赛人听见这话，就说：「难道我们也瞎了眼吗？」"},{"start":41,"end":41,"text":"耶稣对他们说：「你们若瞎了眼，就没有罪了；但如今你们说『我们能看见』，[所以]你们的罪还在。」"}],"10":[{"start":1,"end":1,"text":"「我实实在在地告诉你们，人进羊圈，不从门进去，倒从别处爬进去，那人就是贼，就是强盗。"},{"start":2,"end":2,"text":"从门进去的，才是羊的牧人。"},{"start":3,"end":3,"text":"看门的就给他开门；羊也听他的声音。他按着名叫自己的羊，把羊领出来。"},{"start":4,"end":4,"text":"既放出自己的羊来，就在前头走，羊也跟着他，因为认得他的声音。"},{"start":5,"end":5,"text":"羊不跟着生人；因为不认得他的声音，必要逃跑。」"},{"start":6,"end":6,"text":"耶稣将这比喻告诉他们，但他们不明白所说的是什么意思。"},{"start":7,"end":7,"text":"所以，耶稣又对他们说：「我实实在在地告诉你们，我就是羊的门。"},{"start":8,"end":8,"text":"凡在我以先来的都是贼，是强盗；羊却不听他们。"},{"start":9,"end":9,"text":"我就是门；凡从我进来的，必然得救，并且出入得草吃。"},{"start":10,"end":10,"text":"盗贼来，无非要偷窃，杀害，毁坏；我来了，是要叫羊得生命，并且得的更丰盛。"},{"start":11,"end":11,"text":"我是好牧人；好牧人为羊舍命。"},{"start":12,"end":12,"text":"若是雇工，不是牧人，羊也不是他自己的，他看见狼来，就撇下羊逃走；狼抓住羊，赶散了羊群。"},{"start":13,"end":13,"text":"雇工[逃走]，因他是雇工，并不顾念羊。"},{"start":14,"end":14,"text":"我是好牧人；我认识我的羊，我的羊也认识我，"},{"start":15,"end":15,"text":"正如父认识我，我也认识父一样；并且我为羊舍命。"},{"start":16,"end":16,"text":"我另外有羊，不是这圈里的；我必须领他们来，他们也要听我的声音，并且要合成一群，归一个牧人了。"},{"start":17,"end":17,"text":"我父爱我；因我将命舍去，好再取回来。"},{"start":18,"end":18,"text":"没有人夺我的命去，是我自己舍的。我有权柄舍了，也有权柄取回来。这是我从我父所受的命令。」"},{"start":19,"end":19,"text":"犹太人为这些话又起了纷争。"},{"start":20,"end":20,"text":"内中有好些人说：「他是被鬼附着，而且疯了，为什么听他呢？」"},{"start":21,"end":21,"text":"又有人说：「这不是鬼附之人所说的话。鬼岂能叫瞎子的眼睛开了呢？」"},{"start":22,"end":22,"text":"在耶路撒冷有修殿节，是冬天的时候。"},{"start":23,"end":23,"text":"耶稣在殿里所罗门的廊下行走。"},{"start":24,"end":24,"text":"犹太人围着他，说：「你叫我们犹疑不定到几时呢？你若是基督，就明明地告诉我们。」"},{"start":25,"end":25,"text":"耶稣回答说：「我已经告诉你们，你们不信。我奉我父之名所行的事可以为我作见证；"},{"start":26,"end":26,"text":"只是你们不信，因为你们不是我的羊。"},{"start":27,"end":27,"text":"我的羊听我的声音，我也认识他们，他们也跟着我。"},{"start":28,"end":28,"text":"我又赐给他们永生；他们永不灭亡，谁也不能从我手里把他们夺去。"},{"start":29,"end":29,"text":"我父把羊赐给我，他比万有都大，谁也不能从我父手里把他们夺去。"},{"start":30,"end":30,"text":"我与父原为一。」"},{"start":31,"end":31,"text":"犹太人又拿起石头来要打他。"},{"start":32,"end":32,"text":"耶稣对他们说：「我从父显出许多善事给你们看，你们是为哪一件拿石头打我呢？」"},{"start":33,"end":33,"text":"犹太人回答说：「我们不是为善事拿石头打你，是为你说僭妄的话；又为你是个人，反将自己当作　神。」"},{"start":34,"end":34,"text":"耶稣说：「你们的律法上岂不是写着『我曾说你们是神』吗？"},{"start":35,"end":35,"text":"经上的话是不能废的；若那些承受　神道的人尚且称为神，"},{"start":36,"end":36,"text":"父所分别为圣、又差到世间来的，他自称是　神的儿子，你们还向他说『你说僭妄的话』吗？"},{"start":37,"end":37,"text":"我若不行我父的事，你们就不必信我；"},{"start":38,"end":38,"text":"我若行了，你们纵然不信我，也当信这些事，叫你们又知道又明白父在我里面，我也在父里面。」"},{"start":39,"end":39,"text":"他们又要拿他，他却逃出他们的手走了。"},{"start":40,"end":40,"text":"耶稣又往约旦河外去，到了约翰起初施洗的地方，就住在那里。"},{"start":41,"end":41,"text":"有许多人来到他那里。他们说：「约翰一件神迹没有行过，但约翰指着这人所说的一切话都是真的。」"},{"start":42,"end":42,"text":"在那里，信耶稣的人就多了。"}],"12":[{"start":1,"end":1,"text":"逾越节前六日，耶稣来到伯大尼，就是他叫拉撒路从死里复活之处。"},{"start":2,"end":2,"text":"有人在那里给耶稣预备筵席；马大伺候，拉撒路也在那同耶稣坐席的人中。"},{"start":3,"end":3,"text":"马利亚就拿着一斤极贵的真哪哒香膏，抹耶稣的脚，又用自己头发去擦，屋里就满了膏的香气。"},{"start":4,"end":4,"text":"有一个门徒，就是那将要卖耶稣的加略人犹大，"},{"start":5,"end":5,"text":"说：「这香膏为什么不卖三十两银子周济穷人呢？」"},{"start":6,"end":6,"text":"他说这话，并不是挂念穷人，乃因他是个贼，又带着钱囊，常取其中所存的。"},{"start":7,"end":7,"text":"耶稣说：「由她吧！她是为我安葬之日存留的。"},{"start":8,"end":8,"text":"因为常有穷人和你们同在，只是你们不常有我。」"},{"start":12,"end":12,"text":"第二天，有许多上来过节的人听见耶稣将到耶路撒冷，"},{"start":13,"end":13,"text":"就拿着棕树枝出去迎接他，喊着说： 和散那！ 奉主名来的以色列王是应当称颂的！"},{"start":14,"end":14,"text":"耶稣得了一个驴驹，就骑上，如[经]上所记的说："},{"start":15,"end":15,"text":"锡安的民哪，不要惧怕！ 你的王骑着驴驹来了。"},{"start":16,"end":16,"text":"这些事门徒起先不明白，等到耶稣得了荣耀以后才想起这话是指着他写的，并且众人果然向他这样行了。"},{"start":17,"end":17,"text":"当耶稣呼唤拉撒路，叫他从死复活出坟墓的时候，同耶稣在那里的众人就作见证。"},{"start":18,"end":18,"text":"众人因听见耶稣行了这神迹，就去迎接他。"},{"start":19,"end":19,"text":"法利赛人彼此说：「看哪，你们是徒劳无益，世人都随从他去了。」"}],"13":[{"start":1,"end":1,"text":"逾越节以前，耶稣知道自己离世归父的时候到了。他既然爱世间属自己的人，就爱他们到底。"},{"start":2,"end":2,"text":"吃晚饭的时候，魔鬼已将卖耶稣的意思放在西门的儿子加略人犹大心里。"},{"start":3,"end":3,"text":"耶稣知道父已将万有交在他手里，且知道自己是从　神出来的，又要归到　神那里去，"},{"start":4,"end":4,"text":"就离席站起来，脱了衣服，拿一条手巾束腰，"},{"start":5,"end":5,"text":"随后把水倒在盆里，就洗门徒的脚，并用自己所束的手巾擦干。"},{"start":6,"end":6,"text":"挨到西门·彼得，彼得对他说：「主啊，你洗我的脚吗？」"},{"start":7,"end":7,"text":"耶稣回答说：「我所做的，你如今不知道，后来必明白。」"},{"start":8,"end":8,"text":"彼得说：「你永不可洗我的脚！」耶稣说：「我若不洗你，你就与我无分了。」"},{"start":9,"end":9,"text":"西门·彼得说：「主啊，不但我的脚，连手和头也要洗。」"},{"start":10,"end":10,"text":"耶稣说：「凡洗过澡的人，只要把脚一洗，全身就干净了。你们是干净的，然而不都是干净的。」"},{"start":11,"end":11,"text":"耶稣原知道要卖他的是谁，所以说：「你们不都是干净的。」"},{"start":12,"end":12,"text":"耶稣洗完了他们的脚，就穿上衣服，又坐下，对他们说：「我向你们所做的，你们明白吗？"},{"start":13,"end":13,"text":"你们称呼我夫子，称呼我主，你们说的不错，我本来是。"},{"start":14,"end":14,"text":"我是你们的主，你们的夫子，尚且洗你们的脚，你们也当彼此洗脚。"},{"start":15,"end":15,"text":"我给你们作了榜样，叫你们照着我向你们所做的去做。"},{"start":16,"end":16,"text":"我实实在在地告诉你们，仆人不能大于主人，差人也不能大于差他的人。"},{"start":17,"end":17,"text":"你们既知道这事，若是去行就有福了。"},{"start":18,"end":18,"text":"我这话不是指着你们众人说的，我知道我所拣选的是谁。现在要应验经上的话，说：『同我吃饭的人用脚踢我。』"},{"start":19,"end":19,"text":"如今事情还没有成就，我要先告诉你们，叫你们到事情成就的时候可以信我是[基督]。"},{"start":20,"end":20,"text":"我实实在在地告诉你们，有人接待我所差遣的，就是接待我；接待我，就是接待那差遣我的。」"},{"start":21,"end":21,"text":"耶稣说了这话，心里忧愁，就明说：「我实实在在地告诉你们，你们中间有一个人要卖我了。」"},{"start":22,"end":22,"text":"门徒彼此对看，猜不透所说的是谁。"},{"start":23,"end":23,"text":"有一个门徒，是耶稣所爱的，侧身挨近耶稣的怀里。"},{"start":24,"end":24,"text":"西门·彼得点头对他说：「你告诉我们，主是指着谁说的。」"},{"start":25,"end":25,"text":"那门徒便就势靠着耶稣的胸膛，问他说：「主啊，是谁呢？」"},{"start":26,"end":26,"text":"耶稣回答说：「我蘸一点饼给谁，就是谁。」耶稣就蘸了一点饼，递给加略人西门的儿子犹大。"},{"start":27,"end":27,"text":"他吃了以后，撒但就入了他的心。耶稣便对他说：「你所做的，快做吧！」"},{"start":28,"end":28,"text":"同席的人没有一个知道是为什么对他说这话。"},{"start":29,"end":29,"text":"有人因犹大带着钱囊，以为耶稣是对他说：「你去买我们过节所应用的东西」，或是叫他拿什么周济穷人。"},{"start":30,"end":30,"text":"犹大受了那点饼，立刻就出去。那时候是夜间了。"},{"start":31,"end":31,"text":"他既出去，耶稣就说：「如今人子得了荣耀，　神在人子身上也得了荣耀。"},{"start":32,"end":32,"text":"神要因自己荣耀人子，并且要快快地荣耀他。"},{"start":33,"end":33,"text":"小子们，我还有不多的时候与你们同在；后来你们要找我，但我所去的地方你们不能到。这话我曾对犹太人说过，如今也照样对你们说。"},{"start":34,"end":34,"text":"我赐给你们一条新命令，乃是叫你们彼此相爱；我怎样爱你们，你们也要怎样相爱。"},{"start":35,"end":35,"text":"你们若有彼此相爱的心，众人因此就认出你们是我的门徒了。」"},{"start":36,"end":36,"text":"西门·彼得问耶稣说：「主往哪里去？」耶稣回答说：「我所去的地方，你现在不能跟我去，后来却要跟我去。」"},{"start":37,"end":37,"text":"彼得说：「主啊，我为什么现在不能跟你去？我愿意为你舍命！」"},{"start":38,"end":38,"text":"耶稣说：「你愿意为我舍命吗？我实实在在地告诉你，鸡叫以先，你要三次不认我。」"}],"18":[{"start":1,"end":1,"text":"耶稣说了这话，就同门徒出去，过了汲沦溪。在那里有一个园子，他和门徒进去了。"},{"start":2,"end":2,"text":"卖耶稣的犹大也知道那地方，因为耶稣和门徒屡次上那里去聚集。"},{"start":3,"end":3,"text":"犹大领了一队兵，和祭司长并法利赛人的差役，拿着灯笼、火把、兵器，就来到园里。"},{"start":4,"end":4,"text":"耶稣知道将要临到自己的一切事，就出来对他们说：「你们找谁？」"},{"start":5,"end":5,"text":"他们回答说：「找拿撒勒人耶稣。」耶稣说：「我就是！」卖他的犹大也同他们站在那里。"},{"start":6,"end":6,"text":"耶稣一说「我就是」，他们就退后倒在地上。"},{"start":7,"end":7,"text":"他又问他们说：「你们找谁？」他们说：「找拿撒勒人耶稣。」"},{"start":8,"end":8,"text":"耶稣说：「我已经告诉你们，我就是。你们若找我，就让这些人去吧。」"},{"start":9,"end":9,"text":"这要应验耶稣从前的话，说：「你所赐给我的人，我没有失落一个。」"},{"start":10,"end":10,"text":"西门·彼得带着一把刀，就拔出来，将大祭司的仆人砍了一刀，削掉他的右耳；那仆人名叫马勒古。"},{"start":11,"end":11,"text":"耶稣就对彼得说：「收刀入鞘吧，我父所给我的那杯，我岂可不喝呢？」"},{"start":12,"end":12,"text":"那队兵和千夫长，并犹太人的差役就拿住耶稣，把他捆绑了，"},{"start":13,"end":13,"text":"先带到亚那面前，因为亚那是本年作大祭司该亚法的岳父。"},{"start":14,"end":14,"text":"这该亚法就是从前向犹太人发议论说「一个人替百姓死是有益的」那位。"},{"start":15,"end":15,"text":"西门·彼得跟着耶稣，还有一个门徒跟着。那门徒是大祭司所认识的，他就同耶稣进了大祭司的院子。"},{"start":16,"end":16,"text":"彼得却站在门外。大祭司所认识的那个门徒出来，和看门的使女说了一声，就领彼得进去。"},{"start":17,"end":17,"text":"那看门的使女对彼得说：「你不也是这人的门徒吗？」他说：「我不是。」"},{"start":18,"end":18,"text":"仆人和差役因为天冷，就生了炭火，站在那里烤火；彼得也同他们站着烤火。"},{"start":19,"end":19,"text":"大祭司就以耶稣的门徒和他的教训盘问他。"},{"start":20,"end":20,"text":"耶稣回答说：「我从来是明明地对世人说话。我常在会堂和殿里，就是犹太人聚集的地方教训人；我在暗地里并没有说什么。"},{"start":21,"end":21,"text":"你为什么问我呢？可以问那听见的人，我对他们说的是什么；我所说的，他们都知道。」"},{"start":22,"end":22,"text":"耶稣说了这话，旁边站着的一个差役用手掌打他，说：「你这样回答大祭司吗？」"},{"start":23,"end":23,"text":"耶稣说：「我若说的不是，你可以指证那不是；我若说的是，你为什么打我呢？」"},{"start":24,"end":24,"text":"亚那就把耶稣解到大祭司该亚法那里，仍是捆着解去的。"},{"start":25,"end":25,"text":"西门·彼得正站着烤火，有人对他说：「你不也是他的门徒吗？」彼得不承认，说：「我不是。」"},{"start":26,"end":26,"text":"有大祭司的一个仆人，是彼得削掉耳朵那人的亲属，说：「我不是看见你同他在园子里吗？」"},{"start":27,"end":27,"text":"彼得又不承认。立时鸡就叫了。"},{"start":28,"end":28,"text":"众人将耶稣从该亚法那里往衙门内解去，那时天还早。他们自己却不进衙门，恐怕染了污秽，不能吃逾越[节的筵席]。"},{"start":29,"end":29,"text":"彼拉多就出来，到他们那里，说：「你们告这人是为什么事呢？」"},{"start":30,"end":30,"text":"他们回答说：「这人若不是作恶的，我们就不把他交给你。」"},{"start":31,"end":31,"text":"彼拉多说：「你们自己带他去，按着你们的律法审问他吧。」犹太人说：「我们没有杀人的权柄。」"},{"start":32,"end":32,"text":"这要应验耶稣所说自己将要怎样死的话了。"},{"start":33,"end":33,"text":"彼拉多又进了衙门，叫耶稣来，对他说：「你是犹太人的王吗？」"},{"start":34,"end":34,"text":"耶稣回答说：「这话是你自己说的，还是别人论我对你说的呢？」"},{"start":35,"end":35,"text":"彼拉多说：「我岂是犹太人呢？你本国的人和祭司长把你交给我。你做了什么事呢？」"},{"start":36,"end":36,"text":"耶稣回答说：「我的国不属这世界；我的国若属这世界，我的臣仆必要争战，使我不至于被交给犹太人。只是我的国不属这世界。」"},{"start":37,"end":37,"text":"彼拉多就对他说：「这样，你是王吗？」耶稣回答说：「你说我是王。我为此而生，也为此来到世间，特为给真理作见证。凡属真理的人就听我的话。」"},{"start":38,"end":38,"text":"彼拉多说：「真理是什么呢？」 说了这话，又出来到犹太人那里，对他们说：「我查不出他有什么罪来。"},{"start":39,"end":39,"text":"但你们有个规矩，在逾越节要我给你们释放一个人，你们要我给你们释放犹太人的王吗？」"},{"start":40,"end":40,"text":"他们又喊着说：「不要这人，要巴拉巴！」这巴拉巴是个强盗。"}],"19":[{"start":1,"end":1,"text":"当下彼拉多将耶稣鞭打了。"},{"start":2,"end":2,"text":"兵丁用荆棘编做冠冕戴在他头上，给他穿上紫袍，"},{"start":3,"end":3,"text":"又挨近他，说：「恭喜，犹太人的王啊！」他们就用手掌打他。"},{"start":4,"end":4,"text":"彼拉多又出来对众人说：「我带他出来见你们，叫你们知道我查不出他有什么罪来。」"},{"start":5,"end":5,"text":"耶稣出来，戴着荆棘冠冕，穿着紫袍。[彼拉多]对他们说：「你们看这个人！」"},{"start":6,"end":6,"text":"祭司长和差役看见他，就喊着说：「钉他十字架！钉他十字架！」彼拉多说：「你们自己把他钉十字架吧！我查不出他有什么罪来。」"},{"start":7,"end":7,"text":"犹太人回答说：「我们有律法，按那律法，他是该死的，因他以自己为　神的儿子。」"},{"start":8,"end":8,"text":"彼拉多听见这话，越发害怕，"},{"start":9,"end":9,"text":"又进衙门，对耶稣说：「你是哪里来的？」耶稣却不回答。"},{"start":10,"end":10,"text":"彼拉多说：「你不对我说话吗？你岂不知我有权柄释放你，也有权柄把你钉十字架吗？」"},{"start":11,"end":11,"text":"耶稣回答说：「若不是从上头赐给你的，你就毫无权柄办我。所以，把我交给你的那人罪更重了。」"},{"start":12,"end":12,"text":"从此，彼拉多想要释放耶稣，无奈犹太人喊着说：「你若释放这个人，就不是凯撒的忠臣。凡以自己为王的，就是背叛凯撒了。」"},{"start":13,"end":13,"text":"彼拉多听见这话，就带耶稣出来，到了一个地方，名叫「铺华石处」，希伯来话叫厄巴大，就在那里坐堂。"},{"start":14,"end":14,"text":"那日是预备逾越[节]的日子，约有午正。彼拉多对犹太人说：「看哪，这是你们的王！」"},{"start":15,"end":15,"text":"他们喊着说：「除掉他！除掉他！钉他在十字架上！」彼拉多说：「我可以把你们的王钉十字架吗？」祭司长回答说：「除了凯撒，我们没有王。」"},{"start":16,"end":16,"text":"于是彼拉多将耶稣交给他们去钉十字架。"},{"start":30,"end":30,"text":"耶稣尝了那醋，就说：「成了！」便低下头，将灵魂交付　[神]了。"},{"start":31,"end":31,"text":"犹太人因这日是预备日，又因那安息日是个大日，就求彼拉多叫人打断他们的腿，把他们拿去，免得尸首当安息日留在十字架上。"},{"start":32,"end":32,"text":"于是兵丁来，把头一个人的腿，并与耶稣同钉第二个人的腿，都打断了。"},{"start":33,"end":33,"text":"只是来到耶稣那里，见他已经死了，就不打断他的腿。"},{"start":34,"end":34,"text":"惟有一个兵拿枪扎他的肋旁，随即有血和水流出来。"},{"start":35,"end":35,"text":"看见[这事]的那人就作见证—他的见证也是真的，并且他知道自己所说的是真的—叫你们也可以信。"},{"start":36,"end":36,"text":"这些事成了，为要应验经上的话说：「他的骨头一根也不可折断。」"},{"start":37,"end":37,"text":"经上又有一句说：「他们要仰望自己所扎的人。」"},{"start":38,"end":38,"text":"这些事以后，有亚利马太人约瑟，是耶稣的门徒，只因怕犹太人，就暗暗地作门徒。他来求彼拉多，要把耶稣的身体领去。彼拉多允准，他就把耶稣的身体领去了。"},{"start":39,"end":39,"text":"又有尼哥德慕，就是先前夜里去见耶稣的，带着没药和沉香约有一百斤前来。"},{"start":40,"end":40,"text":"他们就照犹太人殡葬的规矩，把耶稣的身体用细麻布加上香料裹好了。"},{"start":41,"end":41,"text":"在耶稣钉十字架的地方有一个园子，园子里有一座新坟墓，是从来没有葬过人的。"},{"start":42,"end":42,"text":"只因是犹太人的预备日，又因那坟墓近，他们就把耶稣安放在那里。"}],"21":[{"start":1,"end":1,"text":"这些事以后，耶稣在提比哩亚海边又向门徒显现。他怎样显现记在下面："},{"start":2,"end":2,"text":"有西门·彼得和称为低土马的多马，并加利利的迦拿人拿但业，还有西庇太的两个儿子，又有两个门徒，都在一处。"},{"start":3,"end":3,"text":"西门·彼得对他们说：「我打鱼去。」他们说：「我们也和你同去。」他们就出去，上了船；那一夜并没有打着什么。"},{"start":4,"end":4,"text":"天将亮的时候，耶稣站在岸上，门徒却不知道是耶稣。"},{"start":5,"end":5,"text":"耶稣就对他们说：「小子！你们有吃的没有？」他们回答说：「没有。」"},{"start":6,"end":6,"text":"耶稣说：「你们把网撒在船的右边，就必得着。」他们便撒下网去，竟拉不上来了，因为鱼甚多。"},{"start":7,"end":7,"text":"耶稣所爱的那门徒对彼得说：「是主！」那时西门·彼得赤着身子，一听见是主，就束上一件外衣，跳在海里。"},{"start":8,"end":8,"text":"其余的门徒离岸不远，约有二百肘，就在小船上把那网鱼拉过来。"},{"start":9,"end":9,"text":"他们上了岸，就看见那里有炭火，上面有鱼，又有饼。"},{"start":10,"end":10,"text":"耶稣对他们说：「把刚才打的鱼拿几条来。」"},{"start":11,"end":11,"text":"西门·彼得就去，把网拉到岸上。那网满了大鱼，共一百五十三条；鱼虽这样多，网却没有破。"},{"start":12,"end":12,"text":"耶稣说：「你们来吃早饭。」门徒中没有一个敢问他：「你是谁？」因为知道是主。"},{"start":13,"end":13,"text":"耶稣就来拿饼和鱼给他们。"},{"start":14,"end":14,"text":"耶稣从死里复活以后，向门徒显现，这是第三次。"},{"start":15,"end":15,"text":"他们吃完了早饭，耶稣对西门·彼得说：「约翰的儿子西门，你爱我比这些更深吗？」彼得说：「主啊，是的，你知道我爱你。」耶稣对他说：「你喂养我的小羊。」"},{"start":16,"end":16,"text":"耶稣第二次又对他说：「约翰的儿子西门，你爱我吗？」彼得说：「主啊，是的，你知道我爱你。」耶稣说：「你牧养我的羊。」"},{"start":17,"end":17,"text":"第三次对他说：「约翰的儿子西门，你爱我吗？」彼得因为耶稣第三次对他说「你爱我吗」，就忧愁，对耶稣说：「主啊，你是无所不知的；你知道我爱你。」耶稣说：「你喂养我的羊。"},{"start":18,"end":18,"text":"我实实在在地告诉你，你年少的时候，自己束上[带子]，随意往来；但年老的时候，你要伸出手来，别人要把你束上，带你到不愿意去的地方。」"},{"start":19,"end":19,"text":"（耶稣说这话是指着彼得要怎样死，荣耀　神。）说了这话，就对他说：「你跟从我吧！」"}]},"EXO":{"3":[{"start":1,"end":1,"text":"摩西牧养他岳父米甸祭司叶忒罗的羊群；一日领羊群往野外去，到了　神的山，就是何烈山。"},{"start":2,"end":2,"text":"耶和华的使者从荆棘里火焰中向摩西显现。摩西观看，不料，荆棘被火烧着，却没有烧毁。"},{"start":3,"end":3,"text":"摩西说：「我要过去看这大异象，这荆棘为何没有烧坏呢？」"},{"start":4,"end":4,"text":"耶和华　神见他过去要看，就从荆棘里呼叫说：「摩西！摩西！」他说：「我在这里。」"},{"start":5,"end":5,"text":"神说：「不要近前来。当把你脚上的鞋脱下来，因为你所站之地是圣地」；"},{"start":6,"end":6,"text":"又说：「我是你父亲的　神，是亚伯拉罕的　神，以撒的　神，雅各的　神。」摩西蒙上脸，因为怕看　神。"},{"start":7,"end":7,"text":"耶和华说：「我的百姓在埃及所受的困苦，我实在看见了；他们因受督工的辖制所发的哀声，我也听见了。我原知道他们的痛苦，"},{"start":8,"end":8,"text":"我下来是要救他们脱离埃及人的手，领他们出了那地，到美好、宽阔、流奶与蜜之地，就是到迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人之地。"},{"start":9,"end":9,"text":"现在以色列人的哀声达到我耳中，我也看见埃及人怎样欺压他们。"},{"start":10,"end":10,"text":"故此，我要打发你去见法老，使你可以将我的百姓以色列人从埃及领出来。」"},{"start":11,"end":11,"text":"摩西对　神说：「我是什么人，竟能去见法老，将以色列人从埃及领出来呢？」"},{"start":12,"end":12,"text":"神说：「我必与你同在。你将百姓从埃及领出来之后，你们必在这山上事奉我；这就是我打发你去的证据。」"},{"start":13,"end":13,"text":"摩西对　神说：「我到以色列人那里，对他们说：『你们祖宗的　神打发我到你们这里来。』他们若问我说：『他叫什么名字？』我要对他们说什么呢？」"},{"start":14,"end":14,"text":"神对摩西说：「我是自有永有的」；又说：「你要对以色列人这样说：『那自有的打发我到你们这里来。』」"},{"start":15,"end":15,"text":"神又对摩西说：「你要对以色列人这样说：『耶和华—你们祖宗的　神，就是亚伯拉罕的　神，以撒的　神，雅各的　神，打发我到你们这里来。』耶和华是我的名，直到永远；这也是我的纪念，直到万代。"},{"start":16,"end":16,"text":"你去招聚以色列的长老，对他们说：『耶和华—你们祖宗的　神，就是亚伯拉罕的　神，以撒的　神，雅各的　神，向我显现，说：我实在眷顾了你们，我也[看见]埃及人怎样待你们。"},{"start":17,"end":17,"text":"我也说：要将你们从埃及的困苦中领出来，往迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶与蜜之地。』"},{"start":18,"end":18,"text":"他们必听你的话。你和以色列的长老要去见埃及王，对他说：『耶和华—希伯来人的　神遇见了我们，现在求你容我们往旷野去，走三天的路程，为要祭祀耶和华—我们的　神。』"},{"start":19,"end":19,"text":"我知道虽用大能的手，埃及王也不容你们去。"},{"start":20,"end":20,"text":"我必伸手在埃及中间施行我一切的奇事，攻击那地，然后他才容你们去。"},{"start":21,"end":21,"text":"我必叫你们在埃及人眼前蒙恩，你们去的时候就不至于空手而去。"},{"start":22,"end":22,"text":"但各妇女必向她的邻舍，并居住在她家里的女人，要金器银器和衣裳，好给你们的儿女穿戴。这样你们就把埃及人的[财物]夺去了。」"}],"8":[{"start":7,"end":7,"text":"行法术的也用他们的邪术照样而行，叫青蛙上了埃及地。"},{"start":8,"end":8,"text":"法老召了摩西、亚伦来，说：「请你们求耶和华使这青蛙离开我和我的民，我就容百姓去祭祀耶和华。」"},{"start":9,"end":9,"text":"摩西对法老说：「任凭你吧，我要何时为你和你的臣仆并你的百姓祈求，除灭青蛙离开你和你的宫殿只留在河里呢？」"}],"12":[{"start":1,"end":1,"text":"耶和华在埃及地晓谕摩西、亚伦说："},{"start":2,"end":2,"text":"「你们要以本月为正月，为一年之首。"},{"start":3,"end":3,"text":"你们吩咐以色列全会众说：本月初十日，各人要按着父家取羊羔，一家一只。"},{"start":4,"end":4,"text":"若是一家的人太少，吃不了一只羊羔，本人就要和他隔壁的邻舍共取一只。你们预备羊羔，要按着人数和饭量计算。"},{"start":5,"end":5,"text":"要无残疾、一岁的公羊羔，你们或从绵羊里取，或从山羊里取，都可以。"},{"start":6,"end":6,"text":"要留到本月十四日，在黄昏的时候，以色列全会众把羊羔宰了。"},{"start":7,"end":7,"text":"各家要取点血，涂在吃羊羔的房屋左右的门框上和门楣上。"},{"start":8,"end":8,"text":"当夜要吃羊羔的肉；用火烤了，与无酵饼和苦菜同吃。"},{"start":9,"end":9,"text":"不可吃生的，断不可吃水煮的，要带着头、腿、五脏，用火烤了吃。"},{"start":10,"end":10,"text":"不可剩下一点留到早晨；若留到早晨，要用火烧了。"},{"start":11,"end":11,"text":"你们吃羊羔当腰间束带，脚上穿鞋，手中拿杖，赶紧地吃；这是耶和华的逾越节。"},{"start":12,"end":12,"text":"因为那夜我要巡行埃及地，把埃及地一切头生的，无论是人是牲畜，都击杀了，又要败坏埃及一切的神。我是耶和华。"},{"start":13,"end":13,"text":"这血要在你们所住的房屋上作记号；我一见这血，就越过你们去。我击杀埃及地[头生]的时候，灾殃必不临到你们身上灭你们。」"},{"start":14,"end":14,"text":"「你们要记念这日，守为耶和华的节，作为你们世世代代永远的定例。"},{"start":15,"end":15,"text":"你们要吃无酵饼七日。头一日要把酵从你们各家中除去；因为从头一日起，到第七日为止，凡吃有酵之饼的，必从以色列中剪除。"},{"start":16,"end":16,"text":"头一日你们当有圣会，第七日也当有圣会。这两日之内，除了预备各人所要吃的以外，无论何工都不可做。"},{"start":17,"end":17,"text":"你们要守无酵节，因为我正当这日把你们的军队从埃及地领出来。所以，你们要守这日，作为世世代代永远的定例。"},{"start":18,"end":18,"text":"从正月十四日晚上，直到二十一日晚上，你们要吃无酵饼。"},{"start":19,"end":19,"text":"在你们各家中，七日之内不可有酵；因为凡吃有酵之物的，无论是寄居的，是本地的，必从以色列的会中剪除。"},{"start":20,"end":20,"text":"有酵的物，你们都不可吃；在你们一切住处要吃无酵饼。」"},{"start":21,"end":21,"text":"于是，摩西召了以色列的众长老来，对他们说：「你们要按着家口取出羊羔，把这逾越节[的羊羔]宰了。"},{"start":22,"end":22,"text":"拿一把牛膝草，蘸盆里的血，打在门楣上和左右的门框上。你们谁也不可出自己的房门，直到早晨。"},{"start":23,"end":23,"text":"因为耶和华要巡行击杀埃及人，他看见血在门楣上和左右的门框上，就必越过那门，不容灭命的进你们的房屋，击杀你们。"},{"start":24,"end":24,"text":"这例，你们要守着，作为你们和你们子孙永远的定例。"},{"start":25,"end":25,"text":"日后，你们到了耶和华按着所应许赐给你们的那地，就要守这礼。"},{"start":26,"end":26,"text":"你们的儿女问你们说：『行这礼是什么意思？』"},{"start":27,"end":27,"text":"你们就说：『这是献给耶和华逾越节的祭。当以色列人在埃及的时候，他击杀埃及人，越过以色列人的房屋，救了我们各家。』」于是百姓低头下拜。"},{"start":28,"end":28,"text":"耶和华怎样吩咐摩西、亚伦，以色列人就怎样行。"},{"start":29,"end":29,"text":"到了半夜，耶和华把埃及地所有的长子，就是从坐宝座的法老，直到被掳囚在监里之人的长子，以及一切头生的牲畜，尽都杀了。"},{"start":30,"end":30,"text":"法老和一切臣仆，并埃及众人，夜间都起来了。在埃及有大哀号，无一家不死一个人的。"},{"start":31,"end":31,"text":"夜间，法老召了摩西、亚伦来，说：「起来！连你们带以色列人，从我民中出去，依你们所说的，去事奉耶和华吧！"},{"start":32,"end":32,"text":"也依你们所说的，连羊群牛群带着走吧！并要为我祝福。」"},{"start":33,"end":33,"text":"埃及人催促百姓，打发他们快快出离那地，因为埃及人说：「我们都要死了。」"},{"start":34,"end":34,"text":"百姓就拿着没有酵的生面，把抟面盆包在衣服中，扛在肩头上。"},{"start":35,"end":35,"text":"以色列人照着摩西的话行，向埃及人要金器、银器，和衣裳。"},{"start":36,"end":36,"text":"耶和华叫百姓在埃及人眼前蒙恩，以致埃及人给他们所要的。他们就把埃及人的[财物]夺去了。"},{"start":37,"end":37,"text":"以色列人从兰塞起行，往疏割去；除了[妇人]孩子，步行的男人约有六十万。"},{"start":38,"end":38,"text":"又有许多闲杂人，并有羊群牛群，和他们一同上去。"},{"start":39,"end":39,"text":"他们用埃及带出来的生面烤成无酵饼。这生面原没有发起；因为他们被催逼离开埃及，不能耽延，也没有为自己预备什么食物。"},{"start":40,"end":40,"text":"以色列人住在埃及共有四百三十年。"},{"start":41,"end":41,"text":"正满了四百三十年的那一天，耶和华的军队都从埃及地出来了。"},{"start":42,"end":42,"text":"这夜是耶和华的夜；因耶和华领他们出了埃及地，所以当向耶和华谨守，是以色列众人世世代代该谨守的。"},{"start":43,"end":43,"text":"耶和华对摩西、亚伦说：「逾越节的例是这样：外邦人都不可吃这羊羔。"},{"start":44,"end":44,"text":"但各人用银子买的奴仆，既受了割礼就可以吃。"},{"start":45,"end":45,"text":"寄居的和雇工人都不可吃。"},{"start":46,"end":46,"text":"应当在一个房子里吃；不可把一点肉从房子里带到外头去。羊羔的骨头一根也不可折断。"},{"start":47,"end":47,"text":"以色列全会众都要守这礼。"},{"start":48,"end":48,"text":"若有外人寄居在你们中间，愿向耶和华守逾越节，他所有的男子务要受割礼，然后才容他前来遵守，他也就像本地人一样；但未受割礼的，都不可吃这羊羔。"},{"start":49,"end":49,"text":"本地人和寄居在你们中间的外人同归一例。」"},{"start":50,"end":50,"text":"耶和华怎样吩咐摩西、亚伦，以色列众人就怎样行了。"},{"start":51,"end":51,"text":"正当那日，耶和华将以色列人按着他们的军队，从埃及地领出来。"}],"13":[{"start":1,"end":1,"text":"耶和华晓谕摩西说："},{"start":2,"end":2,"text":"「以色列中凡头生的，无论是人是牲畜，都是我的，要分别为圣归我。」"}],"16":[{"start":1,"end":1,"text":"以色列全会众从以琳起行，在出埃及后第二个月十五日到了以琳和西奈中间、汛的旷野。"},{"start":2,"end":2,"text":"以色列全会众在旷野向摩西、亚伦发怨言，"},{"start":3,"end":3,"text":"说：「巴不得我们早死在埃及地、耶和华的手下；那时我们坐在肉锅旁边，吃得饱足。你们将我们领出来，到这旷野，是要叫这全会众都饿死啊！」"},{"start":4,"end":4,"text":"耶和华对摩西说：「我要将粮食从天降给你们。百姓可以出去，每天收每天的分，我好试验他们遵不遵我的法度。"},{"start":5,"end":5,"text":"到第六天，他们要把所收进来的预备好了，比每天所收的多一倍。」"},{"start":6,"end":6,"text":"摩西、亚伦对以色列众人说：「到了晚上，你们要知道是耶和华将你们从埃及地领出来的。"},{"start":7,"end":7,"text":"早晨，你们要看见耶和华的荣耀，因为耶和华听见你们向他所发的怨言了。我们算什么，你们竟向我们发怨言呢？」"},{"start":8,"end":8,"text":"摩西又说：「耶和华晚上必给你们肉吃，早晨必给你们食物得饱；因为你们向耶和华发的怨言，他都听见了。我们算什么，你们的怨言不是向我们发的，乃是向耶和华发的。」"},{"start":9,"end":9,"text":"摩西对亚伦说：「你告诉以色列全会众说：『你们就近耶和华面前，因为他已经听见你们的怨言了。』」"},{"start":10,"end":10,"text":"亚伦正对以色列全会众说话的时候，他们向旷野观看，不料，耶和华的荣光在云中显现。"},{"start":11,"end":11,"text":"耶和华晓谕摩西说："},{"start":12,"end":12,"text":"「我已经听见以色列人的怨言。你告诉他们说：『到黄昏的时候，你们要吃肉，早晨必有食物得饱，你们就知道我是耶和华—你们的　神。』」"},{"start":13,"end":13,"text":"到了晚上，有鹌鹑飞来，遮满了营；早晨在营四围的地上有露水。"},{"start":14,"end":14,"text":"露水上升之后，不料，野地面上有如白霜的小圆物。"},{"start":15,"end":15,"text":"以色列人看见，不知道是什么，就彼此对问说：「这是什么呢？」摩西对他们说：「这就是耶和华给你们吃的食物。"},{"start":16,"end":16,"text":"耶和华所吩咐的是这样：你们要按着各人的饭量，为帐棚里的人，按着人数收起来，各拿一俄梅珥。」"},{"start":17,"end":17,"text":"以色列人就这样行；有多收的，有少收的。"},{"start":18,"end":18,"text":"及至用俄梅珥量一量，多收的也没有余，少收的也没有缺；各人按着自己的饭量收取。"},{"start":19,"end":19,"text":"摩西对他们说：「所收的，不许什么人留到早晨。」"},{"start":20,"end":20,"text":"然而他们不听摩西的话，内中有留到早晨的，就生虫变臭了；摩西便向他们发怒。"},{"start":21,"end":21,"text":"他们每日早晨，按着各人的饭量收取，日头一发热，就消化了。"},{"start":22,"end":22,"text":"到第六天，他们收了双倍的食物，每人两俄梅珥。会众的官长来告诉摩西；"},{"start":23,"end":23,"text":"摩西对他们说：「耶和华这样说：『明天是圣安息日，是向耶和华守的圣安息日。你们要烤的就烤了，要煮的就煮了，所剩下的都留到早晨。』」"},{"start":24,"end":24,"text":"他们就照摩西的吩咐留到早晨，也不臭，里头也没有虫子。"},{"start":25,"end":25,"text":"摩西说：「你们今天吃这个吧！因为今天是向耶和华守的安息日；你们在田野必找不着了。"},{"start":26,"end":26,"text":"六天可以收取，第七天乃是安息日，那一天必没有了。」"},{"start":27,"end":27,"text":"第七天，百姓中有人出去收，什么也找不着。"},{"start":28,"end":28,"text":"耶和华对摩西说：「你们不肯守我的诫命和律法，要到几时呢？"},{"start":29,"end":29,"text":"你们看！耶和华既将安息日赐给你们，所以第六天他赐给你们两天的食物，第七天各人要住在自己的地方，不许什么人出去。」"},{"start":30,"end":30,"text":"于是百姓第七天安息了。"},{"start":31,"end":31,"text":"这食物，以色列家叫吗哪；样子像芫荽子，颜色是白的，滋味如同搀蜜的薄饼。"},{"start":32,"end":32,"text":"摩西说：「耶和华所吩咐的是这样：『要将一满俄梅珥吗哪留到世世代代，使后人可以看见我当日将你们领出埃及地，在旷野所给你们吃的食物。』」"},{"start":33,"end":33,"text":"摩西对亚伦说：「你拿一个罐子，盛一满俄梅珥吗哪，存在耶和华面前，要留到世世代代。」"},{"start":34,"end":34,"text":"耶和华怎么吩咐摩西，亚伦就怎么行，把吗哪放在法[柜]前存留。"},{"start":35,"end":35,"text":"以色列人吃吗哪共四十年，直到进了有人居住之地，就是迦南的境界。（"},{"start":36,"end":36,"text":"俄梅珥就是伊法十分之一。）"}],"20":[{"start":1,"end":1,"text":"神吩咐这一切的话说："},{"start":2,"end":2,"text":"「我是耶和华—你的　神，曾将你从埃及地为奴之家领出来。"},{"start":3,"end":3,"text":"「除了我以外，你不可有别的神。"},{"start":4,"end":4,"text":"「不可为自己雕刻偶像，也不可做什么形象仿佛上天、下地，和地底下、水中的[百物]。"},{"start":5,"end":5,"text":"不可跪拜那些像，也不可事奉它，因为我耶和华—你的　神是忌邪的　神。恨我的，我必追讨他的罪，自父及子，直到三四代；"},{"start":6,"end":6,"text":"爱我、守我诫命的，我必向他们发慈爱，直到千代。"},{"start":7,"end":7,"text":"「不可妄称耶和华—你　神的名；因为妄称耶和华名的，耶和华必不以他为无罪。"},{"start":8,"end":8,"text":"「当记念安息日，守为圣日。"},{"start":9,"end":9,"text":"六日要劳碌做你一切的工，"},{"start":10,"end":10,"text":"但第七日是向耶和华—你　神当守的安息日。[这一日]你和你的儿女、仆婢、牲畜，并你城里寄居的客旅，无论何工都不可做；"},{"start":11,"end":11,"text":"因为六日之内，耶和华造天、地、海，和其中的万物，第七日便安息，所以耶和华赐福与安息日，定为圣日。"},{"start":12,"end":12,"text":"「当孝敬父母，使你的日子在耶和华—你　神所赐你的地上得以长久。"},{"start":13,"end":13,"text":"「不可杀人。"},{"start":14,"end":14,"text":"「不可奸淫。"},{"start":15,"end":15,"text":"「不可偷盗。"},{"start":16,"end":16,"text":"「不可作假见证陷害人。"},{"start":17,"end":17,"text":"「不可贪恋人的房屋；也不可贪恋人的妻子、仆婢、牛驴，并他一切所有的。」"}],"22":[{"start":1,"end":1,"text":"「人若偷牛或羊，无论是宰了，是卖了，他就要以五牛赔一牛，四羊赔一羊。"},{"start":2,"end":2,"text":"人若遇见贼挖窟窿，把贼打了，以至于死，就不能为他有流血的罪。"},{"start":3,"end":3,"text":"若太阳已经出来，就为他有流血的罪。贼若被拿，总要赔还。若他一无所有，就要被卖，顶他所偷的物。"},{"start":4,"end":4,"text":"若他所偷的，或牛，或驴，或羊，仍在他手下存活，他就要加倍赔还。"}],"23":[{"start":4,"end":4,"text":"「若遇见你仇敌的牛或驴失迷了路，总要牵回来交给他。"},{"start":5,"end":5,"text":"若看见恨你人的驴压卧在重驮之下，不可走开，务要和驴主一同抬开[重驮]。"},{"start":20,"end":20,"text":"「看哪，我差遣使者在你前面，在路上保护你，领你到我所预备的地方去。"},{"start":21,"end":21,"text":"他是奉我名来的；你们要在他面前谨慎，听从他的话，不可惹他，因为他必不赦免你们的过犯。"},{"start":22,"end":22,"text":"「你若实在听从他的话，照着我一切所说的去行，我就向你的仇敌作仇敌，向你的敌人作敌人。"},{"start":23,"end":23,"text":"「我的使者要在你前面行，领你到亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里去，我必将他们剪除。"},{"start":24,"end":24,"text":"你不可跪拜他们的神，不可事奉他，也不可效法他们的行为，却要把神像尽行拆毁，打碎他们的柱像。"},{"start":25,"end":25,"text":"你们要事奉耶和华—你们的　神，他必赐福与你的粮与你的水，也必从你们中间除去疾病。"},{"start":26,"end":26,"text":"你境内必没有坠胎的，不生产的。我要使你满了你年日的数目。"},{"start":27,"end":27,"text":"凡你所到的地方，我要使那里的众民在你面前惊骇，扰乱，又要使你一切仇敌转背[逃跑]。"},{"start":28,"end":28,"text":"我要打发黄蜂飞在你前面，把希未人、迦南人、赫人撵出去。"},{"start":29,"end":29,"text":"我不在一年之内将他们从你面前撵出去，恐怕地成为荒凉，野地的兽多起来害你。"},{"start":30,"end":30,"text":"我要渐渐地将他们从你面前撵出去，等到你的人数加多，承受那地为业。"},{"start":31,"end":31,"text":"我要定你的境界，从红海直到非利士海，又从旷野直到大河。我要将那地的居民交在你手中，你要将他们从你面前撵出去。"},{"start":32,"end":32,"text":"不可和他们并他们的神立约。"},{"start":33,"end":33,"text":"他们不可住在你的地上，恐怕他们使你得罪我。你若事奉他们的神，这必成为你的网罗。」"}],"24":[{"start":3,"end":3,"text":"摩西下山，将耶和华的命令典章都述说与百姓听。众百姓齐声说：「耶和华所吩咐的，我们都必遵行。」"},{"start":4,"end":4,"text":"摩西将耶和华的命令都写上。清早起来，在山下筑一座坛，按以色列十二支派立十二根柱子，"},{"start":5,"end":5,"text":"又打发以色列人中的少年人去献燔祭，又向耶和华献牛为平安祭。"},{"start":6,"end":6,"text":"摩西将血一半盛在盆中，一半洒在坛上；"},{"start":7,"end":7,"text":"又将约书念给百姓听。他们说：「耶和华所吩咐的，我们都必遵行。」"},{"start":8,"end":8,"text":"摩西将血洒在百姓身上，说：「你看！这是立约的血，是耶和华按这一切话与你们立约[的凭据]。」"},{"start":9,"end":9,"text":"摩西、亚伦、拿答、亚比户，并以色列长老中的七十人，都上了山。"},{"start":10,"end":10,"text":"他们看见以色列的　神，他脚下仿佛有平铺的蓝宝石，如同天色明净。"},{"start":11,"end":11,"text":"他的手不加害在以色列的尊者身上。他们观看　神；他们又吃又喝。"},{"start":12,"end":12,"text":"耶和华对摩西说：「你上山到我这里来，住在这里，我要将石版并我所写的律法和诫命赐给你，使你可以教训百姓。」"},{"start":13,"end":13,"text":"摩西和他的帮手约书亚起来，上了　神的山。"},{"start":14,"end":14,"text":"摩西对长老说：「你们在这里等着，等到我们再回来，有亚伦、户珥与你们同在。凡有争讼的，都可以就近他们去。」"},{"start":15,"end":15,"text":"摩西上山，有云彩把山遮盖。"},{"start":16,"end":16,"text":"耶和华的荣耀停于西奈山；云彩遮盖山六天，第七天他从云中召摩西。"},{"start":17,"end":17,"text":"耶和华的荣耀在山顶上，在以色列人眼前，形状如烈火。"},{"start":18,"end":18,"text":"摩西进入云中上山，在山上四十昼夜。"}],"26":[{"start":31,"end":31,"text":"「你要用蓝色、紫色、朱红色[线]，和捻的细麻织幔子，以巧匠的手工绣上基路伯。"},{"start":32,"end":32,"text":"要把幔子挂在四根包金的皂荚木柱子上，柱子上当有金钩，柱子安在四个带卯的银座上。"},{"start":33,"end":33,"text":"要使幔子垂在钩子下，把法柜抬进幔子内；这幔子要将圣所和至圣所隔开。"}],"34":[{"start":6,"end":6,"text":"耶和华在他面前宣告[说]：「耶和华，耶和华，是有怜悯有恩典的　神，不轻易发怒，并有丰盛的慈爱和诚实，"},{"start":7,"end":7,"text":"为千万人存留慈爱，赦免罪孽、过犯，和罪恶，万不以[有罪的]为无罪，必追讨他的罪，自父及子，直到三、四代。」"}]},"LEV":{"6":[{"start":1,"end":1,"text":"耶和华晓谕摩西说："},{"start":2,"end":2,"text":"「若有人犯罪，干犯耶和华，在邻舍交付他的物上，或是在交易上行了诡诈，或是抢夺人的财物，或是欺压邻舍，"},{"start":3,"end":3,"text":"或是在捡了遗失的物上行了诡诈，说谎起誓，在这一切的事上犯了什么罪；"},{"start":4,"end":4,"text":"他既犯了罪，有了过犯，就要归还他所抢夺的，或是因欺压所得的，或是人交付他的，或是人遗失他所捡的物，"},{"start":5,"end":5,"text":"或是他因什么物起了假誓，就要如数归还，另外加上五分之一，在查出他有罪的日子要交还本主。"}],"12":[{"start":1,"end":1,"text":"耶和华对摩西说："},{"start":2,"end":2,"text":"「你晓谕以色列人说：若有妇人怀孕生男孩，她就不洁净七天，像在月经污秽的日子不洁净一样。"},{"start":3,"end":3,"text":"第八天，要给婴孩行割礼。"},{"start":4,"end":4,"text":"妇人在产血不洁之中，要家居三十三天。她洁净的日子未满，不可摸圣物，也不可进入圣所。"},{"start":5,"end":5,"text":"她若生女孩，就不洁净两个七天，像污秽[的时候]一样，要在产血不洁之中，家居六十六天。"},{"start":6,"end":6,"text":"「满了洁净的日子，无论是为男孩是为女孩，她要把一岁的羊羔为燔祭，一只雏鸽或是一只斑鸠为赎罪祭，带到会幕门口交给祭司。"},{"start":7,"end":7,"text":"祭司要献在耶和华面前，为她赎罪，她的血源就洁净了。这条例是为生育的妇人，无论是生男生女。"},{"start":8,"end":8,"text":"她的力量若不够献一只羊羔，她就要取两只斑鸠或是两只雏鸽，一只为燔祭，一只为赎罪祭。祭司要为她赎罪，她就洁净了。」"}],"13":[{"start":1,"end":1,"text":"耶和华晓谕摩西、亚伦说："},{"start":2,"end":2,"text":"「人的肉皮上若长了疖子，或长了癣，或长了火斑，在他肉皮上成了大麻风的灾病，就要将他带到祭司亚伦或亚伦作祭司的一个子孙面前。"},{"start":3,"end":3,"text":"祭司要察看肉皮上的灾病，若灾病处的毛已经变白，灾病的现象深于肉上的皮，这便是大麻风的灾病。祭司要察看他，定他为不洁净。"},{"start":4,"end":4,"text":"若火斑在他肉皮上是白的，现象不深于皮，其上的毛也没有变白，祭司就要将有灾病的人关锁七天。"},{"start":5,"end":5,"text":"第七天，祭司要察看他，若看灾病止住了，没有在皮上发散，祭司还要将他关锁七天。"},{"start":6,"end":6,"text":"第七天，祭司要再察看他，若灾病发暗，而且没有在皮上发散，祭司要定他为洁净，原来是癣；那人就要洗衣服，得为洁净。"},{"start":7,"end":7,"text":"但他为得洁净，将身体给祭司察看以后，癣若在皮上发散开了，他要再将身体给祭司察看。"},{"start":8,"end":8,"text":"祭司要察看，癣若在皮上发散，就要定他为不洁净，是大麻风。"},{"start":9,"end":9,"text":"「人有了大麻风的灾病，就要将他带到祭司面前。"},{"start":10,"end":10,"text":"祭司要察看，皮上若长了白疖，使毛变白，在长白疖之处有了红瘀肉，"},{"start":11,"end":11,"text":"这是肉皮上的旧大麻风，祭司要定他为不洁净，不用将他关锁，因为他是不洁净了。"},{"start":12,"end":12,"text":"大麻风若在皮上四外发散，长满了患灾病人的皮，据祭司察看，从头到脚无处不有，"},{"start":13,"end":13,"text":"祭司就要察看，全身的肉若长满了大麻风，就要定那患灾病的为洁净；全身都变为白，他乃洁净了。"},{"start":14,"end":14,"text":"但红肉几时显在他的身上就几时不洁净。"},{"start":15,"end":15,"text":"祭司一看那红肉就定他为不洁净。红肉本是不洁净，是大麻风。"},{"start":16,"end":16,"text":"红肉若复原，又变白了，他就要来见祭司。"},{"start":17,"end":17,"text":"祭司要察看，灾病处若变白了，祭司就要定那患灾病的为洁净，他乃洁净了。"},{"start":18,"end":18,"text":"「人若在皮肉上长疮，却治好了，"},{"start":19,"end":19,"text":"在长疮之处又起了白疖，或是白中带红的火斑，就要给祭司察看。"},{"start":20,"end":20,"text":"祭司要察看，若现象洼于皮，其上的毛也变白了，就要定他为不洁净，是大麻风的灾病发在疮中。"},{"start":21,"end":21,"text":"祭司若察看，其上没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。"},{"start":22,"end":22,"text":"若在皮上发散开了，祭司就要定他为不洁净，是灾病。"},{"start":23,"end":23,"text":"火斑若在原处止住，没有发散，便是疮的痕迹，祭司就要定他为洁净。"},{"start":24,"end":24,"text":"「人的皮肉上若起了火毒，火毒的瘀[肉]成了火斑，或是白中带红的，或是全白的，"},{"start":25,"end":25,"text":"祭司就要察看，火斑中的毛若变白了，现象又深于皮，是大麻风在火毒中发出，就要定他为不洁净，是大麻风的灾病。"},{"start":26,"end":26,"text":"但是祭司察看，在火斑中若没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。"},{"start":27,"end":27,"text":"到第七天，祭司要察看他，火斑若在皮上发散开了，就要定他为不洁净，是大麻风的灾病。"},{"start":28,"end":28,"text":"火斑若在原处止住，没有在皮上发散，乃是发暗，是起的火毒，祭司要定他为洁净，不过是火毒的痕迹。"},{"start":29,"end":29,"text":"「无论男女，若在头上有灾病，或是男人胡须上有灾病，"},{"start":30,"end":30,"text":"祭司就要察看；这灾病现象若深于皮，其间有细黄毛，就要定他为不洁净，这是头疥，是头上或是胡须上的大麻风。"},{"start":31,"end":31,"text":"祭司若察看头疥的灾病，现象不深于皮，其间也没有黑毛，就要将长头疥灾病的关锁七天。"},{"start":32,"end":32,"text":"第七天，祭司要察看灾病，若头疥没有发散，其间也没有黄毛，头疥的现象不深于皮，"},{"start":33,"end":33,"text":"那人就要剃去须发，但他不可剃头疥之处。祭司要将那长头疥的，再关锁七天。"},{"start":34,"end":34,"text":"第七天，祭司要察看头疥，头疥若没有在皮上发散，现象也不深于皮，就要定他为洁净，他要洗衣服，便成为洁净。"},{"start":35,"end":35,"text":"但他得洁净以后，头疥若在皮上发散开了，"},{"start":36,"end":36,"text":"祭司就要察看他。头疥若在皮上发散，就不必找那黄毛，他是不洁净了。"},{"start":37,"end":37,"text":"祭司若看头疥已经止住，其间也长了黑毛，头疥已然痊愈，那人是洁净了，就要定他为洁净。"},{"start":38,"end":38,"text":"「无论男女，皮肉上若起了火斑，就是白火斑，"},{"start":39,"end":39,"text":"祭司就要察看，他们肉皮上的火斑若白中带黑，这是皮上发出的白癣，那人是洁净了。"},{"start":40,"end":40,"text":"「人头上的发若掉了，他不过是头秃，还是洁净。"},{"start":41,"end":41,"text":"他顶前若掉了头发，他不过是顶门秃，还是洁净。"},{"start":42,"end":42,"text":"头秃处或是顶门秃处若有白中带红的灾病，这就是大麻风发在他头秃处或是顶门秃处，"},{"start":43,"end":43,"text":"祭司就要察看，他起的那灾病若在头秃处或是顶门秃处有白中带红的，像肉皮上大麻风的现象，"},{"start":44,"end":44,"text":"那人就是长大麻风，不洁净的，祭司总要定他为不洁净，他的灾病是在头上。"},{"start":45,"end":45,"text":"「身上有长大麻风灾病的，他的衣服要撕裂，也要蓬头散发，蒙着上唇，喊叫说：『不洁净了！不洁净了！』"},{"start":46,"end":46,"text":"灾病在他身上的日子，他便是不洁净；他既是不洁净，就要独居营外。」"},{"start":47,"end":47,"text":"「染了大麻风灾病的衣服，无论是羊毛衣服、是麻布衣服，"},{"start":48,"end":48,"text":"无论是在经上、在纬上，是麻布的、是羊毛的，是在皮子上，或在皮子做的什么物件上，"},{"start":49,"end":49,"text":"或在衣服上、皮子上，经上、纬上，或在皮子做的什么物件上，这灾病若是发绿，或是发红，是大麻风的灾病，要给祭司察看。"},{"start":50,"end":50,"text":"祭司就要察看那灾病，把染了灾病的物件关锁七天。"},{"start":51,"end":51,"text":"第七天，他要察看那灾病，灾病或在衣服上，经上、纬上，皮子上，若发散，这皮子无论当作何用，这灾病是蚕食的大麻风，都是不洁净了。"},{"start":52,"end":52,"text":"那染了灾病的衣服，或是经上、纬上，羊毛上，麻衣上，或是皮子做的什么物件上，他都要焚烧；因为这是蚕食的大麻风，必在火中焚烧。"},{"start":53,"end":53,"text":"「祭司要察看，若灾病在衣服上，经上、纬上，或是皮子做的什么物件上，没有发散，"},{"start":54,"end":54,"text":"祭司就要吩咐他们，把染了灾病的物件洗了，再关锁七天。"},{"start":55,"end":55,"text":"洗过以后，祭司要察看，那物件若没有变色，灾病也没有消散，那物件就不洁净，是透重的灾病，无论正面反面，都要在火中焚烧。"},{"start":56,"end":56,"text":"洗过以后，祭司要察看，若见那灾病发暗，他就要把那灾病从衣服上，皮子上，经上、纬上，都撕去。"},{"start":57,"end":57,"text":"若仍现在衣服上，或是经上、纬上、皮子做的什么物件上，这就是灾病又发了，必用火焚烧那染灾病的物件。"},{"start":58,"end":58,"text":"所洗的衣服，或是经，或是纬，或是皮子做的什么物件，若灾病离开了，要再洗，就洁净了。」"},{"start":59,"end":59,"text":"这就是大麻风灾病的条例，无论是在羊毛衣服上，麻布衣服上，经上、纬上，和皮子做的什么物件上，可以定为洁净或是不洁净。"}],"15":[{"start":1,"end":1,"text":"耶和华对摩西、亚伦说："},{"start":2,"end":2,"text":"「你们晓谕以色列人说：人若身患漏症，他因这漏症就不洁净了。"},{"start":3,"end":3,"text":"他患漏症，无论是下流的，是止住的，都是不洁净。"},{"start":4,"end":4,"text":"他所躺的床都为不洁净，所坐的物也为不洁净。"},{"start":5,"end":5,"text":"凡摸那床的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":6,"end":6,"text":"那坐患漏症人所坐之物的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":7,"end":7,"text":"那摸患漏症人身体的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":8,"end":8,"text":"若患漏症人吐在洁净的人身上，那人必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":9,"end":9,"text":"患漏症人所骑的鞍子也为不洁净。"},{"start":10,"end":10,"text":"凡摸了他身下之物的，必不洁净到晚上；拿了那物的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":11,"end":11,"text":"患漏症的人没有用水涮手，无论摸了谁，谁必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":12,"end":12,"text":"患漏症人所摸的瓦器就必打破；所摸的一切木器也必用水涮洗。"},{"start":13,"end":13,"text":"「患漏症的人痊愈了，就要为洁净自己计算七天，也必洗衣服，用活水洗身，就洁净了。"},{"start":14,"end":14,"text":"第八天，要取两只斑鸠或是两只雏鸽，来到会幕门口、耶和华面前，把鸟交给祭司。"},{"start":15,"end":15,"text":"祭司要献上一只为赎罪祭，一只为燔祭；因那人患的漏症，祭司要在耶和华面前为他赎罪。"},{"start":16,"end":16,"text":"「人若[梦]遗，他必不洁净到晚上，并要用水洗全身。"},{"start":17,"end":17,"text":"无论是衣服是皮子，被精所染，必不洁净到晚上，并要用水洗。"},{"start":18,"end":18,"text":"若男女交合，两个人必不洁净到晚上，并要用水洗澡。"},{"start":19,"end":19,"text":"「女人行经，必污秽七天；凡摸她的，必不洁净到晚上。"},{"start":20,"end":20,"text":"女人在污秽之中，凡她所躺的物件都为不洁净，所坐的物件也都不洁净。"},{"start":21,"end":21,"text":"凡摸她床的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":22,"end":22,"text":"凡摸她所坐什么物件的，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":23,"end":23,"text":"在女人的床上，或在她坐的物上，若有别的物件，人一摸了，必不洁净到晚上。"},{"start":24,"end":24,"text":"男人若与那女人同房，染了她的污秽，就要七天不洁净；所躺的床也为不洁净。"},{"start":25,"end":25,"text":"「女人若在经期以外患多日的血漏，或是经期过长，有了漏症，她就因这漏症不洁净，与她在经期不洁净一样。"},{"start":26,"end":26,"text":"她在患漏症的日子所躺的床、所坐的物都要看为不洁净，与她月经的时候一样。"},{"start":27,"end":27,"text":"凡摸这些物件的，就为不洁净，必不洁净到晚上，并要洗衣服，用水洗澡。"},{"start":28,"end":28,"text":"女人的漏症若好了，就要计算七天，然后才为洁净。"},{"start":29,"end":29,"text":"第八天，要取两只斑鸠或是两只雏鸽，带到会幕门口给祭司。"},{"start":30,"end":30,"text":"祭司要献一只为赎罪祭，一只为燔祭；因那人血漏不洁，祭司要在耶和华面前为她赎罪。"},{"start":31,"end":31,"text":"「你们要这样使以色列人与他们的污秽隔绝，免得他们玷污我的帐幕，就因自己的污秽死亡。」"},{"start":32,"end":32,"text":"这是患漏症和[梦]遗而不洁净的，"},{"start":33,"end":33,"text":"并有月经病的和患漏症的，无论男女，并人与不洁净女人同房的条例。"}],"19":[{"start":9,"end":9,"text":"「在你们的地收割庄稼，不可割尽田角，也不可拾取所遗落的。"},{"start":10,"end":10,"text":"不可摘尽葡萄园的果子，也不可拾取葡萄园所掉的果子；要留给穷人和寄居的。我是耶和华—你们的　神。"},{"start":11,"end":11,"text":"「你们不可偷盗，不可欺骗，也不可彼此说谎。"},{"start":12,"end":12,"text":"不可指着我的名起假誓，亵渎你　神的名。我是耶和华。"},{"start":13,"end":13,"text":"「不可欺压你的邻舍，也不可抢夺他的物。雇工人的工价，不可在你那里过夜，留到早晨。"},{"start":14,"end":14,"text":"不可咒骂聋子，也不可将绊脚石放在瞎子面前，只要敬畏你的　神。我是耶和华。"},{"start":15,"end":15,"text":"「你们施行审判，不可行不义；不可偏护穷人，也不可重看有势力的人，只要按着公义审判你的邻舍。"},{"start":16,"end":16,"text":"不可在民中往来搬弄是非，也不可与邻舍为敌，置之于死。我是耶和华。"},{"start":17,"end":17,"text":"「不可心里恨你的弟兄；总要指摘你的邻舍，免得因他担罪。"},{"start":18,"end":18,"text":"不可报仇，也不可埋怨你本国的子民，却要爱人如己。我是耶和华。"},{"start":19,"end":19,"text":"「你们要守我的律例。不可叫你的牲畜与异类配合；不可用两样搀杂的种种你的地，也不可用两样搀杂的料做衣服穿在身上。"},{"start":20,"end":20,"text":"「婢女许配了丈夫，还没有被赎、得释放，人若与她行淫，二人要受刑罚，却不把他们治死，因为婢女还没有得自由。"},{"start":21,"end":21,"text":"那人要把赎愆祭，就是一只公绵羊牵到会幕门口、耶和华面前。"},{"start":22,"end":22,"text":"祭司要用赎愆祭的羊在耶和华面前赎他所犯的罪，他的罪就必蒙赦免。"},{"start":23,"end":23,"text":"「你们到了迦南地，栽种各样结果子的树木，就要以所结的果子如未受割礼的一样。三年之久，你们要以这些果子，如未受割礼的，是不可吃的。"},{"start":24,"end":24,"text":"但第四年所结的果子全要成为圣，用以赞美耶和华。"},{"start":25,"end":25,"text":"第五年，你们要吃那树上的果子，好叫树给你们结果子更多。我是耶和华—你们的　神。"},{"start":26,"end":26,"text":"「你们不可吃带血的物；不可用法术，也不可观兆。"},{"start":27,"end":27,"text":"头的周围不可剃，胡须的周围也不可损坏。"},{"start":28,"end":28,"text":"不可为死人用刀划身，也不可在身上刺花纹。我是耶和华。"},{"start":29,"end":29,"text":"「不可辱没你的女儿，使她为娼妓，恐怕地上[的人]专向淫乱，地就满了大恶。"},{"start":30,"end":30,"text":"你们要守我的安息日，敬我的圣所。我是耶和华。"},{"start":31,"end":31,"text":"「不可偏向那些交鬼的和行巫术的；不可求问他们，以致被他们玷污了。我是耶和华—你们的　神。"},{"start":32,"end":32,"text":"「在白发的人面前，你要站起来；也要尊敬老人，又要敬畏你的　神。我是耶和华。"},{"start":33,"end":33,"text":"「若有外人在你们国中和你同居，就不可欺负他。"},{"start":34,"end":34,"text":"和你们同居的外人，你们要看他如本地人一样，并要爱他如己，因为你们在埃及地也作过寄居的。我是耶和华—你们的　神。"},{"start":35,"end":35,"text":"「你们施行审判，不可行不义；在尺、秤、升、斗上也是如此。"},{"start":36,"end":36,"text":"要用公道天平、公道法码、公道升斗、公道秤。我是耶和华—你们的　神，曾把你们从埃及地领出来的。"},{"start":37,"end":37,"text":"你们要谨守遵行我一切的律例典章。我是耶和华。」"}],"25":[{"start":8,"end":8,"text":"「你要计算七个安息年，就是七七年。这便为你成了七个安息年，共是四十九年。"},{"start":9,"end":9,"text":"当年七月初十日，你要大发角声；这日就是赎罪日，要在遍地发出角声。"},{"start":10,"end":10,"text":"第五十年，你们要当作圣年，在遍地给一切的居民宣告自由。这年必为你们的禧年，各人要归自己的产业，各归本家。"},{"start":11,"end":11,"text":"第五十年要作为你们的禧年。这年不可耕种；地中自长的，不可收割；没有修理的葡萄树也不可摘取[葡萄]。"},{"start":12,"end":12,"text":"因为这是禧年，你们要当作圣年，吃地中[自出]的土产。"}]},"PRO":{"3":[{"start":1,"end":1,"text":"我儿，不要忘记我的法则； 你心要谨守我的诫命；"},{"start":2,"end":2,"text":"因为它必将长久的日子， 生命的年数与平安，加给你。"},{"start":3,"end":3,"text":"不可使慈爱、诚实离开你， 要系在你颈项上，刻在你心版上。"},{"start":4,"end":4,"text":"这样，你必在　神和世人眼前 蒙恩宠，有聪明。"},{"start":5,"end":5,"text":"你要专心仰赖耶和华， 不可倚靠自己的聪明，"},{"start":6,"end":6,"text":"在你一切所行的事上都要认定他， 他必指引你的路。"}],"9":[{"start":1,"end":1,"text":"智慧建造房屋， 凿成七根柱子，"},{"start":2,"end":2,"text":"宰杀牲畜， 调和旨酒， 设摆筵席；"},{"start":3,"end":3,"text":"打发使女出去， 自己在城中至高处呼叫，"},{"start":4,"end":4,"text":"说：谁是愚蒙人，可以转到这里来！ 又对那无知的人说："},{"start":5,"end":5,"text":"你们来，吃我的饼， 喝我调和的酒。"},{"start":6,"end":6,"text":"你们愚蒙人，要舍弃[愚蒙]， 就得存活，并要走光明的道。"}],"11":[{"start":4,"end":4,"text":"发怒的日子资财无益； 惟有公义能救人脱离死亡。"},{"start":5,"end":5,"text":"完全人的义必指引他的路； 但恶人必因自己的恶跌倒。"},{"start":6,"end":6,"text":"正直人的义必拯救自己； 奸诈人必陷在自己的罪孽中。"},{"start":7,"end":7,"text":"恶人一死，他的指望必灭绝； 罪人的盼望也必灭没。"},{"start":8,"end":8,"text":"义人得脱离患难， 有恶人来代替他。"},{"start":9,"end":9,"text":"不虔敬的人用口败坏邻舍； 义人却因知识得救。"},{"start":10,"end":10,"text":"义人享福，合城喜乐； 恶人灭亡，人都欢呼。"},{"start":11,"end":11,"text":"城因正直人祝福便高举， 却因邪恶人的口就倾覆。"},{"start":12,"end":12,"text":"藐视邻舍的，毫无智慧； 明哲人却静默不言。"},{"start":13,"end":13,"text":"往来传舌的，泄漏密事； 心中诚实的，遮隐事情。"},{"start":14,"end":14,"text":"无智谋，民就败落； 谋士多，人便安居。"},{"start":15,"end":15,"text":"为外人作保的，必受亏损； 恨恶击掌的，却得安稳。"},{"start":16,"end":16,"text":"恩德的妇女得尊荣； 强暴的男子得资财。"},{"start":17,"end":17,"text":"仁慈的人善待自己； 残忍的人扰害己身。"},{"start":18,"end":18,"text":"恶人经营，得虚浮的工价； 撒义种的，得实在的果效。"},{"start":19,"end":19,"text":"恒心为义的，[必得]生命； 追求邪恶的，[必致]死亡。"},{"start":20,"end":20,"text":"心中乖僻的，为耶和华所憎恶； 行事完全的，为他所喜悦。"},{"start":21,"end":21,"text":"恶人[虽然]连手，必不免受罚； 义人的后裔必得拯救。"},{"start":22,"end":22,"text":"妇女美貌而无见识， [如同]金环带在猪鼻上。"},{"start":23,"end":23,"text":"义人的心愿尽得好处； 恶人的指望致干忿怒。"},{"start":24,"end":24,"text":"有施散的，却更增添； 有吝惜过度的，反致穷乏。"},{"start":25,"end":25,"text":"好施舍的，必得丰裕； 滋润人的，必得滋润。"},{"start":26,"end":26,"text":"屯粮不卖的，民必咒诅他； 情愿出卖的，人必为他祝福。"},{"start":27,"end":27,"text":"恳切求善的，就求得恩惠； 惟独求恶的，恶必临到他身。"},{"start":28,"end":28,"text":"倚仗自己财物的，必跌倒； 义人必发旺，如青叶。"},{"start":29,"end":29,"text":"扰害己家的，必承受清风； 愚昧人必作慧心人的仆人。"},{"start":30,"end":30,"text":"义人所结的果子就是生命树； 有智慧的，必能得人。"},{"start":31,"end":31,"text":"看哪，义人在世尚且受报， 何况恶人和罪人呢？"}],"23":[{"start":29,"end":29,"text":"谁有祸患？谁有忧愁？ 谁有争斗？谁有哀叹？ 谁无故受伤？谁眼目红赤？"},{"start":30,"end":30,"text":"就是那流连饮酒、 常去寻找调和酒的人。"},{"start":31,"end":31,"text":"酒发红，在杯中闪烁， 你不可观看， [虽然]下咽舒畅， 终久是咬你如蛇，刺你如毒蛇。"},{"start":33,"end":33,"text":"你眼必看见异怪的事； 你心必发出乖谬的话。"},{"start":34,"end":34,"text":"你必像躺在海中， 或像卧在桅杆上。"},{"start":35,"end":35,"text":"[你必]说：人打我，我却未受伤； 人鞭打我，我竟不觉得。 我几时清醒，我仍去寻酒。"}],"25":[{"start":6,"end":6,"text":"不要在王面前妄自尊大； 不要在大人的位上站立。"},{"start":7,"end":7,"text":"宁可有人说：请你上来， 强如在你觐见的王子面前叫你退下。"},{"start":21,"end":21,"text":"你的仇敌若饿了，就给他饭吃； 若渴了，就给他水喝；"},{"start":22,"end":22,"text":"因为，你[这样行]就是把炭火堆在他的头上； 耶和华也必赏赐你。"}]},"COL":{"1":[{"start":9,"end":9,"text":"因此，我们自从听见的日子，也就为你们不住地祷告祈求，愿你们在一切属灵的智慧悟性上，满心知道　神的旨意；"},{"start":10,"end":10,"text":"好叫你们行事为人对得起主，凡事蒙他喜悦，在一切善事上结果子，渐渐地多知道　神；"}],"3":[{"start":12,"end":12,"text":"所以，你们既是　神的选民，圣洁蒙爱的人，就要存怜悯、恩慈、谦虚、温柔、忍耐的心。"},{"start":13,"end":13,"text":"倘若这人与那人有嫌隙，总要彼此包容，彼此饶恕；主怎样饶恕了你们，你们也要怎样饶恕人。"},{"start":15,"end":15,"text":"又要叫基督的平安在你们心里作主；你们也为此蒙召，归为一体；且要存感谢的心。"},{"start":16,"end":16,"text":"当用各样的智慧，把基督的道理丰丰富富地存在心里，用诗章、颂词、灵歌，彼此教导，互相劝戒，心被恩感，歌颂　神。"},{"start":17,"end":17,"text":"无论做什么，或说话或行事，都要奉主耶稣的名，借着他感谢父　神。"}]},"JAM":{"1":[{"start":14,"end":14,"text":"但各人被试探，乃是被自己的私欲牵引诱惑的。"},{"start":15,"end":15,"text":"私欲既怀了胎，就生出罪来；罪既长成，就生出死来。"},{"start":21,"end":21,"text":"所以，你们要脱去一切的污秽和盈余的邪恶，存温柔的心领受那所栽种的道，就是能救你们灵魂的道。"},{"start":22,"end":22,"text":"只是你们要行道，不要单单听道，自己欺哄自己。"},{"start":23,"end":23,"text":"因为听道而不行道的，就像人对着镜子看自己本来的面目，"},{"start":24,"end":24,"text":"看见，走后，随即忘了他的相貌如何。"},{"start":25,"end":25,"text":"惟有详细察看那全备、[使人]自由之律法的，并且时常如此，这人既不是听了就忘，乃是实在行出来，就在他所行的事上必然得福。"}],"2":[{"start":1,"end":1,"text":"我的弟兄们，你们信奉我们荣耀的主耶稣基督，便不可按着外貌待人。"},{"start":2,"end":2,"text":"若有一个人带着金戒指，穿着华美衣服，进你们的会堂去；又有一个穷人穿着肮脏衣服也进去；"},{"start":3,"end":3,"text":"你们就重看那穿华美衣服的人，说：「请坐在这好位上」；又对那穷人说：「你站在那里」，或「坐在我脚凳下边。」"},{"start":4,"end":4,"text":"这岂不是你们偏心待人，用恶意断定人吗？"},{"start":5,"end":5,"text":"我亲爱的弟兄们，请听，　神岂不是拣选了世上的贫穷人，叫他们在信上富足，并承受他所应许给那些爱他之人的国吗？"},{"start":6,"end":6,"text":"你们反倒羞辱贫穷人。那富足人岂不是欺压你们、拉你们到公堂去吗？"},{"start":7,"end":7,"text":"他们不是亵渎你们所敬奉的尊名吗？"},{"start":8,"end":8,"text":"经上记着说：「要爱人如己。」你们若全守这至尊的律法才是好的。"},{"start":9,"end":9,"text":"但你们若按外貌待人，便是犯罪，被律法定为犯法的。"},{"start":10,"end":10,"text":"因为凡遵守全律法的，只在一条上跌倒，他就是犯了众条。"},{"start":11,"end":11,"text":"原来那说「不可奸淫」的，也说「不可杀人」；你就是不奸淫，却杀人，仍是成了犯律法的。"},{"start":12,"end":12,"text":"你们既然要按[使人]自由的律法受审判，就该照这律法说话行事。"},{"start":13,"end":13,"text":"因为那不怜悯人的，也要受无怜悯的审判；怜悯原是向审判夸胜。"},{"start":14,"end":14,"text":"我的弟兄们，若有人说自己有信心，却没有行为，有什么益处呢？这信心能救他吗？"},{"start":15,"end":15,"text":"若是弟兄或是姊妹，赤身露体，又缺了日用的饮食；"},{"start":16,"end":16,"text":"你们中间有人对他们说：「平平安安地去吧！愿你们穿得暖，吃得饱」，却不给他们身体所需用的，这有什么益处呢？"},{"start":17,"end":17,"text":"这样，信心若没有行为就是死的。"},{"start":18,"end":18,"text":"必有人说：「你有信心，我有行为；你将你没有行为的信心指给我看，我便借着我的行为，将我的信心指给你看。」"},{"start":19,"end":19,"text":"你信　神只有一位，你信的不错；鬼魔也信，却是战惊。"},{"start":20,"end":20,"text":"虚浮的人哪，你愿意知道没有行为的信心是死的吗？"},{"start":21,"end":21,"text":"我们的祖宗亚伯拉罕把他儿子以撒献在坛上，岂不是因行为称义吗？"},{"start":22,"end":22,"text":"可见，信心是与他的行为并行，而且信心因着行为才得成全。"},{"start":23,"end":23,"text":"这就应验经上所说：「亚伯拉罕信　神，这就算为他的义。」他又得称为　神的朋友。"},{"start":24,"end":24,"text":"这样看来，人称义是因着行为，不是单因着信。"},{"start":25,"end":25,"text":"妓女喇合接待使者，又放他们从别的路上出去，不也是一样因行为称义吗？"},{"start":26,"end":26,"text":"身体没有灵魂是死的，信心没有行为也是死的。"}],"3":[{"start":1,"end":1,"text":"我的弟兄们，不要多人作师傅，因为晓得我们要受更重的判断。"},{"start":2,"end":2,"text":"原来我们在许多事上都有过失；若有人在话语上没有过失，他就是完全人，也能勒住自己的全身。"},{"start":3,"end":3,"text":"我们若把嚼环放在马嘴里，叫它顺服，就能调动它的全身。"},{"start":4,"end":4,"text":"看哪，船只虽然甚大，又被大风催逼，只用小小的舵，就随着掌舵的意思转动。"},{"start":5,"end":5,"text":"这样，舌头在百体里也是最小的，却能说大话。 看哪，最小的火能点着最大的树林。"},{"start":6,"end":6,"text":"舌头就是火，在我们百体中，舌头是个罪恶的世界，能污秽全身，也能把生命的轮子点起来，并且是从地狱里点着的。"},{"start":7,"end":7,"text":"各类的走兽、飞禽、昆虫、水族，本来都可以制伏，也已经被人制伏了；"},{"start":8,"end":8,"text":"惟独舌头没有人能制伏，是不止息的恶物，满了害死人的毒气。"},{"start":9,"end":9,"text":"我们用舌头颂赞那为主、为父的，又用舌头咒诅那照着　神形象被造的人。"},{"start":10,"end":10,"text":"颂赞和咒诅从一个口里出来！我的弟兄们，这是不应当的！"},{"start":11,"end":11,"text":"泉源从一个眼里能发出甜苦两样的水吗？"},{"start":12,"end":12,"text":"我的弟兄们，无花果树能生橄榄吗？葡萄树能结无花果吗？咸水里也不能发出甜水来。"},{"start":13,"end":13,"text":"你们中间谁是有智慧有见识的呢？他就当在智慧的温柔上显出他的善行来。"},{"start":14,"end":14,"text":"你们心里若怀着苦毒的嫉妒和纷争，就不可自夸，也不可说谎话抵挡真道。"},{"start":15,"end":15,"text":"这样的智慧不是从上头来的，乃是属地的，属情欲的，属鬼魔的。"},{"start":16,"end":16,"text":"在何处有嫉妒、纷争，就在何处有扰乱和各样的坏事。"},{"start":17,"end":17,"text":"惟独从上头来的智慧，先是清洁，后是和平，温良柔顺，满有怜悯，多结善果，没有偏见，没有假冒。"},{"start":18,"end":18,"text":"并且使人和平的，是用和平所栽种的义果。"}],"5":[{"start":1,"end":1,"text":"嗐！你们这些富足人哪，应当哭泣、号咷，因为将有苦难临到你们身上。"},{"start":2,"end":2,"text":"你们的财物坏了，衣服也被虫子咬了。"},{"start":3,"end":3,"text":"你们的金银都长了锈；那锈要证明你们的不是，又要吃你们的肉，如同火烧。你们在这末世只知积攒钱财。"},{"start":4,"end":4,"text":"工人给你们收割庄稼，你们亏欠他们的工钱，这工钱有声音呼叫，并且那收割之人的冤声已经入了万军之主的耳了。"},{"start":5,"end":5,"text":"你们在世上享美福，好宴乐，当宰杀的日子竟娇养你们的心。"},{"start":6,"end":6,"text":"你们定了义人的罪，把他杀害，他也不抵挡你们。"},{"start":7,"end":7,"text":"弟兄们哪，你们要忍耐，直到主来。看哪，农夫忍耐等候地里宝贵的出产，直到得了秋雨春雨。"},{"start":8,"end":8,"text":"你们也当忍耐，坚固你们的心，因为主来的日子近了。"},{"start":9,"end":9,"text":"弟兄们，你们不要彼此埋怨，免得受审判。看哪，审判的[主]站在门前了。"},{"start":10,"end":10,"text":"弟兄们，你们要把那先前奉主名说话的众先知当作能受苦能忍耐的榜样。"},{"start":11,"end":11,"text":"那先前忍耐的人，我们称他们是有福的。你们听见过约伯的忍耐，也知道主[给他]的结局，明显主是满心怜悯，大有慈悲。"}]},"JOE":{"2":[{"start":12,"end":12,"text":"耶和华说：虽然如此， 你们应当禁食、哭泣、悲哀， 一心归向我。"},{"start":13,"end":13,"text":"你们要撕裂心肠， 不撕裂衣服。 归向耶和华—你们的　神； 因为他有恩典，有怜悯， 不轻易发怒， 有丰盛的慈爱， 并且后悔不降所说的灾。"},{"start":28,"end":28,"text":"以后，我要将我的灵浇灌凡有血气的。 你们的儿女要说预言； 你们的老年人要做异梦， 少年人要见异象。"},{"start":29,"end":29,"text":"在那些日子， 我要将我的灵浇灌我的仆人和使女。"},{"start":30,"end":30,"text":"「在天上地下，我要显出奇事，有血，有火，有烟柱。"},{"start":31,"end":31,"text":"日头要变为黑暗，月亮要变为血，这都在耶和华大而可畏的日子未到以前。"},{"start":32,"end":32,"text":"到那时候，凡求告耶和华名的就必得救；因为照耶和华所说的，在锡安山，耶路撒冷必有逃脱的人，在剩下的人中必有耶和华所召的。」"}]},"ROM":{"2":[{"start":17,"end":17,"text":"你称为犹太人，又倚靠律法，且指着　神夸口；"},{"start":18,"end":18,"text":"既从律法中受了教训，就晓得　神的旨意，也能分别是非；"},{"start":19,"end":19,"text":"又深信自己是给瞎子领路的，是黑暗中人的光，"},{"start":20,"end":20,"text":"是蠢笨人的师傅，是小孩子的先生，在律法上有知识和真理的模范。"},{"start":21,"end":21,"text":"你既是教导别人，还不教导自己吗？你讲说人不可偷窃，自己还偷窃吗？"},{"start":22,"end":22,"text":"你说人不可奸淫，自己还奸淫吗？你厌恶偶像，自己还偷窃庙中之物吗？"},{"start":23,"end":23,"text":"你指着律法夸口，自己倒犯律法、玷辱　神吗？"},{"start":24,"end":24,"text":"神的名在外邦人中，因你们受了亵渎，正如[经上]所记的。"}],"3":[{"start":21,"end":21,"text":"但如今，　神的义在律法以外已经显明出来，有律法和先知为证："},{"start":22,"end":22,"text":"就是　神的义，因信耶稣基督加给一切相信的人，并没有分别。"},{"start":23,"end":23,"text":"因为世人都犯了罪，亏缺了　神的荣耀；"},{"start":24,"end":24,"text":"如今却蒙　神的恩典，因基督耶稣的救赎，就白白地称义。"},{"start":25,"end":25,"text":"神设立耶稣作挽回祭，是凭着耶稣的血，借着人的信，要显明　神的义；因为他用忍耐的心宽容人先时所犯的罪，"},{"start":26,"end":26,"text":"好在今时显明他的义，使人知道他自己为义，也称信耶稣的人为义。"},{"start":27,"end":27,"text":"既是这样，哪里能夸口呢？没有可夸的了。用何法没有的呢？是用立功之法吗？不是，乃用信[主]之法。"},{"start":28,"end":28,"text":"所以我们看定了：人称义是因着信，不在乎遵行律法。"},{"start":31,"end":31,"text":"这样，我们因信废了律法吗？断乎不是！更是坚固律法。"}],"5":[{"start":12,"end":12,"text":"这就如罪是从一人入了世界，死又是从罪来的，于是死就临到众人，因为众人都犯了罪。"},{"start":13,"end":13,"text":"没有律法之先，罪已经在世上；但没有律法，罪也不算罪。"},{"start":14,"end":14,"text":"然而从亚当到摩西，死就作了王，连那些不与亚当犯一样罪过的，也在他的权下。亚当乃是那以后要来之人的预像。"},{"start":15,"end":15,"text":"只是过犯不如恩赐，若因一人的过犯，众人都死了，何况　神的恩典，与那因耶稣基督一人恩典中的赏赐，岂不更加倍地临到众人吗？"},{"start":16,"end":16,"text":"因一人犯罪就定罪，也不如恩赐，原来审判是由一人而定罪，恩赐乃是由许多过犯而称义。"},{"start":17,"end":17,"text":"若因一人的过犯，死就因这一人作了王，何况那些受洪恩又蒙所赐之义的，岂不更要因耶稣基督一人在生命中作王吗？"},{"start":18,"end":18,"text":"如此说来，因一次的过犯，众人都被定罪；照样，因一次的义行，众人也就被称义得生命了。"},{"start":19,"end":19,"text":"因一人的悖逆，众人成为罪人；照样，因一人的顺从，众人也成为义了。"}],"6":[{"start":3,"end":3,"text":"岂不知我们这受洗归入基督耶稣的人是受洗归入他的死吗？"},{"start":4,"end":4,"text":"所以，我们借着洗礼归入死，和他一同埋葬，原是叫我们一举一动有新生的样式，像基督借着父的荣耀从死里复活一样。"},{"start":5,"end":5,"text":"我们若在他死的形状上与他联合，也要在他复活的形状上与他联合；"},{"start":6,"end":6,"text":"因为知道我们的旧人和他同钉十字架，使罪身灭绝，叫我们不再作罪的奴仆；"},{"start":7,"end":7,"text":"因为已死的人是脱离了罪。"},{"start":8,"end":8,"text":"我们若是与基督同死，就信必与他同活。"},{"start":9,"end":9,"text":"因为知道基督既从死里复活，就不再死，死也不再作他的主了。"},{"start":10,"end":10,"text":"他死是向罪死了，只有一次；他活是向　神活着。"},{"start":11,"end":11,"text":"这样，你们向罪也当看自己是死的；向　神在基督耶稣里，却当看自己是活的。"},{"start":12,"end":12,"text":"所以，不要容罪在你们必死的身上作王，使你们顺从身子的私欲。"},{"start":13,"end":13,"text":"也不要将你们的肢体献给罪作不义的器具；倒要像从死里复活的人，将自己献给　神，并将肢体作义的器具献给　神。"},{"start":14,"end":14,"text":"罪必不能作你们的主；因你们不在律法之下，乃在恩典之下。"},{"start":15,"end":15,"text":"这却怎么样呢？我们在恩典之下，不在律法之下，就可以犯罪吗？断乎不可！"},{"start":16,"end":16,"text":"岂不晓得你们献上自己作奴仆，顺从谁，就作谁的奴仆吗？或作罪的奴仆，以至于死；或作顺命的奴仆，以至成义。"},{"start":17,"end":17,"text":"感谢　神！因为你们从前虽然作罪的奴仆，现今却从心里顺服了所传给你们道理的模范。"},{"start":18,"end":18,"text":"你们既从罪里得了释放，就作了义的奴仆。"},{"start":19,"end":19,"text":"我因你们肉体的软弱，就照人的常话对你们说。你们从前怎样将肢体献给不洁不法作奴仆，以至于不法；现今也要照样将肢体献给义作奴仆，以至于成圣。"},{"start":20,"end":20,"text":"因为你们作罪之奴仆的时候，就不被义约束了。"},{"start":21,"end":21,"text":"你们现今所看为羞耻的事，当日有什么果子呢？那些事的结局就是死。"},{"start":22,"end":22,"text":"但现今，你们既从罪里得了释放，作了　神的奴仆，就有成圣的果子，那结局就是永生。"},{"start":23,"end":23,"text":"因为罪的工价乃是死；惟有　神的恩赐，在我们的主基督耶稣里，乃是永生。"}],"8":[{"start":15,"end":15,"text":"你们所受的，不是奴仆的心，仍旧害怕；所受的，乃是儿子的心，因此我们呼叫：「阿爸！父！」"},{"start":16,"end":16,"text":"圣灵与我们的心同证我们是　神的儿女；"},{"start":17,"end":17,"text":"既是儿女，便是后嗣，就是　神的后嗣，和基督同作后嗣。如果我们和他一同受苦，也必和他一同得荣耀。"},{"start":18,"end":18,"text":"我想，现在的苦楚若比起将来要显于我们的荣耀就不足介意了。"},{"start":19,"end":19,"text":"受造之物切望等候　神的众子显出来。"},{"start":20,"end":20,"text":"因为受造之物服在虚空之下，不是自己愿意，乃是因那叫他如此的。"},{"start":21,"end":21,"text":"但受造之物仍然指望脱离败坏的辖制，得享　神儿女自由的荣耀。"},{"start":22,"end":22,"text":"我们知道，一切受造之物一同叹息，劳苦，直到如今。"},{"start":23,"end":23,"text":"不但如此，就是我们这有[圣]灵初结果子的，也是自己心里叹息，等候得着儿子的名分，乃是我们的身体得赎。"},{"start":24,"end":24,"text":"我们得救是在乎盼望；只是所见的盼望不是盼望，谁还盼望他所见的呢？"},{"start":25,"end":25,"text":"但我们若盼望那所不见的，就必忍耐等候。"},{"start":26,"end":26,"text":"况且，我们的软弱有[圣]灵帮助；我们本不晓得当怎样祷告，只是[圣]灵亲自用说不出来的叹息替我们祷告。"},{"start":27,"end":27,"text":"鉴察人心的，晓得[圣]灵的意思，因为[圣]灵照着　神的[旨意]替圣徒祈求。"},{"start":28,"end":28,"text":"我们晓得万事都互相效力，叫爱　神的人得益处，就是按他旨意被召的人。"},{"start":29,"end":29,"text":"因为他预先所知道的人，就预先定下效法他儿子的模样，使他儿子在许多弟兄中作长子。"},{"start":30,"end":30,"text":"预先所定下的人又召他们来；所召来的人又称他们为义；所称为义的人又叫他们得荣耀。"},{"start":31,"end":31,"text":"既是这样，还有什么说的呢？　神若帮助我们，谁能敌挡我们呢？"},{"start":32,"end":32,"text":"神既不爱惜自己的儿子，为我们众人舍了，岂不也把万物和他一同白白地赐给我们吗？"},{"start":33,"end":33,"text":"谁能控告　神所拣选的人呢？有　神称他们为义了。"},{"start":34,"end":34,"text":"谁能定他们的罪呢？有基督耶稣已经死了，而且从死里复活，现今在　神的右边，也替我们祈求。"},{"start":35,"end":35,"text":"谁能使我们与基督的爱隔绝呢？难道是患难吗？是困苦吗？是逼迫吗？是饥饿吗？是赤身露体吗？是危险吗？是刀剑吗？"},{"start":36,"end":36,"text":"如[经上]所记： 我们为你的缘故终日被杀； 人看我们如将宰的羊。"},{"start":37,"end":37,"text":"然而，靠着爱我们的[主]，在这一切的事上已经得胜有余了。"},{"start":38,"end":38,"text":"因为我深信无论是死，是生，是天使，是掌权的，是有能的，是现在的事，是将来的事，"},{"start":39,"end":39,"text":"是高处的，是低处的，是别的受造之物，都不能叫我们与　神的爱隔绝；这爱是在我们的主基督耶稣里的。"}],"9":[{"start":6,"end":6,"text":"这不是说　神的话落了空。因为从以色列生的不都是以色列人，"},{"start":7,"end":7,"text":"也不因为是亚伯拉罕的后裔就都作他的儿女；惟独「从以撒生的才要称为你的后裔。」"},{"start":8,"end":8,"text":"这就是说，肉身所生的儿女不是　神的儿女，惟独那应许的儿女才算是后裔。"},{"start":30,"end":30,"text":"这样，我们可说什么呢？那本来不追求义的外邦人反得了义，就是因信而得的义。"},{"start":31,"end":31,"text":"但以色列人追求律法的义，反得不着律法的义。"},{"start":32,"end":32,"text":"这是什么缘故呢？是因为他们不凭着信心求，只凭着行为求；他们正跌在那绊脚石上。"},{"start":33,"end":33,"text":"就如经上所记： 我在锡安放一块绊脚的石头，跌人的磐石； 信靠他的人必不至于羞愧。"}],"12":[{"start":10,"end":10,"text":"爱弟兄，要彼此亲热；恭敬人，要彼此推让。"},{"start":11,"end":11,"text":"殷勤，不可懒惰；要心里火热，常常服事主。"},{"start":12,"end":12,"text":"在指望中要喜乐；在患难中要忍耐；祷告要恒切。"},{"start":13,"end":13,"text":"圣徒缺乏，要帮补；客，要一味地款待。"},{"start":14,"end":14,"text":"逼迫你们的，要给他们祝福；只要祝福，不可咒诅。"},{"start":15,"end":15,"text":"与喜乐的人要同乐；与哀哭的人要同哭。"},{"start":16,"end":16,"text":"要彼此同心；不要志气高大，倒要俯就卑微的人。不要自以为聪明。"},{"start":17,"end":17,"text":"不要以恶报恶；众人以为美的事要留心去做。"},{"start":18,"end":18,"text":"若是能行，总要尽力与众人和睦。"},{"start":19,"end":19,"text":"亲爱的弟兄，不要自己伸冤，宁可让步，听凭主怒；因为[经上]记着：「主说：『伸冤在我，我必报应。』」"},{"start":20,"end":20,"text":"所以，「你的仇敌若饿了，就给他吃，若渴了，就给他喝；因为你这样行就是把炭火堆在他的头上。」"},{"start":21,"end":21,"text":"你不可为恶所胜，反要以善胜恶。"}],"13":[{"start":1,"end":1,"text":"在上有权柄的，人人当顺服他，因为没有权柄不是出于　神的。凡掌权的都是　神所命的。"},{"start":2,"end":2,"text":"所以，抗拒掌权的就是抗拒　神的命；抗拒的必自取刑罚。"},{"start":3,"end":3,"text":"作官的原不是叫行善的惧怕，乃是叫作恶的惧怕。你愿意不惧怕掌权的吗？你只要行善，就可得他的称赞；"},{"start":4,"end":4,"text":"因为他是　神的用人，是与你有益的。你若作恶，却当惧怕，因为他不是空空地佩剑；他是　神的用人，是伸冤的，刑罚那作恶的。"},{"start":5,"end":5,"text":"所以，你们必须顺服，不但是因为刑罚，也是因为良心。"},{"start":6,"end":6,"text":"你们纳粮，也为这个缘故；因他们是　神的差役，常常特管这事。"},{"start":7,"end":7,"text":"凡人所当得的，就给他。当得粮的，给他纳粮；当得税的，给他上税；当惧怕的，惧怕他；当恭敬的，恭敬他。"},{"start":11,"end":11,"text":"再者，你们晓得，现今就是该趁早睡醒的时候；因为我们得救，现今比[初]信的时候更近了。"},{"start":12,"end":12,"text":"黑夜已深，白昼将近。我们就当脱去暗昧的行为，带上光明的兵器。"},{"start":13,"end":13,"text":"行事为人要端正，好像行在白昼。不可荒宴醉酒；不可好色邪荡；不可争竞嫉妒。"},{"start":14,"end":14,"text":"总要披戴主耶稣基督，不要为肉体安排，去[放纵]私欲。"}],"16":[{"start":1,"end":1,"text":"我对你们举荐我们的姊妹非比；她是坚革哩教会中的女执事。"},{"start":2,"end":2,"text":"请你们为主接待她，合乎圣徒的体统。她在何事上要你们帮助，你们就帮助她；因她素来帮助许多人，也帮助了我。"},{"start":3,"end":3,"text":"问百基拉和亚居拉安。他们在基督耶稣里与我同工，"},{"start":4,"end":4,"text":"也为我的命将自己的颈项置之度外。不但我感谢他们，就是外邦的众教会也感谢他们。"},{"start":5,"end":5,"text":"又问在他们家中的教会安。问我所亲爱的以拜尼土安；他在亚细亚是归基督初结的果子。"},{"start":6,"end":6,"text":"又问马利亚安；她为你们多受劳苦。"},{"start":7,"end":7,"text":"又问我亲属与我一同坐监的安多尼古和犹尼亚安；他们在使徒中是有名望的，也是比我先在基督里。"}]},"1CO":{"1":[{"start":18,"end":18,"text":"因为十字架的道理，在那灭亡的人为愚拙；在我们得救的人，却为　神的大能。"},{"start":19,"end":19,"text":"就如[经上]所记： 我要灭绝智慧人的智慧， 废弃聪明人的聪明。"},{"start":20,"end":20,"text":"智慧人在哪里？文士在哪里？这世上的辩士在哪里？　神岂不是叫这世上的智慧变成愚拙吗？"},{"start":21,"end":21,"text":"世人凭自己的智慧，既不认识　神，　神就乐意用[人所当作]愚拙的道理拯救那些信的人；这就是　神的智慧了。"},{"start":22,"end":22,"text":"犹太人是要神迹，希腊人是求智慧，"},{"start":23,"end":23,"text":"我们却是传钉在十字架的基督，在犹太人为绊脚石，在外邦人为愚拙；"},{"start":24,"end":24,"text":"但在那蒙召的，无论是犹太人、希腊人，基督总为　神的能力，　神的智慧。"},{"start":25,"end":25,"text":"因　神的愚拙总比人智慧，　神的软弱总比人强壮。"},{"start":26,"end":26,"text":"弟兄们哪，可见你们蒙召的，按着肉体有智慧的不多，有能力的不多，有尊贵的也不多。"},{"start":27,"end":27,"text":"神却拣选了世上愚拙的，叫有智慧的羞愧；又拣选了世上软弱的，叫那强壮的羞愧。"},{"start":28,"end":28,"text":"神也拣选了世上卑贱的，被人厌恶的，以及那无有的，为要废掉那有的，"},{"start":29,"end":29,"text":"使一切有血气的，在　神面前一个也不能自夸。"},{"start":30,"end":30,"text":"但你们得在基督耶稣里是本乎　神，　神又使他成为我们的智慧、公义、圣洁、救赎。"},{"start":31,"end":31,"text":"如[经上]所记：「夸口的，当指着主夸口。」"}],"3":[{"start":6,"end":6,"text":"我栽种了，亚波罗浇灌了，惟有　神叫他生长。"},{"start":7,"end":7,"text":"可见栽种的，算不得什么，浇灌的，也算不得什么；只在那叫他生长的　神。"},{"start":8,"end":8,"text":"栽种的和浇灌的，都是一样，但将来各人要照自己的工夫得自己的赏赐。"},{"start":9,"end":9,"text":"因为我们是与　神同工的；你们是　神所耕种的田地，所建造的房屋。"},{"start":16,"end":16,"text":"岂不知你们是　神的殿，　神的灵住在你们里头吗？"},{"start":17,"end":17,"text":"若有人毁坏　神的殿，　神必要毁坏那人；因为　神的殿是圣的，这殿就是你们。"}],"9":[{"start":14,"end":14,"text":"主也是这样命定，叫传福音的靠着福音养生。"},{"start":15,"end":15,"text":"但这权柄我全没有用过。我写这话，并非要你们这样待我，因为我宁可死也不叫人使我所夸的落了空。"},{"start":16,"end":16,"text":"我传福音原没有可夸的，因为我是不得已的。若不传福音，我便有祸了。"},{"start":17,"end":17,"text":"我若甘心做这事，就有赏赐；若不甘心，责任却已经托付我了。"},{"start":18,"end":18,"text":"既是这样，我的赏赐是什么呢？就是我传福音的时候叫人不花钱得福音，免得用尽我传福音的权柄。"},{"start":19,"end":19,"text":"我虽是自由的，无人辖管；然而我甘心作了众人的仆人，为要多得人。"},{"start":20,"end":20,"text":"向犹太人，我就作犹太人，为要得犹太人；向律法以下的人，我虽不在律法以下，还是作律法以下的人，为要得律法以下的人。"},{"start":21,"end":21,"text":"向没有律法的人，我就作没有律法的人，为要得没有律法的人；其实我在　神面前，不是没有律法；在基督面前，正在律法之下。"},{"start":22,"end":22,"text":"向软弱的人，我就作软弱的人，为要得软弱的人。向什么样的人，我就作什么样的人。无论如何，总要救些人。"},{"start":23,"end":23,"text":"凡我所行的，都是为福音的缘故，为要与人同得这福音[的好处]。"},{"start":24,"end":24,"text":"岂不知在场上赛跑的都跑，但得奖赏的只有一人？你们也当这样跑，好叫你们得着奖赏。"},{"start":25,"end":25,"text":"凡较力争胜的，诸事都有节制，他们不过是要得能坏的冠冕；我们却是要得不能坏的冠冕。"},{"start":26,"end":26,"text":"所以，我奔跑不像无定向的；我斗拳不像打空气的。"},{"start":27,"end":27,"text":"我是攻克己身，叫身服我，恐怕我传[福音]给别人，自己反被弃绝了。"}],"11":[{"start":23,"end":23,"text":"我当日传给你们的，原是从主领受的，就是主耶稣被卖的那一夜，拿起饼来，"},{"start":24,"end":24,"text":"祝谢了，就擘开，说：「这是我的身体，为你们舍的，你们应当如此行，为的是记念我。」"},{"start":25,"end":25,"text":"饭后，也照样拿起杯来，说：「这杯是用我的血所立的新约，你们每逢喝的时候，要如此行，为的是记念我。」"},{"start":26,"end":26,"text":"你们每逢吃这饼，喝这杯，是表明主的死，直等到他来。"}],"15":[{"start":3,"end":3,"text":"我当日所领受又传给你们的：第一，就是基督照圣经所说，为我们的罪死了，"},{"start":4,"end":4,"text":"而且埋葬了；又照圣经所说，第三天复活了，"},{"start":5,"end":5,"text":"并且显给矶法看，然后显给十二使徒看；"},{"start":6,"end":6,"text":"后来一时显给五百多弟兄看，其中一大半到如今还在，却也有已经睡了的。"},{"start":7,"end":7,"text":"以后显给雅各看，再显给众使徒看，"},{"start":8,"end":8,"text":"末了也显给我看；我如同未到产期而生的人一般。"},{"start":12,"end":12,"text":"既传基督是从死里复活了，怎么在你们中间有人说没有死人复活的事呢？"},{"start":13,"end":13,"text":"若没有死人复活的事，基督也就没有复活了。"},{"start":14,"end":14,"text":"若基督没有复活，我们所传的便是枉然，你们所信的也是枉然；"},{"start":15,"end":15,"text":"并且明显我们是为　神妄作见证的，因我们见证　神是叫基督复活了。若死人真不复活，　神也就没有叫基督复活了。"},{"start":16,"end":16,"text":"因为死人若不复活，基督也就没有复活了。"},{"start":17,"end":17,"text":"基督若没有复活，你们的信便是徒然，你们仍在罪里。"},{"start":18,"end":18,"text":"就是在基督里睡了的人也灭亡了。"},{"start":19,"end":19,"text":"我们若靠基督只在今生有指望，就算比众人更可怜。"},{"start":20,"end":20,"text":"但基督已经从死里复活，成为睡了之人初熟的果子。"},{"start":21,"end":21,"text":"死既是因一人而来，死人复活也是因一人而来。"},{"start":22,"end":22,"text":"在亚当里众人都死了；照样，在基督里众人也都要复活。"},{"start":23,"end":23,"text":"但各人是按着自己的次序复活：初熟的果子是基督；以后，在他来的时候，是那些属基督的。"},{"start":24,"end":24,"text":"再后，末期到了，那时基督既将一切执政的、掌权的、有能的都毁灭了，就把国交与父　神。"},{"start":25,"end":25,"text":"因为基督必要作王，等　神把一切仇敌都放在他的脚下。"},{"start":26,"end":26,"text":"尽末了所毁灭的仇敌就是死。"},{"start":27,"end":27,"text":"因为[经上]说：「　神叫万物都服在他的脚下。」既说万物都服了他，明显那叫万物服他的，不在其内了。"},{"start":28,"end":28,"text":"万物既服了他，那时子也要自己服那叫万物服他的，叫　神在万物之上，为万物之主。"},{"start":45,"end":45,"text":"[经上]也是这样记着说：「首先的人亚当成了有灵的活人」；末后的亚当成了叫人活的灵。"},{"start":46,"end":46,"text":"但属灵的不在先，属血气的在先，以后才有属灵的。"},{"start":47,"end":47,"text":"头一个人是出于地，乃属土；第二个人是出于天。"},{"start":48,"end":48,"text":"那属土的怎样，凡属土的也就怎样；属天的怎样，凡属天的也就怎样。"},{"start":49,"end":49,"text":"我们既有属土的形状，将来也必有属天的形状。"}]},"HEB":{"4":[{"start":9,"end":9,"text":"这样看来，必另有一安息日的安息为　神的子民存留。"},{"start":10,"end":10,"text":"因为那进入安息的，乃是歇了自己的工，正如　神歇了他的工一样。"},{"start":11,"end":11,"text":"所以，我们务必竭力进入那安息，免得有人学那不信从的样子跌倒了。"},{"start":15,"end":15,"text":"因我们的大祭司并非不能体恤我们的软弱。他也曾凡事受过试探，与我们一样，只是他没有犯罪。"},{"start":16,"end":16,"text":"所以，我们只管坦然无惧地来到施恩的宝座前，为要得怜恤，蒙恩惠，作随时的帮助。"}],"5":[{"start":7,"end":7,"text":"基督在肉体的时候，既大声哀哭，流泪祷告，恳求那能救他免死的主，就因他的虔诚蒙了应允。"},{"start":8,"end":8,"text":"他虽然为儿子，还是因所受的苦难学了顺从。"},{"start":9,"end":9,"text":"他既得以完全，就为凡顺从他的人成了永远得救的根源，"}],"7":[{"start":25,"end":25,"text":"凡靠着他进到　神面前的人，他都能拯救到底；因为他是长远活着，替他们祈求。"},{"start":26,"end":26,"text":"像这样圣洁、无邪恶、无玷污、远离罪人、高过诸天的大祭司，原是与我们合宜的。"},{"start":27,"end":27,"text":"他不像那些大祭司，每日必须先为自己的罪，后为百姓的罪献祭；因为他只一次将自己献上，就把这事成全了。"},{"start":28,"end":28,"text":"律法本是立软弱的人为大祭司；但在律法以后起誓的话，是立儿子为大祭司，乃是成全到永远的。"}],"9":[{"start":11,"end":11,"text":"但现在基督已经来到，作了将来美事的大祭司，经过那更大更全备的帐幕，不是人手所造，也不是属乎这世界的；"},{"start":12,"end":12,"text":"并且不用山羊和牛犊的血，乃用自己的血，只一次进入圣所，成了永远赎罪的事。"},{"start":13,"end":13,"text":"若山羊和公牛的血，并母牛犊的灰，洒在不洁的人身上，尚且叫人成圣，身体洁净，"},{"start":14,"end":14,"text":"何况基督借着永远的灵，将自己无瑕无疵献给　神，他的血岂不更能洗净你们的心，除去你们的死行，使你们事奉那永生　神吗？"},{"start":15,"end":15,"text":"为此，他作了新约的中保，既然受死赎了人在前约之时所犯的罪过，便叫蒙召之人得着所应许永远的产业。"}],"10":[{"start":19,"end":19,"text":"弟兄们，我们既因耶稣的血得以坦然进入至圣所，"},{"start":20,"end":20,"text":"是借着他给我们开了一条又新又活的路，从幔子经过，这幔子就是他的身体。"},{"start":21,"end":21,"text":"又有一位大祭司治理　神的家，"},{"start":22,"end":22,"text":"并我们心中天良的亏欠已经洒去，身体用清水洗净了，就当存着诚心和充足的信心来到　神面前；"}],"11":[{"start":1,"end":1,"text":"信就是所望之事的实底，是未见之事的确据。"},{"start":2,"end":2,"text":"古人在这信上得了美好的证据。"},{"start":3,"end":3,"text":"我们因着信，就知道诸世界是借　神的话造成的；这样，所看见的，并不是从显然之物造出来的。"},{"start":4,"end":4,"text":"亚伯因着信，献祭与　神，比该隐所献的更美，因此便得了称义的见证，就是　神指他礼物作的见证。他虽然死了，却因这信，仍旧说话。"},{"start":5,"end":5,"text":"以诺因着信，被接去，不至于见死，人也找不着他，因为　神已经把他接去了；只是他被接去以先，已经得了　神喜悦他的明证。"},{"start":6,"end":6,"text":"人非有信，就不能得　神的喜悦；因为到　神面前来的人必须信有　神，且信他赏赐那寻求他的人。"},{"start":7,"end":7,"text":"挪亚因着信，既蒙　[神]指示他未见的事，动了敬畏的心，预备了一只方舟，使他全家得救。因此就定了那世代的罪，自己也承受了那从信而来的义。"},{"start":8,"end":8,"text":"亚伯拉罕因着信，蒙召的时候就遵命出去，往将来要得为业的地方去；出去的时候，还不知往哪里去。"},{"start":9,"end":9,"text":"他因着信，就在所应许之地作客，好像在异地居住帐棚，与那同蒙一个应许的以撒、雅各一样。"},{"start":10,"end":10,"text":"因为他等候那座有根基的城，就是　神所经营所建造的。"},{"start":11,"end":11,"text":"因着信，连撒拉自己，虽然过了生育的岁数，还能怀孕，因她以为那应许她的是可信的。"},{"start":12,"end":12,"text":"所以从一个仿佛已死的人就生出[子孙]，如同天上的星那样众多，海边的沙那样无数。"},{"start":13,"end":13,"text":"这些人都是存着信心死的，并没有得着所应许的；却从远处望见，且欢喜迎接，又承认自己在世上是客旅，是寄居的。"},{"start":14,"end":14,"text":"说这样话的人是表明自己要找一个家乡。"},{"start":15,"end":15,"text":"他们若想念所离开的家乡，还有可以回去的机会。"},{"start":16,"end":16,"text":"他们却羡慕一个更美的家乡，就是在天上的。所以　神被称为他们的　神，并不以为耻，因为他已经给他们预备了一座城。"},{"start":17,"end":17,"text":"亚伯拉罕因着信，被试验的时候，就把以撒献上；这便是那欢喜领受应许的，将自己独生的儿子献上。"},{"start":18,"end":18,"text":"[论到这儿子]，曾有话说：「从以撒生的才要称为你的后裔。」"},{"start":19,"end":19,"text":"他以为　神还能叫人从死里复活；他也仿佛从死中得回他的儿子来。"},{"start":20,"end":20,"text":"以撒因着信，就指着将来的事给雅各、以扫祝福。"},{"start":21,"end":21,"text":"雅各因着信，临死的时候，给约瑟的两个儿子各自祝福，扶着杖头敬拜　神。"},{"start":22,"end":22,"text":"约瑟因着信，临终的时候，提到以色列族将来要出[埃及]，并为自己的骸骨留下遗命。"},{"start":23,"end":23,"text":"摩西生下来，他的父母见他是个俊美的孩子，就因着信，把他藏了三个月，并不怕王命。"},{"start":24,"end":24,"text":"摩西因着信，长大了就不肯称为法老女儿之子。"},{"start":25,"end":25,"text":"他宁可和　神的百姓同受苦害，也不愿暂时享受罪中之乐。"},{"start":26,"end":26,"text":"他看为基督受的凌辱比埃及的财物更宝贵，因他想望所要得的赏赐。"},{"start":27,"end":27,"text":"他因着信，就离开埃及，不怕王怒；因为他恒心忍耐，如同看见那不能看见的[主]。"},{"start":28,"end":28,"text":"他因着信，就守逾越节，行洒血的礼，免得那灭长子的临近以色列人。"},{"start":29,"end":29,"text":"他们因着信，过红海如行干地；埃及人试着要过去，就被吞灭了。"},{"start":30,"end":30,"text":"以色列人因着信，围绕耶利哥城七日，城墙就倒塌了。"},{"start":31,"end":31,"text":"妓女喇合因着信，曾和和平平地接待探子，就不与那些不顺从的人一同灭亡。"},{"start":32,"end":32,"text":"我又何必再说呢？若要一一细说，基甸、巴拉、参孙、耶弗他、大卫、撒母耳，和众先知的事，时候就不够了。"},{"start":33,"end":33,"text":"他们因着信，制伏了敌国，行了公义，得了应许，堵了狮子的口，"},{"start":34,"end":34,"text":"灭了烈火的猛势，脱了刀剑的锋刃；软弱变为刚强，争战显出勇敢，打退外邦的全军。"},{"start":35,"end":35,"text":"有妇人得自己的死人复活。又有人忍受严刑，不肯苟且得释放，为要得着更美的复活。"},{"start":36,"end":36,"text":"又有人忍受戏弄、鞭打、捆锁、监禁、各等的磨炼，"},{"start":37,"end":37,"text":"被石头打死，被锯锯死，受试探，被刀杀，披着绵羊山羊的皮各处奔跑，受穷乏、患难、苦害，"},{"start":38,"end":38,"text":"在旷野、山岭、山洞、地穴，飘流无定，本是世界不配有的人。"},{"start":39,"end":39,"text":"这些人都是因信得了美好的证据，却仍未得着所应许的；"},{"start":40,"end":40,"text":"因为　神给我们预备了更美的事，叫他们若不与我们同得，就不能完全。"}],"12":[{"start":1,"end":1,"text":"我们既有这许多的见证人，如同云彩围着我们，就当放下各样的重担，脱去容易缠累我们的罪，存心忍耐，奔那摆在我们前头的路程，"},{"start":2,"end":2,"text":"仰望为我们信心创始成终的耶稣。他因那摆在前面的喜乐，就轻看羞辱，忍受了十字架[的苦难]，便坐在　神宝座的右边。"},{"start":3,"end":3,"text":"那忍受罪人这样顶撞的，你们要思想，免得疲倦灰心。"}],"13":[{"start":12,"end":12,"text":"所以，耶稣要用自己的血叫百姓成圣，也就在城门外受苦。"},{"start":13,"end":13,"text":"这样，我们也当出到营外，就了他去，忍受他所受的凌辱。"}]},"1KI":{"8":[{"start":41,"end":41,"text":"「论到不属你民以色列的外邦人，为你名从远方而来，"},{"start":42,"end":42,"text":"（他们听人论说你的大名和大能的手，并伸出来的膀臂）向这殿祷告，"},{"start":43,"end":43,"text":"求你在天上你的居所垂听，照着外邦人所祈求的而行，使天下万民都认识你的名，敬畏你像你的民以色列一样；又使他们知道我建造的这殿是称为你名下的。"}],"10":[{"start":1,"end":1,"text":"示巴女王听见所罗门因耶和华之名所得的名声，就来要用难解的话试问所罗门。"},{"start":2,"end":2,"text":"跟随她到耶路撒冷的人甚多，又有骆驼驮着香料、宝石，和许多金子。她来见了所罗门王，就把心里所有的对所罗门都说出来。"},{"start":3,"end":3,"text":"所罗门王将她所问的都答上了，没有一句不明白、不能答的。"},{"start":4,"end":4,"text":"示巴女王见所罗门大有智慧，和他所建造的宫室，"},{"start":5,"end":5,"text":"席上的珍馐美味，群臣分列而坐，仆人两旁侍立，以及他们的衣服装饰和酒政的[衣服装饰]，又见他上耶和华殿的台阶，就诧异得神不守舍；"},{"start":6,"end":6,"text":"对王说：「我在本国里所听见论到你的事和你的智慧实在是真的！"},{"start":7,"end":7,"text":"我先不信那些话，及至我来亲眼见了才知道人所告诉我的还不到一半。你的智慧和你的福分越过我所听见的风声。"},{"start":8,"end":8,"text":"你的臣子、你的仆人常侍立在你面前听你智慧的话是有福的！"},{"start":9,"end":9,"text":"耶和华—你的　神是应当称颂的！他喜悦你，使你坐以色列的国位；因为他永远爱以色列，所以立你作王，使你秉公行义。」"},{"start":10,"end":10,"text":"于是，示巴女王将一百二十他连得金子和宝石，与极多的香料，送给所罗门王。她送给王的香料，以后奉来的不再有这样多。"}],"12":[{"start":1,"end":1,"text":"罗波安往示剑去；因为以色列人都到了示剑要立他作王。"},{"start":2,"end":2,"text":"尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里（他听见这事。）"},{"start":3,"end":3,"text":"以色列人打发人去请他来，他就和以色列会众都来见罗波安，对他说："},{"start":4,"end":4,"text":"「你父亲使我们负重轭，[做苦工]，现在求你使我们做的苦工、负的重轭轻松些，我们就事奉你。」"},{"start":5,"end":5,"text":"罗波安对他们说：「你们暂且去，第三日再来见我。」民就去了。"},{"start":6,"end":6,"text":"罗波安之父所罗门在世的日子，有侍立在他面前的老年人，罗波安王和他们商议，说：「你们给我出个什么主意，我好回复这民。」"},{"start":7,"end":7,"text":"老年人对他说：「现在王若服事这民如仆人，用好话回答他们，他们就永远作王的仆人。」"},{"start":8,"end":8,"text":"王却不用老年人给他出的主意，就和那些与他一同长大、在他面前侍立的少年人商议，"},{"start":9,"end":9,"text":"说：「这民对我说：『你父亲使我们负重轭，求你使我们轻松些。』你们给我出个什么主意，我好回复他们。」"},{"start":10,"end":10,"text":"那同他长大的少年人说：「这民对王说：『你父亲使我们负重轭，求你使我们轻松些。』王要对他们如此说：『我的小拇指头比我父亲的腰还粗。"},{"start":11,"end":11,"text":"我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子[鞭]责打你们！』」"},{"start":12,"end":12,"text":"耶罗波安和众百姓遵着罗波安王所说「你们第三日再来见我」的那话，第三日他们果然来了。"},{"start":13,"end":13,"text":"王用严厉的话回答百姓，不用老年人给他所出的主意，"},{"start":14,"end":14,"text":"照着少年人所出的主意对民说：「我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子[鞭]责打你们！」"},{"start":15,"end":15,"text":"王不肯依从百姓，这事乃出于耶和华，为要应验他借示罗人亚希雅对尼八的儿子耶罗波安所说的话。"},{"start":16,"end":16,"text":"以色列众民见王不依从他们，就对王说： 我们与大卫有什么分儿呢？ 与耶西的儿子并没有关涉。 以色列人哪，各回各家去吧！ 大卫家啊，自己顾自己吧！ 于是，以色列人都回自己家里去了，"},{"start":17,"end":17,"text":"惟独住犹大城邑的以色列人，罗波安仍作他们的王。"},{"start":18,"end":18,"text":"罗波安王差遣掌管服苦之人的亚多兰往以色列人那里去，以色列人就用石头打死他。罗波安王急忙上车，逃回耶路撒冷去了。"},{"start":19,"end":19,"text":"这样，以色列人背叛大卫家，直到今日。"},{"start":20,"end":20,"text":"以色列众人听见耶罗波安回来了，就打发人去请他到会众面前，立他作以色列众人的王。除了犹大支派以外，没有顺从大卫家的。"}],"17":[{"start":1,"end":1,"text":"基列寄居的提斯比人以利亚对亚哈说：「我指着所事奉永生耶和华—以色列的　神起誓，这几年我若不祷告，必不降露，不下雨。」"},{"start":2,"end":2,"text":"耶和华的话临到以利亚说："},{"start":3,"end":3,"text":"「你离开这里往东去，藏在约旦河东边的基立溪旁。"},{"start":4,"end":4,"text":"你要喝那溪里的水，我已吩咐乌鸦在那里供养你。」"},{"start":5,"end":5,"text":"于是以利亚照着耶和华的话，去住在约旦河东的基立溪旁。"},{"start":6,"end":6,"text":"乌鸦早晚给他叼饼和肉来，他也喝那溪里的水。"},{"start":7,"end":7,"text":"过了些日子，溪水就干了，因为雨没有下在地上。"},{"start":8,"end":8,"text":"耶和华的话临到他说："},{"start":9,"end":9,"text":"「你起身往西顿的撒勒法去，住在那里；我已吩咐那里的一个寡妇供养你。」"},{"start":10,"end":10,"text":"以利亚就起身往撒勒法去。到了城门，见有一个寡妇在那里捡柴，以利亚呼叫她说：「求你用器皿取点水来给我喝。」"},{"start":11,"end":11,"text":"她去取水的时候，以利亚又呼叫她说：「也求你拿点饼来给我！」"},{"start":12,"end":12,"text":"她说：「我指着永生耶和华—你的　神起誓，我没有饼，坛内只有一把面，瓶里只有一点油；我现在找两根柴，回家要为我和我儿子做[饼]；我们吃了，死就死吧！」"},{"start":13,"end":13,"text":"以利亚对她说：「不要惧怕！可以照你所说的去做吧！只要先为我做一个小饼拿来给我，然后为你和你的儿子做饼。"},{"start":14,"end":14,"text":"因为耶和华—以色列的　神如此说：坛内的面必不减少，瓶里的油必不缺短，直到耶和华使雨降在地上的日子。」"},{"start":15,"end":15,"text":"妇人就照以利亚的话去行。她和她家中的人，并以利亚，吃了许多日子。"},{"start":16,"end":16,"text":"坛内的面果不减少，瓶里的油也不缺短，正如耶和华借以利亚所说的话。"},{"start":17,"end":17,"text":"这事以后，作那家主母的妇人，她儿子病了；病得甚重，以致身无气息。"},{"start":18,"end":18,"text":"妇人对以利亚说：「神人哪，我与你何干？你竟到我这里来，使　[神]想念我的罪，以致我的儿子死呢？」"},{"start":19,"end":19,"text":"以利亚对她说：「把你儿子交给我。」以利亚就从妇人怀中将孩子接过来，抱到他所住的楼中，放在自己的床上，"},{"start":20,"end":20,"text":"就求告耶和华说：「耶和华—我的　神啊，我寄居在这寡妇的家里，你就降祸与她，使她的儿子死了吗？」"},{"start":21,"end":21,"text":"以利亚三次伏在孩子的身上，求告耶和华说：「耶和华—我的　神啊，求你使这孩子的灵魂仍入他的身体！」"},{"start":22,"end":22,"text":"耶和华应允以利亚的话，孩子的灵魂仍入他的身体，他就活了。"},{"start":23,"end":23,"text":"以利亚将孩子从楼上抱下来，进屋子交给他母亲，说：「看哪，你的儿子活了！」"},{"start":24,"end":24,"text":"妇人对以利亚说：「现在我知道你是神人，耶和华借你口所说的话是真的。」"}],"19":[{"start":8,"end":8,"text":"他就起来吃了喝了，仗着这饮食的力，走了四十昼夜，到了　神的山，就是何烈山。"},{"start":9,"end":9,"text":"他在那里进了一个洞，就住在洞中。耶和华的话临到他说：「以利亚啊，你在这里做什么？」"},{"start":10,"end":10,"text":"他说：「我为耶和华—万军之　神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。」"},{"start":11,"end":11,"text":"耶和华说：「你出来站在山上，在我面前。」那时耶和华从那里经过，在他面前有烈风大作，崩山碎石，耶和华却不在风中；风后地震，耶和华却不在其中；"},{"start":12,"end":12,"text":"地震后有火，耶和华也不在火中；火后有微小的声音。"},{"start":13,"end":13,"text":"以利亚听见，就用外衣蒙上脸，出来站在洞口。有声音向他说：「以利亚啊，你在这里做什么？」"},{"start":14,"end":14,"text":"他说：「我为耶和华—万军之　神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。」"},{"start":15,"end":15,"text":"耶和华对他说：「你回去，从旷野往大马士革去。到了那里，就要膏哈薛作亚兰王，"},{"start":16,"end":16,"text":"又膏宁示的孙子耶户作以色列王，并膏亚伯·米何拉人沙法的儿子以利沙作先知接续你。"},{"start":17,"end":17,"text":"将来躲避哈薛之刀的，必被耶户所杀；躲避耶户之刀的，必被以利沙所杀。"},{"start":18,"end":18,"text":"但我在以色列人中[为自己]留下七千人，是未曾向巴力屈膝的，未曾与巴力亲嘴的。」"},{"start":19,"end":19,"text":"于是，以利亚离开那里走了，遇见沙法的儿子以利沙耕地；在他前头有十二对[牛]，自己赶着第十二对。以利亚到他那里去，将自己的外衣搭在他身上。"},{"start":20,"end":20,"text":"以利沙就离开牛，跑到以利亚那里，说：「求你容我先与父母亲嘴，然后我便跟随你。」以利亚对他说：「你回去吧，我向你做了什么呢？」"},{"start":21,"end":21,"text":"以利沙就离开他回去，宰了一对牛，用套牛的器具煮肉给民吃，随后就起身跟随以利亚，服事他。"}],"21":[{"start":1,"end":1,"text":"这事以后，又有一事。耶斯列人拿伯在耶斯列有一个葡萄园，靠近撒马利亚王亚哈的宫。"},{"start":2,"end":2,"text":"亚哈对拿伯说：「你将你的葡萄园给我作菜园，因为是靠近我的宫；我就把更好的葡萄园换给你，或是你要银子，我就按着价值给你。」"},{"start":3,"end":3,"text":"拿伯对亚哈说：「我敬畏耶和华，万不敢将我先人留下的产业给你。」"},{"start":4,"end":4,"text":"亚哈因耶斯列人拿伯说「我不敢将我先人留下的产业给你」，就闷闷不乐地回宫，躺在床上，转脸向内，也不吃饭。"},{"start":5,"end":5,"text":"王后耶洗别来问他说：「你为什么心里这样忧闷，不吃饭呢？」"},{"start":6,"end":6,"text":"他回答说：「因我向耶斯列人拿伯说：『你将你的葡萄园给我，我给你价银，或是你愿意，我就把[别的]葡萄园换给你』；他却说：『我不将我的葡萄园给你。』」"},{"start":7,"end":7,"text":"王后耶洗别对亚哈说：「你现在是治理以色列国不是？只管起来，心里畅畅快快地吃饭，我必将耶斯列人拿伯的葡萄园给你。」"},{"start":8,"end":8,"text":"于是托亚哈的名写信，用王的印印上，送给那些与拿伯同城居住的长老贵胄。"},{"start":9,"end":9,"text":"信上写着说：「你们当宣告禁食，叫拿伯坐在民间的高位上，"},{"start":10,"end":10,"text":"又叫两个匪徒坐在拿伯对面，作见证告他说：『你谤渎　神和王了』；随后就把他拉出去用石头打死。」"},{"start":11,"end":11,"text":"那些与拿伯同城居住的长老贵胄得了耶洗别的信，就照信而行，"},{"start":12,"end":12,"text":"宣告禁食，叫拿伯坐在民间的高位上。"},{"start":13,"end":13,"text":"有两个匪徒来，坐在拿伯的对面，当着众民作见证告他说：「拿伯谤渎　神和王了！」众人就把他拉到城外，用石头打死。"},{"start":14,"end":14,"text":"于是打发人去见耶洗别，说：「拿伯被石头打死了。」"},{"start":15,"end":15,"text":"耶洗别听见拿伯被石头打死，就对亚哈说：「你起来得耶斯列人拿伯不肯为价银给你的葡萄园吧！现在他已经死了。」"},{"start":16,"end":16,"text":"亚哈听见拿伯死了，就起来，下去要得耶斯列人拿伯的葡萄园。"}]},"2KI":{"1":[{"start":9,"end":9,"text":"于是，王差遣五十夫长，带领五十人去见以利亚，他就上到以利亚那里；以利亚正坐在山顶上。五十夫长对他说：「神人哪，王吩咐你下来！」"},{"start":10,"end":10,"text":"以利亚回答说：「我若是神人，愿火从天上降下来，烧灭你和你那五十人！」于是有火从天上降下来，烧灭五十夫长和他那五十人。"},{"start":11,"end":11,"text":"王第二次差遣一个五十夫长，带领五十人去见以利亚。五十夫长对以利亚说：「神人哪，王吩咐你快快下来！」"},{"start":12,"end":12,"text":"以利亚回答说：「我若是神人，愿火从天上降下来，烧灭你和你那五十人！」于是　神的火从天上降下来，烧灭五十夫长和他那五十人。"},{"start":13,"end":13,"text":"王第三次差遣一个五十夫长，带领五十人去。这五十夫长上去，双膝跪在以利亚面前，哀求他说：「神人哪，愿我的性命和你这五十个仆人的性命在你眼前看为宝贵！"},{"start":14,"end":14,"text":"已经有火从天上降下来，烧灭前两次来的五十夫长和他们各自带的五十人；现在愿我的性命在你眼前看为宝贵！」"},{"start":15,"end":15,"text":"耶和华的使者对以利亚说：「你同着他下去，不要怕他！」以利亚就起来，同着他下去见王，"},{"start":16,"end":16,"text":"对王说：「耶和华如此说：『你差人去问以革伦神巴力·西卜，岂因以色列中没有　神可以求问吗？所以你必不下所上的床，必定要死！』」"}],"2":[{"start":9,"end":9,"text":"过去之后，以利亚对以利沙说：「我未曾被接去离开你，你要我为你做什么，只管求我。」以利沙说：「愿[感动]你的灵加倍地感动我。」"},{"start":10,"end":10,"text":"以利亚说：「你所求的难得。[虽然如此]，我被接去离开你的时候，你若看见我，就必得着；不然，必得不着了。」"},{"start":11,"end":11,"text":"他们正走着说话，忽有火车火马将二人隔开，以利亚就乘旋风升天去了。"},{"start":12,"end":12,"text":"以利沙看见，就呼叫说：「我父啊！我父啊！以色列的战车马兵啊！」以后不再见他了。于是以利沙把自己的衣服撕为两片。"},{"start":13,"end":13,"text":"他拾起以利亚身上掉下来的外衣，回去站在约旦河边。"},{"start":14,"end":14,"text":"他用以利亚身上掉下来的外衣打水，说：「耶和华—以利亚的　神在哪里呢？」打水之后，水也左右分开，以利沙就过来了。"},{"start":15,"end":15,"text":"住耶利哥的先知门徒从对面看见他，就说：「[感动]以利亚的灵感动以利沙了。」他们就来迎接他，在他面前俯伏于地，"}],"4":[{"start":8,"end":8,"text":"一日，以利沙走到书念，在那里有一个大户的妇人强留他吃饭。此后，以利沙每从那里经过就进去吃饭。"},{"start":9,"end":9,"text":"妇人对丈夫说：「我看出那常从我们这里经过的是圣洁的神人。"},{"start":10,"end":10,"text":"我们可以为他在墙上盖一间小楼，在其中安放床榻、桌子、椅子、灯台，他来到我们这里，就可以住在其间。」"},{"start":18,"end":18,"text":"孩子渐渐长大，一日到他父亲和收割的人那里，"},{"start":19,"end":19,"text":"他对父亲说：「我的头啊，我的头啊！」他父亲对仆人说：「把他抱到他母亲那里。」"},{"start":20,"end":20,"text":"仆人抱去，交给他母亲；孩子坐在母亲的膝上，到晌午就死了。"},{"start":21,"end":21,"text":"他母亲抱他上了楼，将他放在神人的床上，关上[门]出来，"},{"start":22,"end":22,"text":"呼叫她丈夫说：「你叫一个仆人给我牵一匹驴来，我要快快地去见神人，就回来。」"},{"start":23,"end":23,"text":"丈夫说：「今日不是月朔，也不是安息日，你为何要去见他呢？」妇人说：「平安无事。」"},{"start":24,"end":24,"text":"于是备上驴，对仆人说：「你快快赶着走，我若不吩咐你，就不要迟慢。」"},{"start":25,"end":25,"text":"妇人就往迦密山去见神人。 神人远远地看见她，对仆人基哈西说：「看哪，书念的妇人来了！"},{"start":26,"end":26,"text":"你跑去迎接她，问她说：你平安吗？你丈夫平安吗？孩子平安吗？」她说：「平安。」"},{"start":27,"end":27,"text":"妇人上了山，到神人那里，就抱住神人的脚。基哈西前来要推开她，神人说：「由她吧！因为她心里愁苦，耶和华向我隐瞒，没有指示我。」"},{"start":28,"end":28,"text":"妇人说：「我何尝向我主求过儿子呢？我岂没有说过，不要欺哄我吗？」"},{"start":29,"end":29,"text":"以利沙吩咐基哈西说：「你束上腰，手拿我的杖前去；若遇见人，不要向他问安；人若向你问安，也不要回答；要把我的杖放在孩子脸上。」"},{"start":30,"end":30,"text":"孩子的母亲说：「我指着永生的耶和华，又敢在你面前起誓，我必不离开你。」于是以利沙起身，随着她去了。"},{"start":31,"end":31,"text":"基哈西先去，把杖放在孩子脸上，却没有声音，也没有动静。基哈西就迎着以利沙回来，告诉他说：「孩子还没有醒过来。」"},{"start":32,"end":32,"text":"以利沙来到，进了屋子，看见孩子死了，放在自己的床上。"},{"start":33,"end":33,"text":"他就关上门，只有自己和孩子在里面，他便祈祷耶和华，"},{"start":34,"end":34,"text":"上床伏在孩子身上，口对口，眼对眼，手对手；既伏在孩子身上，孩子的身体就渐渐温和了。"},{"start":35,"end":35,"text":"然后他下来，在屋里来往走了一趟，又上去伏在孩子身上，孩子打了七个喷嚏，就睁开眼睛了。"},{"start":36,"end":36,"text":"以利沙叫基哈西说：「你叫这书念妇人来」；于是叫了她来。以利沙说：「将你儿子抱起来。」"},{"start":37,"end":37,"text":"妇人就进来，在以利沙脚前俯伏于地，抱起她儿子出去了。"},{"start":42,"end":42,"text":"有一个人从巴力·沙利沙来，带着初熟大麦做的饼二十个，并新穗子，装在口袋里送给神人。神人说：「把这些给众人吃。」"},{"start":43,"end":43,"text":"仆人说：「这一点岂可摆给一百人吃呢？」以利沙说：「你只管给众人吃吧！因为耶和华如此说，众人必吃了，还剩下。」"},{"start":44,"end":44,"text":"仆人就摆在众人面前，他们吃了，果然还剩下，正如耶和华所说的。"}],"5":[{"start":1,"end":1,"text":"亚兰王的元帅乃缦在他主人面前为尊为大，因耶和华曾借他使亚兰人得胜；他又是大能的勇士，只是长了大麻风。"},{"start":2,"end":2,"text":"先前亚兰人成群地出去，从以色列国掳了一个小女子，这女子就服事乃缦的妻。"},{"start":3,"end":3,"text":"她对主母说：「巴不得我主人去见撒马利亚的先知，必能治好他的大麻风。」"},{"start":4,"end":4,"text":"乃缦进去，告诉他主人说，以色列国的女子如此如此说。"},{"start":5,"end":5,"text":"亚兰王说：「你可以去，我也达信于以色列王。」于是乃缦带银子十他连得，金子六千[舍客勒]，衣裳十套，就去了；"},{"start":6,"end":6,"text":"且带信给以色列王，信上说：「我打发臣仆乃缦去见你，你接到这信，就要治好他的大麻风。」"},{"start":7,"end":7,"text":"以色列王看了信就撕裂衣服，说：「我岂是　神，能使人死使人活呢？这人竟打发人来，叫我治好他的大麻风。你们看一看，这人何以寻隙攻击我呢？」"},{"start":8,"end":8,"text":"神人以利沙听见以色列王撕裂衣服，就打发人去见王，说：「你为什么撕了衣服呢？可使那人到我这里来，他就知道以色列中有先知了。」"},{"start":9,"end":9,"text":"于是，乃缦带着车马到了以利沙的家，站在门前。"},{"start":10,"end":10,"text":"以利沙打发一个使者，对乃缦说：「你去在约旦河中沐浴七回，你的肉就必复原，而得洁净。」"},{"start":11,"end":11,"text":"乃缦却发怒走了，说：「我想他必定出来见我，站着求告耶和华—他　神的名，在患处以上摇手，治好这大麻风。"},{"start":12,"end":12,"text":"大马士革的河亚罢拿和法珥法岂不比以色列的一切水更好吗？我在那里沐浴不得洁净吗？」于是气忿忿地转身去了。"},{"start":13,"end":13,"text":"他的仆人进前来，对他说：「我父啊，先知若吩咐你做一件大事，你岂不做吗？何况说你去沐浴而得洁净呢？」"},{"start":14,"end":14,"text":"于是乃缦下去，照着神人的话，在约旦河里沐浴七回；他的肉复原，好像小孩子的肉，他就洁净了。"},{"start":15,"end":15,"text":"乃缦带着一切跟随他的人，回到神人那里，站在他面前，说：「如今我知道，除了以色列之外，普天下没有　神。现在求你收点仆人的礼物。」"},{"start":16,"end":16,"text":"以利沙说：「我指着所事奉永生的耶和华起誓，我必不受。」乃缦再三地求他，他却不受。"},{"start":17,"end":17,"text":"乃缦说：「你若不肯受，请将两骡子驮的土赐给仆人。从今以后，仆人必不再将燔祭或[平安]祭献与别神，只献给耶和华。"},{"start":18,"end":18,"text":"惟有一件事，愿耶和华饶恕你仆人：我主人进临门庙叩拜的时候，我用手搀他在临门庙，我也屈身。我在临门庙屈身的这事，愿耶和华饶恕我。」"},{"start":19,"end":19,"text":"以利沙对他说：「你可以平平安安地回去！」 乃缦就离开他去了；走了不远，"}],"9":[{"start":13,"end":13,"text":"他们就急忙各将自己的衣服铺在上层台阶，使耶户坐在其上；他们吹角，说：「耶户作王了！」"},{"start":14,"end":14,"text":"这样，宁示的孙子、约沙法的儿子耶户背叛约兰。先是约兰和以色列众人因为亚兰王哈薛的缘故，把守基列的拉末；"},{"start":15,"end":15,"text":"但约兰王回到耶斯列，医治与亚兰王哈薛打仗所受的伤。耶户说：「若合你们的意思，就不容人逃出城往耶斯列报信去。」"},{"start":16,"end":16,"text":"于是耶户坐车往耶斯列去，因为约兰病卧在那里。犹大王亚哈谢已经下去看望他。"},{"start":17,"end":17,"text":"有一个守望的人站在耶斯列的楼上，看见耶户带着一群人来，就说：「我看见一群人。」约兰说：「打发一个骑马的去迎接他们，问说：平安不平安？」"},{"start":18,"end":18,"text":"骑马的就去迎接耶户，说：「王问说，平安不平安？」耶户说：「平安不平安与你何干？你转在我后头吧！」守望的人又说：「使者到了他们那里，却不回来。」"},{"start":19,"end":19,"text":"王又打发一个骑马的去。这人到了他们那里，说：「王问说，平安不平安？」耶户说：「平安不平安与你何干？你转在我后头吧！」"},{"start":20,"end":20,"text":"守望的人又说：「他到了他们那里，也不回来；车赶得甚猛，像宁示的孙子耶户的赶法。」"},{"start":21,"end":21,"text":"约兰吩咐说：「套车！」人就给他套车。以色列王约兰和犹大王亚哈谢各坐自己的车出去迎接耶户，在耶斯列人拿伯的田那里遇见他。"},{"start":22,"end":22,"text":"约兰见耶户就说：「耶户啊，平安吗？」耶户说：「你母亲耶洗别的淫行邪术这样多，焉能平安呢？」"},{"start":23,"end":23,"text":"约兰就转车逃跑，对亚哈谢说：「亚哈谢啊，反了！」"},{"start":24,"end":24,"text":"耶户开满了弓，射中约兰的脊背，箭从心窝穿出，约兰就仆倒在车上。"},{"start":25,"end":25,"text":"耶户对他的军长毕甲说：「你把他抛在耶斯列人拿伯的田间。你当追想，你我一同坐车跟随他父亚哈的时候，耶和华对亚哈所说的预言，"},{"start":26,"end":26,"text":"说：『我昨日看见拿伯的血和他众子的血，我必在这块田上报应你。』这是耶和华说的，现在你要照着耶和华的话，把他抛在这田间。」"},{"start":27,"end":27,"text":"犹大王亚哈谢见这光景，就从园亭之路逃跑。耶户追赶他，说：「把这人也杀在车上。」到了靠近以伯莲姑珥的坡上[击伤了他]。他逃到米吉多，就死在那里。"},{"start":28,"end":28,"text":"他的臣仆用车将他的尸首送到耶路撒冷，葬在大卫城他自己的坟墓里，与他列祖同葬。"},{"start":29,"end":29,"text":"亚哈谢登基作犹大王的时候，是在亚哈的儿子约兰第十一年。"},{"start":30,"end":30,"text":"耶户到了耶斯列；耶洗别听见就擦粉、梳头，从窗户里往外观看。"},{"start":31,"end":31,"text":"耶户进门的时候，耶洗别说：「杀主人的心利啊，平安吗？」"},{"start":32,"end":32,"text":"耶户抬头向窗户观看，说：「谁顺从我？」有两三个太监从窗户往外看他。"},{"start":33,"end":33,"text":"耶户说：「把她扔下来！」他们就把她扔下来。她的血溅在墙上和马上；于是把她践踏了。"},{"start":34,"end":34,"text":"耶户进去，吃了喝了，吩咐说：「你们把这被咒诅的妇人葬埋了，因为她是王的女儿。」"},{"start":35,"end":35,"text":"他们就去葬埋她，只寻得她的头骨和脚，并手掌。"},{"start":36,"end":36,"text":"他们回去告诉耶户，耶户说：「这正应验耶和华借他仆人提斯比人以利亚所说的话，说：『在耶斯列田间，狗必吃耶洗别的肉；"},{"start":37,"end":37,"text":"耶洗别的尸首必在耶斯列田间如同粪土，甚至人不能说这是耶洗别。』」"}]},"MAR":{"1":[{"start":21,"end":21,"text":"到了迦百农，耶稣就在安息日进了会堂教训人。"},{"start":22,"end":22,"text":"众人很希奇他的教训；因为他教训他们，正像有权柄的人，不像文士。"},{"start":23,"end":23,"text":"在会堂里，有一个人被污鬼附着。他喊叫说："},{"start":24,"end":24,"text":"「拿撒勒人耶稣，我们与你有什么相干？你来灭我们吗？我知道你是谁，乃是　神的圣者。」"},{"start":25,"end":25,"text":"耶稣责备他说：「不要作声！从这人身上出来吧。」"},{"start":26,"end":26,"text":"污鬼叫那人抽了一阵风，大声喊叫，就出来了。"},{"start":27,"end":27,"text":"众人都惊讶，以致彼此对问说：「这是什么事？是个新道理啊！他用权柄吩咐污鬼，连污鬼也听从了他。」"},{"start":28,"end":28,"text":"耶稣的名声就传遍了加利利的四方。"},{"start":29,"end":29,"text":"他们一出会堂，就同着雅各、约翰，进了西门和安得烈的家。"},{"start":30,"end":30,"text":"西门的岳母正害热病躺着，就有人告诉耶稣。"},{"start":31,"end":31,"text":"耶稣进前拉着她的手，扶她起来，热就退了，她就服事他们。"},{"start":32,"end":32,"text":"天晚日落的时候，有人带着一切害病的，和被鬼附的，来到耶稣跟前。"},{"start":33,"end":33,"text":"合城的人都聚集在门前。"},{"start":34,"end":34,"text":"耶稣治好了许多害各样病的人，又赶出许多鬼，不许鬼说话，因为鬼认识他。"},{"start":35,"end":35,"text":"次日早晨，天未亮的时候，耶稣起来，到旷野地方去，在那里祷告。"},{"start":36,"end":36,"text":"西门和同伴追了他去，"},{"start":37,"end":37,"text":"遇见了就对他说：「众人都找你。」"},{"start":38,"end":38,"text":"耶稣对他们说：「我们可以往别处去，到邻近的乡村，我也好在那里传道，因为我是为这事出来的。」"},{"start":39,"end":39,"text":"于是在加利利全地，进了会堂，传道，赶鬼。"}],"2":[{"start":13,"end":13,"text":"耶稣又出到海边去，众人都就了他来，他便教训他们。"},{"start":14,"end":14,"text":"耶稣经过的时候，看见亚勒腓的儿子利未坐在税关上，就对他说：「你跟从我来。」他就起来，跟从了耶稣。"},{"start":15,"end":15,"text":"耶稣在利未家里坐席的时候，有好些税吏和罪人与耶稣并门徒一同坐席；因为这样的人多，他们也跟随耶稣。"},{"start":16,"end":16,"text":"法利赛人中的文士看见耶稣和罪人并税吏一同吃饭，就对他门徒说：「他和税吏并罪人一同吃喝吗？」"},{"start":17,"end":17,"text":"耶稣听见，就对他们说：「康健的人用不着医生，有病的人才用得着。我来本不是召义人，乃是召罪人。」"}],"4":[{"start":1,"end":1,"text":"耶稣又在海边教训人。有许多人到他那里聚集，他只得上船坐下。船在海里，众人都靠近海，站在岸上。"},{"start":2,"end":2,"text":"耶稣就用比喻教训他们许多道理。在教训之间，对他们说："},{"start":3,"end":3,"text":"「你们听啊！有一个撒种的出去撒种。"},{"start":4,"end":4,"text":"撒的时候，有落在路旁的，飞鸟来吃尽了；"},{"start":5,"end":5,"text":"有落在土浅石头地上的，土既不深，发苗最快，"},{"start":6,"end":6,"text":"日头出来一晒，因为没有根，就枯干了；"},{"start":7,"end":7,"text":"有落在荆棘里的，荆棘长起来，把它挤住了，就不结实；"},{"start":8,"end":8,"text":"又有落在好土里的，就发生长大，结实有三十倍的，有六十倍的，有一百倍的」；"},{"start":9,"end":9,"text":"又说：「有耳可听的，就应当听！」"},{"start":10,"end":10,"text":"无人的时候，跟随耶稣的人和十二个门徒问他这比喻的意思。"},{"start":11,"end":11,"text":"耶稣对他们说：「　神国的奥秘只叫你们知道，若是对外人讲，凡事就用比喻，"},{"start":12,"end":12,"text":"叫他们 看是看见，却不晓得； 听是听见，却不明白； 恐怕他们回转过来，就得赦免。」"},{"start":13,"end":13,"text":"又对他们说：「你们不明白这比喻吗？这样怎能明白一切的比喻呢？"},{"start":14,"end":14,"text":"撒种之人所撒的就是道。"},{"start":15,"end":15,"text":"那撒在路旁的，就是人听了道，撒但立刻来，把撒在他心里的道夺了去。"},{"start":16,"end":16,"text":"那撒在石头地上的，就是人听了道，立刻欢喜领受，"},{"start":17,"end":17,"text":"但他心里没有根，不过是暂时的，及至为道遭了患难，或是受了逼迫，立刻就跌倒了。"},{"start":18,"end":18,"text":"还有那撒在荆棘里的，就是人听了道，"},{"start":19,"end":19,"text":"后来有世上的思虑、钱财的迷惑，和别样的私欲进来，把道挤住了，就不能结实。"},{"start":20,"end":20,"text":"那撒在好地上的，就是人听道，又领受，并且结实，有三十倍的，有六十倍的，有一百倍的。」"},{"start":35,"end":35,"text":"当那天晚上，耶稣对门徒说：「我们渡到那边去吧。」"},{"start":36,"end":36,"text":"门徒离开众人，耶稣仍在船上，他们就把他一同带去；也有别的船和他同行。"},{"start":37,"end":37,"text":"忽然起了暴风，波浪打入船内，甚至船要满了水。"},{"start":38,"end":38,"text":"耶稣在船尾上，枕着枕头睡觉。门徒叫醒了他，说：「夫子！我们丧命，你不顾吗？」"},{"start":39,"end":39,"text":"耶稣醒了，斥责风，向海说：「住了吧！静了吧！」风就止住，大大地平静了。"},{"start":40,"end":40,"text":"耶稣对他们说：「为什么胆怯？你们还没有信心吗？」"},{"start":41,"end":41,"text":"他们就大大地惧怕，彼此说：「这到底是谁，连风和海也听从他了。」"}],"5":[{"start":21,"end":21,"text":"耶稣坐船又渡到那边去，就有许多人到他那里聚集；他正在海边上。"},{"start":22,"end":22,"text":"有一个管会堂的人，名叫睚鲁，来见耶稣，就俯伏在他脚前，"},{"start":23,"end":23,"text":"再三地求他，说：「我的小女儿快要死了，[求你]去按手在她身上，使她痊愈，得以活了。」"},{"start":24,"end":24,"text":"耶稣就和他同去。 有许多人跟随拥挤他。"},{"start":25,"end":25,"text":"有一个女人，患了十二年的血漏，"},{"start":26,"end":26,"text":"在好些医生手里受了许多的苦，又花尽了她所有的，一点也不见好，病势反倒更重了。"},{"start":27,"end":27,"text":"她听见耶稣的事，就从后头来，杂在众人中间，摸耶稣的衣裳，"},{"start":28,"end":28,"text":"意思说：「我只摸他的衣裳，就必痊愈。」"},{"start":29,"end":29,"text":"于是她血漏的源头立刻干了；她便觉得身上的灾病好了。"},{"start":30,"end":30,"text":"耶稣顿时心里觉得有能力从自己身上出去，就在众人中间转过来，说：「谁摸我的衣裳？」"},{"start":31,"end":31,"text":"门徒对他说：「你看众人拥挤你，还说『谁摸我』吗？」"},{"start":32,"end":32,"text":"耶稣周围观看，要见做这事的女人。"},{"start":33,"end":33,"text":"那女人知道在自己身上所成的事，就恐惧战兢，来俯伏在耶稣跟前，将实情全告诉他。"},{"start":34,"end":34,"text":"耶稣对她说：「女儿，你的信救了你，平平安安地回去吧！你的灾病痊愈了。」"},{"start":35,"end":35,"text":"还说话的时候，有人从管会堂的家里来，说：「你的女儿死了，何必还劳动先生呢？」"},{"start":36,"end":36,"text":"耶稣听见所说的话，就对管会堂的说：「不要怕，只要信！」"},{"start":37,"end":37,"text":"于是带着彼得、雅各，和雅各的兄弟约翰同去，不许别人跟随他。"},{"start":38,"end":38,"text":"他们来到管会堂的家里；耶稣看见那里乱嚷，并有人大大地哭泣哀号，"},{"start":39,"end":39,"text":"进到里面，就对他们说：「为什么乱嚷哭泣呢？孩子不是死了，是睡着了。」"},{"start":40,"end":40,"text":"他们就嗤笑耶稣。耶稣把他们都撵出去，就带着孩子的父母和跟随的人进了孩子所在的地方，"},{"start":41,"end":41,"text":"就拉着孩子的手，对她说：「大利大，古米！」（翻出来就是说：「闺女，我吩咐你起来！」）"},{"start":42,"end":42,"text":"那闺女立时起来走。他们就大大地惊奇；闺女已经十二岁了。"},{"start":43,"end":43,"text":"耶稣切切地嘱咐他们，不要叫人知道这事，又吩咐给她东西吃。"}],"9":[{"start":33,"end":33,"text":"他们来到迦百农。耶稣在屋里问门徒说：「你们在路上议论的是什么？」"},{"start":34,"end":34,"text":"门徒不作声，因为他们在路上彼此争论谁为大。"},{"start":35,"end":35,"text":"耶稣坐下，叫十二个门徒来，说：「若有人愿意作首先的，他必作众人末后的，作众人的用人。」"},{"start":36,"end":36,"text":"于是领过一个小孩子来，叫他站在门徒中间，又抱起他来，对他们说："},{"start":37,"end":37,"text":"「凡为我名接待一个像这小孩子的，就是接待我；凡接待我的，不是接待我，乃是接待那差我来的。」"},{"start":38,"end":38,"text":"约翰对耶稣说：「夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不跟从我们。」"},{"start":39,"end":39,"text":"耶稣说：「不要禁止他；因为没有人奉我名行异能，反倒轻易毁谤我。"},{"start":40,"end":40,"text":"不敌挡我们的，就是帮助我们的。"},{"start":41,"end":41,"text":"凡因你们是属基督，给你们一杯水喝的，我实在告诉你们，他不能不得赏赐。」"}],"10":[{"start":13,"end":13,"text":"有人带着小孩子来见耶稣，要耶稣摸他们，门徒便责备那些人。"},{"start":14,"end":14,"text":"耶稣看见就恼怒，对门徒说：「让小孩子到我这里来，不要禁止他们；因为在　神国的，正是这样的人。"},{"start":15,"end":15,"text":"我实在告诉你们，凡要承受　神国的，若不像小孩子，断不能进去。」"},{"start":16,"end":16,"text":"于是抱着小孩子，给他们按手，为他们祝福。"}],"12":[{"start":41,"end":41,"text":"耶稣对银库坐着，看众人怎样投钱入库。有好些财主往里投了若干的钱。"},{"start":42,"end":42,"text":"有一个穷寡妇来，往里投了两个小钱，就是一个大钱。"},{"start":43,"end":43,"text":"耶稣叫门徒来，说：「我实在告诉你们，这穷寡妇投入库里的，比众人所投的更多。"},{"start":44,"end":44,"text":"因为，他们都是自己有余，拿出来投在里头；但这寡妇是自己不足，把她一切养生的都投上了。」"}]},"JER":{"4":[{"start":3,"end":3,"text":"耶和华对犹大和耶路撒冷人如此说： 要开垦你们的荒地， 不要撒种在荆棘中。"},{"start":4,"end":4,"text":"犹大人和耶路撒冷的居民哪， 你们当自行割礼，归耶和华， 将心里的污秽除掉； 恐怕我的忿怒因你们的恶行发作， 如火着起， 甚至无人能以熄灭！"},{"start":5,"end":5,"text":"你们当传扬在犹大， 宣告在耶路撒冷说： 你们当在国中吹角，高声呼叫说： 你们当聚集！ 我们好进入坚固城！"},{"start":6,"end":6,"text":"应当向锡安竖立大旗。 要逃避，不要迟延， 因我必使灾祸与大毁灭从北方来到。"},{"start":7,"end":7,"text":"有狮子从密林中上来， 是毁坏列国的。 它已经动身出离本处， 要使你的地荒凉， 使你的城邑变为荒场无人居住。"},{"start":8,"end":8,"text":"因此，你们当腰束麻布，大声哀号， 因为耶和华的烈怒没有向我们转消。"},{"start":9,"end":9,"text":"耶和华说：「到那时，君王和首领的心都要消灭；祭司都要惊奇，先知都要诧异。」"},{"start":10,"end":10,"text":"我说：「哀哉！主耶和华啊，你真是大大地欺哄这百姓和耶路撒冷，说：『你们必得平安。』其实刀剑害及性命了。」"},{"start":11,"end":11,"text":"那时，必有话对这百姓和耶路撒冷说：「有一阵热风从旷野净光的高处向我的众民刮来，不是为簸扬，也不是为扬净。"},{"start":12,"end":12,"text":"必有一阵更大的风从这些地方为我刮来；现在我又必发出判语，攻击他们。」"},{"start":13,"end":13,"text":"看哪，仇敌必如云上来； 他的战车如旋风， 他的马匹比鹰更快。 我们有祸了！ 我们败落了！"},{"start":14,"end":14,"text":"耶路撒冷啊，你当洗去心中的恶， 使你可以得救。 恶念存在你心里要到几时呢？"},{"start":15,"end":15,"text":"有声音从但传扬， 从以法莲山报祸患。"},{"start":16,"end":16,"text":"你们当传给列国， 报告攻击耶路撒冷的事说： 有探望的人从远方来到， 向犹大的城邑大声呐喊。"},{"start":17,"end":17,"text":"他们周围攻击耶路撒冷， 好像看守田园的， 因为她背叛了我。 这是耶和华说的。"},{"start":18,"end":18,"text":"你的行动，你的作为，招惹这事； 这是你罪恶的结果， 实在是苦， 是害及你心了！"},{"start":19,"end":19,"text":"我的肺腑啊，我的肺腑啊，我心疼痛！ 我心在我里面烦躁不安。 我不能静默不言， 因为我已经听见角声和打仗的喊声。"},{"start":20,"end":20,"text":"毁坏的信息连络不绝， 因为全地荒废。 我的帐棚忽然毁坏； 我的幔子顷刻破裂。"},{"start":21,"end":21,"text":"我看见大旗，听见角声， 要到几时呢？"},{"start":22,"end":22,"text":"[耶和华说]：我的百姓愚顽，不认识我； 他们是愚昧无知的儿女， 有智慧行恶，没有知识行善。"},{"start":23,"end":23,"text":"[先知说]：我观看地， 不料，地是空虚混沌； 我观看天，天也无光。"},{"start":24,"end":24,"text":"我观看大山，不料，尽都震动， 小山也都摇来摇去。"},{"start":25,"end":25,"text":"我观看，不料，无人； 空中的飞鸟也都躲避。"},{"start":26,"end":26,"text":"我观看，不料，肥田变为荒地； 一切城邑在耶和华面前， 因他的烈怒都被拆毁。"},{"start":27,"end":27,"text":"耶和华如此说：全地必然荒凉， 我却不毁灭净尽。"},{"start":28,"end":28,"text":"因此，地要悲哀， 在上的天也必黑暗； 因为我言已出，我意已定， 必不后悔，也不转意不做。"},{"start":29,"end":29,"text":"各城的人因马兵和弓箭手的响声就都逃跑， 进入密林，爬上磐石； 各城被撇下， 无人住在其中。"},{"start":30,"end":30,"text":"你凄凉的时候要怎样行呢？ 你虽穿上朱红[衣服]， 佩戴黄金装饰， 用颜料修饰眼目， 这样标致是枉然的！ 恋爱[你的]藐视你， 并且寻索你的性命。"},{"start":31,"end":31,"text":"我听见有声音，仿佛妇人产难的声音， 好像生头胎疼痛[的声音]， 是锡安女子的声音； 她喘着气、挓挲手， [说]：我有祸了！ 在杀人的跟前，我的心发昏了。"}],"7":[{"start":1,"end":1,"text":"耶和华的话临到耶利米说："},{"start":2,"end":2,"text":"「你当站在耶和华殿的门口，在那里宣传这话说：你们进这些门敬拜耶和华的一切犹大人，当听耶和华的话。"},{"start":3,"end":3,"text":"万军之耶和华—以色列的　神如此说：你们改正行动作为，我就使你们在这地方仍然居住。"},{"start":4,"end":4,"text":"你们不要倚靠虚谎的话，说：『这些是耶和华的殿，是耶和华的殿，是耶和华的殿！』"},{"start":5,"end":5,"text":"「你们若实在改正行动作为，在人和邻舍中间诚然施行公平，"},{"start":6,"end":6,"text":"不欺压寄居的和孤儿寡妇，在这地方不流无辜人的血，也不随从别神陷害自己，"},{"start":7,"end":7,"text":"我就使你们在这地方仍然居住，就是我古时所赐给你们列祖的地，直到永远。"},{"start":8,"end":8,"text":"「看哪，你们倚靠虚谎无益的话。"},{"start":9,"end":9,"text":"你们偷盗，杀害，奸淫，起假誓，向巴力烧香，并随从素不认识的别神，"},{"start":10,"end":10,"text":"且来到这称为我名下的殿，在我面前敬拜；又说：『我们可以自由了。』你们这样的举动是要行那些可憎的事吗？"},{"start":11,"end":11,"text":"这称为我名下的殿在你们眼中岂可看为贼窝吗？我都看见了。这是耶和华说的。"},{"start":12,"end":12,"text":"你们且往示罗去，就是我先前立为我名的居所，察看我因这百姓以色列的罪恶向那地所行的如何。」"},{"start":13,"end":13,"text":"耶和华说：「现在因你们行了这一切的事，我也从早起来警戒你们，你们却不听从；呼唤你们，你们却不答应。"},{"start":14,"end":14,"text":"所以我要向这称为我名下、你们所倚靠的殿，与我所赐给你们和你们列祖的地施行，照我从前向示罗所行的一样。"},{"start":15,"end":15,"text":"我必将你们从我眼前赶出，正如赶出你们的众弟兄，就是以法莲的一切后裔。」"},{"start":23,"end":23,"text":"我只吩咐他们这一件说：『你们当听从我的话，我就作你们的　神，你们也作我的子民。你们行我所吩咐的一切道，就可以得福。』"},{"start":24,"end":24,"text":"他们却不听从，不侧耳而听，竟随从[自己]的计谋和顽梗的恶心，向后不向前。"},{"start":25,"end":25,"text":"自从你们列祖出埃及地的那日，直到今日，我差遣我的仆人众先知到你们那里去，每日从早起来差遣他们。"},{"start":26,"end":26,"text":"你们却不听从，不侧耳而听，竟硬着颈项行恶，比你们列祖更甚。"},{"start":27,"end":27,"text":"「你要将这一切的话告诉他们，他们却不听从；呼唤他们，他们却不答应。"},{"start":28,"end":28,"text":"你要对他们说：这就是不听从耶和华—他们　神的话、不受教训的国民；从他们的口中，诚实灭绝了。」"}],"8":[{"start":7,"end":7,"text":"空中的鹳鸟知道[来去的]定期； 斑鸠燕子与白鹤也守候当来的时令； 我的百姓却不知道耶和华的法则。"},{"start":8,"end":8,"text":"你们怎么说：我们有智慧， 耶和华的律法在我们这里？ 看哪，文士的假笔舞弄虚假。"},{"start":9,"end":9,"text":"智慧人惭愧，惊惶，被擒拿； 他们弃掉耶和华的话， 心里还有什么智慧呢？"},{"start":10,"end":10,"text":"所以我必将他们的妻子给别人， 将他们的田地给别人为业； 因为他们从最小的到至大的都一味地贪婪， 从先知到祭司都行事虚谎。"},{"start":11,"end":11,"text":"他们轻轻忽忽地医治我百姓的损伤，说： 平安了！平安了！ 其实没有平安。"},{"start":12,"end":12,"text":"他们行可憎的事知道惭愧吗？ 不然，他们毫不惭愧， 也不知羞耻。 因此他们必在仆倒的人中仆倒； 我向他们讨罪的时候， 他们必致跌倒。 这是耶和华说的。"},{"start":13,"end":13,"text":"耶和华说：我必使他们全然灭绝； 葡萄树上必没有葡萄， 无花果树上必没有果子， 叶子也必枯干。 我所赐给他们的， 必离开他们过去。"},{"start":14,"end":14,"text":"我们为何静坐不动呢？ 我们当聚集，进入坚固城， 在那里静默不言； 因为耶和华—我们的　神使我们静默不言， 又将苦胆水给我们喝， 都因我们得罪了耶和华。"},{"start":15,"end":15,"text":"我们指望平安， 却得不着好处； 指望痊愈的时候， 不料，受了惊惶。"},{"start":16,"end":16,"text":"听见从但那里敌人的马喷鼻气， 他的壮马发嘶声， 全地就都震动； 因为他们来吞灭这地和其上所有的， 吞灭这城与其中的居民。"},{"start":17,"end":17,"text":"看哪，我必使毒蛇到你们中间， 是不服法术的， 必咬你们。 这是耶和华说的。"},{"start":18,"end":18,"text":"我有忧愁，愿能自慰； 我心在我里面发昏。"},{"start":19,"end":19,"text":"听啊，是我百姓的哀声从极远之地而来， [说]：耶和华不在锡安吗？ 锡安的王不在其中吗？ [耶和华说]：他们为什么以雕刻的偶像 和外邦虚无[的神]惹我发怒呢？"},{"start":20,"end":20,"text":"麦秋已过，夏令已完， 我们还未得救！"},{"start":21,"end":21,"text":"[先知说]：因我百姓的损伤， 我也受了损伤。 我哀痛，惊惶将我抓住。"},{"start":22,"end":22,"text":"在基列岂没有乳香呢？ 在那里岂没有医生呢？ 我百姓为何不得痊愈呢？"}],"16":[{"start":16,"end":16,"text":"耶和华说：「我要召许多打鱼的把以色列人打上来，然后我要召许多打猎的，从各山上、各冈上、各石穴中猎取他们。"},{"start":17,"end":17,"text":"因我的眼目察看他们的一切行为；他们不能在我面前遮掩，他们的罪孽也不能在我眼前隐藏。"},{"start":18,"end":18,"text":"我先要加倍报应他们的罪孽和罪恶；因为他们用可憎之尸玷污我的地土，又用可厌之物充满我的产业。」"},{"start":19,"end":19,"text":"耶和华啊，你是我的力量， 是我的保障； 在苦难之日是我的避难所。 列国人必从地极来到你这里， 说：我们列祖所承受的， 不过是虚假，是虚空无益之物。"},{"start":20,"end":20,"text":"人岂可为自己制造神呢？ 其实这不是神。"},{"start":21,"end":21,"text":"[耶和华]说：「我要使他们知道，就是这一次使他们知道我的手和我的能力。他们就知道我的名是耶和华了。」"}],"25":[{"start":15,"end":15,"text":"耶和华—以色列的　神对我如此说：「你从我手中接这杯忿怒的酒，使我所差遣你去的各国的民喝。"},{"start":16,"end":16,"text":"他们喝了就要东倒西歪，并要发狂，因我使刀剑临到他们中间。」"},{"start":17,"end":17,"text":"我就从耶和华的手中接了这杯，给耶和华所差遣我去的各国的民喝，"},{"start":18,"end":18,"text":"就是耶路撒冷和犹大的城邑，并耶路撒冷的君王与首领，使这城邑荒凉，令人惊骇、嗤笑、咒诅，正如今日一样。"},{"start":19,"end":19,"text":"又有埃及王法老和他的臣仆、首领，以及他的众民，"},{"start":20,"end":20,"text":"并杂族的人民和乌斯地的诸王，与非利士地的诸王（亚实基伦、迦萨、以革伦，以及亚实突剩下的人）；"},{"start":21,"end":21,"text":"以东、摩押、亚扪人、"},{"start":22,"end":22,"text":"泰尔的诸王、西顿的诸王、海岛的诸王、"},{"start":23,"end":23,"text":"底但、提玛、布斯，和一切剃周围[头发]的；"},{"start":24,"end":24,"text":"阿拉伯的诸王、住旷野杂族人民的诸王、"},{"start":25,"end":25,"text":"心利的诸王、以拦的诸王、米底亚的诸王、"},{"start":26,"end":26,"text":"北方远近的诸王，以及天下地上的万国喝了，以后示沙克王也要喝。"},{"start":27,"end":27,"text":"「你要对他们说：『万军之耶和华—以色列的　神如此说：你们要喝，且要喝醉，要呕吐，且要跌倒，不得再起来，都因我使刀剑临到你们中间。』"},{"start":28,"end":28,"text":"「他们若不肯从你手接这杯喝，你就要对他们说：『万军之耶和华如此说：你们一定要喝！"},{"start":29,"end":29,"text":"我既从称为我名下的城起首施行灾祸，你们能尽免刑罚吗？你们必不能免，因为我要命刀剑临到地上一切的居民。这是万军之耶和华说的。』"},{"start":30,"end":30,"text":"「所以你要向他们预言这一切的话，攻击他们，说： 耶和华必从高天吼叫， 从圣所发声， 向自己的羊群大声吼叫； 他要向地上一切的居民呐喊， 像踹[葡萄]的一样。"},{"start":31,"end":31,"text":"必有响声达到地极， 因为耶和华与列国相争； 凡有血气的，他必审问； 至于恶人，他必交给刀剑。 这是耶和华说的。"},{"start":32,"end":32,"text":"万军之耶和华如此说： 看哪，必有灾祸从这国发到那国， 并有大暴风从地极刮起。"},{"start":33,"end":33,"text":"「到那日，从地这边直到地那边都有耶和华所杀戮的。必无人哀哭，不得收殓，不得葬埋，必在地上成为粪土。"},{"start":34,"end":34,"text":"牧人哪，你们当哀号，呼喊； 群众的头目啊，你们要滚[在灰中]； 因为你们被杀戮分散的日子足足来到。 你们要跌碎，好像美器打碎一样。"},{"start":35,"end":35,"text":"牧人无路逃跑； 群众的头目也无法逃脱。"},{"start":36,"end":36,"text":"听啊，有牧人呼喊， 有群众头目哀号的声音， 因为耶和华使他们的草场变为荒场。"},{"start":37,"end":37,"text":"耶和华发出猛烈的怒气， 平安的羊圈就都寂静无声。"},{"start":38,"end":38,"text":"他离了隐密处像狮子一样， 他们的地，因[刀剑]凶猛的欺压， 又因他猛烈的怒气都成为可惊骇的。」"}],"29":[{"start":4,"end":4,"text":"信上说：「万军之耶和华—以色列的　神对一切被掳去的（就是我使他们从耶路撒冷被掳到巴比伦的人）如此说："},{"start":5,"end":5,"text":"你们要盖造房屋，住在其中；栽种田园，吃其中所产的；"},{"start":6,"end":6,"text":"娶妻生儿女，为你们的儿子娶妻，使你们的女儿嫁人，生儿养女。在那里生养众多，不致减少。"},{"start":7,"end":7,"text":"我所使你们被掳到的那城，你们要为那城求平安，为那城祷告耶和华；因为那城得平安，你们也随着得平安。"}],"31":[{"start":31,"end":31,"text":"耶和华说：「日子将到，我要与以色列家和犹大家另立新约，"},{"start":32,"end":32,"text":"不像我拉着他们祖宗的手，领他们出埃及地的时候，与他们所立的约。我虽作他们的丈夫，他们却背了我的约。这是耶和华说的。」"},{"start":33,"end":33,"text":"耶和华说：「那些日子以后，我与以色列家所立的约乃是这样：我要将我的律法放在他们里面，写在他们心上。我要作他们的　神，他们要作我的子民。"},{"start":34,"end":34,"text":"他们各人不再教导自己的邻舍和自己的弟兄说：『你该认识耶和华』，因为他们从最小的到至大的都必认识我。我要赦免他们的罪孽，不再记念他们的罪恶。这是耶和华说的。」"}]},"DAN":{"2":[{"start":20,"end":20,"text":"但以理说：「　神的名是应当称颂的！从亘古直到永远，因为智慧能力都属乎他。"},{"start":21,"end":21,"text":"他改变时候、日期，废王，立王，将智慧赐与智慧人，将知识赐与聪明人。"},{"start":22,"end":22,"text":"他显明深奥隐秘的事，知道暗中所有的，光明也与他同居。"},{"start":44,"end":44,"text":"当那列王在位的时候，天上的　神必另立一国，永不败坏，也不归别国的人，却要打碎灭绝那一切国，这国必存到永远。"},{"start":45,"end":45,"text":"你既看见非人手凿出来的一块石头从山而出，打碎金、银、铜、铁、泥，那就是至大的　神把后来必有的事给王指明。这梦准是这样，这讲解也是确实的。」"},{"start":46,"end":46,"text":"当时，尼布甲尼撒王俯伏在地，向但以理下拜，并且吩咐人给他奉上供物和香品。"},{"start":47,"end":47,"text":"王对但以理说：「你既能显明这奥秘的事，你们的　神诚然是万神之神、万王之主，又是显明奥秘事的。」"},{"start":48,"end":48,"text":"于是王高抬但以理，赏赐他许多上等礼物，派他管理巴比伦全省，又立他为总理，掌管巴比伦的一切哲士。"},{"start":49,"end":49,"text":"但以理求王，王就派沙得拉、米煞、亚伯尼歌管理巴比伦省的事务，只是但以理常在朝中侍立。"}],"3":[{"start":16,"end":16,"text":"沙得拉、米煞、亚伯尼歌对王说：「尼布甲尼撒啊，这件事我们不必回答你，"},{"start":17,"end":17,"text":"即便如此，我们所事奉的　神能将我们从烈火的窑中救出来。王啊，他也必救我们脱离你的手；"},{"start":18,"end":18,"text":"即或不然，王啊，你当知道我们决不事奉你的神，也不敬拜你所立的金像。」"}],"4":[{"start":10,"end":10,"text":"「我在床上脑中的异象是这样：我看见地当中有一棵树，极其高大。"},{"start":11,"end":11,"text":"那树渐长，而且坚固，高得顶天，从地极都能看见，"},{"start":12,"end":12,"text":"叶子华美，果子甚多，可作众生的食物；田野的走兽卧在荫下，天空的飞鸟宿在枝上；凡有血气的都从这树得食。"}],"7":[{"start":1,"end":1,"text":"巴比伦王伯沙撒元年，但以理在床上做梦，见了脑中的异象，就记录这梦，述说其中的大意。"},{"start":2,"end":2,"text":"但以理说： 我夜里见异象，看见天的四风陡起，刮在大海之上。"},{"start":3,"end":3,"text":"有四个大兽从海中上来，[形状]各有不同："},{"start":4,"end":4,"text":"头一个像狮子，有鹰的翅膀；我正观看的时候，兽的翅膀被拔去，兽从地上得立起来，用两脚站立，像人一样，又得了人心。"},{"start":5,"end":5,"text":"又有一兽如熊，就是第二兽，旁跨而坐，口齿内衔着三根肋骨。有吩咐这兽的说：「起来吞吃多肉。」"},{"start":6,"end":6,"text":"此后我观看，又有一兽如豹，背上有鸟的四个翅膀；这兽有四个头，又得了权柄。"},{"start":7,"end":7,"text":"其后我在夜间的异象中观看，见第四兽甚是可怕，极其强壮，大有力量，有大铁牙，吞吃嚼碎，所剩下的用脚践踏。这兽与前三兽大不相同，头有十角。"},{"start":8,"end":8,"text":"我正观看这些角，见其中又长起一个小角；先前的角中有三角在这角前，连根被它拔出来。这角有眼，像人的眼，有口说夸大的话。"},{"start":9,"end":9,"text":"我观看， 见有宝座设立， 上头坐着亘古常在者。 他的衣服洁白如雪， 头发如纯净的羊毛。 宝座乃火焰， 其轮乃烈火。"},{"start":10,"end":10,"text":"从他面前有火，像河发出； 事奉他的有千千， 在他面前侍立的有万万； 他坐着要行审判， 案卷都展开了。"},{"start":11,"end":11,"text":"那时我观看，见那兽因小角说夸大话的声音被杀，身体损坏，扔在火中焚烧。"},{"start":12,"end":12,"text":"其余的兽，权柄都被夺去，生命却仍存留，直到所定的时候和日期。"},{"start":13,"end":13,"text":"我在夜间的异象中观看， 见有一位像人子的， 驾着天云而来， 被领到亘古常在者面前，"},{"start":14,"end":14,"text":"得了权柄、荣耀、国度， 使各方、各国、各族的人都事奉他。 他的权柄是永远的，不能废去； 他的国必不败坏。"},{"start":15,"end":15,"text":"至于我—但以理，我的灵在我里面愁烦，我脑中的异象使我惊惶。"},{"start":16,"end":16,"text":"我就近一位侍立者，问他这一切的真情。他就告诉我，将那事的讲解给我说明："},{"start":17,"end":17,"text":"这四个大兽就是四王将要在世上兴起。"},{"start":18,"end":18,"text":"然而，至高者的圣民，必要得国享受，直到永永远远。"},{"start":19,"end":19,"text":"那时我愿知道第四兽的真情，它为何与那三兽的真情大不相同，甚是可怕，有铁牙铜爪，吞吃嚼碎，所剩下的用脚践踏；"},{"start":20,"end":20,"text":"头有十角和那另长的一角，在这角前有三角被它打落。这角有眼，有说夸大话的口，形状强横，过于它的同类。"},{"start":21,"end":21,"text":"我观看，见这角与圣民争战，胜了他们。"},{"start":22,"end":22,"text":"直到亘古常在者来给至高者的圣民伸冤，圣民得国的时候就到了。"},{"start":23,"end":23,"text":"那侍立者这样说： 第四兽就是世上必有的第四国， 与一切国大不相同， 必吞吃全地， 并且践踏嚼碎。"},{"start":24,"end":24,"text":"至于那十角，就是从这国中必兴起的十王， 后来又兴起一王， 与先前的不同； 他必制伏三王。"},{"start":25,"end":25,"text":"他必向至高者说[夸大的]话， 必折磨至高者的圣民， 必想改变节期和律法。 圣民必交付他手一载、二载、半载。"},{"start":26,"end":26,"text":"然而，审判者必坐着行审判； 他的权柄必被夺去， 毁坏，灭绝，一直到底。"},{"start":27,"end":27,"text":"国度、权柄，和天下诸国的大权 必赐给至高者的圣民。 他的国是永远的； 一切掌权的都必事奉他，顺从他。"},{"start":28,"end":28,"text":"那事至此完毕。至于我—但以理，心中甚是惊惶，脸色也改变了，却将那事存记在心。"}],"12":[{"start":1,"end":1,"text":"「那时，保佑你本国之民的天使长米迦勒必站起来，并且有大艰难，从有国以来直到此时，没有这样的。你本国的民中，凡名录在册上的，必得拯救。"},{"start":2,"end":2,"text":"睡在尘埃中的，必有多人复醒。其中有得永生的，有受羞辱永远被憎恶的。"},{"start":3,"end":3,"text":"智慧人必发光如同天上的光；那使多人归义的，必发光如星，直到永永远远。"},{"start":4,"end":4,"text":"但以理啊，你要隐藏这话，封闭这书，直到末时。必有多人来往奔跑，知识就必增长。」"},{"start":5,"end":5,"text":"我—但以理观看，见另有两个人站立：一个在河这边，一个在河那边。"},{"start":6,"end":6,"text":"有一个问那站在河水以上、穿细麻衣的说：「这奇异的事到几时才应验呢？」"},{"start":7,"end":7,"text":"我听见那站在河水以上、穿细麻衣的，向天举起左右手，指着活到永远的[主]起誓说：「要到一载、二载、半载，打破圣民权力的时候，这一切事就都应验了。」"},{"start":8,"end":8,"text":"我听见这话，却不明白，就说：「我主啊，这些事的结局是怎样呢？」"},{"start":9,"end":9,"text":"他说：「但以理啊，你只管去；因为这话已经隐藏封闭，直到末时。"},{"start":10,"end":10,"text":"必有许多人使自己清净洁白，且被熬炼；但恶人仍必行恶，一切恶人都不明白，惟独智慧人能明白。"},{"start":11,"end":11,"text":"从除掉常献的[燔祭]，并设立那行毁坏可憎之物的时候，必有一千二百九十日。"},{"start":12,"end":12,"text":"等到一千三百三十五日的，那人便为有福。"},{"start":13,"end":13,"text":"「你且去等候结局，因为你必安歇。到了末期，你必起来，享受你的[福]分。」"}]},"HOS":{"2":[{"start":19,"end":19,"text":"我必聘你永远归我为妻，以仁义、公平、慈爱、怜悯聘你归我；"},{"start":20,"end":20,"text":"也以诚实聘你归我，你就必认识[我]—耶和华。"}],"6":[{"start":2,"end":2,"text":"过两天他必使我们苏醒， 第三天他必使我们兴起， 我们就在他面前得以存活。"},{"start":3,"end":3,"text":"我们务要认识耶和华， 竭力追求认识他。 他出现确如晨[光]； 他必临到我们像甘雨， 像滋润田地的春雨。"},{"start":4,"end":4,"text":"主说：以法莲哪，我可向你怎样行呢？ 犹大啊，我可向你怎样做呢？ 因为你们的良善如同早晨的云雾， 又如速散的甘露。"},{"start":5,"end":5,"text":"因此，我借先知砍伐他们， 以我口中的话杀戮他们； 我施行的审判如光发出。"},{"start":6,"end":6,"text":"我喜爱良善，不喜爱祭祀； 喜爱认识　神，胜于燔祭。"},{"start":7,"end":7,"text":"他们却如亚当背约， 在境内向我行事诡诈。"},{"start":8,"end":8,"text":"基列是作孽之人的城， 被血沾染。"},{"start":9,"end":9,"text":"强盗成群，怎样埋伏杀人， 祭司结党，也照样在示剑的路上杀戮， 行了邪恶。"},{"start":10,"end":10,"text":"在以色列家，我见了可憎的事； 在以法莲那里有淫行， 以色列被玷污。"},{"start":11,"end":11,"text":"犹大啊，我使被掳之民归回的时候， 必有为你所命定的收场。"}],"10":[{"start":8,"end":8,"text":"伯·亚文的邱坛— 就是以色列取罪[的地方]必被毁灭； 荆棘和蒺藜必长在他们的祭坛上。 他们必对大山说：遮盖我们！ 对小山说：倒在我们身上！"},{"start":9,"end":9,"text":"以色列啊， 你从基比亚的日子以来时常犯罪。 你们的先人曾站在那里， 现今住基比亚的人 以为攻击罪孽之辈的战事临不到自己。"},{"start":10,"end":10,"text":"我必随意惩罚他们。 他们为两样的罪所缠； 列邦的民必聚集攻击他们。"},{"start":11,"end":11,"text":"以法莲是驯良的母牛犊，喜爱踹[谷]， 我却将轭加在它肥美的颈项上， 我要使以法莲拉套。 犹大必耕田； 雅各必耙地。"},{"start":12,"end":12,"text":"你们要为自己栽种公义， 就能收割慈爱。 现今正是寻求耶和华的时候； 你们要开垦荒地，等他临到， 使公义如雨降在你们身上。"},{"start":13,"end":13,"text":"你们耕种的是奸恶， 收割的是罪孽， 吃的是谎话的果子。 因你倚靠自己的行为， 仰赖勇士众多，"},{"start":14,"end":14,"text":"所以在这民中必有哄嚷之声， 你一切的保障必被拆毁， 就如沙勒幔在争战的日子拆毁伯·亚比勒， 将其中的母子一同摔死。"},{"start":15,"end":15,"text":"因他们的大恶， 伯特利必使你们遭遇如此。 到了黎明，以色列的王必全然灭绝。"}],"11":[{"start":1,"end":1,"text":"以色列年幼的时候，我爱他， 就从埃及召出我的儿子来。"},{"start":2,"end":2,"text":"先知越发招呼他们， 他们越发走开， 向诸巴力献祭， 给雕刻的偶像烧香。"},{"start":3,"end":3,"text":"我原教导以法莲行走， 用膀臂抱着他们， 他们却不知道是我医治他们。"},{"start":4,"end":4,"text":"我用慈绳爱索牵引他们； 我待他们如人放松[牛的]两腮夹板， 把粮食放在他们面前。"},{"start":5,"end":5,"text":"他们必不归回埃及地， 亚述人却要作他们的王， 因他们不肯归向[我]。"},{"start":6,"end":6,"text":"刀剑必临到他们的城邑， 毁坏门闩，把人吞灭， 都因他们[随从]自己的计谋。"},{"start":7,"end":7,"text":"我的民偏要背道离开我； 众先知虽然招呼他们归向至上的[主]， 却无人尊崇[主]。"},{"start":8,"end":8,"text":"以法莲哪，我怎能舍弃你？ 以色列啊，我怎能弃绝你？ 我怎能使你如押玛？ 怎能使你如洗扁？ 我回心转意， 我的怜爱大大发动。"},{"start":9,"end":9,"text":"我必不发猛烈的怒气， 也不再毁灭以法莲。 因我是　神，并非世人， 是你们中间的圣者； 我必不在怒中临到你们。"}]},"1PE":{"1":[{"start":10,"end":10,"text":"论到这救恩，那预先说你们要得恩典的众先知早已详细地寻求考察，"},{"start":11,"end":11,"text":"就是考察在他们心里基督的灵，预先证明基督受苦难，后来得荣耀，是指着什么时候，并怎样的时候。"},{"start":12,"end":12,"text":"他们得了启示，知道他们所传讲的一切事，不是为自己，乃是为你们。那靠着从天上差来的圣灵传福音给你们的人，现在将这些事报给你们；天使也愿意详细察看这些事。"},{"start":18,"end":18,"text":"知道你们得赎，脱去你们祖宗所传流虚妄的行为，不是凭着能坏的金银等物，"},{"start":19,"end":19,"text":"乃是凭着基督的宝血，如同无瑕疵、无玷污的羔羊之血。"}],"2":[{"start":2,"end":2,"text":"就要爱慕那纯净的灵奶，像才生的婴孩爱慕奶一样，叫你们因此渐长，以致得救。"},{"start":3,"end":3,"text":"你们若尝过主恩的滋味，[就必如此]。"},{"start":4,"end":4,"text":"主乃活石，固然是被人所弃的，却是被　神所拣选、所宝贵的。"},{"start":5,"end":5,"text":"你们来到主面前，也就像活石，被建造成为灵宫，作圣洁的祭司，借着耶稣基督奉献　神所悦纳的灵祭。"},{"start":6,"end":6,"text":"因为经上说： 看哪，我把所拣选、 所宝贵的房角石安放在锡安； 信靠他的人必不至于羞愧。"},{"start":7,"end":7,"text":"所以，他在你们信的人就为宝贵，在那不信的人[有话说]： 匠人所弃的石头 已作了房角的头块石头。"},{"start":8,"end":8,"text":"又说：作了绊脚的石头，跌人的磐石。他们既不顺从，就在道理上绊跌；他们这样绊跌也是预定的。"},{"start":9,"end":9,"text":"惟有你们是被拣选的族类，是有君尊的祭司，是圣洁的国度，是属　[神]的子民，要叫你们宣扬那召你们出黑暗入奇妙光明者的美德。"},{"start":10,"end":10,"text":"你们从前算不得子民， 现在却作了　神的子民； 从前未曾蒙怜恤， 现在却蒙了怜恤。"},{"start":11,"end":11,"text":"亲爱的[弟兄]啊，你们是客旅，是寄居的。我劝你们要禁戒肉体的私欲；这私欲是与灵魂争战的。"},{"start":12,"end":12,"text":"你们在外邦人中，应当品行端正，叫那些毁谤你们是作恶的，因看见你们的好行为，便在鉴察的日子归荣耀给　神。"},{"start":13,"end":13,"text":"你们为主的缘故，要顺服人的一切制度，或是在上的君王，"},{"start":14,"end":14,"text":"或是君王所派罚恶赏善的臣宰。"},{"start":15,"end":15,"text":"因为　神的旨意原是要你们行善，可以堵住那糊涂无知人的口。"},{"start":16,"end":16,"text":"你们虽是自由的，却不可借着自由遮盖恶毒，总要作　神的仆人。"},{"start":17,"end":17,"text":"务要尊敬众人，亲爱教中的弟兄，敬畏　神，尊敬君王。"},{"start":18,"end":18,"text":"你们作仆人的，凡事要存敬畏的心顺服主人；不但顺服那善良温和的，就是那乖僻的也要顺服。"},{"start":19,"end":19,"text":"倘若人为叫良心对得住　神，就忍受冤屈的苦楚，这是可喜爱的。"},{"start":20,"end":20,"text":"你们若因犯罪受责打，能忍耐，有什么可夸的呢？但你们若因行善受苦，能忍耐，这在　神看是可喜爱的。"},{"start":21,"end":21,"text":"你们蒙召原是为此；因基督也为你们受过苦，给你们留下榜样，叫你们跟随他的脚踪行。"},{"start":22,"end":22,"text":"他并没有犯罪，口里也没有诡诈。"},{"start":23,"end":23,"text":"他被骂不还口；受害不说威吓的话，只将自己交托那按公义审判人的[主]。"},{"start":24,"end":24,"text":"他被挂在木头上，亲身担当了我们的罪，使我们既然在罪上死，就得以在义上活。因他受的鞭伤，你们便得了医治。"},{"start":25,"end":25,"text":"你们从前好像迷路的羊，如今却归到你们灵魂的牧人监督了。"}],"3":[{"start":15,"end":15,"text":"只要心里尊主基督为圣。有人问你们心中盼望的缘由，就要常作准备，以温柔、敬畏的心回答各人；"},{"start":16,"end":16,"text":"存着无亏的良心，叫你们在何事上被毁谤，就在何事上可以叫那诬赖你们在基督里有好品行的人自觉羞愧。"}],"4":[{"start":12,"end":12,"text":"亲爱的[弟兄]啊，有火炼的试验临到你们，不要以为奇怪（似乎是遭遇非常的事），"},{"start":13,"end":13,"text":"倒要欢喜；因为你们是与基督一同受苦，使你们在他荣耀显现的时候，也可以欢喜快乐。"},{"start":14,"end":14,"text":"你们若为基督的名受辱骂，便是有福的；因为　神荣耀的灵常住在你们身上。"},{"start":15,"end":15,"text":"你们中间却不可有人因为杀人、偷窃、作恶、好管闲事而受苦。"},{"start":16,"end":16,"text":"若为作基督徒受苦，却不要羞耻，倒要因这名归荣耀给　神。"},{"start":17,"end":17,"text":"因为时候到了，审判要从　神的家起首。若是先从我们起首，那不信从　神福音的人将有何等的结局呢？"},{"start":18,"end":18,"text":"若是义人仅仅得救，那不虔敬和犯罪的人将有何地可站呢？"},{"start":19,"end":19,"text":"所以，那照　神旨意受苦的人要一心为善，将自己灵魂交与那信实的造化之主。"}],"5":[{"start":1,"end":1,"text":"我这作长老、作基督受苦的见证、同享后来所要显现之荣耀的，劝你们中间与我同作长老的人："},{"start":2,"end":2,"text":"务要牧养在你们中间　神的群羊，按着　神[旨意]照管他们；不是出于勉强，乃是出于甘心；也不是因为贪财，乃是出于乐意；"},{"start":3,"end":3,"text":"也不是辖制所托付你们的，乃是作群羊的榜样。"},{"start":4,"end":4,"text":"到了牧长显现的时候，你们必得那永不衰残的荣耀冠冕。"},{"start":5,"end":5,"text":"你们年幼的，也要顺服年长的。就是你们众人也都要以谦卑束腰，彼此顺服；因为 　神阻挡骄傲的人， 赐恩给谦卑的人。"},{"start":6,"end":6,"text":"所以，你们要自卑，服在　神大能的手下，到了时候，他必叫你们升高。"},{"start":7,"end":7,"text":"你们要将一切的忧虑卸给　神，因为他顾念你们。"},{"start":8,"end":8,"text":"务要谨守，警醒。[因为]你们的仇敌魔鬼，如同吼叫的狮子，遍地游行，寻找可吞吃的人。"},{"start":9,"end":9,"text":"你们要用坚固的信心抵挡他，因为知道你们在世上的众弟兄也是经历这样的苦难。"},{"start":10,"end":10,"text":"那赐诸般恩典的　神曾在基督里召你们，得享他永远的荣耀，等你们暂受苦难之后，必要亲自成全你们，坚固你们，赐力量给你们。"},{"start":11,"end":11,"text":"愿权能归给他，直到永永远远。阿们！"},{"start":12,"end":12,"text":"我略略地写了这信，托我所看为忠心的兄弟西拉转交你们，劝勉你们，又证明这恩是　神的真恩。你们务要在这恩上站立得住。"},{"start":13,"end":13,"text":"在巴比伦与你们同蒙拣选的教会问你们安。我儿子马可也问你们安。"},{"start":14,"end":14,"text":"你们要用爱心彼此亲嘴问安。愿平安归与你们凡在基督里的人！"}]},"JOB":{"1":[{"start":1,"end":1,"text":"乌斯地有一个人名叫约伯；那人完全正直，敬畏　神，远离恶事。"},{"start":2,"end":2,"text":"他生了七个儿子，三个女儿。"},{"start":3,"end":3,"text":"他的家产有七千羊，三千骆驼，五百对牛，五百母驴，并有许多仆婢。这人在东方人中就为至大。"},{"start":4,"end":4,"text":"他的儿子按着日子各在自己家里设摆筵宴，就打发人去，请了他们的三个姊妹来，与他们一同吃喝。"},{"start":5,"end":5,"text":"筵宴的日子过了，约伯打发人去叫他们自洁。他清早起来，按着他们众人的数目献燔祭；因为他说：「恐怕我儿子犯了罪，心中弃掉　神。」约伯常常这样行。"},{"start":6,"end":6,"text":"有一天，　神的众子来侍立在耶和华面前，撒但也来在其中。"},{"start":7,"end":7,"text":"耶和华问撒但说：「你从哪里来？」撒但回答说：「我从地上走来走去，往返而来。」"},{"start":8,"end":8,"text":"耶和华问撒但说：「你曾用心察看我的仆人约伯没有？地上再没有人像他完全正直，敬畏　神，远离恶事。」"},{"start":9,"end":9,"text":"撒但回答耶和华说：「约伯敬畏　神，岂是无故呢？"},{"start":10,"end":10,"text":"你岂不是四面圈上篱笆围护他和他的家，并他一切所有的吗？他手所做的都蒙你赐福；他的家产也在地上增多。"},{"start":11,"end":11,"text":"你且伸手毁他一切所有的；他必当面弃掉你。」"},{"start":12,"end":12,"text":"耶和华对撒但说：「凡他所有的都在你手中；只是不可伸手加害于他。」于是撒但从耶和华面前退去。"},{"start":13,"end":13,"text":"有一天，约伯的儿女正在他们长兄的家里吃饭喝酒，"},{"start":14,"end":14,"text":"有报信的来见约伯，说：「牛正耕地，驴在旁边吃草，"},{"start":15,"end":15,"text":"示巴人忽然闯来，把牲畜掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」"},{"start":16,"end":16,"text":"他还说话的时候，又有人来说：「　神从天上降下火来，将群羊和仆人都烧灭了；惟有我一人逃脱，来报信给你。」"},{"start":17,"end":17,"text":"他还说话的时候，又有人来说：「迦勒底人分作三队忽然闯来，把骆驼掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」"},{"start":18,"end":18,"text":"他还说话的时候，又有人来说：「你的儿女正在他们长兄的家里吃饭喝酒，"},{"start":19,"end":19,"text":"不料，有狂风从旷野刮来，击打房屋的四角，房屋倒塌在少年人身上，他们就都死了；惟有我一人逃脱，来报信给你。」"},{"start":20,"end":20,"text":"约伯便起来，撕裂外袍，剃了头，伏在地上下拜，"},{"start":21,"end":21,"text":"说：「我赤身出于母胎，也必赤身归回；赏赐的是耶和华，收取的也是耶和华。耶和华的名是应当称颂的。」"},{"start":22,"end":22,"text":"在这一切的事上约伯并不犯罪，也不以　神为愚妄。"}],"19":[{"start":25,"end":25,"text":"我知道我的救赎主活着， 末了必站立在地上。"},{"start":26,"end":26,"text":"我这皮肉灭绝之后， 我必在肉体之外得见　神。"},{"start":27,"end":27,"text":"我自己要见他， 亲眼要看他，并不像外人。 我的心肠在我里面消灭了！"}],"38":[{"start":8,"end":8,"text":"海水冲出，如出胎胞， 那时谁将它关闭呢？"},{"start":9,"end":9,"text":"是我用云彩当海的衣服， 用幽暗当包裹它的布，"},{"start":10,"end":10,"text":"为它定界限， 又安门和闩，"},{"start":11,"end":11,"text":"说：你只可到这里，不可越过； 你狂傲的浪要到此止住。"}]},"2PE":{"1":[{"start":16,"end":16,"text":"我们从前将我们主耶稣基督的大能和他降临的事告诉你们，并不是随从乖巧捏造的虚言，乃是亲眼见过他的威荣。"},{"start":17,"end":17,"text":"他从父　神得尊贵荣耀的时候，从极大荣光之中有声音出来，向他说：「这是我的爱子，我所喜悦的。」"},{"start":18,"end":18,"text":"我们同他在圣山的时候，亲自听见这声音从天上出来。"}],"3":[{"start":9,"end":9,"text":"主所应许的[尚未成就]，有人以为他是耽延，其实不是耽延，乃是宽容你们，不愿有一人沉沦，乃愿人人都悔改。"},{"start":10,"end":10,"text":"但主的日子要像贼来到一样。那日，天必大有响声废去，有形质的都要被烈火销化，地和其上的物都要烧尽了。"},{"start":11,"end":11,"text":"这一切既然都要如此销化，你们为人该当怎样圣洁，怎样敬虔，"},{"start":12,"end":12,"text":"切切仰望　神的日子来到。在那日，天被火烧就销化了，有形质的都要被烈火熔化。"},{"start":13,"end":13,"text":"但我们照他的应许，盼望新天新地，有义居在其中。"},{"start":14,"end":14,"text":"亲爱的[弟兄]啊，你们既盼望这些事，就当殷勤，使自己没有玷污，无可指摘，安然见主；"},{"start":15,"end":15,"text":"并且要以我主长久忍耐为得救的因由，就如我们所亲爱的兄弟保罗，照着所赐给他的智慧写了信给你们。"},{"start":16,"end":16,"text":"他一切的信上也都是讲论这事。信中有些难明白的，那无学问、不坚固的人强解，如强解别的经书一样，就自取沉沦。"},{"start":17,"end":17,"text":"亲爱的[弟兄]啊，你们既然预先知道这事，就当防备，恐怕被恶人的错谬诱惑，就从自己坚固的地步上坠落。"},{"start":18,"end":18,"text":"你们却要在我们主—救主耶稣基督的恩典和知识上有长进。愿荣耀归给他，从今直到永远。阿们！"}]},"NUM":{"5":[{"start":7,"end":7,"text":"他要承认所犯的罪，将所亏负人的，如数赔还，另外加上五分之一，也归与所亏负的人。"},{"start":8,"end":8,"text":"那人若没有亲属可受所赔还的，那所赔还的就要归与服事耶和华的祭司；至于那为他赎罪的公羊是在外。"},{"start":9,"end":9,"text":"以色列人一切的圣物中，所奉给祭司的举祭都要归与祭司。"},{"start":10,"end":10,"text":"各人所分别为圣的物，无论是什么，都要归给祭司。」"},{"start":11,"end":11,"text":"耶和华对摩西说："},{"start":12,"end":12,"text":"「你晓谕以色列人说：人的妻若有邪行，得罪她丈夫，"},{"start":13,"end":13,"text":"有人与她行淫，事情严密，瞒过她丈夫，而且她被玷污，没有作见证的人，当她行淫的时候也没有被捉住，"},{"start":14,"end":14,"text":"她丈夫生了疑恨的心，疑恨她，她是被玷污，或是她丈夫生了疑恨的心，疑恨她，她并没有被玷污，"},{"start":15,"end":15,"text":"这人就要将妻送到祭司那里，又为她带着大麦面伊法十分之一作供物，不可浇上油，也不可加上乳香；因为这是疑恨的素祭，是思念的素祭，使人思念罪孽。"},{"start":16,"end":16,"text":"「祭司要使那妇人近前来，站在耶和华面前。"},{"start":17,"end":17,"text":"祭司要把圣水盛在瓦器里，又从帐幕的地上取点尘土，放在水中。"},{"start":18,"end":18,"text":"祭司要叫那妇人蓬头散发，站在耶和华面前，把思念的素祭，就是疑恨的素祭，放在她手中。祭司手里拿着致咒诅的苦水，"},{"start":19,"end":19,"text":"要叫妇人起誓，对她说：『若没有人与你行淫，也未曾背着丈夫做污秽的事，你就免受这致咒诅苦水的灾。"},{"start":20,"end":20,"text":"你若背着丈夫行了污秽的事，在你丈夫以外有人与你行淫，"},{"start":21,"end":21,"text":"（祭司叫妇人发咒起誓，）愿耶和华叫你大腿消瘦，肚腹发胀，使你在你民中被人咒诅，成了誓语；"},{"start":22,"end":22,"text":"并且这致咒诅的水入你的肠中，要叫你的肚腹发胀，大腿消瘦。』妇人要回答说：『阿们，阿们。』"},{"start":23,"end":23,"text":"「祭司要写这咒诅的话，将所写的字抹在苦水里，"},{"start":24,"end":24,"text":"又叫妇人喝这致咒诅的苦水；这水要进入她里面[变]苦了。"},{"start":25,"end":25,"text":"祭司要从妇人的手中取那疑恨的素祭，在耶和华面前摇一摇，拿到坛前；"},{"start":26,"end":26,"text":"又要从素祭中取出一把，作为这事的纪念，烧在坛上，然后叫妇人喝这水。"},{"start":27,"end":27,"text":"叫她喝了以后，她若被玷污，得罪了丈夫，这致咒诅的水必进入她里面[变]苦了，她的肚腹就要发胀，大腿就要消瘦，那妇人便要在他民中被人咒诅。"},{"start":28,"end":28,"text":"若妇人没有被玷污，却是清洁的，就要免受这灾，且要怀孕。"},{"start":29,"end":29,"text":"「妻子背着丈夫行了污秽的事，"},{"start":30,"end":30,"text":"或是人生了疑恨的心，疑恨他的妻，就有这疑恨的条例。那时他要叫妇人站在耶和华面前，祭司要在她身上照这条例而行。"},{"start":31,"end":31,"text":"男人就为无罪，妇人必担当自己的罪孽。」"}],"6":[{"start":22,"end":22,"text":"耶和华晓谕摩西说："},{"start":23,"end":23,"text":"「你告诉亚伦和他儿子说：你们要这样为以色列人祝福，说："},{"start":24,"end":24,"text":"『愿耶和华赐福给你，保护你。"},{"start":25,"end":25,"text":"愿耶和华使他的脸光照你，赐恩给你。"},{"start":26,"end":26,"text":"愿耶和华向你仰脸，赐你平安。』"},{"start":27,"end":27,"text":"他们要如此奉我的名为以色列人祝福；我也要赐福给他们。」"}],"11":[{"start":16,"end":16,"text":"耶和华对摩西说：「你从以色列的长老中招聚七十个人，就是你所知道作百姓的长老和官长的，到我这里来，领他们到会幕前，使他们和你一同站立。"},{"start":17,"end":17,"text":"我要在那里降临，与你说话，也要把降于你身上的灵分赐他们，他们就和你同当这管百姓的重任，免得你独自担当。"},{"start":18,"end":18,"text":"又要对百姓说：『你们应当自洁，预备明天吃肉，因为你们哭号说：谁给我们肉吃！我们在埃及很好。这声音达到了耶和华的耳中，所以他必给你们肉吃。"},{"start":19,"end":19,"text":"你们不止吃一天、两天、五天、十天、二十天，"},{"start":20,"end":20,"text":"要吃一个整月，甚至肉从你们鼻孔里喷出来，使你们厌恶了，因为你们厌弃住在你们中间的耶和华，在他面前哭号说：我们为何出了埃及呢！』」"},{"start":21,"end":21,"text":"摩西[对耶和华]说：「这与我同住的百姓、步行的男人有六十万，你还说：『我要把肉给他们，使他们可以吃一个整月。』"},{"start":22,"end":22,"text":"难道给他们宰了羊群牛群，或是把海中所有的鱼都聚了来，就够他们吃吗？」"},{"start":23,"end":23,"text":"耶和华对摩西说：「耶和华的膀臂岂是缩短了吗？现在要看我的话向你应验不应验。」"},{"start":24,"end":24,"text":"摩西出去，将耶和华的话告诉百姓，又招聚百姓的长老中七十个人来，使他们站在[会]幕的四围。"},{"start":25,"end":25,"text":"耶和华在云中降临，对摩西说话，把降与他身上的灵分赐那七十个长老。灵停在他们身上的时候，他们就受感说话，以后却没有再说。"},{"start":26,"end":26,"text":"但有两个人仍在营里，一个名叫伊利达，一个名叫米达。他们本是在那些被录的人中，却没有到[会]幕那里去。灵停在他们身上，他们就在营里说预言。"},{"start":27,"end":27,"text":"有个少年人跑来告诉摩西说：「伊利达、米达在营里说预言。」"},{"start":28,"end":28,"text":"摩西的帮手，嫩的儿子约书亚，就是摩西所拣选的一个人，说：「请我主摩西禁止他们。」"},{"start":29,"end":29,"text":"摩西对他说：「你为我的缘故嫉妒人吗？惟愿耶和华的百姓都受感说话！愿耶和华把他的灵降在他们身上！」"},{"start":30,"end":30,"text":"于是，摩西和以色列的长老都回到营里去。"}]},"2CH":{"28":[{"start":9,"end":9,"text":"但那里有耶和华的一个先知，名叫俄德，出来迎接往撒马利亚去的军兵，对他们说：「因为耶和华—你们列祖的　神恼怒犹大人，所以将他们交在你们手里，你们竟怒气冲天，大行杀戮。"},{"start":10,"end":10,"text":"如今你们又有意强逼犹大人和耶路撒冷人作你们的奴婢，你们岂不也有得罪耶和华—你们　神的事吗？"},{"start":11,"end":11,"text":"现在你们当听我说，要将掳来的弟兄释放回去，因为耶和华向你们已经大发烈怒。」"},{"start":12,"end":12,"text":"于是，以法莲人的几个族长—就是约哈难的儿子亚撒利雅、米实利末的儿子比利家、沙龙的儿子耶希西家、哈得莱的儿子亚玛撒—起来拦挡出兵回来的人，"},{"start":13,"end":13,"text":"对他们说：「你们不可带进这被掳的人来！你们想要使我们得罪耶和华，加增我们的罪恶过犯？因为我们的罪过甚大，已经有烈怒临到以色列人了。」"},{"start":14,"end":14,"text":"于是带兵器的人将掳来的人口和掠来的财物都留在众首领和会众的面前。"},{"start":15,"end":15,"text":"以上提名的那些人就站起，使被掳的人前来；其中有赤身的，就从所掠的财物中拿出衣服和鞋来，给他们穿，又给他们吃喝，用膏抹他们；其中有软弱的，就使他们骑驴，送到棕树城耶利哥他们弟兄那里；随后就回撒马利亚去了。"}]},"1JO":{"3":[{"start":16,"end":16,"text":"主为我们舍命，我们从此就知道何为爱；我们也当为弟兄舍命。"},{"start":17,"end":17,"text":"凡有世上财物的，看见弟兄穷乏，却塞住怜恤的心，爱　神的心怎能存在他里面呢？"},{"start":18,"end":18,"text":"小子们哪，我们相爱，不要只在言语和舌头上，总要在行为和诚实上。"}]},"JON":{"2":[{"start":10,"end":10,"text":"耶和华吩咐鱼，鱼就把约拿吐在旱地上。"}],"3":[{"start":5,"end":5,"text":"尼尼微人信服　神，便宣告禁食，从最大的到至小的都穿麻衣。"},{"start":6,"end":6,"text":"这信息传到尼尼微王的耳中，他就下了宝座，脱下朝服，披上麻布，坐在灰中。"},{"start":7,"end":7,"text":"他又使人遍告尼尼微通城，说：「王和大臣有令，人不可尝什么，牲畜、牛羊不可吃草，也不可喝水。"},{"start":8,"end":8,"text":"人与牲畜都当披上麻布；人要切切求告　神。各人回头离开所行的恶道，丢弃手中的强暴。"},{"start":9,"end":9,"text":"或者　神转意后悔，不发烈怒，使我们不致灭亡，也未可知。」"},{"start":10,"end":10,"text":"于是　神察看他们的行为，见他们离开恶道，他就后悔，不把所说的灾祸降与他们了。"}],"4":[{"start":1,"end":1,"text":"这事约拿大大不悦，且甚发怒，"},{"start":2,"end":2,"text":"就祷告耶和华说：「耶和华啊，我在本国的时候岂不是这样说吗？我知道你是有恩典、有怜悯的　神，不轻易发怒，有丰盛的慈爱，并且后悔不降所说的灾，所以我急速逃往他施去。"},{"start":3,"end":3,"text":"耶和华啊，现在求你取我的命吧！因为我死了比活着还好。」"},{"start":4,"end":4,"text":"耶和华说：「你这样发怒合乎理吗？」"},{"start":5,"end":5,"text":"于是约拿出城，坐在城的东边，在那里为自己搭了一座棚，坐在棚的荫下，要看看那城究竟如何。"},{"start":6,"end":6,"text":"耶和华　神安排一棵蓖麻，使其发生高过约拿，影儿遮盖他的头，救他脱离苦楚；约拿因这棵蓖麻大大喜乐。"},{"start":7,"end":7,"text":"次日黎明，　神却安排一条虫子咬这蓖麻，以致枯槁。"},{"start":8,"end":8,"text":"日头出来的时候，　神安排炎热的东风，日头曝晒约拿的头，使他发昏，他就为自己求死，说：「我死了比活着还好！」"},{"start":9,"end":9,"text":"神对约拿说：「你因这棵蓖麻发怒合乎理吗？」他说：「我发怒以至于死，都合乎理！」"},{"start":10,"end":10,"text":"耶和华说：「这蓖麻不是你栽种的，也不是你培养的；一夜发生，一夜干死，你尚且爱惜；"},{"start":11,"end":11,"text":"何况这尼尼微大城，其中不能分辨左手右手的有十二万多人，并有许多牲畜，我岂能不爱惜呢？」"}]},"EPH":{"1":[{"start":20,"end":20,"text":"就是照他在基督身上所运行的大能大力，使他从死里复活，叫他在天上坐在自己的右边，"},{"start":21,"end":21,"text":"远超过一切执政的、掌权的、有能的、主治的，和一切有名的；不但是今世的，连来世的也都超过了。"},{"start":22,"end":22,"text":"又将万有服在他的脚下，使他为教会作万有之首。"},{"start":23,"end":23,"text":"教会是他的身体，是那充满万有者所充满的。"}],"2":[{"start":13,"end":13,"text":"你们从前远离　[神]的人，如今却在基督耶稣里，靠着他的血，已经得亲近了。"},{"start":14,"end":14,"text":"因他使我们和睦，将两下合而为一，拆毁了中间隔断的墙；"},{"start":15,"end":15,"text":"而且以自己的身体废掉冤仇，就是那[记]在律法上的规条，为要将两下借着自己造成一个新人，[如此]便成就了和睦。"},{"start":16,"end":16,"text":"既在十字架上灭了冤仇，便借这十字架使两下归为一体，与　神和好了，"},{"start":17,"end":17,"text":"并且来传和平的福音给你们远处的人，也给那近处的人。"},{"start":18,"end":18,"text":"因为我们两下借着他被一个[圣]灵所感，得以进到父面前。"},{"start":19,"end":19,"text":"这样，你们不再作外人和客旅，是与圣徒同国，是　神家里的人了；"}],"4":[{"start":31,"end":31,"text":"一切苦毒、恼恨、忿怒、嚷闹、毁谤，并一切的恶毒，都当从你们中间除掉；"},{"start":32,"end":32,"text":"并要以恩慈相待，存怜悯的心，彼此饶恕，正如　神在基督里饶恕了你们一样。"}],"5":[{"start":8,"end":8,"text":"从前你们是暗昧的，但如今在主里面是光明的，行事为人就当像光明的子女。"},{"start":9,"end":9,"text":"光明所结的果子就是一切良善、公义、诚实。"},{"start":10,"end":10,"text":"总要察验何为主所喜悦的事。"},{"start":11,"end":11,"text":"那暗昧无益的事，不要与人同行，倒要责备[行这事的人]；"},{"start":12,"end":12,"text":"因为他们暗中所行的，就是提起来也是可耻的。"},{"start":13,"end":13,"text":"凡事受了责备，就被光显明出来，因为一切能显明的就是光。"},{"start":14,"end":14,"text":"所以[主]说： 你这睡着的人当醒过来， 从死里复活！ 基督就要光照你了。"}]},"AMO":{"3":[{"start":6,"end":6,"text":"城中若吹角，百姓岂不惊恐呢？ 灾祸若临到一城，岂非耶和华所降的吗？"},{"start":7,"end":7,"text":"主耶和华若不将奥秘指示他的仆人—众先知， 就一无所行。"},{"start":8,"end":8,"text":"狮子吼叫，谁不惧怕呢？ 主耶和华发命，谁能不说预言呢？"}],"5":[{"start":21,"end":21,"text":"我厌恶你们的节期， 也不喜悦你们的严肃会。"},{"start":22,"end":22,"text":"你们虽然向我献燔祭和素祭， 我却不悦纳， 也不顾你们用肥畜献的平安祭；"},{"start":23,"end":23,"text":"要使你们歌唱的声音远离我， 因为我不听你们弹琴的响声。"},{"start":24,"end":24,"text":"惟愿公平如大水滚滚， 使公义如江河滔滔。"}],"6":[{"start":4,"end":4,"text":"你们躺卧在象牙床上，舒身在榻上， 吃群中的羊羔，棚里的牛犊；"},{"start":5,"end":5,"text":"弹琴鼓瑟唱消闲的歌曲， 为自己制造乐器，如同大卫[所造]的；"},{"start":6,"end":6,"text":"以大碗喝酒，用上等的油抹身， 却不为约瑟的苦难担忧。"},{"start":7,"end":7,"text":"所以这些人必在被掳的人中首先被掳； 舒身的人荒宴之乐必消灭了。"}],"8":[{"start":4,"end":4,"text":"你们这些要吞吃穷乏人、 使困苦人衰败的，当听我的话！"},{"start":5,"end":5,"text":"你们说：月朔几时过去， 我们好卖粮； 安息日几时过去， 我们好摆开麦子； [卖出]用小升斗， [收银]用大戥子， 用诡诈的天平欺哄人，"},{"start":6,"end":6,"text":"好用银子买贫寒人， 用一双鞋换穷乏人， 将坏了的麦子卖给人。"},{"start":9,"end":9,"text":"主耶和华说：到那日， 我必使日头在午间落下， 使地在白昼黑暗。"},{"start":10,"end":10,"text":"我必使你们的节期变为悲哀， 歌曲变为哀歌。 众人腰束麻布，头上光秃， 使这场悲哀如丧独生子， 至终如痛苦的日子一样。"}],"9":[{"start":9,"end":9,"text":"我必出令， 将以色列家分散在列国中， 好像用筛子筛[谷]， 连一粒也不落在地上。"},{"start":10,"end":10,"text":"我民中的一切罪人说： 灾祸必追不上我们， 也迎不着我们。 他们必死在刀下。"},{"start":11,"end":11,"text":"到那日，我必建立大卫倒塌的帐幕， 堵住其中的破口， 把那破坏的建立起来， 重新修造，像古时一样，"},{"start":12,"end":12,"text":"使以色列人得以东所余剩的 和所有称为我名下的国。 此乃行这事的耶和华说的。"},{"start":13,"end":13,"text":"耶和华说： 日子将到， 耕种的必接续收割的； 踹葡萄的必接续撒种的； 大山要滴下甜酒； 小山都必流奶。"},{"start":14,"end":14,"text":"我必使我民以色列被掳的归回； 他们必重修荒废的城邑居住， 栽种葡萄园，喝其中所出的酒， 修造果木园，吃其中的果子。"},{"start":15,"end":15,"text":"我要将他们栽于本地， 他们不再从我所赐给他们的地上拔出来。 这是耶和华—你的　神说的。"}]},"ECC":{"5":[{"start":10,"end":10,"text":"贪爱银子的，不因得银子知足；贪爱丰富的，也不因得利益知足。这也是虚空。"},{"start":11,"end":11,"text":"货物增添，吃的人也增添，物主得什么益处呢？不过眼看而已！"},{"start":12,"end":12,"text":"劳碌的人不拘吃多吃少，睡得香甜；富足人的丰满却不容他睡觉。"},{"start":13,"end":13,"text":"我见日光之下有一宗大祸患，就是财主积存资财，反害自己。"},{"start":14,"end":14,"text":"因遭遇祸患，这些资财就消灭；那人若生了儿子，手里也一无所有。"},{"start":15,"end":15,"text":"他怎样从母胎赤身而来，也必照样赤身而去；他所劳碌得来的，手中分毫不能带去。"}]},"1TI":{"6":[{"start":6,"end":6,"text":"然而，敬虔加上知足的心便是大利了；"},{"start":7,"end":7,"text":"因为我们没有带什么到世上来，也不能带什么去。"},{"start":8,"end":8,"text":"只要有衣有食，就当知足。"},{"start":9,"end":9,"text":"但那些想要发财的人，就陷在迷惑、落在网罗和许多无知有害的私欲里，叫人沉在败坏和灭亡中。"},{"start":10,"end":10,"text":"贪财是万恶之根。有人贪恋钱财，就被引诱离了真道，用许多愁苦把自己刺透了。"},{"start":11,"end":11,"text":"但你这属　神的人要逃避这些事，追求公义、敬虔、信心、爱心、忍耐、温柔。"},{"start":12,"end":12,"text":"你要为真道打那美好的仗，持定永生。你为此被召，也在许多见证人面前，已经作了那美好的见证。"},{"start":13,"end":13,"text":"我在叫万物生活的　神面前，并在向本丢·彼拉多作过那美好见证的基督耶稣面前嘱咐你："},{"start":14,"end":14,"text":"要守这命令，毫不玷污，无可指责，直到我们的主耶稣基督显现。"},{"start":15,"end":15,"text":"到了日期，那可称颂、独有权能的万王之王、万主之主，"},{"start":16,"end":16,"text":"就是那独一不死、住在人不能靠近的光里，是人未曾看见、也是不能看见的，要将他显明出来。但愿尊贵和永远的权能都归给他。阿们！"},{"start":17,"end":17,"text":"你要嘱咐那些今世富足的人，不要自高，也不要倚靠无定的钱财；只要倚靠那厚赐百物给我们享受的　神。"},{"start":18,"end":18,"text":"又要嘱咐他们行善，在好事上富足，甘心施舍，乐意供给人，"},{"start":19,"end":19,"text":"为自己积成美好的根基，预备将来，叫他们持定那真正的生命。"},{"start":20,"end":20,"text":"提摩太啊，你要保守所托付你的，躲避世俗的虚谈和那敌真道、似是而非的学问。"},{"start":21,"end":21,"text":"已经有人自称有这学问，就偏离了真道。 愿恩惠[常]与你们同在！"}]},"2CO":{"1":[{"start":3,"end":3,"text":"愿颂赞归与我们的主耶稣基督的父　神，就是发慈悲的父，赐各样安慰的　神。"},{"start":4,"end":4,"text":"我们在一切患难中，他就安慰我们，叫我们能用　神所赐的安慰去安慰那遭各样患难的人。"}],"5":[{"start":17,"end":17,"text":"若有人在基督里，他就是新造的人，旧事已过，都变成新的了。"},{"start":18,"end":18,"text":"一切都是出于　神；他借着基督使我们与他和好，又将劝人与他和好的职分赐给我们。"},{"start":19,"end":19,"text":"这就是　神在基督里，叫世人与自己和好，不将他们的过犯归到他们身上，并且将这和好的道理托付了我们。"},{"start":20,"end":20,"text":"所以，我们作基督的使者，就好像　神借我们劝你们一般。我们替基督求你们与　神和好。"},{"start":21,"end":21,"text":"神使那无罪的，替我们成为罪，好叫我们在他里面成为　神的义。"}],"8":[{"start":1,"end":1,"text":"弟兄们，我把　神赐给马其顿众教会的恩告诉你们，"},{"start":2,"end":2,"text":"就是他们在患难中受大试炼的时候，仍有满足的快乐，在极穷之间还格外显出他们乐捐的厚恩。"},{"start":3,"end":3,"text":"我可以证明，他们是按着力量，而且也过了力量，自己甘心乐意地捐助，"},{"start":4,"end":4,"text":"再三地求我们，准他们在这供给圣徒的恩情上有分；"},{"start":5,"end":5,"text":"并且他们所做的，不但照我们所想望的，更照　神的旨意先把自己献给主，又归附了我们。"},{"start":6,"end":6,"text":"因此我劝提多，既然在你们中间开办这慈惠的事，就当办成了。"},{"start":7,"end":7,"text":"你们既然在信心、口才、知识、热心，和待我们的爱心上，都格外显出满足来，就当在这慈惠的事上也格外显出满足来。"},{"start":8,"end":8,"text":"我说这话，不是吩咐你们，乃是借着别人的热心试验你们爱心的实在。"},{"start":9,"end":9,"text":"你们知道我们主耶稣基督的恩典：他本来富足，却为你们成了贫穷，叫你们因他的贫穷，可以成为富足。"},{"start":10,"end":10,"text":"我在这事上把我的意见告诉你们，是与你们有益；因为你们下手办这事，而且起此心意，已经有一年了，"},{"start":11,"end":11,"text":"如今就当办成这事。既有愿做的心，也当照你们所有的去办成。"},{"start":12,"end":12,"text":"因为人若有愿做的心，必蒙悦纳，乃是照他所有的，并不是照他所无的。"},{"start":13,"end":13,"text":"我原不是要别人轻省，你们受累，"},{"start":14,"end":14,"text":"乃要均平，就是要你们的富余，现在[可以补]他们的不足，使他们的富余，[将来]也可以[补]你们的不足，这就均平了。"},{"start":15,"end":15,"text":"如[经上]所记： 多[收]的也没有余； 少[收]的也没有缺。"}]},"ZEP":{"3":[{"start":17,"end":17,"text":"耶和华—你的　神是施行拯救、 大有能力的[主]。 他在你中间必因你欢欣喜乐， 默然爱你，且因你喜乐而欢呼。"},{"start":18,"end":18,"text":"那些属你、为无大会愁烦、 因你担当羞辱的，我必聚集他们。"},{"start":19,"end":19,"text":"那时，我必罚办一切苦待你的人， 又拯救你瘸腿的，聚集你被赶出的。 那些在全地受羞辱的， 我必使他们得称赞，有名声。"},{"start":20,"end":20,"text":"那时，我必领你们进来，聚集你们； 我使你们被掳之人归回的时候， 就必使你们在地上的万民中有名声，得称赞。 这是耶和华说的。"}]},"1TH":{"4":[{"start":13,"end":13,"text":"论到睡了的人，我们不愿意弟兄们不知道，恐怕你们忧伤，像那些没有指望的人一样。"},{"start":14,"end":14,"text":"我们若信耶稣死而复活了，那已经在耶稣里睡了的人，　神也必将他们与耶稣一同带来。"},{"start":15,"end":15,"text":"我们现在照主的话告诉你们一件事：我们这活着还存留到主降临的人，断不能在那已经睡了的人之先。"},{"start":16,"end":16,"text":"因为主必亲自从天降临，有呼叫的声音和天使长的声音，又有　神的号[吹响]；那在基督里死了的人必先复活。"},{"start":17,"end":17,"text":"以后我们这活着还存留的人必和他们一同被提到云里，在空中与主相遇。这样，我们就要和主永远同在。"},{"start":18,"end":18,"text":"所以，你们当用这些话彼此劝慰。"}],"5":[{"start":1,"end":1,"text":"弟兄们，论到时候、日期，不用写信给你们，"},{"start":2,"end":2,"text":"因为你们自己明明晓得，主的日子来到，好像夜间的贼一样。"},{"start":3,"end":3,"text":"人正说「平安稳妥」的时候，灾祸忽然临到他们，如同产难临到怀胎的妇人一样，他们绝不能逃脱。"},{"start":4,"end":4,"text":"弟兄们，你们却不在黑暗里，叫那日子临到你们像贼一样。"},{"start":5,"end":5,"text":"你们都是光明之子，都是白昼之子。我们不是属黑夜的，也不是属幽暗的。"},{"start":6,"end":6,"text":"所以，我们不要睡觉像别人一样，总要警醒谨守。"},{"start":7,"end":7,"text":"因为睡了的人是在夜间睡，醉了的人是在夜间醉。"},{"start":8,"end":8,"text":"但我们既然属乎白昼，就应当谨守，把信和爱当作护心镜遮胸，把得救的盼望当作头盔戴上。"},{"start":9,"end":9,"text":"因为　神不是预定我们受刑，乃是预定我们借着我们主耶稣基督得救。"},{"start":10,"end":10,"text":"他替我们死，叫我们无论醒着，睡着，都与他同活。"},{"start":11,"end":11,"text":"所以，你们该彼此劝慰，互相建立，正如你们素常所行的。"}]},"ZEC":{"9":[{"start":9,"end":9,"text":"锡安的民哪，应当大大喜乐； 耶路撒冷的民哪，应当欢呼。 看哪，你的王来到你这里！ 他是公义的，并且施行拯救， 谦谦和和地骑着驴， 就是骑着驴的驹子。"},{"start":10,"end":10,"text":"我必除灭以法莲的战车 和耶路撒冷的战马； 争战的弓也必除灭。 他必向列国讲和平； 他的权柄必从这海管到那海， 从大河管到地极。"}],"11":[{"start":12,"end":12,"text":"我对他们说：「你们若以为美，就给我工价。不然，就罢了！」于是他们给了三十块钱作为我的工价。"},{"start":13,"end":13,"text":"耶和华吩咐我说：「要把众人所估定美好的价值丢给窑户。」我便将这三十块钱，在耶和华的殿中丢给窑户了。"}],"12":[{"start":10,"end":10,"text":"「我必将那施恩叫人恳求的灵，浇灌大卫家和耶路撒冷的居民。他们必仰望我，就是他们所扎的；必为我悲哀，如丧独生子，又为我愁苦，如丧长子。"},{"start":11,"end":11,"text":"那日，耶路撒冷必有大大的悲哀，如米吉多平原之哈达临门的悲哀。"},{"start":12,"end":12,"text":"境内一家一家地都必悲哀。大卫家，男的独在一处，女的独在一处。拿单家，男的独在一处，女的独在一处。"},{"start":13,"end":13,"text":"利未家，男的独在一处，女的独在一处。示每家，男的独在一处，女的独在一处。"},{"start":14,"end":14,"text":"其余的各家，男的独在一处，女的独在一处。"}],"13":[{"start":7,"end":7,"text":"万军之耶和华说： 刀剑哪，应当兴起， 攻击我的牧人和我的同伴。 击打牧人，羊就分散； 我必反手加在微小者的身上。"},{"start":8,"end":8,"text":"耶和华说：这全地的人， 三分之二必剪除而死， 三分之一仍必存留。"},{"start":9,"end":9,"text":"我要使这三分之一经火， 熬炼他们，如熬炼银子； 试炼他们，如试炼金子。 他们必求告我的名， 我必应允他们。 我要说：这是我的子民。 他们也要说：耶和华是我[们]的　神。"}]}};

